n(\"5 3 8 1\");\n    std::vector<int> v(std::istream_iterator<int>{in}, std::istream_iterator<int>{});   // read all ints\n\n    std::vector<int> evens;\n    std::copy_if(v.begin(), v.end(), std::back_inserter(evens), [](int x) { return x % 2 == 0; });\n\n    std::copy(v.begin(), v.end(), std::ostream_iterator<int>(std::cout, \",\"));   // print with separator\n    std::cout << \" evens=\" << evens.size() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"351dd3c2-7b45-7076-b536-bf3ef3e796bc","type":"code","position":"aA","content":{"language":"text","code":"5,3,8,1, evens=1","filename":"Output"},"revision":1},{"id":"216e46d7-9910-704a-a296-e43c4c2d270d","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Making your own class iterable"}]},"revision":1},{"id":"30c87bc9-200e-78b8-8ce7-4f4f4c227fe8","type":"code","position":"aC","content":{"language":"cpp","code":"#include <iostream>\n\nclass Range {                                   // like Python''s range(lo, hi)\n    int lo_, hi_;\npublic:\n    Range(int lo, int hi) : lo_(lo), hi_(hi) {}\n    struct iterator {\n        int cur;\n        int operator*() const { return cur; }\n        iterator& operator++() { ++cur; return *this; }\n        bool operator==(const iterator&) const = default;\n    };\n    iterator begin() const { return {lo_}; }\n    iterator end() const { return {hi_}; }\n};\n\nint main() {\n    for (int i : Range(3, 7)) std::cout << i << '' '';\n    std::cout << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"7939348b-55b7-741e-8bd4-9d3a2383c06a","type":"code","position":"aD","content":{"language":"text","code":"3 4 5 6","filename":"Output"},"revision":1},{"id":"ebc7048d-87b9-7826-b6e2-ad26bf9b0e85","type":"callout","position":"aE","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An iterator is only valid while its container isn''t restructured: e.g. a "},{"type":"text","text":"vector","marks":[{"type":"code"}]},{"type":"text","text":" reallocation or erasing the element it points to invalidates it. Using an invalidated iterator is undefined behaviour."}]}]}},"revision":1},{"id":"8509816c-03eb-7555-9e65-ff85fc4d5061","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does the STL use half-open ranges [begin, end)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An empty range is simply "},{"type":"text","text":"begin == end","marks":[{"type":"code"}]},{"type":"text","text":", the length is "},{"type":"text","text":"end - begin","marks":[{"type":"code"}]},{"type":"text","text":", loops are "},{"type":"text","text":"while (it != end)","marks":[{"type":"code"}]},{"type":"text","text":", and ranges split cleanly: "},{"type":"text","text":"[a, m)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"[m, b)","marks":[{"type":"code"}]},{"type":"text","text":" share no element and miss none. It also allows "},{"type":"text","text":"end()","marks":[{"type":"code"}]},{"type":"text","text":" for containers where a “last element” pointer would be awkward."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
