SELECT '3e7678fd-813d-798f-8401-4a9238aadf8b', '2de923d1-844c-7179-a42a-d40fdd309796', 1, 'PUBLISHED', 'map & multimap', '[{"id":"104a208e-ee06-7129-a699-7552c03acd72","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::map<K, V>","marks":[{"type":"code"}]},{"type":"text","text":" stores key → value pairs sorted by key, with unique keys and O(log n) operations. "},{"type":"text","text":"std::multimap","marks":[{"type":"code"}]},{"type":"text","text":" allows repeated keys."}]}]}},"revision":1},{"id":"cca5272a-e81c-74f4-9777-4992573107ff","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Core operations"}]},"revision":1},{"id":"e5993d8f-83da-793d-a107-ff68a429ced4","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <map>\n#include <string>\n\nint main() {\n    std::map<std::string, int> stock{{\"apple\", 5}, {\"pear\", 2}};\n    stock[\"kiwi\"] = 7;                          // insert or overwrite\n    stock[\"apple\"] += 1;\n    stock.insert({\"pear\", 100});                // no effect: key exists\n    stock.emplace(\"fig\", 3);\n\n    for (const auto& [fruit, qty] : stock) std::cout << fruit << ''='' << qty << '' '';   // sorted by key\n    std::cout << ''\\n'';\n\n    if (auto it = stock.find(\"kiwi\"); it != stock.end()) std::cout << \"kiwi: \" << it->second << ''\\n'';\n    std::cout << stock.count(\"mango\") << '' '' << stock.contains(\"fig\") << ''\\n'';\n    stock.erase(\"pear\");\n    std::cout << stock.size() << '' '' << stock.at(\"fig\") << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"e55ce15a-f397-7c85-b800-d1bfc5548db4","type":"code","position":"a3","content":{"language":"text","code":"apple=6 fig=3 kiwi=7 pear=2\nkiwi: 7\n0 1\n3 3","filename":"Output"},"revision":1},{"id":"bf597d2d-846d-7cbf-a6da-2f03b946139c","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"The "},{"type":"text","text":"operator[]","marks":[{"type":"code"}]},{"type":"text","text":" trap"}]},"revision":1},{"id":"32012c0a-67b0-7497-a375-5cc146308b74","type":"code","position":"a5","content":{"language":"cpp","code":"#include <iostream>\n#include <map>\n#include <string>\nint main() {\n    std::map<std::string, int> ages{{\"ada\", 36}};\n    if (ages[\"bob\"] == 0) std::cout << \"bob not found?\\n\";   // [] INSERTS \"bob\" with 0!\n    std::cout << ages.size() << ''\\n'';\n    // const std::map<...>& cref = ages; cref[\"x\"];          // error: no const operator[]\n    try { std::cout << ages.at(\"cy\"); } catch (const std::out_of_range&) { std::cout << \"at() throws\\n\"; }\n}","filename":"C++"},"revision":1},{"id":"fca7138f-3b12-7a3d-8545-a54a9017a377","type":"code","position":"a6","content":{"language":"text","code":"bob not found?\n2\nat() throws","filename":"Output"},"revision":1},{"id":"18a2a777-8458-7ba0-8b02-569344b8e277","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Access"}],[{"type":"text","text":"Missing key"}],[{"type":"text","text":"Use for"}]],[[{"type":"text","text":"m[key]","marks":[{"type":"code"}]}],[{"type":"text","text":"Inserts a default-constructed value"}],[{"type":"text","text":"Counting, building up ("},{"type":"text","text":"freq[word]++","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"m.at(key)","marks":[{"type":"code"}]}],[{"type":"text","text":"Throws "},{"type":"text","text":"std::out_of_range","marks":[{"type":"code"}]}],[{"type":"text","text":"Must exist"}]],[[{"type":"text","text":"m.find(key)","marks":[{"type":"code"}]}],[{"type":"text","text":"Returns "},{"type":"text","text":"m.end()","marks":[{"type":"code"}]}],[{"type":"text","text":"Lookup without side effects"}]],[[{"type":"text","text":"m.contains(key)","marks":[{"type":"code"}]},{"type":"text","text":" (C++20) / "},{"type":"text","text":"m.count(key)","marks":[{"type":"cod