on":1},{"id":"3d91cd11-51f0-7c24-9723-62efdf6b4e98","type":"code","position":"a5","content":{"language":"cpp","code":"#include <iostream>\n#include <utility>\n\nclass Buffer {\n    int* data_ = nullptr;\n    std::size_t size_ = 0;\npublic:\n    explicit Buffer(std::size_t n) : data_(new int[n]{}), size_(n) {}\n    ~Buffer() { delete[] data_; }\n\n    Buffer(const Buffer& o) : data_(new int[o.size_]), size_(o.size_) {\n        std::copy(o.data_, o.data_ + size_, data_);\n        std::cout << \"copy\\n\";\n    }\n    Buffer(Buffer&& o) noexcept                                        // move constructor\n        : data_(std::exchange(o.data_, nullptr)), size_(std::exchange(o.size_, 0)) {\n        std::cout << \"move\\n\";\n    }\n    Buffer& operator=(Buffer&& o) noexcept {                           // move assignment\n        if (this != &o) {\n            delete[] data_;\n            data_ = std::exchange(o.data_, nullptr);\n            size_ = std::exchange(o.size_, 0);\n        }\n        return *this;\n    }\n    Buffer& operator=(const Buffer&) = delete;   // kept short for the example\n    std::size_t size() const { return size_; }\n};\n\nBuffer make() { return Buffer(8); }             // guaranteed elision: no copy, no move\n\nint main() {\n    Buffer a(4);\n    Buffer b = std::move(a);        // move\n    Buffer c = b;                   // copy\n    Buffer d = make();              // nothing printed\n    d = std::move(c);               // move assignment\n    std::cout << a.size() << '' '' << b.size() << '' '' << c.size() << '' '' << d.size() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"bb6e77fa-99ac-704d-a33a-67e9aa7641e1","type":"code","position":"a6","content":{"language":"text","code":"move\ncopy\n0 4 0 4","filename":"Output"},"revision":1},{"id":"0b572528-5916-7396-b7b7-0d916ed8c0cf","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Steal","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Take the source''s pointers/handles."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reset the source","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Leave it in a valid, destructible state (usually empty) — "},{"type":"text","text":"std::exchange(o.p, nullptr)","marks":[{"type":"code"}]},{"type":"text","text":" does both in one step."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark ","marks":[{"type":"bold"}]},{"type":"text","text":"noexcept","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"std::vector","marks":[{"type":"code"}]},{"type":"text","text":" only moves elements during reallocation if the move constructor is "},{"type":"text","text":"noexcept","marks":[{"type":"code"}]},{"type":"text","text":"; otherwise it copies to keep the strong guarantee."}]}]}]}]}},"revision":1},{"id":"7b30c1cc-b0fb-72bc-892d-0219660c20d7","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Why "},{"type":"text","text":"noexcept","marks":[{"type":"code"}]},{"type":"text","text":" matters"}]},"revision":1},{"id":"d4d51998-20bf-768c-922a-ef20d16f4735","type":"code","position":"a9","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nstruct Safe   { Safe() = default;   Safe(const Safe&)   { std::cout << \"C\"; } Safe(Safe&&) noexcept { std::cout << \"M\"; } };\nstruct Unsafe { Unsafe() = default; Unsafe(const Unsafe&) { std::cout << \"C\"; } Unsafe(Unsafe&&)       { std::cout << \"M\"; } };\nint main() {\n    std::vector<Safe> a(2);\n    a.reserve(10);             // reallocation moves the 2 elements\n    std::cout << ''\\n'';\n    std::vector<Unsafe> b(2);\n    b.reserve(10);             // reallocation copies — the move might throw\n    std: