SELECT '5aa605d8-670e-7607-a314-b7f61feb903f', '284d182c-b08b-7895-a975-5ecdfd5f620e', 'Move Semantics & rvalue References', 'Move Semantics & rvalue References', 'Moving transfers a resource from an object that''s about to die (or that you no longer need) instead of copying it. A std::vector move is three pointer copies — no matter how many elements it holds.
Copy vs move
#include <iostream>
#include <string>
#include <utility>
#include <vector>

int main() {
    std::vector<int> a(1''000''000, 7);
    std::vector<int> b = a;               // copy: allocates and copies a million ints
    std::vector<int> c = std::move(a);    // move: steals a''s buffer
    std::cout << a.size() << '' '' << b.size() << '' '' << c.size() << ''\n'';   // a is now empty (valid, unspecified)

    std::string s = "a fairly long string that will not fit in SSO";
    std::vector<std::string> names;
    names.push_back(s);                   // copies
    names.push_back(std::move(s));        // moves — s is left valid but unspecified
    std::cout << names.size() << '' '' << names[1].size() << ''\n'';
}
