SELECT 'f130d248-890d-7698-a341-679900f79fcc', '5618b918-08a8-7930-b328-9bfbbe3ff537', 1, 'PUBLISHED', 'Multiple & Virtual Inheritance', '[{"id":"830d41f2-a48e-76b7-8827-618d375b5fc8","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class can inherit from several bases. That''s safe for interfaces, but when two bases share a common ancestor you get the "},{"type":"text","text":"diamond problem","marks":[{"type":"bold"}]},{"type":"text","text":" — solved by "},{"type":"text","text":"virtual","marks":[{"type":"code"}]},{"type":"text","text":" inheritance."}]}]}},"revision":1},{"id":"3db6518f-d877-7e8d-9c92-7bd7c4ca7c91","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Multiple inheritance"}]},"revision":1},{"id":"9f429bb9-ffd5-7f83-b159-7c4c88b3f39d","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n\nstruct Printable { virtual void print() const = 0; virtual ~Printable() = default; };\nstruct Serializable { virtual std::string serialize() const = 0; virtual ~Serializable() = default; };\n\nstruct Point : Printable, Serializable {         // implements two interfaces\n    int x = 1, y = 2;\n    void print() const override { std::cout << \"Point(\" << x << \", \" << y << \")\\n\"; }\n    std::string serialize() const override { return std::to_string(x) + \",\" + std::to_string(y); }\n};\n\nint main() {\n    Point p;\n    const Printable& pr = p;\n    const Serializable& se = p;\n    pr.print();\n    std::cout << se.serialize() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"a9339e1f-63d4-7b66-b572-f2d19b3d80eb","type":"code","position":"a3","content":{"language":"text","code":"Point(1, 2)\n1,2","filename":"Output"},"revision":1},{"id":"2103e3ee-d434-7937-84e9-5c4ead99c5c1","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"The diamond problem"}]},"revision":1},{"id":"611d3e27-b080-71c9-83d8-593f262fc64c","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Device","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"Scanner","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Printer","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"Copier","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"c751cac7-bdce-7eef-8f44-bb334ae7cad9","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\n\nstruct Device { int id = 0; };\nstruct Scanner : Device {};\nstruct Printer : Device {};\nstruct Copier : Scanner, Printer {};      // contains TWO Device sub-objects\n\nint main() {\n    Copier c;\n    c.Scanner::id = 1;                     // must disambiguate\n    c.Printer::id = 2;\n    std::cout << c.Scanner::id << '' '' << c.Printer::id << '' '' << sizeof(Copier) / sizeof(int) << ''\\n'';\n    // c.id = 5;                           // error: ambiguous\n}","filename":"C++"},"revision":1},{"id":"37db6392-b8eb-7c50-8e9b-5a574eca5137","type":"code","position":"a7","content":{"language":"text","code":"1 2 2","filename":"Output"},"revision":1},{"id":"1a288f60-cbb1-7b4e-8da9-5e3a228a916b","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Virtual inheritance"}]},"revision":1},{"id":"3efe194e-de05-7026-bbe0-04dde0eff24a","type":"code","position":"a9","content":{"language":"cpp","code":"#include <iostream>\n\nstruct Device {\n    int id;\n    explicit Device(int i) : id(i) { std::cout << \"Device(\" << i << \")\\n\"; }\n};\nstruct Scanner : virtual Device { Scanner() : Device(1) {} };   // shared base\nstruct Printer : virtual Device { Printer() : Device(2) {} };\nstruct Copier : Scanner, Printer {\n    Copier() : Device(3) {}               // the MOST-DERIVED class initialises the virtual base\n};\n\nint main() {\n    Copier c;\n    std::cout << c.id << ''\\n'';            // one Device, no ambiguity\n}","filename":"C++"},"revision":1},{"id":"b37fc0f5-050d-72c1-bd38-327988276a46","type":"code","position":"aA","content":{"language":"text","code":"Device(3)\n3","filename":"Output"},"revision":1},{"id":"abfc97a3-10ff-7d8d-8524-3bdb94515e86","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"With "},{"type":"text","text":"virtual","marks":[{"type":"code"}]},{"type":"text","text":" inheritance there is exactly "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" shared base sub-object."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The most-derived class constructs the virtual base; the intermediate classes'' initialisers for it are ignored."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost: an extra indirection (virtual base offset) to reach the shared base, and more complex object layout."}]}]}]}]}},"revision":1},{"id":"c9e1706a-e9c4-7886-8136-a2663dc09854","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Name clashes between bases"}]},"revision":1},{"id":"a8ff34cf-11e5-725f-b18e-7e47e045818f","type":"code","position":"aD","content":{"language":"cpp","code":"#include <iostream>\nstruct Camera { void start() const { std::cout << \"camera on\\n\"; } };\nstruct Phone  { void start() const { std::cout << \"phone on\\n\"; } };\nstruct SmartPhone : Camera, Phone {\n    void start() const { Phone::start(); Camera::start(); }   // resolve explicitly\n};\nint main() { SmartPhone{}.start(); }","filename":"C++"},"revision":1},{"id":"f2f907ec-1e1e-76ab-9a09-97cc30fb7994","type":"code","position":"aE","content":{"language":"text","code":"phone on\ncamera on","filename":"Output"},"revision":1},{"id":"1c5ab2c7-02b4-7e16-b0db-3c99f680dac5","type":"callout","position":"aF","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use multiple inheritance of "},{"type":"text","text":"interfaces","marks":[{"type":"italic"}]},{"type":"text","text":" (pure abstract bases) freely."}]}]}},"revision":1},{"id":"36fd242c-8f66-7218-b91d-03462d11a2f2","type":"callout","position":"aG","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Deep hierarchies with multiple "},{"type":"text","text":"stateful","marks":[{"type":"italic"}]},{"type":"text","text":" bases — prefer composition."}]}]}},"revision":1},{"id":"46cc4c65-7ee2-78e9-84b7-e145eea75a89","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the diamond problem and how does C++ solve it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When "},{"type":"text","text":"D","marks":[{"type":"code"}]},{"type":"text","text":" inherits from "},{"type":"text","text":"B","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"C","marks":[{"type":"code"}]},{"type":"text","text":", which both inherit from "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"D","marks":[{"type":"code"}]},{"type":"text","text":" contains two copies of "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":"''s members are ambiguous and the state is duplicated. Declaring "},{"type":"text","text":"B : virtual A","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"C : virtual A","marks":[{"type":"code"}]},{"type":"text","text":" makes them share one "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":" sub-object, which the most-derived class ("},{"type":"text","text":"D","marks":[{"type":"code"}]},{"type":"text","text":") constructs."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
