Anonymous namespaces & ::
#include <iostream>

namespace {                    // anonymous: visible only in this .cpp (internal linkage)
    int helperCalls = 0;
    void helper() { ++helperCalls; }
}

int value = 1;                 // global

int main() {
    int value = 2;             // local shadows the global
    helper();
    helper();
    std::cout << value << '' '' << ::value << '' '' << helperCalls << ''\n'';   // ::value = global scope
}
