SELECT 'cdbe13da-366b-71b2-a05c-06652ea6d5bf', '7d4d451d-fdbf-72ba-9c9d-b254c0003049', 1, 'PUBLISHED', 'Operator Overloading', '[{"id":"21abf7bb-5089-7d72-844d-cfd23cc0a86d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You can give operators like "},{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<<","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"[]","marks":[{"type":"code"}]},{"type":"text","text":" a meaning for your own types, so they read like built-ins. Overload only when the meaning is obvious."}]}]}},"revision":1},{"id":"91f360f5-63e7-705f-ac47-ed49f46b59f4","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"A value type with arithmetic"}]},"revision":1},{"id":"94700084-32a4-760b-8945-e8e006f2fc6d","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n\nstruct Vec2 {\n    double x = 0, y = 0;\n\n    Vec2& operator+=(const Vec2& o) { x += o.x; y += o.y; return *this; }   // member: modifies *this\n    Vec2 operator-() const { return {-x, -y}; }                             // unary minus\n    bool operator==(const Vec2&) const = default;                           // C++20: memberwise ==\n};\n\nVec2 operator+(Vec2 a, const Vec2& b) { return a += b; }        // non-member, built from +=\nVec2 operator*(const Vec2& v, double k) { return {v.x * k, v.y * k}; }\nVec2 operator*(double k, const Vec2& v) { return v * k; }         // allow 2 * v too\n\nstd::ostream& operator<<(std::ostream& os, const Vec2& v) {       // printing\n    return os << ''('' << v.x << \", \" << v.y << '')'';\n}\n\nint main() {\n    Vec2 a{1, 2}, b{3, 4};\n    std::cout << a + b << '' '' << -a << '' '' << 2 * b << ''\\n'';\n    a += b;\n    std::cout << a << '' '' << (a == Vec2{4, 6}) << '' '' << (a != b) << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"75f0d3cb-55ff-7d96-90da-f9ff99a8315e","type":"code","position":"a3","content":{"language":"text","code":"(4, 6) (-1, -2) (6, 8)\n(4, 6) 1 1","filename":"Output"},"revision":1},{"id":"80768c52-0a54-7d3a-983b-56ba4bb4907d","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Member or non-member?"}]},"revision":1},{"id":"7096e695-a059-7525-b842-436dc366cd90","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operator"}],[{"type":"text","text":"Usually"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"=","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"->","marks":[{"type":"code"}]},{"type":"text","text":", conversion"}],[{"type":"text","text":"Must","marks":[{"type":"bold"}]},{"type":"text","text":" be members"}],[{"type":"text","text":"Language rule"}]],[[{"type":"text","text":"+=","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"-=","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"++","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"--","marks":[{"type":"code"}]},{"type":"text","text":", unary ops"}],[{"type":"text","text":"Member"}],[{"type":"text","text":"They modify / belong to "},{"type":"text","text":"*this","marks":[{"type":"code"}]}]],[[{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"-","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"*","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<","marks":[{"type":"code"}]}],[{"type":"text","text":"Non-member (often "},{"type":"text","text":"friend","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Symmetric: allows conversions on "},{"type":"text","text":"both","marks":[{"type":"italic"}]},{"type":"text","text":" sides ("},{"type":"text","text":"2 * v","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"<<","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":">>","marks":[{"type":"code"}]},{"type":"text","text":" (streams)"}],[{"type":"text","text":"Non-member"}],[{"type":"text","text":"Left operand is the stream, not your type"}]]]},"revision":1},{"id":"8d5aca02-777f-7356-87ea-8592c465d106","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Comparison with "},{"type":"text","text":"<=>","marks":[{"type":"code"}]},{"type":"text","text":" (C++20)"}]},"revision":1},{"id":"b3182a86-139e-76e4-8b06-abf8555a9440","type":"code","position":"a7","content":{"language":"cpp","code":"#include <algorithm>\n#include <compare>\n#include <iostream>\n#include <string>\n#include <vector>\n\nstruct Version {\n    int major, minor, patch;\n    auto operator<=>(const Version&) const = default;   // generates <, <=, >, >=, == and !=\n};\n\nstruct Employee {\n    std::string name;\n    int salary;\n    std::strong_ordering operator<=>(const Employee& o) const { return salary <=> o.salary; }\n    bool operator==(const Employee& o) const { return salary == o.salary; }\n};\n\nint main() {\n    std::cout << (Version{1, 2, 3} < Version{1, 10, 0}) << (Version{2, 0, 0} >= Version{1, 9, 9}) << ''\\n'';\n    std::vector<Employee> team{{\"Bo\", 50}, {\"Al\", 90}, {\"Cy\", 70}};\n    std::sort(team.begin(), team.end());\n    for (const auto& e : team) std::cout << e.name << '' '';\n    std::cout << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"bade94c1-6058-7add-aba1-68f1340d5fa8","type":"code","position":"a8","content":{"language":"text","code":"11\nBo Cy Al","filename":"Output"},"revision":1},{"id":"a3b12559-12fb-7a5d-afae-445d1240ead1","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Subscript, call, increment"}]},"revision":1},{"id":"4d7492c9-17ac-7673-b4b2-f575fdfa09ad","type":"code","position":"aA","content":{"language":"cpp","code":"#include <iostream>\n#include <stdexcept>\n\nclass IntArray {\n    int data_[4] = {};\npublic:\n    int& operator[](std::size_t i) { return data_[i]; }              // non-const: allows writes\n    const int& operator[](std::size_t i) const { return data_[i]; }  // const overload for const objects\n};\n\nstruct Counter {\n    int n = 0;\n    Counter& operator++() { ++n; return *this; }                 // prefix\n    Counter operator++(int) { Counter old = *this; ++n; return old; }   // postfix (dummy int)\n    int operator()(int step) { return n += step; }               // call operator: a functor\n    explicit operator bool() const { return n != 0; }            // conversion\n};\n\nint main() {\n    IntArray a;\n    a[2] = 7;\n    std::cout << a[2] << ''\\n'';\n    Counter c;\n    Counter before = c++;\n    ++c;\n    std::cout << before.n << '' '' << c.n << '' '' << c(10) << '' '' << static_cast<bool>(c) << ''\\n'';\n    if (c) std::cout << \"non-zero\\n\";      // explicit bool still works in conditions\n}","filename":"C++"},"revision":1},{"id":"f5c44724-ef01-77f3-a779-22c766bdd0ce","type":"code","position":"aB","content":{"language":"text","code":"7\n0 2 12 1\nnon-zero","filename":"Output"},"revision":1},{"id":"0636b8f4-e98d-7832-b37e-f9cfa83f54c4","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Copy assignment"}]},"revision":1},{"id":"5a41a55e-6d66-72eb-b74e-9219664db520","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"operator=","marks":[{"type":"code"}]},{"type":"text","text":" should return "},{"type":"text","text":"*this","marks":[{"type":"code"}]},{"type":"text","text":" by reference and survive self-assignment. The "},{"type":"text","text":"copy-and-swap","marks":[{"type":"italic"}]},{"type":"text","text":" idiom gets both, plus exception safety — see "},{"type":"text","text":"Copy Semantics","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"7b275016-8e8b-715d-bfa1-099b5a7eb112","type":"table","position":"aE","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Can''t overload"}],[{"type":"text","text":"Shouldn''t overload"}]],[[{"type":"text","text":"::","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":".","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":".*","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"?:","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"sizeof","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"typeid","marks":[{"type":"code"}]}],[{"type":"text","text":"&&","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"||","marks":[{"type":"code"}]},{"type":"text","text":" (lose short-circuiting), "},{"type":"text","text":",","marks":[{"type":"code"}]},{"type":"text","text":", unary "},{"type":"text","text":"&","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"b14a7e8b-0df7-7159-86d6-b788a86085da","type":"callout","position":"aF","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep the natural meaning: "},{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":" shouldn''t modify its operands, "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" must be symmetric and consistent with "},{"type":"text","text":"!=","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":" must be a strict weak ordering if you want to use the type in "},{"type":"text","text":"std::sort","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"std::map","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"aa3ad8bd-11e5-7b84-9ea7-7679939fce5f","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why return a reference from operator+= but a value from operator+?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"a += b","marks":[{"type":"code"}]},{"type":"text","text":" modifies "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" and yields "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" itself, so returning "},{"type":"text","text":"*this","marks":[{"type":"code"}]},{"type":"text","text":" by reference allows chaining without copies. "},{"type":"text","text":"a + b","marks":[{"type":"code"}]},{"type":"text","text":" produces a "},{"type":"text","text":"new","marks":[{"type":"italic"}]},{"type":"text","text":" value, leaving both operands untouched — returning a reference would dangle."}]}]}},"revision":1},{"id":"d8db15f8-e437-70b0-99bf-ad45348d7286","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is operator<< for streams a non-member function?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The left operand of "},{"type":"text","text":"std::cout << obj","marks":[{"type":"code"}]},{"type":"text","text":" is the stream. A member "},{"type":"text","text":"operator<<","marks":[{"type":"code"}]},{"type":"text","text":" would have to be a member of "},{"type":"text","text":"std::ostream","marks":[{"type":"code"}]},{"type":"text","text":", which you can''t modify. As a non-member it takes "},{"type":"text","text":"(std::ostream&, const T&)","marks":[{"type":"code"}]},{"type":"text","text":" and returns the stream for chaining. Make it a "},{"type":"text","text":"friend","marks":[{"type":"code"}]},{"type":"text","text":" if it needs private members."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
