SELECT '422487b5-2647-74dc-8e1d-5a4e4645c3da', '0177c2b7-ca9a-7317-aff8-6481d4449291', 1, 'PUBLISHED', 'optional, variant & any', '[{"id":"708f3793-cb2f-7747-8175-3bc63edd7493","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"C++17 vocabulary types: "},{"type":"text","text":"std::optional<T>","marks":[{"type":"code"}]},{"type":"text","text":" for “a value or nothing”, "},{"type":"text","text":"std::variant<A, B, …>","marks":[{"type":"code"}]},{"type":"text","text":" for “exactly one of these types”, "},{"type":"text","text":"std::any","marks":[{"type":"code"}]},{"type":"text","text":" for “any type at all”."}]}]}},"revision":1},{"id":"a464aca7-349c-7af2-8b98-8b33f1ca4c0b","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"std::optional","marks":[{"type":"code"}]}]},"revision":1},{"id":"53ba1637-63c3-75c1-9a9c-b75292233577","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <map>\n#include <optional>\n#include <string>\n\nstd::optional<int> findAge(const std::map<std::string, int>& db, const std::string& name) {\n    auto it = db.find(name);\n    if (it == db.end()) return std::nullopt;          // “no value” — no sentinel like -1\n    return it->second;\n}\n\nint main() {\n    std::map<std::string, int> db{{\"ada\", 36}};\n    if (auto age = findAge(db, \"ada\")) std::cout << \"ada \" << *age << ''\\n'';     // contextual bool\n    auto missing = findAge(db, \"bob\");\n    std::cout << missing.has_value() << '' '' << missing.value_or(-1) << ''\\n'';\n    try { std::cout << missing.value(); }                                       // throws if empty\n    catch (const std::bad_optional_access&) { std::cout << \"bad_optional_access\\n\"; }\n\n    std::optional<std::string> nick;\n    nick = \"Addy\";\n    nick.reset();\n    nick.emplace(3, ''z'');\n    std::cout << *nick << '' '' << nick->size() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"87983a4c-f483-7486-8e4f-c71f23c89804","type":"code","position":"a3","content":{"language":"text","code":"ada 36\n0 -1\nbad_optional_access\nzzz 3","filename":"Output"},"revision":1},{"id":"be477ba5-c940-70e3-a72c-62aadb9f2dcb","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"optional","marks":[{"type":"code"}]},{"type":"text","text":" stores the value "},{"type":"text","text":"inline","marks":[{"type":"italic"}]},{"type":"text","text":" (no heap allocation) plus a "},{"type":"text","text":"bool","marks":[{"type":"code"}]},{"type":"text","text":". Use it for return values that may be absent and for optional members; don''t use "},{"type":"text","text":"optional<T&>","marks":[{"type":"code"}]},{"type":"text","text":" (not allowed) — use "},{"type":"text","text":"T*","marks":[{"type":"code"}]},{"type":"text","text":" for optional references."}]}]}},"revision":1},{"id":"4f27a955-89b7-756d-be5e-3009de3b0213","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"std::variant","marks":[{"type":"code"}]},{"type":"text","text":" — a type-safe union"}]},"revision":1},{"id":"2efd4343-50b8-70b6-a4f9-f03a9ad8371a","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <variant>\n#include <vector>\n\ntemplate <class... Fs> struct overloaded : Fs... { using Fs::operator()...; };   // visitor helper\n\nusing Json = std::variant<std::nullptr_t, bool, int, std::string>;\n\nint main() {\n    std::vector<Json> values{nullptr, true, 42, std::string(\"hi\")};\n    for (const auto& v : values) {\n        std::visit(overloaded{\n            [](std::nullptr_t)          { std::cout << \"null\\n\"; },\n            [](bool b)                  { std::cout << \"bool \" << b << ''\\n''; },\n            [](int i)                   { std::cout << \"int \"