SELECT 'b6ed2068-cc4d-7dfa-b2e8-a47b475b947a', '33de68c4-ad66-7957-a78d-d2588a47d3e8', 1, 'PUBLISHED', 'pair & tuple', '[{"id":"047d7796-0697-7f8e-bd75-1896a5165ce4","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::pair<A, B>","marks":[{"type":"code"}]},{"type":"text","text":" holds two values; "},{"type":"text","text":"std::tuple<Ts...>","marks":[{"type":"code"}]},{"type":"text","text":" holds any number. Both compare lexicographically, which makes them handy as keys and sort criteria."}]}]}},"revision":1},{"id":"c6b58a2b-0332-749f-8bff-47eae95b5934","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"std::pair","marks":[{"type":"code"}]}]},"revision":1},{"id":"0e64370c-d467-7455-8168-4e209f11c7a9","type":"code","position":"a2","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <string>\n#include <utility>\n#include <vector>\n\nint main() {\n    std::pair<std::string, int> p{\"ada\", 36};\n    auto q = std::make_pair(std::string(\"bob\"), 25);\n    std::cout << p.first << '' '' << p.second << '' '' << (p < q) << ''\\n'';\n\n    std::vector<std::pair<int, char>> v{{2, ''b''}, {1, ''z''}, {2, ''a''}};\n    std::sort(v.begin(), v.end());                  // by first, then by second\n    for (const auto& [n, c] : v) std::cout << n << c << '' '';\n    std::cout << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"01e9f83b-b754-76ce-a98c-e04cf3369037","type":"code","position":"a3","content":{"language":"text","code":"ada 36 1\n1z 2a 2b","filename":"Output"},"revision":1},{"id":"a77ab1ca-c8b5-7bd9-b0ed-e89c6f3ce3c4","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"std::tuple","marks":[{"type":"code"}]}]},"revision":1},{"id":"8dbfb1ca-62cd-762a-a5e6-6a8373657d70","type":"code","position":"a5","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <string>\n#include <tuple>\n\nstd::tuple<int, int, int> minMaxSum(int a, int b, int c) {\n    return {std::min({a, b, c}), std::max({a, b, c}), a + b + c};\n}\n\nint main() {\n    std::tuple<std::string, int, double> t{\"x\", 1, 2.5};\n    std::cout << std::get<0>(t) << '' '' << std::get<int>(t) << '' '' << std::tuple_size_v<decltype(t)> << ''\\n'';\n\n    auto [lo, hi, sum] = minMaxSum(4, 9, 2);        // structured bindings\n    std::cout << lo << '' '' << hi << '' '' << sum << ''\\n'';\n\n    int a, b;\n    std::tie(a, b, std::ignore) = minMaxSum(1, 2, 3);   // unpack into existing variables\n    std::cout << a << b << ''\\n'';\n\n    auto joined = std::tuple_cat(std::make_tuple(1, ''c''), std::make_tuple(2.5));\n    std::cout << std::get<2>(joined) << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"d164221f-a567-7325-861b-33070a56bc03","type":"code","position":"a6","content":{"language":"text","code":"x 1 3\n2 9 15\n13\n2.5","filename":"Output"},"revision":1},{"id":"c1d85d7f-c8c3-766a-a9bd-7cfb87aff482","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Multi-key comparison with "},{"type":"text","text":"std::tie","marks":[{"type":"code"}]}]},"revision":1},{"id":"c805fb79-e07a-7853-814c-5d89ab9dad91","type":"code","position":"a8","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <string>\n#include <tuple>\n#include <vector>\n\nstruct Student { std::string name; int grade; int age; };\n\nint main() {\n    std::vector<Student> s{{\"cy\", 90, 20}, {\"al\", 85, 22}, {\"bo\", 90, 19}};\n    std::sort(s.begin(), s.end(), [](const Student& a, const Student& b) {\n        return std::tie(b.grade, a.age) < std::tie(a.grade, b.age);   // grade desc, then age asc\n    });\n    for (const auto& st : s) std::cout << st.name << '' '';\n    std::cout << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"e60dccef-ab0d-7735-bd0d-2e8922607737","type":"code","position":"a9","content":{"language":"text","code":"bo cy al","filename":"Output"},"revision":1},{"id":"0f654d41-085a-7253-b490-4f4a99b7e3de","type":"callout","position":"aA","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For anything with meaning, prefer a small named "},{"type":"text","text":"struct","marks":[{"type":"code"}]},{"type":"text","text":" over "},{"type":"text","text":"pair","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"tuple","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"result.quotient","marks":[{"type":"code"}]},{"type":"text","text":" reads better than "},{"type":"text","text":"std::get<0>(result)","marks":[{"type":"code"}]},{"type":"text","text":". Tuples shine in generic code and quick multi-value returns."}]}]}},"revision":1},{"id":"b45ed1d3-5f0a-7e90-9dfb-9d82e9f0ca9b","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do pairs and tuples compare?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lexicographically: compare the first elements; only if they''re equal compare the second, and so on. This is why sorting a "},{"type":"text","text":"vector<pair<int,int>>","marks":[{"type":"code"}]},{"type":"text","text":" sorts by "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" then "},{"type":"text","text":"second","marks":[{"type":"code"}]},{"type":"text","text":", and why "},{"type":"text","text":"std::tie(a.x, a.y) < std::tie(b.x, b.y)","marks":[{"type":"code"}]},{"type":"text","text":" is the idiomatic multi-field comparison."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
