SELECT '33de68c4-ad66-7957-a78d-d2588a47d3e8', 'b6ed2068-cc4d-7dfa-b2e8-a47b475b947a', 'pair & tuple', 'pair & tuple', 'std::pair<A, B> holds two values; std::tuple<Ts...> holds any number. Both compare lexicographically, which makes them handy as keys and sort criteria.
std::pair
#include <algorithm>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

int main() {
    std::pair<std::string, int> p{"ada", 36};
    auto q = std::make_pair(std::string("bob"), 25);
    std::cout << p.first << '' '' << p.second << '' '' << (p < q) << ''\n'';

    std::vector<std::pair<int, char>> v{{2, ''b''}, {1, ''z''}, {2, ''a''}};
    std::sort(v.begin(), v.end());                  // by first, then by second
    for (const auto& [n, c] : v) std::cout << n << c << '' '';
    std::cout << ''\n'';
}
