SELECT 'b2774b6d-a377-79b4-af9c-dddcd27195a7', 'e497bbac-b27d-7e7f-981b-2f56ec949f40', 1, 'PUBLISHED', 'Pass by Value, Reference & Pointer', '[{"id":"22fd8728-d58c-7e35-95b6-101e04009a1b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How a parameter is declared decides whether the function gets a copy, an alias to the caller''s object, or its address."}]}]}},"revision":1},{"id":"722bca37-5d09-7f47-aae4-d8b82ed76a60","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The three ways"}]},"revision":1},{"id":"ef31c21b-53fe-790c-8792-4d0a31573ea0","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n\nvoid byValue(int x)      { x = 100; std::cout << \"inside \" << x << ''\\n''; }  // a copy\nvoid byReference(int& x) { x = 200; }        // x IS the caller''s variable\nvoid byPointer(int* x)   { if (x) *x = 300; } // modifies through the address (may be null)\n\nint main() {\n    int a = 1;\n    byValue(a);      std::cout << a << ''\\n'';\n    byReference(a);  std::cout << a << ''\\n'';\n    byPointer(&a);   std::cout << a << ''\\n'';\n    byPointer(nullptr);                       // allowed: pointers can express “no object”\n}","filename":"C++"},"revision":1},{"id":"85440cf0-7fb6-7b6a-8148-9a1ad5355bec","type":"code","position":"a3","content":{"language":"text","code":"inside 100\n1\n200\n300","filename":"Output"},"revision":1},{"id":"f1b63307-f79e-74dd-aec6-0b120ad5b8d5","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Style"}],[{"type":"text","text":"Copies?"}],[{"type":"text","text":"Can modify caller?"}],[{"type":"text","text":"Can be null?"}],[{"type":"text","text":"Use for"}]],[[{"type":"text","text":"T x","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"—"}],[{"type":"text","text":"Cheap types ("},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":", small structs, iterators), or when you need a copy anyway"}]],[[{"type":"text","text":"const T& x","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Read-only","marks":[{"type":"bold"}]},{"type":"text","text":" access to anything non-trivial ("},{"type":"text","text":"std::string","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::vector","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"T& x","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Out/in-out parameters"}]],[[{"type":"text","text":"T* x","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes","marks":[{"type":"bold"}]}],[{"type":"text","text":"Optional objects, C APIs"}]],[[{"type":"text","text":"T&& x","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes (steals)"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Taking ownership of temporaries (move semantics)"}]]]},"revision":1},{"id":"5008be7b-cef7-7a87-9bda-5ebf0faf18b5","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Why "},{"type":"text","text":"const&","marks":[{"type":"code"}]},{"type":"text","text":" for big objects"}]},"revision":1},{"id":"84a6b972-e836-7a2f-aa39-e4d28c2e75f4","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n\nstruct Tracker {\n    std::string name;\n    Tracker(std::string n) : name(std::move(n)) {}\n    Tracker(const Tracker& other) : name(other.name) { std::cout << \"copy!\\n\"; }\n};\n\nvoid slow(Tracker t)        { std::cout << \"slow \" << t.name << ''\\n''; }\nvoid fast(const Tracker& t) { std::cout << \"fast \" << t.name << ''\\n''; }\n\nint main() {\n    Tracker big(\"report\");\n    slow(big);      // copies the whole object\n    fast(big);      // no copy\n}","filename":"C++"},"revision":1},{"id":"e80a4e36-0e8c-7e3f-a98f-da0c6433d181","type":"code","position":"a7","content":{"language":"text","code":"copy!\nslow report\nfast report","filename":"Output"},"revision":1},{"id":"c7960889-d9a0-760f-b439-1fa043e4ed63","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Swapping — the classic example"}]},"revision":1},{"id":"f365d685-ace8-73a1-96e3-1f47cbc71ff3","type":"code","position":"a9","content":{"language":"cpp","code":"#include <iostream>\nvoid swapRef(int& a, int& b) { int t = a; a = b; b = t; }\nvoid swapPtr(int* a, int* b) { int t = *a; *a = *b; *b = t; }\nint main() {\n    int x = 1, y = 2;\n    swapRef(x, y);\n    std::cout << x << y << ''\\n'';\n    swapPtr(&x, &y);\n    std::cout << x << y << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"3c9977c1-f50a-7f81-9d93-57ec5c3deab7","type":"code","position":"aA","content":{"language":"text","code":"21\n12","filename":"Output"},"revision":1},{"id":"e596daf8-0f2c-78d9-9c49-07585a7c43ff","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Passing arrays and containers"}]},"revision":1},{"id":"d1e22174-2a80-72b4-923e-7827f4348826","type":"code","position":"aC","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\n\nint sumArray(const int* arr, std::size_t n) {   // a C array decays to a pointer: size is lost\n    int s = 0;\n    for (std::size_t i = 0; i < n; ++i) s += arr[i];\n    return s;\n}\nvoid doubleAll(std::vector<int>& v) { for (int& x : v) x *= 2; }\n\nint main() {\n    int raw[] = {1, 2, 3};\n    std::cout << sumArray(raw, 3) << ''\\n'';\n    std::vector<int> v{1, 2, 3};\n    doubleAll(v);\n    std::cout << v[0] << v[1] << v[2] << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"569f965f-f46e-7423-a1f3-17148a0a05b1","type":"code","position":"aD","content":{"language":"text","code":"6\n246","filename":"Output"},"revision":1},{"id":"a337d4c0-fbec-72d7-a6a0-3624392cc926","type":"callout","position":"aE","content":{"variant":"note","title":"Guideline","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rule of thumb: "},{"type":"text","text":"in","marks":[{"type":"bold"}]},{"type":"text","text":" params — by value if cheap to copy (≤ ~2 words), else "},{"type":"text","text":"const T&","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"Out/in-out","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"T&","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"Optional","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"T*","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"std::optional","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"Sink","marks":[{"type":"bold"}]},{"type":"text","text":" params you''ll store — by value, then "},{"type":"text","text":"std::move","marks":[{"type":"code"}]},{"type":"text","text":" into place."}]}]}},"revision":1},{"id":"2333d248-24ce-7c4c-ae22-4ef36a35674d","type":"callout","position":"aF","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A non-const reference can''t bind to a temporary: "},{"type":"text","text":"void f(std::string& s); f(\"hi\");","marks":[{"type":"code"}]},{"type":"text","text":" is an error. "},{"type":"text","text":"const std::string&","marks":[{"type":"code"}]},{"type":"text","text":" can — the temporary lives until the call returns."}]}]}},"revision":1},{"id":"e57adfa1-d9a8-7754-835d-6396abb046e4","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is Java/Python-style pass by reference the same as C++ references?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. Java and Python pass a "},{"type":"text","text":"reference value","marks":[{"type":"italic"}]},{"type":"text","text":" by value: reassigning the parameter doesn''t affect the caller. A C++ "},{"type":"text","text":"T&","marks":[{"type":"code"}]},{"type":"text","text":" parameter is a true alias: "},{"type":"text","text":"x = other;","marks":[{"type":"code"}]},{"type":"text","text":" inside the function assigns to the caller''s object."}]}]}},"revision":1},{"id":"ac793c9e-3ce2-73f3-af7b-c680a649a5b5","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you pass by pointer instead of reference?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When “no object” is a valid input ("},{"type":"text","text":"nullptr","marks":[{"type":"code"}]},{"type":"text","text":"), when interoperating with C APIs, or when you want the call site to show that the argument may be modified ("},{"type":"text","text":"update(&config)","marks":[{"type":"code"}]},{"type":"text","text":"). Otherwise references are safer: they can''t be null or re-seated."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
