SELECT '284083c3-f06d-7e1b-a655-03585de86229', '1cf24e65-8526-7d55-861f-ab963d7c31c0', 1, 'PUBLISHED', 'Preprocessor & Macros', '[{"id":"baa84734-9f2f-79e1-92e7-492c05c02e65","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before compilation, the preprocessor rewrites the source text: it pastes headers, expands macros and keeps or drops code with "},{"type":"text","text":"#if","marks":[{"type":"code"}]},{"type":"text","text":". It knows nothing about types or scopes."}]}]}},"revision":1},{"id":"87fe51b7-c422-7955-8597-4a1cccd636b1","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Directives"}]},"revision":1},{"id":"51d254aa-88a3-7668-9a5e-221cfa8f1d55","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Directive"}],[{"type":"text","text":"Does"}]],[[{"type":"text","text":"#include <x>","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#include \"x\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Paste a header (system paths / project paths first)"}]],[[{"type":"text","text":"#define NAME value","marks":[{"type":"code"}]}],[{"type":"text","text":"Object-like macro: textual replacement"}]],[[{"type":"text","text":"#define F(a, b) (…)","marks":[{"type":"code"}]}],[{"type":"text","text":"Function-like macro"}]],[[{"type":"text","text":"#undef NAME","marks":[{"type":"code"}]}],[{"type":"text","text":"Remove a macro"}]],[[{"type":"text","text":"#if","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#ifdef","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#ifndef","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#elif","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#else","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"#endif","marks":[{"type":"code"}]}],[{"type":"text","text":"Conditional compilation"}]],[[{"type":"text","text":"#pragma once","marks":[{"type":"code"}]}],[{"type":"text","text":"Include guard (non-standard but universal)"}]],[[{"type":"text","text":"#error msg","marks":[{"type":"code"}]}],[{"type":"text","text":"Stop compilation with a message"}]]]},"revision":1},{"id":"4708f5df-aa17-7572-a466-a177b2248b65","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Macros and their traps"}]},"revision":1},{"id":"882a775b-3b32-754b-8df3-8862a8916303","type":"code","position":"a4","content":{"language":"cpp","code":"#include <iostream>\n\n#define SQUARE_BAD(x) x * x\n#define SQUARE(x) ((x) * (x))\n#define MAX(a, b) ((a) > (b) ? (a) : (b))\n\nconstexpr int square(int x) { return x * x; }       // the C++ way: typed, scoped, evaluated once\n\nint main() {\n    std::cout << SQUARE_BAD(2 + 3) << '' '' << SQUARE(2 + 3) << '' '' << square(2 + 3) << ''\\n'';   // 2 + 3 * 2 + 3\n    int i = 5;\n    int m = MAX(i++, 0);                             // i++ is evaluated TWICE\n    std::cout << m << '' '' << i << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"01ed1209-1134-7f92-b4ca-670fecebab1b","type":"code","position":"a5","content":{"language":"text","code":"11 25 25\n6 7","filename":"Output"},"revision":1},{"id":"97240458-f5e3-73b6-8f50-caaa15256149","type":"callout","position":"a6","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Macros ignore scope and types, evaluate arguments multiple times and are invisible to the debugger. Use "},{"type":"text","text":"constexpr","marks":[{"type":"code"}]},{"type":"text","text":" variables, "},{"type":"text","text":"inline","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"constexpr","marks":[{"type":"code"}]},{"type":"text","text":" functions, templates and "},{"type":"text","text":"enum class","marks":[{"type":"code"}]},{"type":"text","text":" instead."}]}]}},"revision":1},{"id":"dc9442cb-2d59-7fac-8414-912bf3021026","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Where macros are still useful"}]},"revision":1},{"id":"cc516a0d-a03a-79b1-9d3d-cb390f837df8","type":"code","position":"a8","content":{"language":"cpp","code":"#include <iostream>\n\n#define STRINGIFY(x) #x                         // # turns an argument into a string literal\n#define CONCAT(a, b) a##b                       // ## pastes tokens\n#define LOG_VAR(v) std::cout << #v << \" = \" << (v) << ''\\n''\n\n#ifndef NDEBUG\n#define DEBUG_ONLY(code) code\n#else\n#define DEBUG_ONLY(code)\n#endif\n\nint main() {\n    int CONCAT(user, Count) = 3;                 // declares userCount\n    LOG_VAR(userCount * 2);\n    std::cout << STRINGIFY(hello world) << ''\\n'';\n    std::cout << __LINE__ << '' '' << (__cplusplus >= 202002L) << ''\\n'';   // predefined macros\n    DEBUG_ONLY(std::cout << \"debug build\\n\";)\n}","filename":"C++"},"revision":1},{"id":"65b49e08-a151-7c68-b776-77afdd889269","type":"code","position":"a9","content":{"language":"text","code":"userCount * 2 = 6\nhello world\n17 1\ndebug build","filename":"Output"},"revision":1},{"id":"f9b9689a-5c23-7c11-bf3d-d96e605cfff5","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Predefined macro"}],[{"type":"text","text":"Value"}]],[[{"type":"text","text":"__FILE__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__LINE__","marks":[{"type":"code"}]}],[{"type":"text","text":"Current file name and line (C++20: prefer "},{"type":"text","text":"std::source_location","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"__cplusplus","marks":[{"type":"code"}]}],[{"type":"text","text":"Standard version, e.g. "},{"type":"text","text":"202002L","marks":[{"type":"code"}]},{"type":"text","text":" for C++20"}]],[[{"type":"text","text":"NDEBUG","marks":[{"type":"code"}]}],[{"type":"text","text":"Defined in release builds ("},{"type":"text","text":"-DNDEBUG","marks":[{"type":"code"}]},{"type":"text","text":") — disables "},{"type":"text","text":"assert","marks":[{"type":"code"}]}]],[[{"type":"text","text":"_WIN32","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__linux__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__APPLE__","marks":[{"type":"code"}]}],[{"type":"text","text":"Target platform"}]],[[{"type":"text","text":"__GNUC__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"__clang__","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"_MSC_VER","marks":[{"type":"code"}]}],[{"type":"text","text":"Compiler"}]]]},"revision":1},{"id":"e92d505c-3f0a-7517-a2a2-203fd94456df","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"assert","marks":[{"type":"code"}]}]},"revision":1},{"id":"52c53a85-864d-70ce-940e-c1a6722cf843","type":"code","position":"aC","content":{"language":"cpp","code":"#include <cassert>\n#include <iostream>\nint divide(int a, int b) {\n    assert(b != 0 && \"divisor must be non-zero\");   // checked only when NDEBUG is not defined\n    return a / b;\n}\nint main() { std::cout << divide(10, 2) << ''\\n''; }","filename":"C++"},"revision":1},{"id":"725a4c93-aff5-75a1-a4c7-b5bd40d22a78","type":"code","position":"aD","content":{"language":"text","code":"5","filename":"Output"},"revision":1},{"id":"d6424295-5358-74e1-8c01-dbf3026eacf2","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why prefer constexpr over #define for constants?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"constexpr","marks":[{"type":"code"}]},{"type":"text","text":" constant has a type (so the compiler checks its uses), respects namespaces and scopes, shows up in the debugger, and can''t be silently redefined elsewhere. A "},{"type":"text","text":"#define","marks":[{"type":"code"}]},{"type":"text","text":" is blind text replacement that can clash with any identifier of the same name in any header included later."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
