SELECT 'd380257e-8083-7c26-bac6-04088faf2d2d', '2f941845-4021-7739-a6ae-272e017906e7', 1, 'PUBLISHED', 'Random Numbers with <random>', '[{"id":"92bbf646-8d82-7436-846c-51025c80598e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern C++ separates "},{"type":"text","text":"engines","marks":[{"type":"italic"}]},{"type":"text","text":" (sources of random bits) from "},{"type":"text","text":"distributions","marks":[{"type":"italic"}]},{"type":"text","text":" (shape the bits into the numbers you want). Forget "},{"type":"text","text":"rand() % n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d06cf752-7c70-79b1-83f2-88e98116ed43","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Engine + distribution"}]},"revision":1},{"id":"9f08a865-e3e8-7fcd-823a-aa00df784b65","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <random>\n\nint main() {\n    std::mt19937 rng(12345);                             // Mersenne Twister, fixed seed → reproducible\n    std::uniform_int_distribution<int> dice(1, 6);       // inclusive range\n    std::uniform_real_distribution<double> unit(0.0, 1.0);\n\n    for (int i = 0; i < 5; ++i) std::cout << dice(rng) << '' '';\n    std::cout << ''\\n'';\n\n    int counts[7] = {};\n    for (int i = 0; i < 60000; ++i) ++counts[dice(rng)];\n    bool roughlyUniform = true;\n    for (int f = 1; f <= 6; ++f) roughlyUniform &= counts[f] > 9500 && counts[f] < 10500;\n    std::cout << \"uniform: \" << roughlyUniform << ''\\n'';\n\n    double u = unit(rng);\n    std::cout << (u >= 0.0 && u < 1.0) << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"e88cb30a-72dc-77fe-877f-bf28a88a1c18","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exact numbers from a seeded engine are reproducible for a given standard library, but "},{"type":"text","text":"distributions","marks":[{"type":"italic"}]},{"type":"text","text":" are implementation-defined, so libc++ and libstdc++ may print different dice rolls for the same seed."}]}]}},"revision":1},{"id":"c90a5fa7-0c71-77e7-8a84-ab6596c5909f","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Seeding"}]},"revision":1},{"id":"42bf01a0-9614-77da-b9c6-0444032e1c41","type":"code","position":"a5","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <random>\n#include <vector>\n\nint main() {\n    std::random_device rd;                               // non-deterministic seed source (OS entropy)\n    std::mt19937 rng(rd());                              // different sequence every run\n    std::vector<int> deck{1, 2, 3, 4, 5, 6, 7, 8};\n    std::shuffle(deck.begin(), deck.end(), rng);\n    std::sort(deck.begin(), deck.end());\n    std::cout << deck.front() << deck.back() << ''\\n'';    // deterministic after sorting\n}","filename":"C++"},"revision":1},{"id":"19b6b480-60ce-7df1-a4ab-798332d29fed","type":"code","position":"a6","content":{"language":"text","code":"18","filename":"Output"},"revision":1},{"id":"c1beb87a-441a-796c-92bc-4bbed3bb9d00","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Distribution"}],[{"type":"text","text":"Produces"}]],[[{"type":"text","text":"uniform_int_distribution<int>(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"Integers in [a, b]"}]],[[{"type":"text","text":"uniform_real_distribution<double>(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"Reals in [a, b)"}]],[[{"type":"text","text":"normal_distribution<double>(mean, sd)","marks":[{"type":"code"}]}],[{"type":"text","text":"Gaussian"}]],[[{"type":"text","text":"bernoulli_distribution(p)","marks":[{"type":"code"}]}],[{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" with probability p"}]],[[{"type":"text","text":"discrete_distribution<int>{w...}","marks":[{"type":"code"}]}],[{"type":"text","text":"Index i with probability ∝ wᵢ"}]],[[{"type":"text","text":"poisson_distribution","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"exponential_distribution","marks":[{"type":"code"}]}],[{"type":"text","text":"Counts, waiting times"}]]]},"revision":1},{"id":"8b128191-1d94-7cc6-878e-5c27dc860aec","type":"callout","position":"a8","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Create "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" engine (seeded once) and reuse it; pass it by reference to functions that need randomness."}]}]}},"revision":1},{"id":"3ae05315-71d9-7b11-b303-28d90987d499","type":"callout","position":"a9","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-creating "},{"type":"text","text":"std::mt19937 rng(std::random_device{}())","marks":[{"type":"code"}]},{"type":"text","text":" on every call, or "},{"type":"text","text":"rand() % 6","marks":[{"type":"code"}]},{"type":"text","text":" (biased, low quality, global state)."}]}]}},"revision":1},{"id":"3c5b4d7e-a8f7-7b3e-aa1c-c7e2b88abb9a","type":"callout","position":"aA","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::mt19937","marks":[{"type":"code"}]},{"type":"text","text":" is fast and statistically good but "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" cryptographically secure — never use it for passwords, tokens or keys."}]}]}},"revision":1},{"id":"99e8134b-9392-7cc3-9b29-19dd405fc577","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s wrong with rand() % n?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"rand()","marks":[{"type":"code"}]},{"type":"text","text":" has implementation-defined (often poor) quality and a range that may be as small as 32767; "},{"type":"text","text":"% n","marks":[{"type":"code"}]},{"type":"text","text":" introduces "},{"type":"text","text":"modulo bias","marks":[{"type":"italic"}]},{"type":"text","text":" when "},{"type":"text","text":"RAND_MAX + 1","marks":[{"type":"code"}]},{"type":"text","text":" isn''t a multiple of "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":"; and it uses hidden global state that''s not thread-safe. "},{"type":"text","text":"<random>","marks":[{"type":"code"}]},{"type":"text","text":" fixes all three."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
