SELECT 'c58f2475-cf16-7e5b-9445-eacad3aa82d5', '277d117b-a86f-7ca0-87b8-1d92ae05000a', 1, 'PUBLISHED', 'Recursion', '[{"id":"165ebcc7-db18-7de2-804a-f7fccd625a75","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A recursive function calls itself on a smaller input until it reaches a base case. Every call gets its own stack frame."}]}]}},"revision":1},{"id":"5076780f-5c79-72cb-878a-79a88b58b851","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Anatomy"}]},"revision":1},{"id":"79e170ea-189c-7dca-8949-410711e85f6a","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n\nlong long factorial(int n) {\n    if (n <= 1) return 1;              // base case\n    return n * factorial(n - 1);       // recursive case: smaller problem\n}\n\nint power(int b, int e) {              // fast exponentiation: O(log e)\n    if (e == 0) return 1;\n    int half = power(b, e / 2);\n    return e % 2 ? half * half * b : half * half;\n}\n\nbool isPalindrome(const std::string& s, int l, int r) {\n    if (l >= r) return true;\n    return s[l] == s[r] && isPalindrome(s, l + 1, r - 1);\n}\n\nint main() {\n    std::cout << factorial(20) << ''\\n'';\n    std::cout << power(3, 13) << ''\\n'';\n    std::cout << isPalindrome(\"racecar\", 0, 6) << isPalindrome(\"rocket\", 0, 5) << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"33e6b8f3-8739-7c5f-9279-2725fcd608c2","type":"code","position":"a3","content":{"language":"text","code":"2432902008176640000\n1594323\n10","filename":"Output"},"revision":1},{"id":"d1e86274-dbff-7940-a216-5e5d17d2967c","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Backtracking: generate all subsets"}]},"revision":1},{"id":"cd48f29f-0a11-7c5b-97e5-7fc2953359df","type":"code","position":"a5","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\n\nvoid subsets(const std::vector<int>& nums, std::size_t i, std::vector<int>& cur) {\n    if (i == nums.size()) {\n        std::cout << ''{'';\n        for (int x : cur) std::cout << x;\n        std::cout << \"} \";\n        return;\n    }\n    subsets(nums, i + 1, cur);          // exclude nums[i]\n    cur.push_back(nums[i]);             // include nums[i]\n    subsets(nums, i + 1, cur);\n    cur.pop_back();                     // undo (backtrack)\n}\n\nint main() {\n    std::vector<int> cur;\n    subsets({1, 2, 3}, 0, cur);\n    std::cout << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"546e6f6a-ee55-775b-b51e-5484e52e052e","type":"code","position":"a6","content":{"language":"text","code":"{} {3} {2} {23} {1} {13} {12} {123}","filename":"Output"},"revision":1},{"id":"d4bfa207-b984-791d-b3e6-a79146df8bb4","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Memoisation"}]},"revision":1},{"id":"56212092-f967-7c46-ac75-9f94e9a37d39","type":"code","position":"a8","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\n\nlong long fib(int n, std::vector<long long>& memo) {\n    if (n < 2) return n;\n    if (memo[n] != -1) return memo[n];          // already computed\n    return memo[n] = fib(n - 1, memo) + fib(n - 2, memo);\n}\n\nint main() {\n    std::vector<long long> memo(91, -1);\n    std::cout << fib(90, memo) << ''\\n'';          // instant; naive recursion would take ages\n}","filename":"C++"},"revision":1},{"id":"b7a4c9ee-2175-7e64-9cc5-5bfc7c666654","type":"code","position":"a9","content":{"language":"text","code":"2880067194370816120","filename":"Output"},"revision":1},{"id":"217724ae-2e62-7cb9-91fa-116e1652b53e","type":"callout","position":"aA","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Deep recursion overflows the stack (default ~1–8 MB): a recursive DFS on a 10⁶-node path graph will crash. Convert to an explicit stack/loop when depth can be large."}]}]}},"revision":1},{"id":"7880657c-bbde-768d-86af-9616901afe0c","type":"table","position":"aB","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Recursion"}],[{"type":"text","text":"Iteration"}]],[[{"type":"text","text":"Readability"}],[{"type":"text","text":"Natural for trees, divide & conquer, backtracking"}],[{"type":"text","text":"Natural for linear scans"}]],[[{"type":"text","text":"Memory"}],[{"type":"text","text":"O(depth) stack frames"}],[{"type":"text","text":"O(1) extra (or an explicit stack)"}]],[[{"type":"text","text":"Risk"}],[{"type":"text","text":"Stack overflow"}],[{"type":"text","text":"—"}]]]},"revision":1},{"id":"5eec462e-244b-7bc0-984c-3b52c922df94","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does C++ guarantee tail-call optimisation?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. Compilers often turn tail calls into jumps at "},{"type":"text","text":"-O2","marks":[{"type":"code"}]},{"type":"text","text":", but the standard doesn''t require it and destructors of locals can prevent it. Don''t rely on it for unbounded recursion depth."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
