SELECT '04880be2-7373-75d6-a2af-6b0c3c988f6b', '84ff5e44-4f5a-7315-b2ea-011d23c7d5b4', 1, 'PUBLISHED', 'References in Depth', '[{"id":"27cf2197-f011-750d-9451-73f946cf1e23","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A reference is another name for an existing object. C++ has lvalue references ("},{"type":"text","text":"T&","marks":[{"type":"code"}]},{"type":"text","text":"), const references ("},{"type":"text","text":"const T&","marks":[{"type":"code"}]},{"type":"text","text":") and rvalue references ("},{"type":"text","text":"T&&","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"f8c68ceb-3043-7122-bde5-7c235d7b1821","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"lvalue references"}]},"revision":1},{"id":"5af70a96-88df-73b5-a211-a17bf6f95fdb","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nint main() {\n    int x = 1;\n    int& r = x;          // r is x\n    r = 5;\n    std::cout << x << '' '' << (&r == &x) << ''\\n'';\n\n    int y = 99;\n    r = y;               // NOT re-binding: assigns 99 to x\n    std::cout << x << ''\\n'';\n\n    std::vector<int> v{1, 2, 3};\n    int& first = v[0];   // reference to an element\n    first = 100;\n    std::cout << v[0] << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"413a2ba8-e728-7a2b-8e1e-bd67333d9e9d","type":"code","position":"a3","content":{"language":"text","code":"5 1\n99\n100","filename":"Output"},"revision":1},{"id":"4b2b745d-12e2-7550-bfcd-b3bc452a0aa0","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Must be initialised: "},{"type":"text","text":"int& r;","marks":[{"type":"code"}]},{"type":"text","text":" is an error."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Can''t be null and can''t be re-seated to another object."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No “reference to reference”, no arrays of references, no pointers to references."}]}]}]}]}},"revision":1},{"id":"09f04514-f194-7426-a76f-9a38241e27ef","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"const references bind to temporaries"}]},"revision":1},{"id":"7a9d6399-2d61-7c02-af37-9c0a01ba563d","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\nstd::string makeName() { return \"temp\"; }\nint main() {\n    const std::string& ref = makeName();   // lifetime of the temporary is extended to ref''s scope\n    const int& n = 42;                     // binds to a materialised temporary\n    std::cout << ref << '' '' << n << ''\\n'';\n    // std::string& bad = makeName();      // error: non-const lvalue ref can''t bind to an rvalue\n}","filename":"C++"},"revision":1},{"id":"7a745d23-8356-71a5-81a1-225214d418ab","type":"code","position":"a7","content":{"language":"text","code":"temp 42","filename":"Output"},"revision":1},{"id":"7bc55206-97cc-7dbd-8752-96fd8d57a548","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"lvalues and rvalues"}]},"revision":1},{"id":"30bde696-b184-7227-950c-806c7c003203","type":"callout","position":"a9","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"lvalue","marks":[{"type":"bold"}]},{"type":"text","text":" — an expression that names an object with an identity — you can take its address: variables, "},{"type":"text","text":"*p","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"v[i]","marks":[{"type":"code"}]},{"type":"text","text":", a function returning "},{"type":"text","text":"T&","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"679a7c65-721c-7fc3-80ea-310c3a1eda73","type":"callout","position":"aA","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"rvalue","marks":[{"type":"bold"}]},{"type":"text","text":" — a temporary or literal with no persistent identity: "},{"type":"text","text":"42","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"a + b","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"makeName()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::move(x)","marks":[{"type":"code"}]},{"type":"text","text":". Rvalue references "},{"type":"text","text":"T&&","marks":[{"type":"code"}]},{"type":"text","text":" bind only to these — the basis of move semantics."}]}]}},"revision":1},{"id":"096aca79-3106-74fa-bfb0-c50778687a0b","type":"code","position":"aB","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <utility>\n\nvoid take(const std::string&) { std::cout << \"lvalue (or const)\\n\"; }\nvoid take(std::string&&)      { std::cout << \"rvalue — can steal its guts\\n\"; }\n\nint main() {\n    std::string s = \"hi\";\n    take(s);                     // lvalue\n    take(std::string(\"tmp\"));    // prvalue (temporary)\n    take(s + \"!\");               // result of an expression is a temporary\n    take(std::move(s));          // std::move casts s to an rvalue (xvalue)\n}","filename":"C++"},"revision":1},{"id":"452a5eaf-69b7-7b91-b3b7-964b8e579ebc","type":"code","position":"aC","content":{"language":"text","code":"lvalue (or const)\nrvalue — can steal its guts\nrvalue — can steal its guts\nrvalue — can steal its guts","filename":"Output"},"revision":1},{"id":"43806faf-9189-74f3-b154-287306e14031","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Reference"}],[{"type":"text","text":"Binds to lvalue"}],[{"type":"text","text":"Binds to rvalue"}],[{"type":"text","text":"Typical use"}]],[[{"type":"text","text":"T&","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Modify caller''s object"}]],[[{"type":"text","text":"const T&","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Read-only parameter, no copy"}]],[[{"type":"text","text":"T&&","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Move constructors, sink parameters"}]],[[{"type":"text","text":"auto&&","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"T&&","marks":[{"type":"code"}]},{"type":"text","text":" in a template"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Forwarding (“universal”) reference"}]]]},"revision":1},{"id":"095d4877-cff1-759a-97ef-4b9d4220a16b","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Dangling references"}]},"revision":1},{"id":"03d52485-108f-7df7-8e9a-379ca55c4258","type":"code","position":"aF","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nint main() {\n    std::vector<int> v{1, 2, 3};\n    int& ref = v[0];\n    v.push_back(4);             // may reallocate: ref now refers to freed memory\n    std::cout << ref << ''\\n'';   // AddressSanitizer: heap-use-after-free\n}","filename":"C++ — reference invalidated by reallocation"},"revision":1},{"id":"e4cf6957-8507-7f76-a22e-69050bf6a4e3","type":"callout","position":"aG","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"References don''t keep objects alive (except the temporary-lifetime-extension case above). Returning a reference to a local, or holding one into a "},{"type":"text","text":"vector","marks":[{"type":"code"}]},{"type":"text","text":" that grows, is undefined behaviour."}]}]}},"revision":1},{"id":"9c4d8ebc-c1b0-7cc8-90e7-153db131d274","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can a reference be null?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Not in a valid program. You can "},{"type":"text","text":"create","marks":[{"type":"italic"}]},{"type":"text","text":" one by dereferencing a null pointer ("},{"type":"text","text":"int& r = *p;","marks":[{"type":"code"}]},{"type":"text","text":"), but that dereference is already undefined behaviour. Code may assume references always refer to an object."}]}]}},"revision":1},{"id":"3e0a7efa-c72c-7ea7-b6bb-d039297c0eac","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does it mean that std::move doesn''t move anything?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::move(x)","marks":[{"type":"code"}]},{"type":"text","text":" is just a cast to "},{"type":"text","text":"T&&","marks":[{"type":"code"}]},{"type":"text","text":" — it marks "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" as an rvalue so that overload resolution picks the move constructor/assignment. The actual moving happens in that constructor. After being moved from, "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" is valid but in an unspecified state."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
