SELECT '4818fc26-2c0d-700b-bce3-6c502996246c', 'c893e061-e7f1-7ff5-b72b-1ab33d954085', 1, 'PUBLISHED', 'STL Overview', '[{"id":"d8384fe8-8cf5-7164-beae-2d06c7f34f38","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Standard Template Library is three ideas that plug together: "},{"type":"text","text":"containers","marks":[{"type":"bold"}]},{"type":"text","text":" hold data, "},{"type":"text","text":"iterators","marks":[{"type":"bold"}]},{"type":"text","text":" walk it, "},{"type":"text","text":"algorithms","marks":[{"type":"bold"}]},{"type":"text","text":" process it — all generic, all zero-overhead."}]},{"type":"paragraph","content":[{"type":"text","text":"Container → Iterators "},{"type":"text","text":"begin()","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"end()","marks":[{"type":"code"}]},{"type":"text","text":" → Algorithm"}]}]}},"revision":1},{"id":"cdb4d0e3-2061-77e5-b753-b75ce390392d","type":"code","position":"a1","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <list>\n#include <vector>\n\nint main() {\n    std::vector<int> v{4, 1, 3};\n    std::list<int> l{4, 1, 3};\n    // The same algorithm works on any container through iterators:\n    std::cout << *std::max_element(v.begin(), v.end()) << '' ''\n              << *std::max_element(l.begin(), l.end()) << ''\\n'';\n    std::cout << std::count(v.begin(), v.end(), 3) << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"98acde93-3d82-766b-aa5e-d63650a1144a","type":"code","position":"a2","content":{"language":"text","code":"4 4\n1","filename":"Output"},"revision":1},{"id":"43cdfe7f-4d8a-724c-89f1-fab4ed9efd40","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Container families"}]},"revision":1},{"id":"a3216720-6025-7336-a3e2-37ae7c7f0525","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text"