SELECT 'c5d584a3-9fa6-7542-83e8-0d2dd376128d', '7456fbd3-7327-7ffd-9f06-47719126d09d', 1, 'PUBLISHED', 'Threads: std::thread & std::jthread', '[{"id":"4314208b-bea6-7d18-8cb7-4bd56eed91f7","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"std::thread","marks":[{"type":"code"}]},{"type":"text","text":" runs a callable concurrently with the rest of the program. You must "},{"type":"text","text":"join()","marks":[{"type":"code"}]},{"type":"text","text":" (wait for) or "},{"type":"text","text":"detach()","marks":[{"type":"code"}]},{"type":"text","text":" it before it''s destroyed; C++20''s "},{"type":"text","text":"std::jthread","marks":[{"type":"code"}]},{"type":"text","text":" joins automatically."}]}]}},"revision":1},{"id":"a00a46ca-a5b3-74ea-8599-630ad209a38c","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Starting and joining"}]},"revision":1},{"id":"aa2910d9-2dfb-7dc5-9629-11234d4db98a","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <thread>\n#include <vector>\n\nvoid partialSum(const std::vector<int>& data, std::size_t from, std::size_t to, long long& out) {\n    long long s = 0;\n    for (std::size_t i = from; i < to; ++i) s += data[i];\n    out = s;                                          // each thread writes its own slot: no race\n}\n\nint main() {\n    std::vector<int> data(1''000''000, 1);\n    long long left = 0, right = 0;\n    std::size_t mid = data.size() / 2;\n\n    std::thread t1(partialSum, std::cref(data), 0, mid, std::ref(left));   // args are COPIED unless wrapped\n    std::thread t2([&] { partialSum(data, mid, data.size(), right); });    // or capture in a lambda\n    t1.join();                                        // wait for both to finish\n    t2.join();\n    std::cout << left + right << ''\\n'';\n    std::cout << (std::thread::hardware_concurrency() > 0) << ''\\n'';        // number of cores (hint)\n}","filename":"C++"},"revision":1},{"id":"d1abf885-186b-7c2e-89d4-fecc7124d434","type":"code","position":"a3","content":{"language":"text","code":"1000000\n1","filename":"Output"},"revision":1},{"id":"ede5c579-d121-722e-9611-b572494e6e63","type":"callout","position":"a4","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If a joinable "},{"type":"text","text":"std::thread","marks":[{"type":"code"}]},{"type":"text","text":" is destroyed (goes out of scope without "},{"type":"text","text":"join()","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"detach()","marks":[{"type":"code"}]},{"type":"text","text":"), the program calls "},{"type":"text","text":"std::terminate","marks":[{"type":"code"}]},{"type":"text","text":". An exception thrown between creating and joining causes exactly this — which is why "},{"type":"text","text":"std::jthread","marks":[{"type":"code"}]},{"type":"text","text":" exists."}]}]}},"revision":1},{"id":"a64d91a0-a142-7182-9da7-148e6375014e","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"std::jthread","marks":[{"type":"code"}]},{"type":"text","text":" (C++20)"}]},"revision":1},{"id":"f8a63c61-2656-76d8-8be0-1f1b84b48fa5","type":"code","position":"a6","content":{"language":"cpp","code":"#include <chrono>\n#include <iostream>\n#include <thread>\n\nint main() {\n    int ticks = 0;\n    {\n        std::jthread worker([&ticks](std::stop_token st) {   // receives a stop token\n            while (!st.stop_requested()) {\n                ++ticks;\n                std::this_thread::sleep_for(std::chrono::milliseconds(1));\n            }\n        });\n        std::this_thread::sleep_for(std::chrono::milliseconds(20));\n    }   // ~jthread: request_stop() then join() — automatic\n    std::cout << \"worker stopped after \" << (ticks > 0 ? \"some\" : \"no\") << \" ticks\\n\";\n}","filename":"C++"},"revision":1},{"id":"240c8e00-b92d-7855-96e0-03115779d41f","type":"code","position":"a7","content":{"language":"text","code":"worker stopped after some ticks","filename":"Output"},"revision":1},{"id":"c8b7ecb1-62ad-7788-be1e-73ecec13f141","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Thread basics"}]},"revision":1},{"id":"80b0d207-0b23-7f42-8d7d-d146adbf3f94","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"API"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"std::thread t(f, args...)","marks":[{"type":"code"}]}],[{"type":"text","text":"Start "},{"type":"text","text":"f(args...)","marks":[{"type":"code"}]},{"type":"text","text":" on a new thread (arguments copied/moved into it)"}]],[[{"type":"text","text":"t.join()","marks":[{"type":"code"}]}],[{"type":"text","text":"Block until "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":" finishes"}]],[[{"type":"text","text":"t.detach()","marks":[{"type":"code"}]}],[{"type":"text","text":"Let it run independently (you can no longer join it — rarely a good idea)"}]],[[{"type":"text","text":"t.joinable()","marks":[{"type":"code"}]}],[{"type":"text","text":"Still represents a running/unjoined thread?"}]],[[{"type":"text","text":"std::this_thread::sleep_for(d)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"yield()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"get_id()","marks":[{"type":"code"}]}],[{"type":"text","text":"Helpers for the current thread"}]],[[{"type":"text","text":"std::ref(x)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"std::cref(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Pass by reference into a thread"}]],[[{"type":"text","text":"thread_local int x;","marks":[{"type":"code"}]}],[{"type":"text","text":"One separate variable per thread"}]]]},"revision":1},{"id":"3e810276-869f-7ae0-88c7-9e6785097fe0","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Output order is not deterministic"}]},"revision":1},{"id":"93e9f0ea-9648-7adb-97b9-5e75e26ea0ea","type":"code","position":"aB","content":{"language":"cpp","code":"#include <iostream>\n#include <thread>\n#include <vector>\n\nint main() {\n    std::vector<std::jthread> workers;\n    for (int id = 0; id < 3; ++id)\n        workers.emplace_back([id] { std::cout << \"worker \" << id << \" running\\n\"; });\n}   // lines may appear in any order — or even interleaved mid-line","filename":"C++"},"revision":1},{"id":"9c5e2e66-3895-7b47-a357-a7582ca2af53","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s the difference between a process and a thread?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A process has its own address space; threads within a process share memory (globals, heap) but each has its own stack and registers. Threads are cheaper to create and communicate through shared memory — which is exactly why they need synchronisation."}]}]}},"revision":1},{"id":"17a74c04-ef27-7bf5-baab-4a5e86da7b81","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens if you forget to join a std::thread?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the "},{"type":"text","text":"std::thread","marks":[{"type":"code"}]},{"type":"text","text":" object is destroyed while still joinable, its destructor calls "},{"type":"text","text":"std::terminate()","marks":[{"type":"code"}]},{"type":"text","text":", aborting the program. Use "},{"type":"text","text":"std::jthread","marks":[{"type":"code"}]},{"type":"text","text":" (joins in its destructor) or an RAII guard."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
