SELECT '0cce523d-06c5-79c6-9387-615d1e39ea29', '5e9d4b7e-89c3-71eb-b557-30c0ecbe68d3', 1, 'PUBLISHED', 'Fundamental Types & Variables', '[{"id":"3e485c1f-e938-74de-a3df-89425c231d6c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every variable has a fixed type chosen at compile time. The type decides its size, its range and which operations are legal."}]}]}},"revision":1},{"id":"aac445df-60b1-7e17-856c-76997f6b0aa9","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Built-in types"}]},"revision":1},{"id":"4474d173-3fd9-7056-ae09-4791f302bc1d","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Typical size (64-bit)"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"bool","marks":[{"type":"code"}]}],[{"type":"text","text":"1 byte"}],[{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"false","marks":[{"type":"code"}]}]],[[{"type":"text","text":"char","marks":[{"type":"code"}]}],[{"type":"text","text":"1 byte"}],[{"type":"text","text":"A character "},{"type":"text","text":"and","marks":[{"type":"italic"}]},{"type":"text","text":" a small integer; signedness is platform-defined"}]],[[{"type":"text","text":"short","marks":[{"type":"code"}]}],[{"type":"text","text":"2 bytes"}],[{"type":"text","text":"At least 16 bits"}]],[[{"type":"text","text":"int","marks":[{"type":"code"}]}],[{"type":"text","text":"4 bytes"}],[{"type":"text","text":"At least 16 bits — in practice 32"}]],[[{"type":"text","text":"long","marks":[{"type":"code"}]}],[{"type":"text","text":"8 bytes (Linux/macOS), 4 (Windows)"}],[{"type":"text","text":"At least 32 bits"}]],[[{"type":"text","text":"long long","marks":[{"type":"code"}]}],[{"type":"text","text":"8 bytes"}],[{"type":"text","text":"At least 64 bits — use for big sums"}]],[[{"type":"text","tex