SELECT '7f7d905a-5a14-75d6-a21a-b41c61d5d847', 'c2b8e9fc-d21d-7076-ae92-4efaebddb8ee', 1, 'PUBLISHED', 'Variadic Templates & Fold Expressions', '[{"id":"e68d77aa-9eee-7b98-8c16-95cb2eb46ff4","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"parameter pack","marks":[{"type":"italic"}]},{"type":"text","text":" ("},{"type":"text","text":"typename... Args","marks":[{"type":"code"}]},{"type":"text","text":") lets a template accept any number of arguments of any types — how "},{"type":"text","text":"std::make_unique","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::tuple","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"emplace_back","marks":[{"type":"code"}]},{"type":"text","text":" work."}]}]}},"revision":1},{"id":"db007e20-e97c-7fb8-b797-8421b757400d","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Fold expressions (C++17)"}]},"revision":1},{"id":"4063fd25-2fc9-78e9-8088-e3a4e98eebc1","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <string>\n\ntemplate <typename... Ts>\nauto sum(Ts... xs) { return (xs + ... + 0); }            // binary right fold with init 0\n\ntemplate <typename... Ts>\nvoid printAll(const Ts&... xs) {\n    ((std::cout << xs << '' ''), ...);                     // unary fold over the comma operator\n    std::cout << \"(\" << sizeof...(xs) << \" args)\\n\";    // number of elements in the pack\n}\n\ntemplate <typename... Ts>\nbool allPositive(Ts... xs) { return ((xs > 0) && ...); }\n\nint main() {\n    std::cout << sum(1, 2, 3, 4) << '' '' << sum() << '' '' << sum(1.5, 2) << ''\\n'';\n    printAll(1, \"two\", 3.0, std::string(\"four\"), ''v'');\n    std::cout << allPositive(1, 5, 9) << allPositive(1, -5) << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"5938c8e3-5a8a-76e3-ba48-e8d4a90bb9ca","type":"code","position":"a3","content":{"language":"text","code":"10 0 3.5\n1 two 3 four v (5 args)\n10","filename":"Output"},"revision":1},{"id":"16aa1fec-d177-7ed0-bfcd-725f3fc95cb9","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Fold"}],[{"type":"text","text":"Expands to"}]],[[{"type":"text","text":"(pack op ...)","marks":[{"type":"code"}]}],[{"type":"text","text":"x1 op (x2 op (x3 op x4))","marks":[{"type":"code"}]}]],[[{"type":"text","text":"(... op pack)","marks":[{"type":"code"}]}],[{"type":"text","text":"((x1 op x2) op x3) op x4","marks":[{"type":"code"}]}]],[[{"type":"text","text":"(pack op ... op init)","marks":[{"type":"code"}]}],[{"type":"text","text":"x1 op (x2 op (… op init))","marks":[{"type":"code"}]},{"type":"text","text":" — works for an empty pack"}]]]},"revision":1},{"id":"6f50652b-aaa2-7a4e-b8f2-97aa0cc8ec42","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Recursive style (pre-C++17)"}]},"revision":1},{"id":"97e549b6-a270-7009-8569-3fb63ec4e2ef","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\n\nvoid logAll() { std::cout << ''\\n''; }                 // base case: empty pack\n\ntemplate <typename T, typename... Rest>\nvoid logAll(const T& first, const Rest&... rest) {  // peel off one argument per call\n    std::cout << ''['' << first << '']'';\n    logAll(rest...);                              // pack expansion\n}\n\nint main() { logAll(\"id\", 42, 3.5); }","filename":"C++"},"revision":1},{"id":"f068965e-4457-7355-8d11-561f2c78f49e","type":"code","position":"a7","content":{"language":"text","code":"[id][42][3.5]","filename":"Output"},"revision":1},{"id":"477106c4-433d-728d-b52c-45101009b518","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Forwarding a pack"}]},"revision":1},{"id":"edc5560a-b963-7ba7-ab68-756d75bdd12e","type":"code","position":"a9","content":{"language":"cpp","code":"#include <iostream>\n#include <memory>\n#include <string>\n#include <utility>\n\nstruct User {\n    std::string name;\n    int age;\n    User(std::string n, int a) : name(std::move(n)), age(a) {}\n};\n\ntemplate <typename T, typename... Args>\nstd::unique_ptr<T> create(Args&&... args) {                    // a hand-written make_unique\n    return std::unique_ptr<T>(new T(std::forward<Args>(args)...));\n}\n\nint main() {\n    auto u = create<User>(\"Ada\", 36);\n    std::cout << u->name << '' '' << u->age << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"ca058211-55cb-72bc-9966-e0e135bc813d","type":"code","position":"aA","content":{"language":"text","code":"Ada 36","filename":"Output"},"revision":1},{"id":"780beff4-c9e0-7e5e-8217-9c14dd1bb56f","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does sizeof...(args) return?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The number of elements in the parameter pack, as a compile-time constant. It doesn''t evaluate the arguments or measure their byte sizes."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
