SELECT '150f7df6-a2be-7b6d-a574-5c6daa787ea7', '5cfc0c50-a9bc-71b2-a49e-6dc80f3f47c4', 1, 'PUBLISHED', 'std::vector', '[{"id":"9c55b778-1e60-76a9-a86f-c431ece5cfb3","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A dynamic array: contiguous storage that grows automatically. The container you should reach for first."}]}]}},"revision":1},{"id":"1c4cb450-ae09-77c5-8b5f-96c178ebf476","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Core operations"}]},"revision":1},{"id":"712abac1-b185-7585-9c14-fcc37aa48b6d","type":"code","position":"a2","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\n\nint main() {\n    std::vector<int> v;                      // empty\n    std::vector<int> zeros(5);               // 5 × 0\n    std::vector<int> sevens(3, 7);           // 3 × 7\n    std::vector<int> list{1, 2, 3};          // initializer list\n\n    v.push_back(10);                         // append\n    v.emplace_back(20);                      // construct in place\n    v.insert(v.begin(), 5);                  // insert at front: O(n)\n    std::cout << v.size() << '' '' << v.front() << '' '' << v.back() << '' '' << v[1] << ''\\n'';\n\n    v.pop_back();                            // remove last\n    v.erase(v.begin());                      // remove first: O(n)\n    std::cout << v.size() << '' '' << v[0] << ''\\n'';\n\n    list.resize(5);                          // grow with zeros\n    std::cout << list[4] << '' '' << zeros.size() << '' '' << sevens[2] << ''\\n'';\n    list.clear();\n    std::cout << list.empty() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"35762bb4-d681-79b2-bbb6-2c56c4febd56","type":"code","position":"a3","content":{"language":"text","code":"3 5 20 10\n1 10\n0 5 7\n1","filename":"Output"},"revision":1},{"id":"b11e83c5-252d-7326-af01-6306c973fabb","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Size vs capacity"}]},"revision":1},{"id":"c0a4a6fa-366d-740f-ab40-5be8e0b76db3","type":"code","position":"a5","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nint main() {\n    std::vector<int> v;\n    std::size_t lastCap = 0;\n    for (int i = 0; i < 100; ++i) {\n        v.push_back(i);\n        if (v.capacity() != lastCap) { lastCap = v.capacity(); std::cout << lastCap << '' ''; }\n    }\n    std::cout << ''\\n'';\n    std::vector<int> r;\n    r.reserve(100);                    // one allocation up front\n    std::cout << r.size() << '' '' << r.capacity() << ''\\n'';\n    v.resize(10);\n    v.shrink_to_fit();                 // non-binding request to release spare capacity\n    std::cout << v.size() << '' '' << v.capacity() << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"3195be32-cacd-7f09-9589-08b04dbcc38b","type":"code","position":"a6","content":{"language":"text","code":"1 2 4 8 16 32 64 128\n0 100\n10 10","filename":"Output"},"revision":1},{"id":"22b12b0b-6aac-7e5e-8b0c-1fdc416168af","type":"callout","position":"a7","content":{"variant":"note","title":"Growth","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When full, "},{"type":"text","text":"push_back","marks":[{"type":"code"}]},{"type":"text","text":" allocates a bigger buffer (libc++ and libstdc++ double it; MSVC grows by 1.5×), moves the elements over and frees the old one. Each element is moved O(1) times on average → "},{"type":"text","text":"amortised O(1)","marks":[{"type":"bold"}]},{"type":"text","text":" append. If you know the final size, "},{"type":"text","text":"reserve","marks":[{"type":"code"}]},{"type":"text","text":" it."}]}]}},"revision":1},{"id":"82e75046-4db3-7873-8684-dd7d6ea6e765","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Iterator invalidation"}]},"revision":1},{"id":"b178458c-8709-7ec5-ac57-07d9b713d79c","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Invalidates"}]],[[{"type":"text","text":"push_back","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"emplace_back","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"insert","marks":[{"type":"code"}]},{"type":"text","text":" causing reallocation"}],[{"type":"text","text":"All","marks":[{"type":"bold"}]},{"type":"text","text":" iterators, pointers, references"}]],[[{"type":"text","text":"insert","marks":[{"type":"code"}]},{"type":"text","text":" without reallocation"}],[{"type":"text","text":"Those at or after the insertion point"}]],[[{"type":"text","text":"erase","marks":[{"type":"code"}]}],[{"type":"text","text":"Those at or after the erased element"}]],[[{"type":"text","text":"reserve","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"shrink_to_fit","marks":[{"type":"code"}]}],[{"type":"text","text":"All, if the capacity changes"}]]]},"revision":1},{"id":"4c33f3aa-fee4-72fe-9e29-43516337e5b0","type":"code","position":"aA","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nint main() {\n    std::vector<int> v{1, 2, 3, 4, 5, 6};\n    for (auto it = v.begin(); it != v.end(); ) {     // erase while iterating: use the returned iterator\n        if (*it % 2 == 0) it = v.erase(it);\n        else ++it;\n    }\n    for (int x : v) std::cout << x;\n    std::cout << ''\\n'';\n    std::erase_if(v, [](int x) { return x > 3; });   // C++20 one-liner\n    for (int x : v) std::cout << x;\n    std::cout << ''\\n'';\n}","filename":"C++"},"revision":1},{"id":"7755eb88-4d0a-76b6-aa50-7f7fbbe77068","type":"code","position":"aB","content":{"language":"text","code":"135\n13","filename":"Output"},"revision":1},{"id":"75037345-f3f2-7bc3-8579-1dc6b879a986","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"2-D vectors & useful members"}]},"revision":1},{"id":"9