pe":"text","text":" unrelated classes can have ("},{"type":"text","text":"Comparable","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":"), or need a type to have several such capabilities."}]}]}},"revision":1},{"id":"76603c2d-3063-7224-b4f4-ac700d6a2ac0","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can an abstract class have a constructor? Why?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes. It can''t be called with "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" directly, but subclasses call it via "},{"type":"text","text":"super(...)","marks":[{"type":"code"}]},{"type":"text","text":" to initialise the fields the abstract class declares."}]}]}},"revision":1},{"id":"5ab124b8-ca33-7316-a4b6-987de12f2a9b","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can an abstract class have no abstract methods?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes — marking it "},{"type":"text","text":"abstract","marks":[{"type":"code"}]},{"type":"text","text":" simply prevents instantiation (e.g. "},{"type":"text","text":"HttpServlet","marks":[{"type":"code"}]},{"type":"text","text":" had none historically). It signals "},{"type":"text","text":"extend me, don''t use me directly","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"66331656-6e5d-768e-bf64-cf4f9d6edef1","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can an abstract method be private, static or final?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. An abstract method must be overridden; "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" methods aren''t inherited, "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" methods are hidden not overridden, and "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":" forbids overriding."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
