SELECT '33aee127-7c4f-725f-890c-820cddf4c928', 'db8db7e2-53d7-7fd9-9312-41db317829f8', 1, 'PUBLISHED', 'Arrays', '[{"id":"1a72e621-10c5-7529-b278-9d31e42ed46f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A fixed-size, zero-indexed, contiguous container of one element type. Arrays are objects: they live on the heap and know their "},{"type":"text","text":"length","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"f1712512-294c-77c4-b5ca-a51e1032562f","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Array","marks":[{"type":"bold"}]},{"type":"text","text":" — an object holding "},{"type":"text","text":"length","marks":[{"type":"code"}]},{"type":"text","text":" elements of the same type, accessed by index "},{"type":"text","text":"0 … length-1","marks":[{"type":"code"}]},{"type":"text","text":" in O(1). Its size is fixed at creation; bounds are checked at runtime."}]}]}},"revision":1},{"id":"317ef637-94a0-78ab-9393-836a85866ca9","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Declaring and creating"}]},"revision":1},{"id":"da252a18-64d9-767f-9862-59d86603ed6f","type":"code","position":"a3","content":{"language":"java","code":"import java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[] a = new int[4];                  // all zeros\n        int[] b = {5, 3, 9};                   // array initializer\n        String[] names = new String[2];        // all null\n        boolean[] flags = new boolean[2];      // all false\n        double[] d = new double[]{1.5, 2.5};\n\n        a[0] = 42;\n        System.out.println(Arrays.toString(a) + \" len=\" + a.length);\n        System.out.println(Arrays.toString(b) + \" \" + Arrays.toString(names) + \" \" + Arrays.toString(flags) + \" \" + Arrays.toString(d));\n        System.out.println(b);                 // prints type@hash — not the contents!\n    }\n}","filename":"Java"},"revision":1},{"id":"e32f2b71-b7b8-7ac2-b0dc-1c0c07b5348c","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The last line prints something like "},{"type":"text","text":"[I@1b6d3586","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"[I","marks":[{"type":"code"}]},{"type":"text","text":" means “array of int”. Always print arrays with "},{"type":"text","text":"Arrays.toString","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"Arrays.deepToString","marks":[{"type":"code"}]},{"type":"text","text":" for nested arrays)."}]}]}},"revision":1},{"id":"67171984-fdde-7b04-ae72-f97053bc8994","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Element type"}],[{"type":"text","text":"Default value"}]],[[{"type":"text","text":"byte","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"short","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"long","marks":[{"type":"code"}]}],[{"type":"text","text":"0","marks":[{"type":"code"}]}]],[[{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"double","marks":[{"type":"code"}]}],[{"type":"text","text":"0.0","marks":[{"type":"code"}]}]],[[{"type":"text","text":"char","marks":[{"type":"code"}]}],[{"type":"text","text":"''\\u0000''","marks":[{"type":"code"}]}]],[[{"type":"text","text":"boolean","marks":[{"type":"code"}]}],[{"type":"text","text":"false","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Any reference type"}],[{"type":"text","text":"null","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"4d9271b3-c68e-7f7b-9720-075390602799","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"2D and jagged arrays"}]},"revision":1},{"id":"11ece742-2354-7311-9bb6-2512a3e8ee8e","type":"code","position":"a7","content":{"language":"java","code":"import java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[][] grid = new int[2][3];          // 2 rows × 3 columns\n        grid[1][2] = 7;\n        System.out.println(Arrays.deepToString(grid));\n\n        int[][] jagged = new int[3][];         // rows created separately\n        for (int i = 0; i < jagged.length; i++) {\n            jagged[i] = new int[i + 1];\n            Arrays.fill(jagged[i], i);\n        }\n        System.out.println(Arrays.deepToString(jagged));\n\n        int[][] m = {{1, 2}, {3, 4}};\n        int total = 0;\n        for (int[] row : m) for (int x : row) total += x;\n        System.out.println(\"total=\" + total + \" rows=\" + m.length + \" cols=\" + m[0].length);\n    }\n}","filename":"Java"},"revision":1},{"id":"7e96e463-0ec0-763b-b84f-a4858c08d576","type":"code","position":"a8","content":{"language":"text","code":"[[0, 0, 0], [0, 0, 7]]\n[[0], [1, 1], [2, 2, 2]]\ntotal=10 rows=2 cols=2","filename":"Output"},"revision":1},{"id":"6e1145dc-3f56-7665-b5e5-2efe2c0eb88e","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"The "},{"type":"text","text":"java.util.Arrays","marks":[{"type":"code"}]},{"type":"text","text":" toolbox"}]},"revision":1},{"id":"49c2a16e-0f80-7465-b509-e6f66ee0aee6","type":"code","position":"aA","content":{"language":"java","code":"import java.util.Arrays;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[] a = {5, 2, 8, 1, 9};\n        Arrays.sort(a);                                        // dual-pivot quicksort for primitives\n        System.out.println(Arrays.toString(a));\n        System.out.println(Arrays.binarySearch(a, 8));         // array must be sorted\n        int[