SELECT '59020e77-33c6-702b-9b1f-025ab8861523', '2ec55f5e-1a88-7da8-b70e-70a62efee415', 1, 'PUBLISHED', 'Collections & Arrays Utilities', '[{"id":"75ab6d35-b752-7535-993a-1a4f4facd3b3","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"java.util.Collections","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"java.util.Arrays","marks":[{"type":"code"}]},{"type":"text","text":" are static toolboxes — sorting, searching, filling, copying, wrapping. Knowing them saves writing (and debugging) loops."}]}]}},"revision":1},{"id":"1b92d98e-68a0-7104-a996-f6de851982ed","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Collections","marks":[{"type":"code"}]},{"type":"text","text":" algorithms"}]},"revision":1},{"id":"23f5c478-b7a7-7aca-9a5b-fc7a76ca15ae","type":"code","position":"a2","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> xs = new ArrayList<>(List.of(5, 3, 9, 1, 3));\n        Collections.sort(xs);\n        System.out.println(xs + \" binarySearch(5)=\" + Collections.binarySearch(xs, 5)\n                + \" binarySearch(4)=\" + Collections.binarySearch(xs, 4));\n        Collections.reverse(xs);\n        System.out.println(xs + \" max=\" + Collections.max(xs) + \" min=\" + Collections.min(xs));\n        System.out.println(\"frequency(3)=\" + Collections.frequency(xs, 3));\n        Collections.swap(xs, 0, 4);\n        System.out.println(xs);\n        Collections.rotate(xs, 1);\n        System.out.println(xs);\n        Collections.shuffle(xs, new Random(42));   // seeded -> reproducible\n        System.out.println(xs);\n        System.out.println(Collections.nCopies(3, \"ab\") + \" \" + String.join(\"\", Collections.nCopies(3, \"-\")));\n        System.out.println(Collections.disjoint(List.of(1, 2), List.of(3, 4)));\n    }\n}","filename":"Java"},"revision":1},{"id":"00c124e4-6199-7edc-b3da-38bdea6dd2ac","type":"code","position":"a3","content":{"language":"text","code":"[1, 3, 3, 5, 9] binarySearch(5)=3 binarySearch(4)=-4\n[9, 5, 3, 3, 1] max=9 min=1\nfrequency(3)=2\n[1, 5, 3, 3, 9]\n[9, 1, 5, 3, 3]\n[1, 5, 3, 3, 9]\n[ab, ab, ab] ---\ntrue","filename":"Output"},"revision":1},{"id":"f08cd983-f1f6-778d-a787-3b5d36701664","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"binarySearch","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"-(insertionPoint) - 1","marks":[{"type":"code"}]},{"type":"text","text":" when the key is missing: "},{"type":"text","text":"4","marks":[{"type":"code"}]},{"type":"text","text":" would be inserted at index 3, so the result is "},{"type":"text","text":"-4","marks":[{"type":"code"}]},{"type":"text","text":". The list must already be sorted in the same order."}]}]}},"revision":1},{"id":"2ece55eb-372c-77b5-b1ad-98cfddd16cff","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Wrappers and empty collections"}]},"revision":1},{"id":"6245a3fb-8521-70ad-9bd5-0f7cd1f1bf5f","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"Returns"}]],[[{"type":"text","text":"Collections.unmodifiableList(l)","marks":[{"type":"code"}]},{"type":"text","text":" (…"},{"type":"text","text":"Set","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Read-only "},{"type":"text","text":"view","marks":[{"type":"bold"}]},{"type":"text","text":" — still reflects changes to "},{"type":"text","text":"l","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Collections.synchronizedList(l)","marks":[{"type":"code"}]},{"type":"text","text":" (…"},{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Every method locked on one mutex; iterate inside "},{"type":"text","text":"synchronized (list) { … }","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Collections.emptyList()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"emptyMap()","marks":[{"type":"code"}]}],[{"type":"text","text":"Shared immutable empty instance"}]],[[{"type":"text","text":"Collections.singletonList(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Immutable one-element list"}]],[[{"type":"text","text":"Collections.addAll(c, a, b, c)","marks":[{"type":"code"}]}],[{"type":"text","text":"Add varargs to any collection"}]]]},"revision":1},{"id":"2f988f0d-0224-74ba-89e2-a6402219154e","type":"code","position":"a7","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> src = new ArrayList<>(List.of(\"a\"));\n        List<String> view = Collections.unmodifiableList(src);\n        List<String> copy = List.copyOf(src);\n        src.add(\"b\");\n        System.out.println(view + \" \" + copy);   // the view sees the change, the copy doesn''t\n        try {\n            view.add(\"c\");\n        } catch (UnsupportedOperationException e) {\n            System.out.println(\"view is read-only\");\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"b3ff2ddd-ba5b-718e-adfa-8d88e6122b48","type":"code","position":"a8","content":{"language":"text","code":"[a, b] [a]\nview is read-only","filename":"Output"},"revision":1},{"id":"929a4e09-4b2f-7cd9-8e74-8740e92bfed6","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Arrays","marks":[{"type":"code"}]},{"type":"text","text":" helpers"}]},"revision":1},{"id":"67d18b8d-db14-7fc0-9ecf-68050fb1e8d6","type":"code","position":"aA","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[] a = {5, 2, 8, 1};\n        Arrays.sort(a);\n        System.out.println(Arrays.toString(a) + \" idx(5)=\" + Arrays.binarySearch(a, 5));\n\n        int[] filled = new int[4];\n        Arrays.fill(filled, -1);\n        System.out.println(Arrays.toString(filled));\n\n        int[] bigger = Arrays.copyOf(a, 6);            // pads with 0\n        int[] slice = Arrays.copyOfRange(a, 1, 3);     // [1, 3)\n        System.out.println(Arrays.toString(bigger) + \" \" + Arrays.toString(slice));\n\n        System.out.println(Arrays.stream(a).sum() + \" \" + Arrays.stream(a).max().getAsInt());\n        System.out.println(Arrays.equals(a, new int[]{1, 2, 5, 8}) + \" \" + (a == a.clone()));\n\n        int[][] grid = {{1, 2}, {3, 4}};\n        System.out.println(Arrays.deepToString(grid));\n\n        Integer[] boxed = {3, 1, 2};\n        Arrays.sort(boxed, Collections.reverseOrder()); // comparators need object arrays\n        System.out.println(Arrays.toString(boxed));\n    }\n}","filename":"Java"},"revision":1},{"id":"d8c3a1d4-c025-7cf6-8507-d49726dd878f","type":"code","position":"aB","content":{"language":"text","code":"[1, 2, 5, 8] idx(5)=2\n[-1, -1, -1, -1]\n[1, 2, 5, 8, 0, 0] [2, 5]\n16 8\ntrue false\n[[1, 2], [3, 4]]\n[3, 2, 1]","filename":"Output"},"revision":1},{"id":"4ea49ce3-726d-7b24-bc63-0bc3b36241d8","type":"callout","position":"aC","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrays.sort(int[])","marks":[{"type":"code"}]},{"type":"text","text":" uses dual-pivot quicksort (not stable, but stability is meaningless for primitives); "},{"type":"text","text":"Arrays.sort(Object[])","marks":[{"type":"code"}]},{"type":"text","text":" uses stable TimSort. Primitive arrays can''t take a "},{"type":"text","text":"Comparator","marks":[{"type":"code"}]},{"type":"text","text":" — box them or sort then reverse."}]}]}},"revision":1},{"id":"e4903f5d-cf8e-7be9-894a-0f4bd2f2b649","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Trap: "},{"type":"text","text":"Arrays.asList","marks":[{"type":"code"}]}]},"revision":1},{"id":"a2c1c6ed-1713-74d2-89be-97e38cad73dd","type":"code","position":"aE","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        String[] arr = {\"x\", \"y\", \"z\"};\n        List<String> fixed = Arrays.asList(arr);   // fixed-size view over the array\n        fixed.set(0, \"X\");                          // allowed, writes through\n        System.out.println(Arrays.toString(arr));\n        try {\n            fixed.add(\"w\");\n        } catch (UnsupportedOperationException e) {\n            System.out.println(\"add -> UnsupportedOperationException\");\n        }\n\n        int[] prim = {1, 2, 3};\n        System.out.println(Arrays.asList(prim).size());      // List<int[]> with ONE element\n        System.out.println(Arrays.asList(1, 2, 3).size());   // varargs of Integer\n\n        List<String> growable = new ArrayList<>(Arrays.asList(arr));\n        growable.add(\"w\");\n        System.out.println(growable);\n    }\n}","filename":"Java"},"revision":1},{"id":"0b847442-912b-77dd-99ac-882c6383a1f2","type":"code","position":"aF","content":{"language":"text","code":"[X, y, z]\nadd -> UnsupportedOperationException\n1\n3\n[X, y, z, w]","filename":"Output"},"revision":1},{"id":"a42a5564-d080-7831-9aae-93f8e68d39a9","type":"callout","position":"aG","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrays.asList","marks":[{"type":"code"}]},{"type":"text","text":" returns a fixed-size list backed by the array (no "},{"type":"text","text":"add","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"remove","marks":[{"type":"code"}]},{"type":"text","text":"), and "},{"type":"text","text":"Arrays.asList(intArray)","marks":[{"type":"code"}]},{"type":"text","text":" gives a "},{"type":"text","text":"List<int[]>","marks":[{"type":"code"}]},{"type":"text","text":" of size 1. Wrap it in "},{"type":"text","text":"new ArrayList<>(…)","marks":[{"type":"code"}]},{"type":"text","text":" for a normal list; use "},{"type":"text","text":"Arrays.stream(ints).boxed().toList()","marks":[{"type":"code"}]},{"type":"text","text":" for primitives."}]}]}},"revision":1},{"id":"5f7e36ff-3d21-763e-b92a-11b25cf11cd1","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does Collections.synchronizedList not protect you from?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compound actions and iteration. Each single call is locked, but "},{"type":"text","text":"if (!list.contains(x)) list.add(x)","marks":[{"type":"code"}]},{"type":"text","text":" can interleave between threads, and iterating requires manually holding "},{"type":"text","text":"synchronized (list)","marks":[{"type":"code"}]},{"type":"text","text":". Prefer "},{"type":"text","text":"java.util.concurrent","marks":[{"type":"code"}]},{"type":"text","text":" collections."}]}]}},"revision":1},{"id":"73f308c1-441d-703b-b31d-c9ad5695bc07","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"unmodifiableList vs List.copyOf vs List.of?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"unmodifiableList","marks":[{"type":"code"}]},{"type":"text","text":" is a read-only "},{"type":"text","text":"view","marks":[{"type":"italic"}]},{"type":"text","text":" — changes to the backing list show through. "},{"type":"text","text":"List.copyOf","marks":[{"type":"code"}]},{"type":"text","text":" makes an independent immutable copy (returns the argument itself if it is already an immutable list). "},{"type":"text","text":"List.of","marks":[{"type":"code"}]},{"type":"text","text":" builds an immutable list from values. Neither of the last two allows "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":"s."}]}]}},"revision":1},{"id":"aa25ec73-d52a-78ea-92ca-e1a4587d5511","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which sort algorithms does Java use?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrays.sort","marks":[{"type":"code"}]},{"type":"text","text":" on primitives: dual-pivot quicksort, O(n log n) average, not stable. On objects and in "},{"type":"text","text":"Collections.sort","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"List.sort","marks":[{"type":"code"}]},{"type":"text","text":": TimSort — a stable merge/insertion hybrid, O(n log n) worst case and O(n) on already-sorted data."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
