  ('929a4e09-4b2f-7cd9-8e74-8740e92bfed6', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Arrays","marks":[{"type":"code"}]},{"type":"text","text":" helpers"}]}'),
  ('67d18b8d-db14-7fc0-9ecf-68050fb1e8d6', 'aA', 'code', '{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[] a = {5, 2, 8, 1};\n        Arrays.sort(a);\n        System.out.println(Arrays.toString(a) + \" idx(5)=\" + Arrays.binarySearch(a, 5));\n\n        int[] filled = new int[4];\n        Arrays.fill(filled, -1);\n        System.out.println(Arrays.toString(filled));\n\n        int[] bigger = Arrays.copyOf(a, 6);            // pads with 0\n        int[] slice = Arrays.copyOfRange(a, 1, 3);     // [1, 3)\n        System.out.println(Arrays.toString(bigger) + \" \" + Arrays.toString(slice));\n\n        System.out.println(Arrays.stream(a).sum() + \" \" + Arrays.stream(a).max().getAsInt());\n        System.out.println(Arrays.equals(a, new int[]{1, 2, 5, 8}) + \" \" + (a == a.clone()));\n\n        int[][] grid = {{1, 2}, {3, 4}};\n        System.out.println(Arrays.deepToString(grid));\n\n        Integer[] boxed = {3, 1, 2};\n        Arrays.sort(boxed, Collections.reverseOrder()); // comparators need object arrays\n        System.out.println(Arrays.toString(boxed));\n    }\n}","filename":"Java"}'),
  ('d8c3a1d4-c025-7cf6-8507-d49726dd878f', 'aB', 'code', '{"language":"text","code":"[1, 2, 5, 8] idx(5)=2\n[-1, -1, -1, -1]\n[1, 2, 5, 8, 0, 0] [2, 5]\n16 8\ntrue false\n[[1, 2], [3, 4]]\n[3, 2, 1]","filename":"Output"}'),
  ('4ea49ce3-726d-7b24-bc63-0bc3b36241d8', 'aC', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrays.sort(int[])","marks":[{"type":"code"}]},{"type":"text","text":" uses dual-pivot quicksort (not stable, but stability is meaningless for primitives); "},{"type":"text","text":"Arrays.sort(Object[])","marks":[{"type":"code"}]},{"type":"text","text":" uses stable TimSort. Primitive arrays can''t take a "},{"type":"text","text":"Comparator","marks":[{"type":"code"}]},{"type":"text","text":" — box them or sort then reverse."}]}]}}'),
