t":" (16+)"}],[{"type":"text","text":"List<T>","marks":[{"type":"code"}]}],[{"type":"text","text":"No","marks":[{"type":"bold"}]},{"type":"text","text":" — unmodifiable"}],[{"type":"text","text":"allowed"}]],[[{"type":"text","text":"collect(Collectors.toList())","marks":[{"type":"code"}]}],[{"type":"text","text":"List<T>","marks":[{"type":"code"}]},{"type":"text","text":" (an "},{"type":"text","text":"ArrayList","marks":[{"type":"code"}]},{"type":"text","text":" in practice)"}],[{"type":"text","text":"yes (not guaranteed)"}],[{"type":"text","text":"allowed"}]],[[{"type":"text","text":"collect(Collectors.toUnmodifiableList())","marks":[{"type":"code"}]},{"type":"text","text":" (10+)"}],[{"type":"text","text":"List<T>","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"NPE","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"collect(Collectors.toSet())","marks":[{"type":"code"}]}],[{"type":"text","text":"Set<T>","marks":[{"type":"code"}]},{"type":"text","text":" (a "},{"type":"text","text":"HashSet","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"allowed"}]],[[{"type":"text","text":"collect(Collectors.toCollection(TreeSet::new))","marks":[{"type":"code"}]}],[{"type":"text","text":"the exact type you choose"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"depends"}]]]},"revision":1},{"id":"a5ae5cd3-7d68-7092-9d38-e1b0d66f15c5","type":"code","position":"a4","content":{"language":"java","code":"import java.util.*;\nimport java.util.stream.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> fixed = Stream.of(\"b\", \"a\").toList();\n        List<String> growable = Stream.of(\"b\", \"a\").collect(Collectors.toList());\n        growable.add(\"c\");\n        System.out.println(growable);\n        try {\n            fixed.add(\"c\");\n        } catch (UnsupportedOperationException e) {\n            System.out.println(\"toList() result is unmodifiable\");\n        }\n        TreeSet<String> sorted = Stream.of(\"pear\", \"apple\", \"fig\", \"apple\")\n                .collect(Collectors.toCollection(TreeSet::new));\n        System.out.println(sorted);\n    }\n}","filename":"Java"},"revision":1},{"id":"5b22dac5-44c0-7489-b292-1af8f5a9c2df","type":"code","position":"a5","content":{"language":"text","code":"[b, a, c]\ntoList() result is unmodifiable\n[apple, fig, pear]","filename":"Output"},"revision":1},{"id":"eecfa2b6-171c-79c3-b0ea-155237e3f972","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Into maps: "},{"type":"text","text":"toMap","marks":[{"type":"code"}]}]},"revision":1},{"id":"1850c2ab-615c-7159-8654-1a040ab98e50","type":"code","position":"a7","content":{"language":"java","code":"import java.util.*;\nimport java.util.stream.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> words = List.of(\"apple\", \"avocado\", \"banana\", \"cherry\");\n\n        Map<String, Integer> lengths = words.stream()\n                .collect(Collectors.toMap(w -> w, String::length, (a, b) -> a, TreeMap::new));\n        System.out.println(lengths);\n\n        try {\n            words.stream().collect(Collectors.toMap(w -> w.charAt(0), w -> w));   // ''a'' twice\n        } catch (IllegalStateException e) {\n            System.out.println(e.getMessage());\n        }\n\n        // merge function decides what to do with duplicate keys\n        Map<Character, String> byLetter = words.stream()\n                .collect(Collectors.toMap(w -> w.charAt(0), w -> w, (a, b) -> a + \"|\" + b, TreeMap::new));\n        System.out.println(byLetter);\n    }\n}","filename":"Java"},"revision":1},{"id":"b52e8628-1ede-7a1b-bc87-4aeb720db6da","type":"code","position":"a8","content":{"language":"text","code":"{apple=5, avocado=7, banana=6, cherry=6}\nDuplicate key a (attempted merging values apple and avocado)\n{a=apple|avocado, b=banana, c=cherry}","filename":"Output"},"revision":1},{"id":"398f09f2-add5-7286-a482-d1658dedbb5f","type":"callout","position":"a9","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"toMap(keyFn, valueFn)","marks":[{"type":"code"}]},{"type":"text","text":" throws "},{"type":"text","text":"IllegalStateException: Duplicate key","marks":[{"type":"code"}]},{"type":"text","text":" on the first collision, and "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]},{"type":"text","text":" if a "},{"type":"text","text":"value","marks":[{"type":"italic"}]},{"type":"text","text":" is "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":". Pass a merge function whenever keys might repeat."}]}]}},"revision":1},{"id":"2b9b7b4a-dd51-7a59-9e2e-4b484066f43e","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"groupingBy","marks":[{"type":"code"}]},{"type":"text","text":" — the SQL "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" of Java"}]},"revision":1},{"id":"4510325c-46ae-7b29-b740-1ba1cfb6a3b4","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"groupingBy(classifier)","marks":[{"type":"code"}]},{"type":"text","text":" builds a "},{"type":"text","text":"Map<K, List<T>>","marks":[{"type":"code"}]},{"type":"text","text":". The two optional arguments are the "},{"type":"text","text":"map factory","marks":[{"type":"bold"}]},{"type":"text","text":" and a "},{"type":"text","text":"downstream collector","marks":[{"type":"bold"}]},{"type":"text","text":" applied to each group."}]}]}},"revision":1},{"id":"b0d56aa2-c520-7bad-ac3d-072fdb6649a1","type":"code","position":"aC","content":{"language":"java","code":"import java.util.*;\nimport java.util.stream.*;\n\npublic class Main {\n    record Emp(String name, String dept, int salary) {}\n\n    public static void main(String[] args) {\n        List<Emp> emps = List.of(\n                new Emp(\"Asha\", \"Eng\", 120), new Emp(\"Ravi\", \"HR\", 70),\n                new Emp(\"Zoe\", \"Eng\", 100), new Emp(\"Mohan\", \"Sales\", 80),\n                new Emp(\"Lena\", \"HR\", 75));\n\n        Map<String, List<String>> names = emps.stream().collect(Collectors.groupingBy(\n                Emp::dept, TreeMap::new, Collectors.mapping(Emp::name, Collectors.toList())));\n        System.out.println(names);\n\n        Map<String, Long> counts = emps.stream().collect(\n                Collectors.groupingBy(Emp::dept, TreeMap::new, Collectors.counting()));\n        System.out.println(counts);\n\n        Map<String, Integer> payroll = emps.stream().collect(\n                Collectors.groupingBy(Emp::dept, TreeMap::new, Collectors.summingInt(Emp::salary)));\n        System.out.println(payroll);\n\n        Map<String, Double> avg = emps.stream().collect(\n                Collectors.groupingBy(Emp::dept, TreeMap::new, Collectors.averagingInt(Emp::salary)));\n        System.out.println(avg);\n\n        Map<String, Optional<Emp>> top = emps.stream().collect(Collectors.groupingBy(\n                Emp::dept, TreeMap::new, Collectors.maxBy(Comparator.comparingInt(Emp::salary))));\n        top.forEach((d, e) -> System.out.println(d + \" -> \" + e.get().name()));\n    }\n}","filename":"Java"},"revision":1},{"id":"24d047a4-340e-7fb3-b265-d7622d623715","type":"code","position":"aD","content":{"language":"text","code":"{Eng=[Asha, Zoe], HR=[Ravi, Lena], Sales=[Mohan]}\n{Eng=2, HR=2, Sales=1}\n{Eng=220, HR=145, Sales=80}\n{Eng=110.0, HR=72.5, Sales=80.0}\nEng -> Asha\nHR -> Lena\nSales -> Mohan","filename":"Output"},"revision":1},{"id":"6e0ec210-ab11-766a-9aea-2d87e621a3fc","type":"callout","position":"aE","content":{"variant":"note","title":"Deterministic order","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Plain "},{"type":"text","text":"groupingBy(f)","marks":[{"type":"code"}]},{"type":"text","text":" returns a "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":", so the key order you print is not something to rely on. Pass "},{"type":"text","text":"TreeMap::new","marks":[{"type":"code"}]},{"type":"text","text":" (sorted) or "},{"type":"text","text":"LinkedHashMap::new","marks":[{"type":"code"}]},{"type":"text","text":" (encounter order) when order matters."}]}]}},"revision":1},{"id":"4a3455b5-ad5b-735f-8a89-d6402553e3f8","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Downstream collector"}],[{"type":"text","text":"Per group you get"}]],[[{"type":"text","text":"counting()","marks":[{"type":"code"}]}],[{"type":"text","text":"Long","marks":[{"type":"code"}]},{"type":"text","text":" count"}]],[[{"type":"text","text":"summingInt(f)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"averagingDouble(f)","marks":[{"type":"code"}]}],[{"type":"text","text":"sum / average"}]],[[{"type":"text","text":"mapping(f, toList())","marks":[{"type":"code"}]}],[{"type":"text","text":"a list of a projected field"}]],[[{"type":"text","text":"maxBy(cmp)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"minBy(cmp)","marks":[{"type":"code"}]}],[{"type":"text","text":"Optional<T>","marks":[{"type":"code"}]}]],[[{"type":"text","text":"toSet()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"joining(\", \")","marks":[{"type":"code"}]}],[{"type":"text","text":"set / concatenated string"}]],[[{"type":"text","text":"collectingAndThen(c, fn)","marks":[{"type":"code"}]}],[{"type":"text","text":"post-process, e.g. unwrap the "},{"type":"text","text":"Optional","marks":[{"type":"code"}]}]],[[{"type":"text","text":"groupingBy(...)","marks":[{"type":"code"}]}],[{"type":"text","text":"nested (multi-level) grouping"}]]]},"revision":1},{"id":"aff28dcc-b874-7e3a-8e25-cfec70eb789c","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"partitioningBy","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"joining","marks":[{"type":"code"}]},{"type":"text","text":" and friends"}]},"revision":1},{"id":"af65b588-3c9f-7851-bcb8-b33b52bdb50f","type":"code","position":"aH","content":{"language":"java","code":"import java.util.*;\nimport java.util.stream.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> nums = List.of(1, 2, 3, 4, 5, 6, 7);\n\n        Map<Boolean, List<Integer>> evenOdd = nums.stream()\n                .collect(Collectors.partitioningBy(n -> n % 2 == 0));\n        System.out.println(evenOdd);\n\n        System.out.println(Stream.of(\"a\", \"b\", \"c\").collect(Collectors.joining(\", \", \"[\", \"]\")));\n\n        IntSummaryStatistics st = nums.stream().collect(Collectors.summarizingInt(n -> n));\n        System.out.println(st);\n\n        Map<Integer, Long> byLength = Stream.of(\"hi\", \"yo\", \"hey\", \"java\", \"sun\")\n                .collect(Collectors.groupingBy(String::length, TreeMap::new, Collectors.counting()));\n        System.out.println(byLength);\n    }\n}","filename":"Java"},"revision":1},{"id":"92203b91-4944-7353-81a0-11d8e80d27a5","type":"code","position":"aI","content":{"language":"text","code":"{false=[1, 3, 5, 7], true=[2, 4, 6]}\n[a, b, c]\nIntSummaryStatistics{count=7, sum=28, min=1, average=4.000000, max=7}\n{2=2, 3=2, 4=1}","filename":"Output"},"revision":1},{"id":"64fa2639-ad14-79b7-ae14-4c19f2d5b537","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"partitioningBy","marks":[{"type":"code"}]},{"type":"text","text":" always has exactly two keys, "},{"type":"text","text":"false","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" — even if one group is empty — which makes it nicer than "},{"type":"text","text":"groupingBy","marks":[{"type":"code"}]},{"type":"text","text":" with a boolean."}]}]}},"revision":1},{"id":"7c34c50e-cfb8-709f-a7f7-386d26fcd70d","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stream.toList() vs Collectors.toList()?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stream.toList()","marks":[{"type":"code"}]},{"type":"text","text":" (Java 16) returns an "},{"type":"text","text":"unmodifiable","marks":[{"type":"bold"}]},{"type":"text","text":" list and accepts "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" elements. "},{"type":"text","text":"Collectors.toList()","marks":[{"type":"code"}]},{"type":"text","text":" returns a list with no guarantees on type or mutability (an "},{"type":"text","text":"ArrayList","marks":[{"type":"code"}]},{"type":"text","text":" in practice, so callers often mutate it). Prefer "},{"type":"text","text":"toList()","marks":[{"type":"code"}]},{"type":"text","text":" for results you only read; use "},{"type":"text","text":"toCollection(ArrayList::new)","marks":[{"type":"code"}]},{"type":"text","text":" when you need to mutate."}]}]}},"revision":1},{"id":"1e5517dc-ddde-7c7e-852f-a74b34d22521","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you count word frequencies with streams?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"words.stream().collect(Collectors.groupingBy(Function.identity(), Collectors.counting()))","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"Map<String, Long>","marks":[{"type":"code"}]},{"type":"text","text":". Add "},{"type":"text","text":"TreeMap::new","marks":[{"type":"code"}]},{"type":"text","text":" as the middle argument for sorted keys."}]}]}},"revision":1},{"id":"4c7a00ed-3513-7690-a69d-fe07b33bb0e9","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens with duplicate keys in Collectors.toMap?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without a merge function it throws "},{"type":"text","text":"IllegalStateException","marks":[{"type":"code"}]},{"type":"text","text":" (\"Duplicate key …\"). Supply the third argument, e.g. "},{"type":"text","text":"(a, b) -> a","marks":[{"type":"code"}]},{"type":"text","text":" to keep the first or "},{"type":"text","text":"Integer::sum","marks":[{"type":"code"}]},{"type":"text","text":" to add counts; a fourth argument chooses the map implementation."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
