SELECT 'd4952dec-4071-7ee1-ae69-9ce95be3e3da', '3ed0c79c-a4f5-7c9e-a2e6-24f4b53f6539', 1, 'PUBLISHED', 'Competitive Programming I/O in Java', '[{"id":"31f268fd-9eba-7101-a6c6-09537da9f214","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Java is fast enough for contests "},{"type":"text","text":"if","marks":[{"type":"italic"}]},{"type":"text","text":" you avoid slow input, per-line output and a few well-known traps."}]}]}},"revision":1},{"id":"e593b18f-21f8-7169-bde5-6166d0da2207","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Scanner is slow"}]},"revision":1},{"id":"a22312ce-80c0-7518-9c1d-417e75b5abab","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Scanner","marks":[{"type":"code"}]},{"type":"text","text":" uses regular expressions for every token — fine for 10³ numbers, too slow for 10⁶. Read lines with "},{"type":"text","text":"BufferedReader","marks":[{"type":"code"}]},{"type":"text","text":" and split them with "},{"type":"text","text":"StringTokenizer","marks":[{"type":"code"}]},{"type":"text","text":"; buffer the output with "},{"type":"text","text":"PrintWriter","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"61856fd7-68f0-715d-b788-f0f01d1955fb","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Tool"}],[{"type":"text","text":"Speed"}],[{"type":"text","text":"Use"}]],[[{"type":"text","text":"Scanner(System.in)","marks":[{"type":"code"}]}],[{"type":"text","text":"Slow (regex per token)"}],[{"type":"text","text":"Small inputs, quick scripts"}]],[[{"type":"text","text":"BufferedReader","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"StringTokenizer","marks":[{"type":"code"}]}],[{"type":"text","text":"Fast"}],[{"type":"text","text":"The standard contest template"}]],[[{"type":"text","text":"DataInputStream","marks":[{"type":"code"}]},{"type":"text","text":" custom byte reader"}],[{"type":"text","text":"Fastest"}],[{"type":"text","text":"Huge inputs (10⁷ numbers)"}]],[[{"type":"text","text":"System.out.println","marks":[{"type":"code"}]},{"type":"text","text":" in a loop"}],[{"type":"text","text":"Slow (flushes / locks)"}],[{"type":"text","text":"Avoid for many lines"}]],[[{"type":"text","text":"PrintWriter","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"StringBuilder","marks":[{"type":"code"}]}],[{"type":"text","text":"Fast"}],[{"type":"text","text":"Build output, flush once"}]]]},"revision":1},{"id":"4ca499ff-92ae-76e6-bb30-abfebbe4d3d9","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"The standard template"}]},"revision":1},{"id":"ff955d7d-67b2-75c5-a2f1-31faae715b5b","type":"code","position":"a5","content":{"language":"java","code":"import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));\n\n        int t = Integer.parseInt(br.readLine().trim());          // number of test cases\n        while (t-- > 0) {\n            int n = Integer.parseInt(br.readLine().trim());\n            StringTokenizer st = new StringTokenizer(br.readLine());\n            long sum = 0;                                        // long: sums overflow int\n            int max = Integer.MIN_VALUE;\n            for (int i = 0; i < n; i++) {\n                int x = Integer.parseInt(st.nextToken());\n                sum += x;\n                max = Math.max(max, x);\n            }\n            out.println(sum + \" \" + max);\n        }\n        out.flush();                                             // forget this → no output!\n    }\n}","filename":"Java"},"revision":1},{"id":"a5e52fa2-af64-72b2-8870-0078ecf4ab74","type":"code","position":"a6","content":{"language":"text","code":"6 3\n3000000000 1000000000","filename":"Output"},"revision":1},{"id":"e9310682-5b9d-7ad1-8b89-93b9e7a0a403","type":"code","position":"a7","content":{"language":"text","code":"2\n3\n1 2 3\n3\n1000000000 1000000000 1000000000","filename":"Input (stdin)"},"revision":1},{"id":"9e12547b-747e-7c56-aaf9-02f9a5291ebc","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"A reusable FastReader"}]},"revision":1},{"id":"05a080d0-a1f5-7069-89c8-f68ab0236e21","type":"code","position":"a9","content":{"language":"java","code":"import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    static final class FastReader {\n        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        private StringTokenizer st;\n\n        String next() throws IOException {\n            while (st == null || !st.hasMoreTokens()) {\n                st = new StringTokenizer(br.readLine());   // tokens may span lines\n            }\n            return st.nextToken();\n        }\n        int nextInt() throws IOException { return Integer.parseInt(next()); }\n        long nextLong() throws IOException { return Long.parseLong(next()); }\n    }\n\n    public static void main(String[] args) throws IOException {\n        FastReader in = new FastReader();\n        int n = in.nextInt();\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) a[i] = in.nextInt();\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = n - 1; i >= 0; i--) sb.append(a[i]).append(i > 0 ? '' '' : ''\\n'');\n        System.out.print(sb);                                   // one write\n    }\n}","filename":"Java"},"revision":1},{"id":"36fd4c5a-a91f-7d13-a731-58a5c9c46133","type":"code","position":"aA","content":{"language":"text","code":"5 4 3 2 1","filename":"Output"},"revision":1},{"id":"cd53888a-7f09-771a-8c92-1d203dad1090","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Overflow: when to use long"}]},"revision":1},{"id":"6e7639ed-d96c-7ee3-b0f5-2f11a65e5cde","type":"code","position":"aC","content":{"language":"java","code":"public class Main {\n    static final int MOD = 1_000_000_007;\n\n    static long power(long base, long exp, long mod) {      // fast exponentiation, O(log exp)\n        long result = 1;\n        base %= mod;\n        while (exp > 0) {\n            if ((exp & 1) == 1) result = result * base % mod;\n            base = base * base % mod;\n            exp >>= 1;\n        }\n        return result;\n    }\n\n    public static void main(String[] args) {\n        int a = 1_000_000;\n        System.out.println(a * a);              // int overflow, silently wraps\n        System.out.println((long) a * a);       // widen BEFORE multiplying\n        System.out.println((long) (a * a));     // too late: already overflowed\n        System.out.println(power(2, 1_000_000_000L, MOD));\n        System.out.println(Math.floorMod(-7, 3) + \" \" + (-7 % 3));   // % keeps the sign\n    }\n}","filename":"Java"},"revision":1},{"id":"32dff4b4-087c-73a7-bb11-6dca48056928","type":"code","position":"aD","content":{"language":"text","code":"-727379968\n1000000000000\n-727379968\n140625001\n2 -1","filename":"Output"},"revision":1},{"id":"9a332cff-1878-7668-a4a2-1eb37547fd1b","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"The Arrays.sort(int[]) trap"}]},"revision":1},{"id":"ee3d1a4f-6fc4-7840-beb7-134ae527cdc8","type":"callout","position":"aF","content":{"variant":"warning","title":"Hackable sort","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrays.sort(int[])","marks":[{"type":"code"}]},{"type":"text","text":" uses dual-pivot quicksort: O(n log n) on average but "},{"type":"text","text":"O(n²) on adversarial input","marks":[{"type":"bold"}]},{"type":"text","text":", and contest “anti-Java” tests exploit that. "},{"type":"text","text":"Arrays.sort(Object[])","marks":[{"type":"code"}]},{"type":"text","text":" (e.g. "},{"type":"text","text":"Integer[]","marks":[{"type":"code"}]},{"type":"text","text":") uses TimSort, which is always O(n log n)."}]}]}},"revision":1},{"id":"401fa6e1-4eba-7748-9861-cc8597ae485e","type":"code","position":"aG","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static void safeSort(int[] a) {\n        Random rnd = new Random(42);\n        for (int i = a.length - 1; i > 0; i--) {       // shuffle first → no adversarial order\n            int j = rnd.nextInt(i + 1);\n            int tmp = a[i]; a[i] = a[j]; a[j] = tmp;\n        }\n        Arrays.sort(a);\n    }\n\n    public static void main(String[] args) {\n        int[] a = {5, 1, 4, 2, 3};\n        safeSort(a);\n        System.out.println(Arrays.toString(a));\n\n        Integer[] boxed = {5, 1, 4, 2, 3};             // alternative: object sort = TimSort\n        Arrays.sort(boxed, Collections.reverseOrder());\n        System.out.println(Arrays.toString(boxed));\n    }\n}","filename":"Java"},"revision":1},{"id":"f30d642a-8cd0-77a9-8900-bd39677e9089","type":"code","position":"aH","content":{"language":"text","code":"[1, 2, 3, 4, 5]\n[5, 4, 3, 2, 1]","filename":"Output"},"revision":1},{"id":"0793c217-5bf1-771e-a972-7f3576ccf8be","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Contest checklist"}]},"revision":1},{"id":"dd854c95-3596-727a-80e1-962d7ad89d22","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Class name: most judges require "},{"type":"text","text":"public class Main","marks":[{"type":"code"}]},{"type":"text","text":" (Codeforces accepts any; check the rules)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":" for sums, products and anything that can exceed ~2.1 × 10⁹."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursion depth > ~10⁴ may overflow the default stack — iterate, or run the solver in "},{"type":"text","text":"new Thread(null, task, \"\", 1 << 26)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":" over "},{"type":"text","text":"Stack","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"LinkedList","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"int[]","marks":[{"type":"code"}]},{"type":"text","text":" over "},{"type":"text","text":"List<Integer>","marks":[{"type":"code"}]},{"type":"text","text":" in hot loops (boxing is slow)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare boxed values with "},{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"Integer == Integer","marks":[{"type":"code"}]},{"type":"text","text":" fails above 127."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Flush "},{"type":"text","text":"PrintWriter","marks":[{"type":"code"}]},{"type":"text","text":" at the end (or use "},{"type":"text","text":"try-with-resources","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}]}]}},"revision":1},{"id":"41fc0a5a-54a5-7ac3-a191-db7a4599048d","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is BufferedReader faster than Scanner?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BufferedReader","marks":[{"type":"code"}]},{"type":"text","text":" reads large chunks and hands back raw lines; "},{"type":"text","text":"StringTokenizer","marks":[{"type":"code"}]},{"type":"text","text":" splits on whitespace with a simple loop. "},{"type":"text","text":"Scanner","marks":[{"type":"code"}]},{"type":"text","text":" has a smaller buffer and parses every token with regular expressions and locale-aware number parsing, which is several times slower on large inputs."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
