  ('8b4c9417-03ed-78a3-a9aa-7a585385584e', 'a2', 'table', '{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Hashtable","marks":[{"type":"code"}]}],[{"type":"text","text":"Collections.synchronizedMap","marks":[{"type":"code"}]}],[{"type":"text","text":"ConcurrentHashMap","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Locking"}],[{"type":"text","text":"Every method locks the whole table"}],[{"type":"text","text":"Every method locks one mutex"}],[{"type":"text","text":"CAS + per-bin locks; reads are lock-free"}]],[[{"type":"text","text":"Concurrent reads/writes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" keys/values"}],[{"type":"text","text":"Not allowed"}],[{"type":"text","text":"Allowed (if the backing map allows)"}],[{"type":"text","text":"Not allowed","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"Iteration while modifying"}],[{"type":"text","text":"Fail-fast"}],[{"type":"text","text":"Must lock manually; else CME"}],[{"type":"text","text":"Weakly consistent, never throws CME"}]],[[{"type":"text","text":"Atomic compound ops"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"merge","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"compute","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"putIfAbsent","marks":[{"type":"code"}]},{"type":"text","text":"…"}]],[[{"type":"text","text":"Status"}],[{"type":"text","text":"Legacy"}],[{"type":"text","text":"Simple wrapper"}],[{"type":"text","text":"Default choice"}]]]}'),
  ('65679d21-1e58-78ca-912e-34b9b577358b', 'a3', 'code', '{"language":"java","code":"import java.util.List;\nimport java.util.TreeMap;\nimport java.util.concurrent.ConcurrentHashMap;\n\npublic class Main {\n    public static void main(String[] args) throws InterruptedException {\n        ConcurrentHashMap<String, Integer> counts = new ConcurrentHashMap<>();\n        List<String> words = List.of(\"a\", \"b\", \"a\", \"c\", \"a\", \"b\");\n\n        Runnable countAll = () -> { for (String w : words) counts.merge(w, 1, Integer::sum); };  // atomic\n        Thread[] ts = new Thread[4];\n        for (int i = 0; i < ts.length; i++) (ts[i] = new Thread(countAll)).start();\n        for (Thread t : ts) t.join();\n\n        System.out.println(new TreeMap<>(counts));     // sorted for display\n        counts.computeIfAbsent(\"d\", k -> 0);\n        counts.compute(\"d\", (k, v) -> v + 100);\n        System.out.println(\"d = \" + counts.get(\"d\") + \", size = \" + counts.size());\n    }\n}","filename":"Java"}'),
  ('6ec8e623-c21e-75c5-8887-5b3a9d29ad7f', 'a4', 'code', '{"language":"text","code":"{a=12, b=8, c=4}\nd = 100, size = 4","filename":"Output"}'),
  ('3c12e33e-48b1-7a3a-8777-0e274b5b75f6', 'a5', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"if (!map.containsKey(k)) map.put(k, v);","marks":[{"type":"code"}]},{"type":"text","text":" is a check-then-act race even on a "},{"type":"text","text":"ConcurrentHashMap","marks":[{"type":"code"}]},{"type":"text","text":" — each call is atomic, the pair is not. Use "},{"type":"text","text":"putIfAbsent","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"computeIfAbsent","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"merge","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('187b795f-e70d-7f69-b805-8edea786b09a', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Atomic variables and CAS"}]}'),
  ('3c06c06b-2a09-7e44-8f08-051ae556b218', 'a7', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CAS (compare-and-swap)","marks":[{"type":"bold"}]},{"type":"text","text":" — a single CPU instruction: "},{"type":"text","text":"if the value is still ","marks":[{"type":"italic"}]},{"type":"text","text":"expected","marks":[{"type":"italic"},{"type":"code"}]},{"type":"text","text":", set it to ","marks":[{"type":"italic"}]},{"type":"text","text":"new","marks":[{"type":"italic"},{"type":"code"}]},{"type":"text","text":". Atomic classes retry CAS in a loop, giving lock-free thread safety for single variables."}]}]}}'),
  ('84eef439-e242-7cec-b862-8abce7fe828d', 'a8', 'code', '{"language":"java","code":"import java.util.concurrent.atomic.AtomicInteger;\nimport java.util.concurrent.atomic.LongAdder;\n\npublic class Main {\n    public static void main(String[] args) throws InterruptedException {\n        AtomicInteger a = new AtomicInteger(5);\n        System.out.println(a.compareAndSet(5, 10) + \" \" + a.get());   // expected 5: swap\n        System.out.println(a.compareAndSet(5, 20) + \" \" + a.get());   // stale expectation: no swap\n        System.out.println(a.updateAndGet(x -> x * 3));\n        System.out.println(a.getAndIncrement() + \" then \" + a.get());\n\n        AtomicInteger hits = new AtomicInteger();\n        LongAdder adder = new LongAdder();\n        Runnable work = () -> {\n            for (int i = 0; i < 10_000; i++) { hits.incrementAndGet(); adder.increment(); }\n        };\n        Thread[] ts = new Thread[4];\n        for (int i = 0; i < ts.length; i++) (ts[i] = new Thread(work)).start();\n        for (Thread t : ts) t.join();\n        System.out.println(\"AtomicInteger = \" + hits.get() + \", LongAdder = \" + adder.sum());\n    }\n}","filename":"Java"}'),
  ('c5adec9e-e8de-7398-b3d6-ede7df361d3b', 'a9', 'code', '{"language":"text","code":"true 10\nfalse 10\n30\n30 then 31\nAtomicInteger = 40000, LongAdder = 40000","filename":"Output"}'),
  ('1bd68125-da63-7ffd-b173-af75e636b5a9', 'aA', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Class"}],[{"type":"text","text":"Use"}]],[[{"type":"text","text":"AtomicInteger","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"AtomicLong","marks":[{"type":"code"}]}],[{"type":"text","text":"Counters, sequence numbers, "},{"type":"text","text":"compareAndSet","marks":[{"type":"code"}]},{"type":"text","text":" state machines"}]],[[{"type":"text","text":"AtomicBoolean","marks":[{"type":"code"}]}],[{"type":"text","text":"Run-once flags ("},{"type":"text","text":"if (started.compareAndSet(false, true))","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"AtomicReference<V>","marks":[{"type":"code"}]}],[{"type":"text","text":"Swap an immutable object atomically"}]],[[{"type":"text","text":"LongAdder","marks":[{"type":"code"}]}],[{"type":"text","text":"Hot counters under heavy contention — cells per thread, summed on read"}]],[[{"type":"text","text":"AtomicIntegerArray","marks":[{"type":"code"}]}],[{"type":"text","text":"Per-index atomic updates"}]]]}'),
  ('176223e2-2228-7440-8db5-c524287359e9', 'aB', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ABA problem: CAS only checks the "},{"type":"text","text":"value","marks":[{"type":"italic"}]},{"type":"text","text":", so A → B → A looks unchanged. When it matters (lock-free stacks), use "},{"type":"text","text":"AtomicStampedReference","marks":[{"type":"code"}]},{"type":"text","text":", which pairs the reference with a version stamp."}]}]}}'),
