  ('9cfa2377-4ec1-7a3e-b864-05fcce267ae9', 'aD', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An explicit "},{"type":"text","text":"Lock","marks":[{"type":"code"}]},{"type":"text","text":" does what "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":" does plus: try without blocking, time out, be interrupted while waiting, optional fairness, and several wait-sets ("},{"type":"text","text":"Condition","marks":[{"type":"code"}]},{"type":"text","text":"s) per lock."}]}]}}'),
  ('7795e898-bf7e-7e46-8dc0-119bc663fcee', 'aE', 'code', '{"language":"java","code":"import java.util.concurrent.locks.ReentrantLock;\n\npublic class Main {\n    public static void main(String[] args) throws InterruptedException {\n        ReentrantLock lock = new ReentrantLock();\n        lock.lock();                                   // main holds it\n        try {\n            Thread t = new Thread(() -> System.out.println(\"worker tryLock: \" + lock.tryLock()));\n            t.start();\n            t.join();\n        } finally {\n            lock.unlock();                             // ALWAYS unlock in finally\n        }\n        Thread t2 = new Thread(() -> {\n            if (lock.tryLock()) {\n                try { System.out.println(\"worker tryLock after unlock: true\"); }\n                finally { lock.unlock(); }\n            }\n        });\n        t2.start();\n        t2.join();\n        System.out.println(\"held now? \" + lock.isLocked());\n    }\n}","filename":"Java"}'),
  ('374acb12-ef58-7cfe-8da5-fa90c8a2dcc4', 'aF', 'code', '{"language":"text","code":"worker tryLock: false\nworker tryLock after unlock: true\nheld now? false","filename":"Output"}'),
  ('863acec7-a716-7b45-9ea0-e41f03658d5d', 'aG', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Deque;\nimport java.util.concurrent.locks.Condition;\nimport java.util.concurrent.locks.ReentrantLock;\n\nclass LockBuffer<T> {\n    private final Deque<T> items = new ArrayDeque<>();\n    private final int capacity;\n    private final ReentrantLock lock = new ReentrantLock();\n    private final Condition notFull = lock.newCondition();    // two separate wait-sets\n    private final Condition notEmpty = lock.newCondition();\n\n    LockBuffer(int capacity) { this.capacity = capacity; }\n\n    void put(T x) throws InterruptedException {\n        lock.lock();\n        try {\n            while (items.size() == capacity) notFull.await();\n            items.addLast(x);\n            notEmpty.signal();              // wake only a consumer\n        } finally {\n            lock.unlock();\n        }\n    }\n\n    T take() throws InterruptedException {\n        lock.lock();\n        try {\n            while (items.isEmpty()) notEmpty.await();\n            T x = items.removeFirst();\n            notFull.signal();               // wake only a producer\n            return x;\n        } finally {\n            lock.unlock();\n        }\n    }\n}","filename":"Java — Condition (compile-checked)"}'),
  ('31fcd274-c3bc-72cd-8fcb-3e4be3dbe303', 'aH', 'table', '{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"synchronized","marks":[{"type":"code"}]}],[{"type":"text","text":"ReentrantLock","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Release"}],[{"type":"text","text":"Automatic at block end"}],[{"type":"text","text":"Manual "},{"type":"text","text":"unlock()","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"finally","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Try / timeout"}],[{"type":"text","text":"No"}],[{"type":"text","text":"tryLock()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"tryLock(t, unit)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Interruptible wait for lock"}],[{"type":"text","text":"No"}],[{"type":"text","text":"lockInterruptibly()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Fairness"}],[{"type":"text","text":"No"}],[{"type":"text","text":"new ReentrantLock(true)","marks":[{"type":"code"}]},{"type":"text","text":" (FIFO-ish, slower)"}]],[[{"type":"text","text":"Conditions"}],[{"type":"text","text":"One wait-set ("},{"type":"text","text":"wait","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"notify","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Many ("},{"type":"text","text":"newCondition()","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Reentrant"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}]]]}'),
  ('cff56fcc-c288-7705-9d76-87dd7af54731', 'aI', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ReentrantReadWriteLock","marks":[{"type":"code"}]},{"type":"text","text":" lets many readers in at once but writers alone — good for read-mostly data. "},{"type":"text","text":"StampedLock","marks":[{"type":"code"}]},{"type":"text","text":" (Java 8) adds optimistic reads for even cheaper read paths."}]}]}}'),
