  ('271db09a-569b-7ec8-b514-f68750d80db7', 'aK', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Tool"}],[{"type":"text","text":"What it does"}],[{"type":"text","text":"Reusable?"}],[{"type":"text","text":"Typical use"}]],[[{"type":"text","text":"CountDownLatch(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"await()","marks":[{"type":"code"}]},{"type":"text","text":" blocks until "},{"type":"text","text":"countDown()","marks":[{"type":"code"}]},{"type":"text","text":" was called "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" times"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Wait for N services to start / N tasks to finish"}]],[[{"type":"text","text":"CyclicBarrier(n, action)","marks":[{"type":"code"}]}],[{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" threads wait for each other, then all continue"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Phased parallel algorithms"}]],[[{"type":"text","text":"Semaphore(permits)","marks":[{"type":"code"}]}],[{"type":"text","text":"acquire()","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"release()","marks":[{"type":"code"}]},{"type":"text","text":" permits"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Limit concurrency (max 10 DB connections)"}]],[[{"type":"text","text":"Phaser","marks":[{"type":"code"}]}],[{"type":"text","text":"Flexible barrier with dynamic parties"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Multi-phase work with join/leave"}]],[[{"type":"text","text":"Exchanger","marks":[{"type":"code"}]}],[{"type":"text","text":"Two threads swap objects"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Pipeline buffers"}]]]}'),
