SELECT 'a58a79ce-7287-798a-8485-1cdf66725cc0', 'd7c7e950-e8a3-765d-b81d-6985b54bb1c3', 1, 'PUBLISHED', 'Constructors & Initialization Order', '[{"id":"712e1324-b7f8-770a-a1ca-569669a1fa55","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A constructor initialises a new object. Java runs static setup once per class and then a fixed sequence for every "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"58eace7c-598d-707f-85ef-818e137543b7","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Constructor","marks":[{"type":"bold"}]},{"type":"text","text":" — a special member with the class''s name and "},{"type":"text","text":"no return type","marks":[{"type":"bold"}]},{"type":"text","text":" that runs when "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" creates an object. It is not inherited and cannot be "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"abstract","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"c0e5c136-e334-717c-9e56-7f0d43e9dd04","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Kinds of constructors"}]},"revision":1},{"id":"e0d9ac0d-ba98-7072-9678-e2a3460732e2","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Kind"}],[{"type":"text","text":"What it is"}]],[[{"type":"text","text":"Default","marks":[{"type":"bold"}]}],[{"type":"text","text":"Added by the compiler "},{"type":"text","text":"only if you write no constructor at all","marks":[{"type":"italic"}]},{"type":"text","text":": no args, calls "},{"type":"text","text":"super()","marks":[{"type":"code"}]},{"type":"text","text":"."}]],[[{"type":"text","text":"No-arg","marks":[{"type":"bold"}]}],[{"type":"text","text":"One you write yourself with no parameters."}]],[[{"type":"text","text":"Parameterized","marks":[{"type":"bold"}]}],[{"type":"text","text":"Takes arguments to set up state."}]],[[{"type":"text","text":"Copy","marks":[{"type":"bold"}]}],[{"type":"text","text":"Takes another instance of the same class: "},{"type":"text","text":"Point(Point other)","marks":[{"type":"code"}]},{"type":"text","text":" (Java has no built-in copy constructor)."}]],[[{"type":"text","text":"Private","marks":[{"type":"bold"}]}],[{"type":"text","text":"Prevents outside "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" — singletons, factories, utility classes."}]]]},"revision":1},{"id":"91542bfe-e365-71e5-8cbe-1afc48861427","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Overloading and chaining with "},{"type":"text","text":"this(...)","marks":[{"type":"code"}]}]},"revision":1},{"id":"ca7ca9dc-8b74-7397-9dd6-95b236976f27","type":"code","position":"a5","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(new Pizza());\n        System.out.println(new Pizza(\"large\"));\n        System.out.println(new Pizza(\"small\", 3));\n    }\n}\n\nclass Pizza {\n    private final String size;\n    private final int toppings;\n\n    Pizza() { this(\"medium\"); }                 // delegates\n    Pizza(String size) { this(size, 1); }       // delegates\n    Pizza(String size, int toppings) {          // the one \"real\" constructor\n        this.size = size;\n        this.toppings = toppings;\n    }\n\n    @Override public String toString() { return size + \" pizza, \" + toppings + \" topping(s)\"; }\n}","filename":"Java"},"revision":1},{"id":"452693e1-440d-7131-a294-6a2fec85af40","type":"code","position":"a6","content":{"language":"text","code":"medium pizza, 1 topping(s)\nlarge pizza, 1 topping(s)\nsmall pizza, 3 topping(s)","filename":"Output"},"revision":1},{"id":"537042af-9302-7a08-a788-d9eb3e9a685b","type":"callout","position":"a7","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"this(...)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"super(...)","marks":[{"type":"code"}]},{"type":"text","text":" must be the "},{"type":"text","text":"first statement","marks":[{"type":"bold"}]},{"type":"text","text":" of a constructor, and you can use only one of them. If you write neither, the compiler inserts "},{"type":"text","text":"super()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d4c003ca-3ee0-7cb7-8cc6-1fc3da3f8829","type":"callout","position":"a8","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Writing "},{"type":"text","text":"any","marks":[{"type":"italic"}]},{"type":"text","text":" constructor removes the free default one. "},{"type":"text","text":"class A { A(int x) {} }","marks":[{"type":"code"}]},{"type":"text","text":" means "},{"type":"text","text":"new A()","marks":[{"type":"code"}]},{"type":"text","text":" no longer compiles — a common surprise with frameworks (JPA, Jackson) that need a no-arg constructor."}]}]}},"revision":1},{"id":"876a9b37-d82d-763f-aaaf-ef45fa2d5c2a","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Initializer blocks"}]},"revision":1},{"id":"adecc739-a954-7194-959c-2708bc96a506","type":"callout","position":"aA","content":{"variant":"note","title":"Static initializer static { … }","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runs "},{"type":"text","text":"once","marks":[{"type":"bold"}]},{"type":"text","text":", when the class is initialised (first active use). For complex static setup."}]}]}},"revision":1},{"id":"9c58de0f-c36c-70df-b2c0-d616778db300","type":"callout","position":"aB","content":{"variant":"note","title":"Instance initializer { … }","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runs on "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":", before the constructor body — the compiler copies it into each constructor after "},{"type":"text","text":"super()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"98582464-e38b-7494-97a7-274cbf615e63","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"The full initialization order"}]},"revision":1},{"id":"f90a5425-621b-7dde-a8ce-30b467e028e4","type":"code","position":"aD","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(\"-- first new Child()\");\n        new Child();\n        System.out.println(\"-- second new Child()\");\n        new Child();\n    }\n}\n\nclass Parent {\n    static { System.out.println(\"1. Parent static block\"); }\n    { System.out.println(\"3. Parent instance block\"); }\n    Parent() { System.out.println(\"4. Parent constructor\"); }\n}\n\nclass Child extends Parent {\n    static { System.out.println(\"2. Child static block\"); }\n    private String name = init();\n    { System.out.println(\"6. Child instance block\"); }\n    Child() { System.out.println(\"7. Child constructor\"); }\n\n    private String init() { System.out.println(\"5. Child field initializer\"); return \"child\"; }\n}","filename":"Java"},"revision":1},{"id":"067958fd-9242-71fb-a5da-3fe7e036fe5a","type":"code","position":"aE","content":{"language":"text","code":"-- first new Child()\n1. Parent static block\n2. Child static block\n3. Parent instance block\n4. Parent constructor\n5. Child field initializer\n6. Child instance block\n7. Child constructor\n-- second new Child()\n3. Parent instance block\n4. Parent constructor\n5. Child field initializer\n6. Child instance block\n7. Child constructor","filename":"Output"},"revision":1},{"id":"6619863e-5ac0-7238-aef7-158ba33e3cf5","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Static, parent first","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Superclass static fields/blocks, then subclass static fields/blocks — once per class, in textual order."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parent instance part","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"super(...)","marks":[{"type":"code"}]},{"type":"text","text":" runs first: parent field initialisers + instance blocks (textual order), then parent constructor body."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Child instance part","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Child field initialisers + instance blocks in textual order, then the child constructor body."}]}]}]}]}},"revision":1},{"id":"cbd47d7a-1930-7df7-8802-26072b43314f","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Pitfall: calling an overridable method from a constructor"}]},"revision":1},{"id":"5cd3a6f4-e0b4-7322-ad38-877e1cf31acf","type":"code","position":"aH","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        new Sub();\n    }\n}\n\nclass Base {\n    Base() { describe(); }            // dynamic dispatch — calls Sub.describe()\n    void describe() { System.out.println(\"Base\"); }\n}\n\nclass Sub extends Base {\n    private String label = \"ready\";\n    @Override void describe() { System.out.println(\"Sub label = \" + label); }\n}","filename":"Java"},"revision":1},{"id":"c78f1f44-913d-7b41-bdc9-8db2ec5a5c75","type":"code","position":"aI","content":{"language":"text","code":"Sub label = null","filename":"Output"},"revision":1},{"id":"934bc574-d5dc-79d3-8cf9-81b3f95131d4","type":"callout","position":"aJ","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The subclass override runs "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" the subclass''s fields are initialised, so it sees "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":". Never call overridable methods from a constructor — make them "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ae2cfc36-ec5d-7555-ba35-56992fb521d9","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can a constructor be private? Why would you do that?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes. It stops other classes from calling "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" — used for singletons, static factory methods ("},{"type":"text","text":"List.of","marks":[{"type":"code"}]},{"type":"text","text":"), and utility classes like "},{"type":"text","text":"Math","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Collections","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0be91f0a-0a93-7880-a02a-af616ccc78c3","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is a constructor inherited? Can it be overridden?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Neither. Constructors are not members that are inherited, so they cannot be overridden. A subclass must call a superclass constructor (implicitly "},{"type":"text","text":"super()","marks":[{"type":"code"}]},{"type":"text","text":" or explicitly "},{"type":"text","text":"super(args)","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"bfd69973-b812-7322-a0e4-5ec98d27f5ff","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can a constructor return a value or be final/static?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No return type at all (writing "},{"type":"text","text":"void","marks":[{"type":"code"}]},{"type":"text","text":" turns it into an ordinary method with the class''s name!). It cannot be "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"abstract","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"c335f898-67df-7e33-ba15-74d18bf96a2b","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In what order do static blocks, instance blocks and constructors run?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Static blocks: once per class, parent before child. Then for each "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":": parent instance initialisers → parent constructor → child instance initialisers (fields and blocks in source order) → child constructor."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
