SELECT '2929af2c-7d1f-7446-bdf6-4e107639b44a', 'f58c85f4-7a80-7926-8be9-cd17d1343fed', 1, 'PUBLISHED', 'Conditionals & Loops', '[{"id":"a3dc629a-3e5d-70c7-92f8-ac9605c826cb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"if","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"else","marks":[{"type":"code"}]},{"type":"text","text":", the ternary operator and four loop forms — plus labeled "},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"continue","marks":[{"type":"code"}]},{"type":"text","text":" for nested loops."}]}]}},"revision":1},{"id":"c4b0c35c-36e3-7ef7-8cad-0d53a9c54f8a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"if / else if / else"}]},"revision":1},{"id":"4c505dbb-ab1d-7abf-9c48-b2f1c6ad0d64","type":"code","position":"a2","content":{"language":"java","code":"public class Main {\n    static String grade(int score) {\n        if (score >= 90) return \"A\";\n        else if (score >= 75) return \"B\";\n        else if (score >= 50) return \"C\";\n        else return \"F\";\n    }\n\n    public static void main(String[] args) {\n        System.out.println(grade(95) + grade(80) + grade(60) + grade(10));\n        int n = 7;\n        String parity = (n % 2 == 0) ? \"even\" : \"odd\";     // ternary: an expression\n        System.out.println(n + \" is \" + parity);\n    }\n}","filename":"Java"},"revision":1},{"id":"1aacc8ca-42d4-7dae-9014-bbd2503a8298","type":"code","position":"a3","content":{"language":"text","code":"ABCF\n7 is odd","filename":"Output"},"revision":1},{"id":"2052a35e-a3fc-764a-9575-ebfa647871ee","type":"callout","position":"a4","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Conditions must be "},{"type":"text","text":"boolean","marks":[{"type":"code"}]},{