SELECT '455f2126-90bc-7cf9-a0f5-df506e9c69a3', 'd609fb0f-6de6-7406-9f9b-81969041cb82', 1, 'PUBLISHED', 'Custom Exceptions & Best Practices', '[{"id":"58778bc7-98cd-73ce-8c3e-4b219b2f3394","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Define your own exception types when callers need to react to a specific failure — and always keep the original cause attached."}]}]}},"revision":1},{"id":"2df29b93-be13-7a84-8561-fcdbfc386e83","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Defining one"}]},"revision":1},{"id":"83582f49-cfce-7242-99fa-9c0b756bd2b2","type":"code","position":"a2","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        Account acc = new Account(100);\n        try {\n            acc.withdraw(30);\n            acc.withdraw(500);\n        } catch (InsufficientFundsException e) {\n            System.out.println(e.getMessage());\n            System.out.println(\"short by \" + e.shortfall());\n        }\n    }\n}\n\n// Checked: the caller can reasonably recover (show a message, offer a smaller amount)\nclass InsufficientFundsException extends Exception {\n    private final long shortfall;\n    InsufficientFundsException(long balance, long requested) {\n        super(\"balance \" + balance + \" < requested \" + requested);\n        this.shortfall = requested - balance;\n    }\n    long shortfall() { return shortfall; }\n}\n\nclass Account {\n    private long balance;\n    Account(long balance) { this.balance = balance; }\n    void withdraw(long amount) throws InsufficientFundsException {\n        if (amount <= 0) throw new IllegalArgumentException(\"amount must be positive\");  // bug → unchecked\n        if (amount > balance) throw new InsufficientFundsException(balance, amount);\n        balance -= amount;\n    }\n}","filename":"Java"},"revision":1},{"id":"c5f5013a-0187-7690-8893-b3e84af2d408","type":"code","position":"a3","content":{"language":"text","code":"balance 70 < requested 500\nshort by 430","filename":"Output"},"revision":1},{"id":"f380b616-3d60-7cd8-84b8-5cc5901e5eaf","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Checked or unchecked?"}]},"revision":1},{"id":"7f81c7d8-9c9e-79ff-b238-72d899e475a4","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Choose"}],[{"type":"text","text":"When"}],[{"type":"text","text":"Extend"}]],[[{"type":"text","text":"Checked","marks":[{"type":"bold"}]}],[{"type":"text","text":"The caller can and should recover: file missing, payment declined, validation of external input"}],[{"type":"text","text":"Exception","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Unchecked","marks":[{"type":"bold"}]}],[{"type":"text","text":"Programming errors / violated preconditions, or failures nobody nearby can handle"}],[{"type":"text","text":"RuntimeException","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"af506b60-767a-7399-9095-50bdd28de5db","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern code (Spring, most libraries, lambdas and streams) leans unchecked: checked exceptions don''t compose with functional interfaces like "},{"type":"text","text":"Function","marks":[{"type":"code"}]},{"type":"text","text":", and they leak implementation details up the call chain."}]}]}},"revision":1},{"id":"238bc4cc-497f-7680-9671-a191424d3a43","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Exception chaining: keep the cause"}]},"revision":1},{"id":"0d7e4a52-6f7c-797a-a22e-44203de0efd3","type":"code","position":"a8","content":{"language":"java","code":"public class Main {\n    static class ConfigException extends RuntimeException {\n        ConfigException(String msg, Throwable cause) { super(msg, cause); }\n    }\n\n    static int loadPort(String raw) {\n        try {\n            return Integer.parseInt(raw);\n        } catch (NumberFormatException e) {\n            throw new ConfigException(\"invalid port in config: \" + raw, e);   // wrap, keep cause\n        }\n    }\n\n    public static void main(String[] args) {\n        try {\n            loadPort(\"80a\");\n        } catch (ConfigException e) {\n            System.out.println(e.getMessage());\n            System.out.println(\"caused by \" + e.getCause().getClass().getSimpleName()\n                               + \": \" + e.getCause().getMessage());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"7695b995-a33a-745f-9899-6f98b008bf74","type":"code","position":"a9","content":{"language":"text","code":"invalid port in config: 80a\ncaused by NumberFormatException: For input string: \"80a\"","filename":"Output"},"revision":1},{"id":"a8f47907-3ec0-7198-95bd-3e4ce96248ba","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Translate low-level exceptions into ones that match your layer''s abstraction (a repository throws "},{"type":"text","text":"DataAccessException","marks":[{"type":"code"}]},{"type":"text","text":", not "},{"type":"text","text":"SQLException","marks":[{"type":"code"}]},{"type":"text","text":") — but pass the original as the "},{"type":"text","text":"cause","marks":[{"type":"bold"}]},{"type":"text","text":" so the stack trace still shows the root problem ("},{"type":"text","text":"Caused by: …","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"df32eb11-7111-7750-b921-fbcf00003780","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Anti-patterns"}]},"revision":1},{"id":"f7e59805-ef95-796e-8f4d-08b0f330762b","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Anti-pattern"}],[{"type":"text","text":"Why it hurts"}],[{"type":"text","text":"Instead"}]],[[{"type":"text","text":"catch (Exception e) {}","marks":[{"type":"code"}]}],[{"type":"text","text":"Swallows the failure — the bug disappears silently"}],[{"type":"text","text":"Handle it, or let it propagate"}]],[[{"type":"text","text":"e.printStackTrace()","marks":[{"type":"code"}]},{"type":"text","text":" and continue"}],[{"type":"text","text":"Output goes to stderr, program runs on with bad state"}],[{"type":"text","text":"Log with a logger and rethrow/handle"}]],[[{"type":"text","text":"throw new RuntimeException(e.getMessage())","marks":[{"type":"code"}]}],[{"type":"text","text":"Loses the original type and stack trace"}],[{"type":"text","text":"throw new XException(\"context\", e)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Catch-log-rethrow at every layer"}],[{"type":"text","text":"The same error is logged five times"}],[{"type":"text","text":"Log once, where it''s handled"}]],[[{"type":"text","text":"Exceptions for control flow"}],[{"type":"text","text":"Slow (stack trace capture) and hides intent"}],[{"type":"text","text":"Use "},{"type":"text","text":"if","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Optional","marks":[{"type":"code"}]},{"type":"text","text":", return values"}]],[[{"type":"text","text":"throws Exception","marks":[{"type":"code"}]},{"type":"text","text":" on every method"}],[{"type":"text","text":"Callers can''t tell what can go wrong"}],[{"type":"text","text":"Declare specific types"}]],[[{"type":"text","text":"Catching "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]}],[{"type":"text","text":"Masks a bug"}],[{"type":"text","text":"Fix the null source / validate early"}]]]},"revision":1},{"id":"03822879-5954-7c3b-a1e6-377e65be352b","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Best practices"}]},"revision":1},{"id":"c4765a1f-44da-7e37-a29f-6b2a346859c2","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fail fast","marks":[{"type":"bold"}]},{"type":"text","text":": validate arguments at the start of a method ("},{"type":"text","text":"Objects.requireNonNull","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IllegalArgumentException","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"standard exceptions","marks":[{"type":"bold"}]},{"type":"text","text":" when they fit: "},{"type":"text","text":"IllegalArgumentException","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IllegalStateException","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"UnsupportedOperationException","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"NoSuchElementException","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Put useful context in the message: the bad value, the id, the expected range."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Name custom types "},{"type":"text","text":"…Exception","marks":[{"type":"code"}]},{"type":"text","text":" and provide "},{"type":"text","text":"(String message)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"(String message, Throwable cause)","marks":[{"type":"code"}]},{"type":"text","text":" constructors."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Restore the interrupt flag if you catch "},{"type":"text","text":"InterruptedException","marks":[{"type":"code"}]},{"type":"text","text":" and can''t rethrow it: "},{"type":"text","text":"Thread.currentThread().interrupt();","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clean up with try-with-resources, not "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" blocks."}]}]}]}]}},"revision":1},{"id":"fd375ae7-b6b7-7c5f-99bc-ab44d38534ed","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you create a custom exception?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Extend "},{"type":"text","text":"Exception","marks":[{"type":"code"}]},{"type":"text","text":" (checked) or "},{"type":"text","text":"RuntimeException","marks":[{"type":"code"}]},{"type":"text","text":" (unchecked), add constructors that call "},{"type":"text","text":"super(message)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"super(message, cause)","marks":[{"type":"code"}]},{"type":"text","text":", and optionally add fields carrying extra context (an error code, the invalid value)."}]}]}},"revision":1},{"id":"a82b5da2-ce9b-7834-98d8-30ba6ac52246","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is exception chaining and why use it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wrapping a caught exception as the "},{"type":"text","text":"cause","marks":[{"type":"italic"}]},{"type":"text","text":" of a new, higher-level one ("},{"type":"text","text":"new ServiceException(\"…\", e)","marks":[{"type":"code"}]},{"type":"text","text":"). The API stays at the right abstraction level while the full root cause remains available via "},{"type":"text","text":"getCause()","marks":[{"type":"code"}]},{"type":"text","text":" and in the "},{"type":"text","text":"Caused by:","marks":[{"type":"code"}]},{"type":"text","text":" part of the stack trace."}]}]}},"revision":1},{"id":"cc47a579-08a9-7c7d-ae53-1a0f3425f66b","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why are exceptions expensive?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Creating one captures the whole stack trace ("},{"type":"text","text":"fillInStackTrace","marks":[{"type":"code"}]},{"type":"text","text":"), which walks the stack. That''s fine for exceptional cases but wasteful as normal control flow in a hot loop."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
