SELECT 'dea085d6-89c2-7c33-9885-f12c10819f8e', '31c32cf6-acee-71f8-88a0-a008e546b747', 1, 'PUBLISHED', 'Design Patterns: Strategy, Observer & More', '[{"id":"6ffe1e65-f845-76ff-a76b-ab73fafc028b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Behavioural and structural patterns in modern Java — most of them are a lambda or a small interface away."}]}]}},"revision":1},{"id":"b144448a-5c7d-70a1-9388-13f891d76180","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Strategy"}]},"revision":1},{"id":"5e680778-f795-73de-b988-6dbf17f21543","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Strategy","marks":[{"type":"bold"}]},{"type":"text","text":" — define a family of interchangeable algorithms behind one interface and choose one at run time. With functional interfaces, each strategy is just a lambda."}]}]}},"revision":1},{"id":"e0fa925a-c533-7516-8002-6aabac484833","type":"code","position":"a3","content":{"language":"java","code":"import java.util.Map;\nimport java.util.function.DoubleUnaryOperator;\n\npublic class Main {\n    static final Map<String, DoubleUnaryOperator> DISCOUNTS = Map.of(\n            \"none\", price -> price,\n            \"festive\", price -> price * 0.8,\n            \"flat50\", price -> Math.max(0, price - 50));\n\n    static double checkout(double price, String code) {\n        return DISCOUNTS.getOrDefault(code, DISCOUNTS.get(\"none\")).applyAsDouble(price);\n    }\n\n    public static void main(String[] args) {\n        System.out.println(checkout(200, \"festive\"));\n        System.out.println(checkout(200, \"flat50\"));\n        System.out.println(checkout(200, \"bogus\"));\n    }\n}","filename":"Java"},"revision":1},{"id":"c1e64cfa-018f-73bd-a695-b7cc7f4b9784","type":"code","position":"a4","content":{"language":"text","code":"160.0\n150.0\n200.0","filename":"Output"},"revision":1},{"id":"a93b2662-006d-74d3-80e0-35dbeb0c1c7a","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Comparator","marks":[{"type":"code"}]},{"type":"text","text":" is the JDK''s best-known strategy: "},{"type":"text","text":"list.sort(Comparator.comparing(Person::age))","marks":[{"type":"code"}]},{"type":"text","text":" plugs a comparison algorithm into a sort."}]}]}},"revision":1},{"id":"a9ffb521-daf9-745f-97f3-91f08eb05dab","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Observer"}]},"revision":1},{"id":"d2c0c2bc-3866-71cf-878f-f8788cce9aad","type":"callout","position":"a7","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Observer","marks":[{"type":"bold"}]},{"type":"text","text":" — a subject keeps a list of listeners and notifies them of events; listeners don''t know about each other. The basis of event buses, GUI listeners and reactive streams."}]}]}},"revision":1},{"id":"53521784-5b40-7a68-88d5-f681c47c90a6","type":"code","position":"a8","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.function.Consumer;\n\npublic class Main {\n    static final class StockTicker {\n        private final List<Consumer<Double>> listeners = new ArrayList<>();\n\n        Runnable subscribe(Consumer<Double> l) {\n            listeners.add(l);\n            return () -> listeners.remove(l);          // handle to unsubscribe\n        }\n\n        void publish(double price) {\n            listeners.forEach(l -> l.accept(price));\n        }\n    }\n\n    public static void main(String[] args) {\n        StockTicker ticker = new StockTicker();\n        ticker.subscribe(p -> System.out.println(\"display: \" + p));\n        Runnable cancel = ticker.subscribe(p -> {\n            if (p > 100) System.out.println(\"alert: above 100\");\n        });\n\n        ticker.publish(99.5);\n        ticker.publish(101.0);\n        cancel.run();                                  // stop the alerts\n        ticker.publish(120.0);\n    }\n}","filename":"Java"},"revision":1},{"id":"3223cbfe-4e02-7160-b445-248cd99e89c8","type":"code","position":"a9","content":{"language":"text","code":"display: 99.5\ndisplay: 101.0\nalert: above 100\ndisplay: 120.0","filename":"Output"},"revision":1},{"id":"bff33788-b01f-7142-b546-009d232896ef","type":"callout","position":"aA","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forgotten subscriptions are a classic memory leak — always give listeners a way to unsubscribe. "},{"type":"text","text":"java.util.Observable","marks":[{"type":"code"}]},{"type":"text","text":" is deprecated (Java 9); use your own listener list, "},{"type":"text","text":"PropertyChangeSupport","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"java.util.concurrent.Flow","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"f7726a73-c840-74ed-85f9-b0b9a4a03605","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Decorator"}]},"revision":1},{"id":"feec2945-c915-740b-bd97-5f562cf06daa","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wrap an object in another object with the "},{"type":"text","text":"same interface","marks":[{"type":"italic"}]},{"type":"text","text":" to add behaviour. "},{"type":"text","text":"java.io","marks":[{"type":"code"}]},{"type":"text","text":" is built this way: each stream adds one feature (buffering, decoding, line reading)."}]}]}},"revision":1},{"id":"ad0528fb-aeb1-7b62-b3bc-a20c7b930684","type":"code","position":"aD","content":{"language":"java","code":"import java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.StringReader;\n\npublic class Main {\n    interface Coffee { double cost(); String describe(); }\n\n    record Espresso() implements Coffee {\n        public double cost() { return 2.0; }\n        public String describe() { return \"espresso\"; }\n    }\n\n    record WithMilk(Coffee inner) implements Coffee {\n        public double cost() { return inner.cost() + 0.5; }\n        public String describe() { return inner.describe() + \" + milk\"; }\n    }\n\n    record WithSyrup(Coffee inner) implements Coffee {\n        public double cost() { return inner.cost() + 0.75; }\n        public String describe() { return inner.describe() + \" + syrup\"; }\n    }\n\n    public static void main(String[] args) throws IOException {\n        Coffee order = new WithSyrup(new WithMilk(new Espresso()));\n        System.out.println(order.describe() + \" = \" + order.cost());\n\n        // the JDK version: a Reader decorated with buffering and readLine()\n        try (BufferedReader r = new BufferedReader(new StringReader(\"line 1\\nline 2\"))) {\n            System.out.println(r.readLine());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"3dfc01da-1397-7aaf-865e-0b220bcaf2bc","type":"code","position":"aE","content":{"language":"text","code":"espresso + milk + syrup = 3.25\nline 1","filename":"Output"},"revision":1},{"id":"0bb3c9c2-1cd5-7214-8123-47965feec45c","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Template method"}]},"revision":1},{"id":"61539cb4-803b-7149-b952-b767bcbacc77","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An abstract class fixes the "},{"type":"text","text":"skeleton","marks":[{"type":"italic"}]},{"type":"text","text":" of an algorithm in a "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":" method and lets subclasses fill in the steps."}]}]}},"revision":1},{"id":"f5ddde80-93fc-7ce7-8ef3-0cede2e219d1","type":"code","position":"aH","content":{"language":"java","code":"public class Main {\n    static abstract class Report {\n        final String render() {                      // the template — not overridable\n            return header() + \"\\n\" + body() + \"\\n-- end --\";\n        }\n        String header() { return \"REPORT\"; }         // hook with a default\n        abstract String body();                      // step subclasses must supply\n    }\n\n    static final class SalesReport extends Report {\n        @Override String body() { return \"sales: 42 units\"; }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(new SalesReport().render());\n    }\n}","filename":"Java"},"revision":1},{"id":"78debe5c-7cd5-75bb-a957-b7f780b45421","type":"code","position":"aI","content":{"language":"text","code":"REPORT\nsales: 42 units\n-- end --","filename":"Output"},"revision":1},{"id":"fe2c337f-d839-7856-bce2-eaa625cabfe3","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"Adapter"}]},"revision":1},{"id":"29879e9f-627b-7dd8-bc5b-9d8eaec57b34","type":"text","position":"aK","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Convert one interface into another that a client expects. "},{"type":"text","text":"Arrays.asList","marks":[{"type":"code"}]},{"type":"text","text":" adapts an array to "},{"type":"text","text":"List","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"InputStreamReader","marks":[{"type":"code"}]},{"type":"text","text":" adapts a byte stream to a character "},{"type":"text","text":"Reader","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"9d7c8c22-f2a9-72cc-b965-673d8d5d3b9d","type":"code","position":"aL","content":{"language":"java","code":"import java.util.function.Supplier;\n\npublic class Main {\n    static final class LegacyThermometer {                  // can''t change this class\n        double readFahrenheit() { return 98.6; }\n    }\n\n    interface CelsiusSensor { double celsius(); }\n\n    static CelsiusSensor adapt(LegacyThermometer t) {     // the adapter\n        return () -> (t.readFahrenheit() - 32) * 5 / 9;\n    }\n\n    public static void main(String[] args) {\n        CelsiusSensor s = adapt(new LegacyThermometer());\n        Supplier<String> fmt = () -> String.format(\"%.1f C\", s.celsius());\n        System.out.println(fmt.get());\n    }\n}","filename":"Java"},"revision":1},{"id":"ed71ae7a-5c55-7edf-bb0f-a9eadcdae6dd","type":"code","position":"aM","content":{"language":"text","code":"37.0 C","filename":"Output"},"revision":1},{"id":"0d3ed1ca-b706-7f14-81d1-27010c86e53f","type":"heading","position":"aN","content":{"level":1,"content":[{"type":"text","text":"Where the JDK uses them"}]},"revision":1},{"id":"46597c68-9cdb-7e8b-9fc2-1e8789359b59","type":"table","position":"aO","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Pattern"}],[{"type":"text","text":"Kind"}],[{"type":"text","text":"In the JDK"}]],[[{"type":"text","text":"Strategy"}],[{"type":"text","text":"Behavioural"}],[{"type":"text","text":"Comparator","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ThreadPoolExecutor","marks":[{"type":"code"}]},{"type":"text","text":"''s "},{"type":"text","text":"RejectedExecutionHandler","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Observer"}],[{"type":"text","text":"Behavioural"}],[{"type":"text","text":"PropertyChangeListener","marks":[{"type":"code"}]},{"type":"text","text":", Swing listeners, "},{"type":"text","text":"Flow.Subscriber","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Iterator"}],[{"type":"text","text":"Behavioural"}],[{"type":"text","text":"Iterator","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Iterable","marks":[{"type":"code"}]},{"type":"text","text":" behind every for-each loop"}]],[[{"type":"text","text":"Template method"}],[{"type":"text","text":"Behavioural"}],[{"type":"text","text":"AbstractList","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"get","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":" → everything else), "},{"type":"text","text":"InputStream.read(byte[])","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Command"}],[{"type":"text","text":"Behavioural"}],[{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Callable","marks":[{"type":"code"}]},{"type":"text","text":" submitted to executors"}]],[[{"type":"text","text":"Decorator"}],[{"type":"text","text":"Structural"}],[{"type":"text","text":"BufferedInputStream","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Collections.unmodifiableList","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"synchronizedMap","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Adapter"}],[{"type":"text","text":"Structural"}],[{"type":"text","text":"Arrays.asList","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"InputStreamReader","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"OutputStreamWriter","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Proxy"}],[{"type":"text","text":"Structural"}],[{"type":"text","text":"java.lang.reflect.Proxy","marks":[{"type":"code"}]},{"type":"text","text":" (Spring AOP, mocks)"}]],[[{"type":"text","text":"Factory / static factory"}],[{"type":"text","text":"Creational"}],[{"type":"text","text":"List.of","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Calendar.getInstance","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"NumberFormat.getInstance","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Builder"}],[{"type":"text","text":"Creational"}],[{"type":"text","text":"StringBuilder","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"HttpClient.newBuilder()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Singleton"}],[{"type":"text","text":"Creational"}],[{"type":"text","text":"Runtime.getRuntime()","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"1110e909-be1e-7aef-adde-61d4344587dd","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Strategy vs template method?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both vary part of an algorithm. Template method uses "},{"type":"text","text":"inheritance","marks":[{"type":"italic"}]},{"type":"text","text":" — subclasses override steps of a fixed skeleton. Strategy uses "},{"type":"text","text":"composition","marks":[{"type":"italic"}]},{"type":"text","text":" — the varying algorithm is an object (often a lambda) passed in, so it can change at run time and needs no subclass."}]}]}},"revision":1},{"id":"38410030-3dd8-7128-a507-a98d2ff6f1c3","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Decorator vs inheritance for adding behaviour?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inheritance fixes the combination at compile time and explodes into subclasses for every combination (MilkSyrupCoffee…). Decorators compose at run time: wrap in any order and any number, each class adding one responsibility."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
