  ('a9ffb521-daf9-745f-97f3-91f08eb05dab', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Observer"}]}'),
  ('d2c0c2bc-3866-71cf-878f-f8788cce9aad', 'a7', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Observer","marks":[{"type":"bold"}]},{"type":"text","text":" — a subject keeps a list of listeners and notifies them of events; listeners don''t know about each other. The basis of event buses, GUI listeners and reactive streams."}]}]}}'),
  ('53521784-5b40-7a68-88d5-f681c47c90a6', 'a8', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.function.Consumer;\n\npublic class Main {\n    static final class StockTicker {\n        private final List<Consumer<Double>> listeners = new ArrayList<>();\n\n        Runnable subscribe(Consumer<Double> l) {\n            listeners.add(l);\n            return () -> listeners.remove(l);          // handle to unsubscribe\n        }\n\n        void publish(double price) {\n            listeners.forEach(l -> l.accept(price));\n        }\n    }\n\n    public static void main(String[] args) {\n        StockTicker ticker = new StockTicker();\n        ticker.subscribe(p -> System.out.println(\"display: \" + p));\n        Runnable cancel = ticker.subscribe(p -> {\n            if (p > 100) System.out.println(\"alert: above 100\");\n        });\n\n        ticker.publish(99.5);\n        ticker.publish(101.0);\n        cancel.run();                                  // stop the alerts\n        ticker.publish(120.0);\n    }\n}","filename":"Java"}'),
