  ('bff33788-b01f-7142-b546-009d232896ef', 'aA', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forgotten subscriptions are a classic memory leak — always give listeners a way to unsubscribe. "},{"type":"text","text":"java.util.Observable","marks":[{"type":"code"}]},{"type":"text","text":" is deprecated (Java 9); use your own listener list, "},{"type":"text","text":"PropertyChangeSupport","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"java.util.concurrent.Flow","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('f7726a73-c840-74ed-85f9-b0b9a4a03605', 'aB', 'heading', '{"level":1,"content":[{"type":"text","text":"Decorator"}]}'),
  ('feec2945-c915-740b-bd97-5f562cf06daa', 'aC', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wrap an object in another object with the "},{"type":"text","text":"same interface","marks":[{"type":"italic"}]},{"type":"text","text":" to add behaviour. "},{"type":"text","text":"java.io","marks":[{"type":"code"}]},{"type":"text","text":" is built this way: each stream adds one feature (buffering, decoding, line reading)."}]}]}}'),
  ('ad0528fb-aeb1-7b62-b3bc-a20c7b930684', 'aD', 'code', '{"language":"java","code":"import java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.StringReader;\n\npublic class Main {\n    interface Coffee { double cost(); String describe(); }\n\n    record Espresso() implements Coffee {\n        public double cost() { return 2.0; }\n        public String describe() { return \"espresso\"; }\n    }\n\n    record WithMilk(Coffee inner) implements Coffee {\n        public double cost() { return inner.cost() + 0.5; }\n        public String describe() { return inner.describe() + \" + milk\"; }\n    }\n\n    record WithSyrup(Coffee inner) implements Coffee {\n        public double cost() { return inner.cost() + 0.75; }\n        public String describe() { return inner.describe() + \" + syrup\"; }\n    }\n\n    public static void main(String[] args) throws IOException {\n        Coffee order = new WithSyrup(new WithMilk(new Espresso()));\n        System.out.println(order.describe() + \" = \" + order.cost());\n\n        // the JDK version: a Reader decorated with buffering and readLine()\n        try (BufferedReader r = new BufferedReader(new StringReader(\"line 1\\nline 2\"))) {\n            System.out.println(r.readLine());\n        }\n    }\n}","filename":"Java"}'),
