  ('0bb3c9c2-1cd5-7214-8123-47965feec45c', 'aF', 'heading', '{"level":1,"content":[{"type":"text","text":"Template method"}]}'),
  ('61539cb4-803b-7149-b952-b767bcbacc77', 'aG', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An abstract class fixes the "},{"type":"text","text":"skeleton","marks":[{"type":"italic"}]},{"type":"text","text":" of an algorithm in a "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":" method and lets subclasses fill in the steps."}]}]}}'),
  ('f5ddde80-93fc-7ce7-8ef3-0cede2e219d1', 'aH', 'code', '{"language":"java","code":"public class Main {\n    static abstract class Report {\n        final String render() {                      // the template — not overridable\n            return header() + \"\\n\" + body() + \"\\n-- end --\";\n        }\n        String header() { return \"REPORT\"; }         // hook with a default\n        abstract String body();                      // step subclasses must supply\n    }\n\n    static final class SalesReport extends Report {\n        @Override String body() { return \"sales: 42 units\"; }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(new SalesReport().render());\n    }\n}","filename":"Java"}'),
