SELECT 'f56b9dee-d534-78f8-bbbb-9ed430eec267', '9096eac4-0423-77dd-914c-a2d3c0e7043d', 1, 'PUBLISHED', 'Design Patterns: Singleton, Builder & Factory', '[{"id":"475885b8-f730-7551-943b-13826758f497","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Creational patterns control "},{"type":"text","text":"how objects get made","marks":[{"type":"italic"}]},{"type":"text","text":": exactly one (Singleton), step by step (Builder), or without the caller naming the concrete class (Factory)."}]}]}},"revision":1},{"id":"1bd13786-2291-7b81-a57b-8185666630e4","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Singleton"}]},"revision":1},{"id":"e4cfe182-6923-7c1c-8149-e0db168c4870","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Singleton","marks":[{"type":"bold"}]},{"type":"text","text":" — a class with exactly one instance and a global access point to it. Private constructor + a static way to get the instance."}]}]}},"revision":1},{"id":"482209ca-e35e-7e8c-a2f1-bf8afb314a83","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Variant"}],[{"type":"text","text":"Lazy?"}],[{"type":"text","text":"Thread-safe?"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"Eager "},{"type":"text","text":"static final","marks":[{"type":"code"}]},{"type":"text","text":" field"}],[{"type":"text","text":"No — created at class init"}],[{"type":"text","text":"Yes (class init is thread-safe)"}],[{"type":"text","text":"Simplest; fine when creation is cheap"}]],[[{"type":"text","text":"synchronized getInstance()","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Lock on every call — slow"}]],[[{"type":"text","text":"Double-checked locking"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes "},{"type":"text","text":"only with ","marks":[{"type":"bold"}]},{"type":"text","text":"volatile","marks":[{"type":"bold"},{"type":"code"}]}],[{"type":"text","text":"Verbose; easy to get wrong"}]],[[{"type":"text","text":"Holder idiom (static nested class)"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"JVM class-loading guarantees; no locks"}]],[[{"type":"text","text":"enum","marks":[{"type":"code"}]},{"type":"text","text":" with one constant"}],[{"type":"text","text":"At enum init"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Recommended","marks":[{"type":"bold"}]},{"type":"text","text":" (Effective Java): also safe against reflection and serialization"}]]]},"revision":1},{"id":"ba30e99a-2668-7fe8-a1b6-b78e04987370","type":"code","position":"a4","content":{"language":"java","code":"public class Main {\n    // 1. Eager\n    static final class Eager {\n        private static final Eager INSTANCE = new Eager();\n        private Eager() {}\n        static Eager getInstance() { return INSTANCE; }\n    }\n\n    // 2. Double-checked locking — volatile prevents seeing a half-constructed object\n    static final class Dcl {\n        private static volatile Dcl instance;\n        private Dcl() {}\n        static Dcl getInstance() {\n            Dcl local = instance;\n            if (local == null) {                       // 1st check, no lock\n                synchronized (Dcl.class) {\n                    local = instance;\n                    if (local == null) {               // 2nd check, with lock\n                        instance = local = new Dcl();\n                    }\n                }\n            }\n            return local;\n        }\n    }\n\n    // 3. Holder idiom — Holder is initialised on first getInstance() call\n    static final class Lazy {\n        private Lazy() { System.out.println(\"Lazy created\"); }\n        private static final class Holder { static final Lazy INSTANCE = new Lazy(); }\n        static Lazy getInstance() { return Holder.INSTANCE; }\n    }\n\n    // 4. Enum\n    enum Config {\n        INSTANCE;\n        private int timeout = 30;\n        int timeout() { return timeout; }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(Eager.getInstance() == Eager.getInstance());\n        System.out.println(Dcl.getInstance() == Dcl.getInstance());\n        System.out.println(\"before first use\");\n        System.out.println(Lazy.getInstance() == Lazy.getInstance());\n        System.out.println(Config.INSTANCE.timeout());\n    }\n}","filename":"Java"},"revision":1},{"id":"a393919c-c9fd-7466-9de0-7fd7cdbc0ecd","type":"code","position":"a5","content":{"language":"text","code":"true\ntrue\nbefore first use\nLazy created\ntrue\n30","filename":"Output"},"revision":1},{"id":"96ca4928-2a16-73c5-aa7c-2111ce1c1e03","type":"callout","position":"a6","content":{"variant":"warning","title":"Double-checked locking","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":", double-checked locking is broken: the write of the reference can be reordered before the constructor''s field writes, so another thread may see a non-null but not fully initialised object."}]}]}},"revision":1},{"id":"9790f66b-695e-7bcb-8220-df91bd349e90","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Breaking a singleton — and the enum defence"}]},"revision":1},{"id":"50a48b0c-6655-7b1b-81da-81158545985d","type":"code","position":"a8","content":{"language":"java","code":"import java.lang.reflect.Constructor;\n\npublic class Main {\n    static final class Classic {\n        static final Classic INSTANCE = new Classic();\n        private Classic() {}\n    }\n\n    enum Single { INSTANCE }\n\n    public static void main(String[] args) throws Exception {\n        Constructor<Classic> c = Classic.class.getDeclaredConstructor();\n        c.setAccessible(true);                       // bypass `private`\n        Classic second = c.newInstance();\n        System.out.println(\"classic still single? \" + (second == Classic.INSTANCE));\n\n        Constructor<Single> e = Single.class.getDeclaredConstructor(String.class, int.class);\n        e.setAccessible(true);\n        try {\n            e.newInstance(\"INSTANCE\", 0);\n        } catch (IllegalArgumentException ex) {\n            System.out.println(ex.getMessage());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"775269fe-8a4d-77c9-9eb1-21203bd4d34a","type":"code","position":"a9","content":{"language":"text","code":"classic still single? false\nCannot reflectively create enum objects","filename":"Output"},"revision":1},{"id":"ab07b8c0-a5df-73d5-bd62-9a7065bb7ffd","type":"code","position":"aA","content":{"language":"java","code":"import java.io.*;\n\npublic class Main {\n    static final class Settings implements Serializable {\n        private static final long serialVersionUID = 1L;\n        static final Settings INSTANCE = new Settings();\n        private Settings() {}\n\n        private Object readResolve() {       // deserialization returns this instead\n            return INSTANCE;\n        }\n    }\n\n    public static void main(String[] args) throws Exception {\n        ByteArrayOutputStream bytes = new ByteArrayOutputStream();\n        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {\n            out.writeObject(Settings.INSTANCE);\n        }\n        try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {\n            Object copy = in.readObject();\n            System.out.println(copy == Settings.INSTANCE);   // false without readResolve\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"37ba6042-1eff-7391-9735-9160a8d6603a","type":"code","position":"aB","content":{"language":"text","code":"true","filename":"Output"},"revision":1},{"id":"fcbb4188-7ace-79a0-b185-d60cc33f61d6","type":"callout","position":"aC","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Singletons are global state: they hide dependencies and make unit tests hard. In application code prefer "},{"type":"text","text":"one instance created at startup and passed in","marks":[{"type":"italic"}]},{"type":"text","text":" (dependency injection — what Spring beans are by default)."}]}]}},"revision":1},{"id":"dbf82cbe-b9c5-7fca-988a-5acd78e61c2f","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Builder"}]},"revision":1},{"id":"1d49fcdf-e05a-73a4-80b4-e6cdbf44c2a7","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For classes with many parameters, especially optional ones. Replaces "},{"type":"text","text":"telescoping constructors","marks":[{"type":"italic"}]},{"type":"text","text":" and avoids the half-built objects of the JavaBeans setter style."}]}]}},"revision":1},{"id":"1365e714-7675-7728-80dd-efbba1f33732","type":"code","position":"aF","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static final class Pizza {\n        private final String size;              // required\n        private final boolean extraCheese;      // optional\n        private final List<String> toppings;    // optional\n\n        private Pizza(Builder b) {\n            this.size = b.size;\n            this.extraCheese = b.extraCheese;\n            this.toppings = List.copyOf(b.toppings);\n        }\n\n        static Builder builder(String size) { return new Builder(size); }\n\n        @Override\n        public String toString() {\n            return size + \" pizza, cheese=\" + extraCheese + \", toppings=\" + toppings;\n        }\n\n        static final class Builder {\n            private final String size;\n            private boolean extraCheese;\n            private final List<String> toppings = new ArrayList<>();\n\n            private Builder(String size) { this.size = size; }\n\n            Builder extraCheese() { this.extraCheese = true; return this; }\n            Builder topping(String t) { toppings.add(t); return this; }\n\n            Pizza build() {\n                if (toppings.size() > 5) throw new IllegalStateException(\"too many toppings\");\n                return new Pizza(this);\n            }\n        }\n    }\n\n    public static void main(String[] args) {\n        Pizza p = Pizza.builder(\"large\")\n                .topping(\"olives\")\n                .topping(\"basil\")\n                .extraCheese()\n                .build();\n        System.out.println(p);\n    }\n}","filename":"Java"},"revision":1},{"id":"ee512482-0f7f-7325-a9c6-9d01accdaefd","type":"code","position":"aG","content":{"language":"text","code":"large pizza, cheese=true, toppings=[olives, basil]","filename":"Output"},"revision":1},{"id":"9a0fb551-2fd6-74be-98f8-629ae97d8034","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"StringBuilder","marks":[{"type":"code"}]},{"type":"text","text":" · "},{"type":"text","text":"HttpRequest.newBuilder()","marks":[{"type":"code"}]},{"type":"text","text":" · "},{"type":"text","text":"Stream.builder()","marks":[{"type":"code"}]},{"type":"text","text":" · "},{"type":"text","text":"Locale.Builder","marks":[{"type":"code"}]},{"type":"text","text":" · Lombok "},{"type":"text","text":"@Builder","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"78b8bb2e-47d4-7335-b179-d38ba1ddd450","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Factories"}]},"revision":1},{"id":"8f131941-2155-7677-b8da-3b20097fc4b3","type":"callout","position":"aJ","content":{"variant":"note","title":"Static factory method","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" method that returns an instance: "},{"type":"text","text":"List.of","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Integer.valueOf","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Optional.empty","marks":[{"type":"code"}]},{"type":"text","text":". Has a "},{"type":"text","text":"name","marks":[{"type":"italic"}]},{"type":"text","text":", can cache ("},{"type":"text","text":"valueOf","marks":[{"type":"code"}]},{"type":"text","text":"), can return a subtype."}]}]}},"revision":1},{"id":"a36699e8-2293-78f2-b982-92bb151051bd","type":"callout","position":"aK","content":{"variant":"note","title":"Simple factory","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One method picks the concrete class from a parameter — callers depend only on the interface."}]}]}},"revision":1},{"id":"45a506f3-66fe-7d53-889d-cc7132fc5f2e","type":"callout","position":"aL","content":{"variant":"note","title":"Factory Method (GoF)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A superclass defines an abstract "},{"type":"text","text":"createX()","marks":[{"type":"code"}]},{"type":"text","text":" and subclasses decide which class to instantiate."}]}]}},"revision":1},{"id":"7b066c2b-e07d-7f65-af0e-b553faf90f1e","type":"callout","position":"aM","content":{"variant":"note","title":"Abstract Factory","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An interface for creating "},{"type":"text","text":"families","marks":[{"type":"italic"}]},{"type":"text","text":" of related objects (e.g. a UI kit: "},{"type":"text","text":"createButton","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"createCheckbox","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"035e5aa3-03d0-7684-b27f-30f010a670fd","type":"code","position":"aN","content":{"language":"java","code":"public class Main {\n    sealed interface Shape permits Circle, Square {\n        double area();\n\n        static Shape of(String kind, double size) {        // simple / static factory\n            return switch (kind) {\n                case \"circle\" -> new Circle(size);\n                case \"square\" -> new Square(size);\n                default -> throw new IllegalArgumentException(\"unknown shape: \" + kind);\n            };\n        }\n    }\n\n    record Circle(double r) implements Shape {\n        public double area() { return Math.PI * r * r; }\n    }\n\n    record Square(double side) implements Shape {\n        public double area() { return side * side; }\n    }\n\n    public static void main(String[] args) {\n        Shape s = Shape.of(\"square\", 3);\n        System.out.println(s + \" area=\" + s.area());\n        System.out.printf(\"%.2f%n\", Shape.of(\"circle\", 1).area());\n        System.out.println(Integer.valueOf(100) == Integer.valueOf(100));   // valueOf caches\n    }\n}","filename":"Java"},"revision":1},{"id":"9410dcbf-eb3d-7d9c-a496-923538cc97e1","type":"code","position":"aO","content":{"language":"text","code":"Square[side=3.0] area=9.0\n3.14\ntrue","filename":"Output"},"revision":1},{"id":"5727d850-7beb-72c0-acab-649be8b6eb69","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which singleton implementation would you use and why?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"enum","marks":[{"type":"code"}]},{"type":"text","text":" with a single constant: it is thread-safe by class initialisation, serialization returns the same constant automatically, and reflection cannot create a second instance. If laziness matters and the class must extend something, use the holder idiom."}]}]}},"revision":1},{"id":"0723026e-1c9e-7368-aa8c-6deffcd61490","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why must the instance field be volatile in double-checked locking?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"instance = new X()","marks":[{"type":"code"}]},{"type":"text","text":" is allocate → initialise → publish; without "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" the publish can be reordered before initialisation, so a thread that skips the lock could see a non-null reference to an object whose fields are still defaults. "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" adds the happens-before edge that forbids this."}]}]}},"revision":1},{"id":"df03674c-67b4-7f55-b579-6405836e79f0","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you choose a builder over constructors?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When there are more than a handful of parameters, several are optional, or several have the same type (easy to swap by mistake). The builder gives named, readable calls and still produces an immutable object validated in one place ("},{"type":"text","text":"build()","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
