  ('475885b8-f730-7551-943b-13826758f497', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Creational patterns control "},{"type":"text","text":"how objects get made","marks":[{"type":"italic"}]},{"type":"text","text":": exactly one (Singleton), step by step (Builder), or without the caller naming the concrete class (Factory)."}]}]}}'),
  ('1bd13786-2291-7b81-a57b-8185666630e4', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Singleton"}]}'),
