  ('482209ca-e35e-7e8c-a2f1-bf8afb314a83', 'a3', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Variant"}],[{"type":"text","text":"Lazy?"}],[{"type":"text","text":"Thread-safe?"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"Eager "},{"type":"text","text":"static final","marks":[{"type":"code"}]},{"type":"text","text":" field"}],[{"type":"text","text":"No — created at class init"}],[{"type":"text","text":"Yes (class init is thread-safe)"}],[{"type":"text","text":"Simplest; fine when creation is cheap"}]],[[{"type":"text","text":"synchronized getInstance()","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Lock on every call — slow"}]],[[{"type":"text","text":"Double-checked locking"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes "},{"type":"text","text":"only with ","marks":[{"type":"bold"}]},{"type":"text","text":"volatile","marks":[{"type":"bold"},{"type":"code"}]}],[{"type":"text","text":"Verbose; easy to get wrong"}]],[[{"type":"text","text":"Holder idiom (static nested class)"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"JVM class-loading guarantees; no locks"}]],[[{"type":"text","text":"enum","marks":[{"type":"code"}]},{"type":"text","text":" with one constant"}],[{"type":"text","text":"At enum init"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Recommended","marks":[{"type":"bold"}]},{"type":"text","text":" (Effective Java): also safe against reflection and serialization"}]]]}'),
  ('ba30e99a-2668-7fe8-a1b6-b78e04987370', 'a4', 'code', '{"language":"java","code":"public class Main {\n    // 1. Eager\n    static final class Eager {\n        private static final Eager INSTANCE = new Eager();\n        private Eager() {}\n        static Eager getInstance() { return INSTANCE; }\n    }\n\n    // 2. Double-checked locking — volatile prevents seeing a half-constructed object\n    static final class Dcl {\n        private static volatile Dcl instance;\n        private Dcl() {}\n        static Dcl getInstance() {\n            Dcl local = instance;\n            if (local == null) {                       // 1st check, no lock\n                synchronized (Dcl.class) {\n                    local = instance;\n                    if (local == null) {               // 2nd check, with lock\n                        instance = local = new Dcl();\n                    }\n                }\n            }\n            return local;\n        }\n    }\n\n    // 3. Holder idiom — Holder is initialised on first getInstance() call\n    static final class Lazy {\n        private Lazy() { System.out.println(\"Lazy created\"); }\n        private static final class Holder { static final Lazy INSTANCE = new Lazy(); }\n        static Lazy getInstance() { return Holder.INSTANCE; }\n    }\n\n    // 4. Enum\n    enum Config {\n        INSTANCE;\n        private int timeout = 30;\n        int timeout() { return timeout; }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(Eager.getInstance() == Eager.getInstance());\n        System.out.println(Dcl.getInstance() == Dcl.getInstance());\n        System.out.println(\"before first use\");\n        System.out.println(Lazy.getInstance() == Lazy.getInstance());\n        System.out.println(Config.INSTANCE.timeout());\n    }\n}","filename":"Java"}'),
  ('a393919c-c9fd-7466-9de0-7fd7cdbc0ecd', 'a5', 'code', '{"language":"text","code":"true\ntrue\nbefore first use\nLazy created\ntrue\n30","filename":"Output"}'),
  ('96ca4928-2a16-73c5-aa7c-2111ce1c1e03', 'a6', 'callout', '{"variant":"warning","title":"Double-checked locking","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":", double-checked locking is broken: the write of the reference can be reordered before the constructor''s field writes, so another thread may see a non-null but not fully initialised object."}]}]}}'),
