SELECT 'e0fd8630-80fa-7e95-8bef-880c13cdd2cb', '09e97d56-73bc-75ba-84dc-77d894464108', 1, 'PUBLISHED', 'Encapsulation', '[{"id":"2dfbb675-10dc-788f-bd13-8097c25a820f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep fields "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" and expose behaviour through methods, so the class alone guarantees that its state is always valid."}]}]}},"revision":1},{"id":"82c282a5-1148-7166-9989-bd2ab7c2977e","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Encapsulation","marks":[{"type":"bold"}]},{"type":"text","text":" — bundling data with the methods that operate on it, and "},{"type":"text","text":"hiding the data","marks":[{"type":"bold"}]},{"type":"text","text":" so outside code can change it only through a controlled interface."}]}]}},"revision":1},{"id":"5ffdea6e-4590-718c-8e6f-f9eaafe0a047","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Why it matters"}]},"revision":1},{"id":"e33954b2-e8a5-7985-894f-cd840d9ef84c","type":"callout","position":"a3","content":{"variant":"note","title":"Invariants","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The class validates every change, so an object can never be in an illegal state (negative balance, empty name)."}]}]}},"revision":1},{"id":"43765242-a193-7e3d-8531-44e2fc401149","type":"callout","position":"a4","content":{"variant":"note","title":"Freedom to change","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Internal representation can change (cents instead of double) without breaking callers."}]}]}},"revision":1},{"id":"9112e33d-2691-7421-8b3a-2f15aa09388a","type":"callout","position":"a5","content":{"variant":"note","title":"Easier debugging","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every mutation passes through a few methods — one place for a breakpoint or log."}]}]}},"revision":1},{"id":"295ca2b5-5115-7313-8328-a5e9b7dd0578","type":"callout","position":"a6","content":{"variant":"note","title":"Thread safety","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Controlled access is where you add synchronisation or make the class immutable."}]}]}},"revision":1},{"id":"4d87e920-bf82-7ba0-873c-02d5d67621b0","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Getters, setters and validation"}]},"revision":1},{"id":"234c7d3d-ee29-7edf-8a73-b16b184bd5f1","type":"code","position":"a8","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        Account acc = new Account(\"Asha\", 1000);\n        acc.withdraw(300);\n        System.out.println(acc.getOwner() + \": \" + acc.getBalance());\n        try {\n            acc.withdraw(5000);\n        } catch (IllegalArgumentException e) {\n            System.out.println(\"rejected: \" + e.getMessage());\n        }\n        System.out.println(\"balance still \" + acc.getBalance());\n    }\n}\n\nclass Account {\n    private final String owner;\n    private long balance;                  // hidden: no one can set it to -1\n\n    Account(String owner, long opening) {\n        if (owner == null || owner.isBlank()) throw new IllegalArgumentException(\"owner required\");\n        this.owner = owner;\n        this.balance = opening;\n    }\n\n    String getOwner() { return owner; }\n    long getBalance() { return balance; }  // read-only: no setBalance()\n\n    void withdraw(long amount) {\n        if (amount <= 0 || amount > balance)\n            throw new IllegalArgumentException(\"invalid amount \" + amount);\n        balance -= amount;\n    }\n}","filename":"Java"},"revision":1},{"id":"121ee7a0-ca01-7d39-b369-603abf152dc2","type":"code","position":"a9","content":{"language":"text","code":"Asha: 700\nrejected: invalid amount 5000\nbalance still 700","filename":"Output"},"revision":1},{"id":"b544a6b7-4d6c-7b28-b9a2-aceea6bfcf32","type":"callout","position":"aA","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Don''t generate a setter for every field. Expose "},{"type":"text","text":"operations","marks":[{"type":"italic"}]},{"type":"text","text":" ("},{"type":"text","text":"withdraw","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"rename","marks":[{"type":"code"}]},{"type":"text","text":") that express intent and enforce rules — a public getter + setter pair on every field is barely better than a public field."}]}]}},"revision":1},{"id":"0cf211a4-6870-7da0-b2cd-16f264bfaa7c","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Leaking mutable state — and defensive copies"}]},"revision":1},{"id":"d4b79a22-f8e1-74af-8375-f09799c82f96","type":"code","position":"aC","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> input = new ArrayList<>(List.of(\"math\", \"physics\"));\n        Leaky leaky = new Leaky(input);\n        Safe safe = new Safe(input);\n\n        input.add(\"hacked\");                 // caller mutates its own list\n        leaky.getSubjects().clear();         // caller mutates via the getter\n\n        System.out.println(\"leaky: \" + leaky.getSubjects());\n        System.out.println(\"safe:  \" + safe.getSubjects());\n        try {\n            safe.getSubjects().add(\"x\");\n        } catch (UnsupportedOperationException e) {\n            System.out.println(\"safe getter is read-only\");\n        }\n    }\n}\n\nclass Leaky {\n    private final List<String> subjects;\n    Leaky(List<String> subjects) { this.subjects = subjects; }   // stores caller''s list\n    List<String> getSubjects() { return subjects; }              // hands out internals\n}\n\nclass Safe {\n    private final List<String> subjects;\n    Safe(List<String> subjects) { this.subjects = List.copyOf(subjects); }   // copy in\n    List<String> getSubjects() { return subjects; }                          // already unmodifiable\n}","filename":"Java"},"revision":1},{"id":"eb2ea2ea-5de0-7938-94c4-0f74787d4706","type":"code","position":"aD","content":{"language":"text","code":"leaky: []\nsafe:  [math, physics]\nsafe getter is read-only","filename":"Output"},"revision":1},{"id":"a3fa9b6f-b281-7ebc-8631-9d37ccff16fa","type":"callout","position":"aE","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy mutable arguments on the way in and return copies or unmodifiable views on the way out ("},{"type":"text","text":"List.copyOf","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"new Date(d.getTime())","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"6bd47dd0-7f0c-75b6-8618-82296db0ea31","type":"callout","position":"aF","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returning a reference to an internal array, list or "},{"type":"text","text":"Date","marks":[{"type":"code"}]},{"type":"text","text":" — callers can then change your object''s state behind its back."}]}]}},"revision":1},{"id":"0604d7ab-bd94-7613-969b-7ac3e31dce9d","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Encapsulation vs abstraction"}]},"revision":1},{"id":"7016ae28-b6dd-70f4-ac14-baab946f0553","type":"table","position":"aH","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Encapsulation"}],[{"type":"text","text":"Abstraction"}]],[[{"type":"text","text":"Focus"}],[{"type":"text","text":"How","marks":[{"type":"italic"}]},{"type":"text","text":" data is protected"}],[{"type":"text","text":"What","marks":[{"type":"italic"}]},{"type":"text","text":" is exposed"}]],[[{"type":"text","text":"Mechanism"}],[{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" fields, accessors, validation"}],[{"type":"text","text":"Interfaces, abstract classes, simple method names"}]],[[{"type":"text","text":"Level"}],[{"type":"text","text":"Implementation"}],[{"type":"text","text":"Design"}]]]},"revision":1},{"id":"a8fdae0a-c54b-76b5-8ba8-a55099d157c8","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you achieve encapsulation in Java?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Make fields "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":", provide methods (getters, intention-revealing operations) that validate changes, and avoid leaking references to mutable internals — use defensive copies."}]}]}},"revision":1},{"id":"0c9f1b15-d44c-75cb-aea2-35c082413629","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is a class with private fields and public getters/setters for all of them encapsulated?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Only nominally. If every setter accepts anything, the class can''t protect its invariants. Real encapsulation exposes behaviour and validates every state change."}]}]}},"revision":1},{"id":"d394220f-8ff6-7da6-8bf6-4a5e67642814","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a JavaBean?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A convention: public no-arg constructor, private fields, "},{"type":"text","text":"getX","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"setX","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"isX","marks":[{"type":"code"}]},{"type":"text","text":" for booleans) accessors, and usually "},{"type":"text","text":"Serializable","marks":[{"type":"code"}]},{"type":"text","text":". Frameworks use reflection on these names."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
