SELECT '68492d7d-4d14-7856-ba58-158e39a4c275', 'e7b92afd-a7f5-751e-9cdc-bb140136ab5f', 1, 'PUBLISHED', 'Enums', '[{"id":"4843c282-8194-7ce2-b145-73a467049939","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"enum","marks":[{"type":"code"}]},{"type":"text","text":" is a class with a fixed, named set of instances. It''s type-safe, can carry fields and behaviour, and works in "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"EnumMap","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"EnumSet","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"04295664-c1d6-71b4-96b5-7d7250a6ca48","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Enum","marks":[{"type":"bold"}]},{"type":"text","text":" — a special class whose instances are exactly the listed constants, created once when the class loads. Each constant is a "},{"type":"text","text":"public static final","marks":[{"type":"code"}]},{"type":"text","text":" instance; every enum implicitly extends "},{"type":"text","text":"java.lang.Enum","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"64ad8879-881d-751c-9870-4b9edcbd1982","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Built-in methods"}]},"revision":1},{"id":"0297718f-0613-7876-9f33-7d961435e5e7","type":"code","position":"a3","content":{"language":"java","code":"public class Main {\n    enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }\n\n    public static void main(String[] args) {\n        Day d = Day.WED;\n        System.out.println(d + \" \" + d.name() + \" \" + d.ordinal());\n        System.out.println(Day.valueOf(\"FRI\").compareTo(Day.MON));  // by ordinal\n        System.out.println(Day.values().length);\n        System.out.println(d == Day.WED);          // safe: constants are singletons\n        try {\n            Day.valueOf(\"Funday\");\n        } catch (IllegalArgumentException e) {\n            System.out.println(e.getMessage());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"567c28b8-13f6-7970-940d-f3ab49af45c9","type":"code","position":"a4","content":{"language":"text","code":"WED WED 2\n4\n7\ntrue\nNo enum constant Main.Day.Funday","filename":"Output"},"revision":1},{"id":"184de13d-27b0-7f9d-94ac-f172a6bd4632","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Member"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"values()","marks":[{"type":"code"}]}],[{"type":"text","text":"Array of all constants in declaration order (a fresh copy each call)"}]],[[{"type":"text","text":"valueOf(String)","marks":[{"type":"code"}]}],[{"type":"text","text":"Constant by exact name, else "},{"type":"text","text":"IllegalArgumentException","marks":[{"type":"code"}]}]],[[{"type":"text","text":"name()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"toString()","marks":[{"type":"code"}]}],[{"type":"text","text":"Declared name ("},{"type":"text","text":"toString","marks":[{"type":"code"}]},{"type":"text","text":" can be overridden, "},{"type":"text","text":"name","marks":[{"type":"code"}]},{"type":"text","text":" cannot)"}]],[[{"type":"text","text":"ordinal()","marks":[{"type":"code"}]}],[{"type":"text","text":"0-based position — don''t persist it; reordering constants changes it"}]],[[{"type":"text","text":"compareTo","marks":[{"type":"code"}]}],[{"type":"text","text":"Compares by ordinal; enums are "},{"type":"text","text":"Comparable","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"0444385f-992d-7758-add8-cf864e77cd5a","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Fields, constructors and methods"}]},"revision":1},{"id":"cfe1a7a7-302f-79b6-b5e5-2e1d42c9cb43","type":"code","position":"a7","content":{"language":"java","code":"public class Main {\n    enum Planet {\n        MERCURY(3.303e+23, 2.4397e6),\n        EARTH(5.976e+24, 6.37814e6);\n\n        private final double mass, radius;            // per-constant data\n        Planet(double mass, double radius) {          // constructor is implicitly private\n            this.mass = mass;\n            this.radius = radius;\n        }\n        double surfaceGravity() {\n            return 6.67300E-11 * mass / (radius * radius);\n        }\n    }\n\n    public static void main(String[] args) {\n        for (Planet p : Planet.values())\n            System.out.printf(\"%s %.2f%n\", p, p.surfaceGravity());\n    }\n}","filename":"Java"},"revision":1},{"id":"38e1ab10-4193-7bc4-8550-2c27b018499c","type":"code","position":"a8","content":{"language":"text","code":"MERCURY 3.70\nEARTH 9.80","filename":"Output"},"revision":1},{"id":"22d0aaf2-7159-730e-a3da-6217dfd090b7","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Constant-specific bodies"}]},"revision":1},{"id":"042dfd95-cf48-7438-955d-bbf0772e7153","type":"code","position":"aA","content":{"language":"java","code":"public class Main {\n    enum Op {\n        ADD(\"+\") { int apply(int a, int b) { return a + b; } },\n        MUL(\"*\") { int apply(int a, int b) { return a * b; } };\n\n        final String symbol;\n        Op(String symbol) { this.symbol = symbol; }\n        abstract int apply(int a, int b);            // each constant must implement it\n    }\n\n    public static void main(String[] args) {\n        for (Op op : Op.values())\n            System.out.println(\"6 \" + op.symbol + \" 7 = \" + op.apply(6, 7));\n    }\n}","filename":"Java"},"revision":1},{"id":"e90c2e6d-c827-7eb1-b2ce-d480d7111614","type":"code","position":"aB","content":{"language":"text","code":"6 + 7 = 13\n6 * 7 = 42","filename":"Output"},"revision":1},{"id":"284e50a8-e87b-736c-8158-67f4b6865bb7","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Switch over an enum"}]},"revision":1},{"id":"8ff5dc4c-a8b4-77c2-8682-5d59378074f5","type":"code","position":"aD","content":{"language":"java","code":"public class Main {\n    enum Level { LOW, MEDIUM, HIGH }\n\n    static String action(Level l) {\n        return switch (l) {             // exhaustive: no default needed\n            case LOW -> \"ignore\";\n            case MEDIUM -> \"log\";\n            case HIGH -> \"page on-call\";\n        };\n    }\n\n    public static void main(String[] args) {\n        for (Level l : Level.values()) System.out.println(l + \" -> \" + action(l));\n    }\n}","filename":"Java"},"revision":1},{"id":"a0a3f140-951e-7076-b12b-31b55ecd078f","type":"code","position":"aE","content":{"language":"text","code":"LOW -> ignore\nMEDIUM -> log\nHIGH -> page on-call","filename":"Output"},"revision":1},{"id":"ac4bcea4-797a-76a1-b7ec-b5838683ecea","type":"callout","position":"aF","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a "},{"type":"text","text":"case","marks":[{"type":"code"}]},{"type":"text","text":" label you write the bare constant "},{"type":"text","text":"LOW","marks":[{"type":"code"}]},{"type":"text","text":", not "},{"type":"text","text":"Level.LOW","marks":[{"type":"code"}]},{"type":"text","text":" (qualified names in case labels are only allowed from Java 21). A switch "},{"type":"text","text":"expression","marks":[{"type":"italic"}]},{"type":"text","text":" over an enum must cover every constant or have a "},{"type":"text","text":"default","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"59560d29-c977-764a-80f6-96fd8b7c037e","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"EnumSet and EnumMap"}]},"revision":1},{"id":"b603b61e-e571-726f-ab90-e0c895ebda23","type":"code","position":"aH","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }\n\n    public static void main(String[] args) {\n        EnumSet<Day> weekend = EnumSet.of(Day.SAT, Day.SUN);          // a bit vector inside\n        EnumSet<Day> weekdays = EnumSet.complementOf(weekend);\n        System.out.println(weekdays);\n        System.out.println(EnumSet.range(Day.TUE, Day.THU));\n\n        Map<Day, Integer> hours = new EnumMap<>(Day.class);          // array indexed by ordinal\n        hours.put(Day.FRI, 6);\n        hours.put(Day.MON, 8);\n        System.out.println(hours);                                   // always in declaration order\n    }\n}","filename":"Java"},"revision":1},{"id":"29764691-54dc-7ceb-a6ac-55ec16397fb7","type":"code","position":"aI","content":{"language":"text","code":"[MON, TUE, WED, THU, FRI]\n[TUE, WED, THU]\n{MON=8, FRI=6}","filename":"Output"},"revision":1},{"id":"062e653f-71ab-7226-8cab-2740af17ef4f","type":"callout","position":"aJ","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"EnumSet","marks":[{"type":"code"}]},{"type":"text","text":" instead of bit flags and "},{"type":"text","text":"EnumMap","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":" with enum keys — both are faster, compact, and iterate in declaration order."}]}]}},"revision":1},{"id":"6743a471-36a7-7915-98d2-6da20be5b443","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"The enum singleton"}]},"revision":1},{"id":"a20d4b35-4a86-7133-aaed-537a73a19ea8","type":"code","position":"aL","content":{"language":"java","code":"public class Main {\n    enum Registry {\n        INSTANCE;\n        private int count;\n        int next() { return ++count; }\n    }\n\n    public static void main(String[] args) {\n        Registry.INSTANCE.next();\n        System.out.println(Registry.INSTANCE.next());\n    }\n}","filename":"Java"},"revision":1},{"id":"bdf20daf-8976-7924-8565-bdd9ac7583b9","type":"code","position":"aM","content":{"language":"text","code":"2","filename":"Output"},"revision":1},{"id":"4448e690-2db9-7fff-b98d-70f9fb61de35","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Effective Java","marks":[{"type":"italic"}]},{"type":"text","text":" calls a single-element enum the best singleton: the JVM guarantees one instance, it is thread-safe to initialise, and it is safe against reflection and serialization attacks that break classic singletons."}]}]}},"revision":1},{"id":"9c85b8f0-9319-746e-aac8-714e30314887","type":"callout","position":"aO","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Don''t store or persist "},{"type":"text","text":"ordinal()","marks":[{"type":"code"}]},{"type":"text","text":" (e.g. in a database). Adding or reordering a constant silently changes every ordinal. Persist "},{"type":"text","text":"name()","marks":[{"type":"code"}]},{"type":"text","text":" or an explicit code field instead."}]}]}},"revision":1},{"id":"0afd64e5-f9c4-7a77-9d87-58f1a0d8ce0b","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can an enum extend a class? Implement an interface?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It cannot extend anything — it already extends "},{"type":"text","text":"java.lang.Enum","marks":[{"type":"code"}]},{"type":"text","text":". It "},{"type":"text","text":"can","marks":[{"type":"italic"}]},{"type":"text","text":" implement interfaces, which is a common way to make several enums interchangeable."}]}]}},"revision":1},{"id":"240b7dc0-7ba3-7730-b1f0-98ade757ab6d","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is comparing enums with == safe?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each constant is created exactly once per class loader and can''t be instantiated again (constructors are private; reflection and deserialization are blocked). So identity equals equality, and "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" is also null-safe."}]}]}},"revision":1},{"id":"82f1a2fb-cead-72e2-b5d1-2f082c5be3e1","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can''t an enum constructor be public?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The set of instances is fixed at compile time. Allowing "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" would break that guarantee, so enum constructors are implicitly "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
