SELECT '0f15f581-6d3d-70b2-bad7-18450ad72c3b', '363c9112-22c0-76ef-989b-bde879db1a77', 1, 'PUBLISHED', 'ExecutorService & Thread Pools', '[{"id":"4039271d-cbf5-7280-ab28-03a3202519b1","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Don''t create a thread per task — submit tasks to an "},{"type":"text","text":"ExecutorService","marks":[{"type":"code"}]},{"type":"text","text":", which reuses a pool of threads and gives you "},{"type":"text","text":"Future","marks":[{"type":"code"}]},{"type":"text","text":"s for the results."}]}]}},"revision":1},{"id":"ebf370e1-2a7f-7e3d-9b05-51933de7b0b6","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ExecutorService","marks":[{"type":"bold"}]},{"type":"text","text":" — an "},{"type":"text","text":"Executor","marks":[{"type":"code"}]},{"type":"text","text":" (runs "},{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":"s) that also manages its own lifecycle ("},{"type":"text","text":"shutdown","marks":[{"type":"code"}]},{"type":"text","text":") and returns a "},{"type":"text","text":"Future","marks":[{"type":"code"}]},{"type":"text","text":" for each submitted "},{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"Callable","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"a642755b-5f80-7776-825e-6cc369a98123","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Why a pool?"}]},"revision":1},{"id":"be3e645f-bb94-70c8-8ec9-fccfa99fbdd6","type":"callout","position":"a3","content":{"variant":"note","title":"Reuse","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Creating a platform thread costs a syscall and ~1 MB of stack. A pool pays it once."}]}]}},"revision":1},{"id":"b9ea2150-1954-7e2e-a486-484e26a0785b","type":"callout","position":"a4","content":{"variant":"note","title":"Bounded resources","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"10 000 requests don''t become 10 000 threads — the queue absorbs bursts."}]}]}},"revision":1},{"id":"eb15ba5e-be11-7b41-bf93-0f563479a433","type":"callout","position":"a5","content":{"variant":"note","title":"Results & errors","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Future.get()","marks":[{"type":"code"}]},{"type":"text","text":" returns the value or rethrows the task''s exception."}]}]}},"revision":1},{"id":"08bf2938-4abb-7bf1-a4c4-1cfd45158a8c","type":"callout","position":"a6","content":{"variant":"note","title":"Separation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Business code submits tasks; the pool decides how and where they run."}]}]}},"revision":1},{"id":"76de0e08-ad53-741f-b809-4500596f50da","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"submit, Future and invokeAll"}]},"revision":1},{"id":"721d4b80-16a5-7d93-a308-f7f5cc27fe34","type":"code","position":"a8","content":{"language":"java","code":"import java.util.List;\nimport java.util.concurrent.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        ExecutorService pool = Executors.newFixedThreadPool(3);\n        try {\n            Future<Integer> f = pool.submit(() -> 6 * 7);          // Callable<Integer>\n            System.out.println(\"answer = \" + f.get());            // blocks until done\n\n            List<Callable<String>> tasks = List.of(() -> \"a\".repeat(3), () -> \"b\".repeat(2), () -> \"c\");\n            for (Future<String> r : pool.invokeAll(tasks)) {       // results in task order\n                System.out.println(r.get());\n            }\n\n            Future<?> g = pool.submit(() -> { });                  // Runnable\n            System.out.println(\"runnable result = \" + g.get());\n\n            Future<Integer> bad = pool.submit(() -> 1 / 0);\n            try {\n                bad.get();\n            } catch (ExecutionException e) {                        // the task''s exception is wrapped\n                System.out.println(\"cause: \" + e.getCause());\n            }\n        } finally {\n            pool.shutdown();                                        // stop accepting, finish queued\n            System.out.println(\"terminated = \" + pool.awaitTermination(1, TimeUnit.SECONDS));\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"7714df94-f84f-7473-9ab4-75d9c224792a","type":"code","position":"a9","content":{"language":"text","code":"answer = 42\naaa\nbb\nc\nrunnable result = null\ncause: java.lang.ArithmeticException: / by zero\nterminated = true","filename":"Output"},"revision":1},{"id":"bd8fbc16-4ec0-7ff6-9539-465354e722be","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Future","marks":[{"type":"code"}]},{"type":"text","text":" method"}],[{"type":"text","text":"Purpose"}]],[[{"type":"text","text":"get()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"get(t, unit)","marks":[{"type":"code"}]}],[{"type":"text","text":"Wait for the result; throws "},{"type":"text","text":"ExecutionException","marks":[{"type":"code"}]},{"type":"text","text":" (task failed), "},{"type":"text","text":"TimeoutException","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"InterruptedException","marks":[{"type":"code"}]}]],[[{"type":"text","text":"isDone()","marks":[{"type":"code"}]}],[{"type":"text","text":"Completed normally, exceptionally or cancelled"}]],[[{"type":"text","text":"cancel(mayInterrupt)","marks":[{"type":"code"}]}],[{"type":"text","text":"Try to cancel; "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" interrupts a running task"}]],[[{"type":"text","text":"resultNow()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"state()","marks":[{"type":"code"}]}],[{"type":"text","text":"Java 19+: read a completed result without checked exceptions"}]]]},"revision":1},{"id":"50d86812-bc79-77e0-a95a-777505a9e2c1","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Executors factory methods"}]},"revision":1},{"id":"c62577c8-36d1-7cda-a42d-4e853a4df10d","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Factory"}],[{"type":"text","text":"Pool"}],[{"type":"text","text":"Watch out"}]],[[{"type":"text","text":"newFixedThreadPool(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" threads, unbounded "},{"type":"text","text":"LinkedBlockingQueue","marks":[{"type":"code"}]}],[{"type":"text","text":"Queue can grow until "},{"type":"text","text":"OutOfMemoryError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"newCachedThreadPool()","marks":[{"type":"code"}]}],[{"type":"text","text":"0…∞ threads, idle ones die after 60 s, "},{"type":"text","text":"SynchronousQueue","marks":[{"type":"code"}]}],[{"type":"text","text":"Unbounded "},{"type":"text","text":"threads","marks":[{"type":"italic"}]},{"type":"text","text":" under load"}]],[[{"type":"text","text":"newSingleThreadExecutor()","marks":[{"type":"code"}]}],[{"type":"text","text":"1 thread, tasks run sequentially in order"}],[{"type":"text","text":"Same unbounded queue"}]],[[{"type":"text","text":"newScheduledThreadPool(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Delayed / periodic tasks ("},{"type":"text","text":"schedule","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"scheduleAtFixedRate","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Replaces "},{"type":"text","text":"java.util.Timer","marks":[{"type":"code"}]}]],[[{"type":"text","text":"newWorkStealingPool()","marks":[{"type":"code"}]}],[{"type":"text","text":"ForkJoinPool","marks":[{"type":"code"}]},{"type":"text","text":" with one queue per worker"}],[{"type":"text","text":"Good for many small CPU tasks"}]],[[{"type":"text","text":"newVirtualThreadPerTaskExecutor()","marks":[{"type":"code"}]}],[{"type":"text","text":"Java 21: one virtual thread per task"}],[{"type":"text","text":"For blocking I/O workloads"}]]]},"revision":1},{"id":"e410fa09-5f52-7c83-a954-97b36d3d78d4","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Shutting down"}]},"revision":1},{"id":"32157566-ed35-7fb9-8c63-248b1aed4fdb","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"shutdown()","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"No new tasks accepted; already submitted ones still run."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"awaitTermination(t, unit)","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Block until all tasks finish or the timeout elapses; returns "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" if terminated."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"shutdownNow()","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Interrupt running tasks and return the ones never started (tasks must respond to interrupts)."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Since Java 19 "},{"type":"text","text":"ExecutorService","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"AutoCloseable","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" calls "},{"type":"text","text":"shutdown()","marks":[{"type":"code"}]},{"type":"text","text":" and waits for every task, so try-with-resources is the tidiest pattern."}]}]}},"revision":1},{"id":"30f5565d-42e0-7a3c-b523-033fb10d4cf0","type":"code","position":"aF","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.Future;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        List<Future<Integer>> squares = new ArrayList<>();\n        try (ExecutorService pool = Executors.newFixedThreadPool(4)) {\n            for (int i = 1; i <= 5; i++) {\n                int n = i;\n                squares.add(pool.submit(() -> n * n));\n            }\n        }                                   // close(): shutdown + wait for all tasks\n        int total = 0;\n        for (Future<Integer> f : squares) total += f.resultNow();\n        System.out.println(\"sum of squares = \" + total);\n    }\n}","filename":"Java"},"revision":1},{"id":"67d26c70-0f3d-7763-943f-76256ba53231","type":"code","position":"aG","content":{"language":"text","code":"sum of squares = 55","filename":"Output"},"revision":1},{"id":"80224b38-d49b-7930-a727-2917f6bd259a","type":"callout","position":"aH","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A pool that is never shut down keeps its non-daemon threads alive, so the JVM never exits. And a forgotten "},{"type":"text","text":"Future","marks":[{"type":"code"}]},{"type":"text","text":" hides exceptions: "},{"type":"text","text":"execute()","marks":[{"type":"code"}]},{"type":"text","text":" prints an uncaught task exception, but "},{"type":"text","text":"submit()","marks":[{"type":"code"}]},{"type":"text","text":" stores it in the "},{"type":"text","text":"Future","marks":[{"type":"code"}]},{"type":"text","text":" until someone calls "},{"type":"text","text":"get()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0556de20-e302-7770-b526-8e11dc1b5191","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"ThreadPoolExecutor: the real knobs"}]},"revision":1},{"id":"2a6088d2-15c5-7b13-a8bb-6322c857c318","type":"table","position":"aJ","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Parameter"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"corePoolSize","marks":[{"type":"code"}]}],[{"type":"text","text":"Threads kept alive even when idle"}]],[[{"type":"text","text":"maximumPoolSize","marks":[{"type":"code"}]}],[{"type":"text","text":"Upper bound — extra threads are created only when the queue is "},{"type":"text","text":"full","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"keepAliveTime","marks":[{"type":"code"}]}],[{"type":"text","text":"How long threads above core may stay idle"}]],[[{"type":"text","text":"workQueue","marks":[{"type":"code"}]}],[{"type":"text","text":"Where waiting tasks go: bounded "},{"type":"text","text":"ArrayBlockingQueue","marks":[{"type":"code"}]},{"type":"text","text":" recommended"}]],[[{"type":"text","text":"threadFactory","marks":[{"type":"code"}]}],[{"type":"text","text":"Name threads ("},{"type":"text","text":"order-worker-1","marks":[{"type":"code"}]},{"type":"text","text":"), set daemon/priority"}]],[[{"type":"text","text":"handler","marks":[{"type":"code"}]}],[{"type":"text","text":"Rejection policy when both queue and max threads are full"}]]]},"revision":1},{"id":"4040512b-7805-7c7c-89bc-f7e15bc4c7d4","type":"text","position":"aK","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"task arrives → threads < core? new thread → else queue it → queue full? thread up to max → else reject"}]}]}},"revision":1},{"id":"bc249d83-c7b0-7a1b-8e3e-fe4cdc24dc2f","type":"code","position":"aL","content":{"language":"java","code":"import java.util.concurrent.*;\n\npublic class Main {\n    public static void main(String[] args) throws InterruptedException {\n        CountDownLatch gate = new CountDownLatch(1);\n        ThreadPoolExecutor pool = new ThreadPoolExecutor(\n            1, 1, 0, TimeUnit.SECONDS,                 // exactly one thread\n            new ArrayBlockingQueue<>(1),               // room for one waiting task\n            new ThreadPoolExecutor.AbortPolicy());     // default: throw when full\n        Runnable blocker = () -> {\n            try { gate.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        };\n        pool.execute(blocker);                         // runs on the only thread\n        pool.execute(blocker);                         // waits in the queue\n        try {\n            pool.execute(blocker);                     // no thread, no queue space\n        } catch (RejectedExecutionException e) {\n            System.out.println(\"3rd task rejected\");\n        }\n        System.out.println(\"pool size = \" + pool.getPoolSize() + \", queued = \" + pool.getQueue().size());\n        gate.countDown();\n        pool.shutdown();\n        pool.awaitTermination(1, TimeUnit.SECONDS);\n        System.out.println(\"completed = \" + pool.getCompletedTaskCount());\n    }\n}","filename":"Java"},"revision":1},{"id":"8e71258d-cf45-7461-b904-4bf468fb7dd6","type":"code","position":"aM","content":{"language":"text","code":"3rd task rejected\npool size = 1, queued = 1\ncompleted = 2","filename":"Output"},"revision":1},{"id":"96053c82-2572-7799-a969-6c39775b82b6","type":"table","position":"aN","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Rejection policy"}],[{"type":"text","text":"Behaviour"}]],[[{"type":"text","text":"AbortPolicy","marks":[{"type":"code"}]},{"type":"text","text":" (default)"}],[{"type":"text","text":"Throw "},{"type":"text","text":"RejectedExecutionException","marks":[{"type":"code"}]}]],[[{"type":"text","text":"CallerRunsPolicy","marks":[{"type":"code"}]}],[{"type":"text","text":"Run the task on the submitting thread — natural back-pressure"}]],[[{"type":"text","text":"DiscardPolicy","marks":[{"type":"code"}]}],[{"type":"text","text":"Silently drop the new task"}]],[[{"type":"text","text":"DiscardOldestPolicy","marks":[{"type":"code"}]}],[{"type":"text","text":"Drop the oldest queued task, retry the new one"}]]]},"revision":1},{"id":"e2da8b16-27c0-721c-a74f-0d3dde92f1ca","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"How many threads?"}]},"revision":1},{"id":"d1dcc7cf-bb7b-7aad-92d6-b7c666008712","type":"text","position":"aP","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"threads ≈ cores × (1 + wait time / compute time)","marks":[{"type":"code"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CPU-bound","marks":[{"type":"bold"}]},{"type":"text","text":" (hashing, parsing, math): about "},{"type":"text","text":"Runtime.getRuntime().availableProcessors()","marks":[{"type":"code"}]},{"type":"text","text":" threads — more only adds context switching."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I/O-bound","marks":[{"type":"bold"}]},{"type":"text","text":" (HTTP calls, DB queries): many more, since threads mostly wait. On Java 21 prefer virtual threads here."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use separate pools for separate kinds of work, so a slow dependency can''t starve everything (bulkheads)."}]}]}]}]}},"revision":1},{"id":"3233a9ac-f41b-73d4-b0c1-553fedfddc46","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"submit() vs execute()?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"execute(Runnable)","marks":[{"type":"code"}]},{"type":"text","text":" comes from "},{"type":"text","text":"Executor","marks":[{"type":"code"}]},{"type":"text","text":", returns nothing, and an exception goes to the thread''s uncaught-exception handler. "},{"type":"text","text":"submit()","marks":[{"type":"code"}]},{"type":"text","text":" accepts "},{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Callable","marks":[{"type":"code"}]},{"type":"text","text":", returns a "},{"type":"text","text":"Future","marks":[{"type":"code"}]},{"type":"text","text":", and captures any exception inside it (rethrown as "},{"type":"text","text":"ExecutionException","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"get()","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"f8e3d22c-4508-7144-960d-a2b2e63d2b43","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is Executors.newFixedThreadPool considered risky in production?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Its "},{"type":"text","text":"LinkedBlockingQueue","marks":[{"type":"code"}]},{"type":"text","text":" is unbounded: if producers outpace workers, tasks pile up until "},{"type":"text","text":"OutOfMemoryError","marks":[{"type":"code"}]},{"type":"text","text":". Construct a "},{"type":"text","text":"ThreadPoolExecutor","marks":[{"type":"code"}]},{"type":"text","text":" with a bounded queue, named threads and an explicit rejection policy instead."}]}]}},"revision":1},{"id":"97291814-5205-7661-a712-c7a9176ccba5","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When does a ThreadPoolExecutor create threads beyond corePoolSize?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Only when the work queue is full. With an unbounded queue, "},{"type":"text","text":"maximumPoolSize","marks":[{"type":"code"}]},{"type":"text","text":" is never reached — a common surprise."}]}]}},"revision":1},{"id":"1b0cdc0e-2200-7b96-828c-6e941485de17","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"shutdown() vs shutdownNow()?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"shutdown()","marks":[{"type":"code"}]},{"type":"text","text":" is graceful: no new tasks, queued and running tasks complete. "},{"type":"text","text":"shutdownNow()","marks":[{"type":"code"}]},{"type":"text","text":" interrupts running tasks, drains the queue and returns the unstarted tasks. Follow either with "},{"type":"text","text":"awaitTermination","marks":[{"type":"code"}]},{"type":"text","text":" to actually wait."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
