  ('d0225f5b-36e9-7b6d-8853-f87e0d6ed05e', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Primitive specializations","marks":[{"type":"bold"}]},{"type":"text","text":" avoid boxing: "},{"type":"text","text":"IntPredicate","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IntFunction<R>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ToIntFunction<T>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IntUnaryOperator","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IntBinaryOperator","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IntSupplier","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IntConsumer","marks":[{"type":"code"}]},{"type":"text","text":" (plus "},{"type":"text","text":"Long*","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Double*","marks":[{"type":"code"}]},{"type":"text","text":" versions, and "},{"type":"text","text":"ObjIntConsumer<T>","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}}'),
  ('a0531ee0-b8a1-72e1-ae0c-d9824bea0e54', 'aB', 'code', '{"language":"java","code":"import java.util.function.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Predicate<String> isEmpty = String::isEmpty;\n        Function<String, Integer> length = String::length;\n        Consumer<String> shout = s -> System.out.println(s.toUpperCase());\n        Supplier<String> greeting = () -> \"hello\";\n        UnaryOperator<Integer> square = x -> x * x;\n        BinaryOperator<Integer> max = Math::max;\n        IntBinaryOperator add = (a, b) -> a + b;      // no boxing\n\n        System.out.println(isEmpty.test(\"\"));\n        System.out.println(length.apply(\"lambda\"));\n        shout.accept(\"java\");\n        System.out.println(greeting.get());\n        System.out.println(square.apply(7) + \" \" + max.apply(3, 9) + \" \" + add.applyAsInt(2, 3));\n    }\n}","filename":"Java"}'),
