  ('29dd9dc3-7b57-7b2d-9056-936a3c3a7fff', 'aK', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do primitive specializations like IntPredicate exist?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generics only work with reference types, so "},{"type":"text","text":"Predicate<Integer>","marks":[{"type":"code"}]},{"type":"text","text":" boxes every "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" into an "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"IntPredicate.test(int)","marks":[{"type":"code"}]},{"type":"text","text":" takes the primitive directly — no allocation, no unboxing — which matters in hot loops and streams ("},{"type":"text","text":"IntStream","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}}'),
  ('c2629154-5bd2-753b-be80-80f8b816195b', 'aL', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Function vs UnaryOperator vs BinaryOperator?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UnaryOperator<T>","marks":[{"type":"code"}]},{"type":"text","text":" extends "},{"type":"text","text":"Function<T, T>","marks":[{"type":"code"}]},{"type":"text","text":" (same input and output type); "},{"type":"text","text":"BinaryOperator<T>","marks":[{"type":"code"}]},{"type":"text","text":" extends "},{"type":"text","text":"BiFunction<T, T, T>","marks":[{"type":"code"}]},{"type":"text","text":". Use the narrower one when types match — it documents intent and fits APIs like "},{"type":"text","text":"List.replaceAll(UnaryOperator)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Stream.reduce(BinaryOperator)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}')
