SELECT '147ded25-b535-753d-99b6-6846e1ceac5f', 'fca4d0af-01b4-71b2-9c26-d2901e7b5cec', 1, 'PUBLISHED', 'Garbage Collection', '[{"id":"72c2bc15-f3b0-7cb7-9206-19b002f370ff","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The garbage collector frees heap objects that are no longer "},{"type":"text","text":"reachable","marks":[{"type":"italic"}]},{"type":"text","text":" — you never call "},{"type":"text","text":"free","marks":[{"type":"code"}]},{"type":"text","text":", but you still decide what stays reachable."}]}]}},"revision":1},{"id":"7c2938dd-5815-78fc-be99-8117b3dc2768","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Garbage","marks":[{"type":"bold"}]},{"type":"text","text":" — an object that cannot be reached by following references from any "},{"type":"text","text":"GC root","marks":[{"type":"bold"}]},{"type":"text","text":". Reference counting is "},{"type":"text","text":"not","marks":[{"type":"italic"}]},{"type":"text","text":" used, so cycles of objects pointing at each other are still collected."}]}]}},"revision":1},{"id":"cef0cf99-4925-7ee3-9e07-0e0f7f6ce87d","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"GC roots and reachability"}]},"revision":1},{"id":"6b889a83-3b6c-7ce7-97fd-31749908a9bb","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Local variables and parameters in every live thread''s stack frames."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Static fields of loaded classes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Active threads themselves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"JNI references held by native code, and objects used as monitors ("},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}]}]}},"revision":1},{"id":"c51fb71e-fd0c-7b07-a93f-231c526b487d","type":"code","position":"a4","content":{"language":"java","code":"public class Main {\n    static class Node { Node next; }\n\n    public static void main(String[] args) {\n        Node a = new Node();\n        Node b = new Node();\n        a.next = b;\n        b.next = a;          // a cycle: a → b → a\n\n        a = null;\n        b = null;            // no root reaches the cycle any more → both are garbage\n        System.out.println(\"the cycle is unreachable and will be collected\");\n    }\n}","filename":"Java"},"revision":1},{"id":"f7d62cbf-82cc-7bd5-9fa7-4763aca9ff5f","type":"code","position":"a5","content":{"language":"text","code":"the cycle is unreachable and will be collected","filename":"Output"},"revision":1},{"id":"fbf9b800-43cf-7c44-a94d-eeca7a0fbadb","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Generational collection"}]},"revision":1},{"id":"2b219998-4ecc-7bd9-b9e0-7bdab8e74e2d","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Weak generational hypothesis","marks":[{"type":"bold"}]},{"type":"text","text":": most objects die young (temporary strings, iterators, DTOs). So the heap is split and the young part is collected often and cheaply."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Allocate in Eden","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" bumps a pointer in a thread-local allocation buffer — allocation is extremely cheap."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Minor GC","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"When Eden fills, live objects are copied to a Survivor space; everything left in Eden is reclaimed at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Age and promote","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Each survived minor GC increments an object''s age; past a threshold it is "},{"type":"text","text":"promoted","marks":[{"type":"italic"}]},{"type":"text","text":" to the old generation."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Major / full GC","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"When the old generation fills, it is collected too — more expensive, historically the source of long pauses."}]}]}]}]}},"revision":1},{"id":"6f31350c-dd16-7ea3-8105-9c2173af5b9a","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Phase / term"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"Mark","marks":[{"type":"bold"}]}],[{"type":"text","text":"Trace from the roots and mark every reachable object."}]],[[{"type":"text","text":"Sweep","marks":[{"type":"bold"}]}],[{"type":"text","text":"Reclaim the memory of unmarked objects."}]],[[{"type":"text","text":"Compact","marks":[{"type":"bold"}]}],[{"type":"text","text":"Slide live objects together to remove fragmentation."}]],[[{"type":"text","text":"Copying","marks":[{"type":"bold"}]}],[{"type":"text","text":"Copy live objects to an empty space (used for the young gen: cost ∝ live objects, not heap size)."}]],[[{"type":"text","text":"Stop-the-world (STW)","marks":[{"type":"bold"}]}],[{"type":"text","text":"All application threads are paused while the GC works."}]],[[{"type":"text","text":"Concurrent","marks":[{"type":"bold"}]}],[{"type":"text","text":"GC work done while application threads keep running."}]]]},"revision":1},{"id":"a5aa8a32-296b-7b67-8c40-29749c3e0a80","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"The collectors"}]},"revision":1},{"id":"de62870e-bf11-77f5-b178-5880ec1a97ef","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Collector"}],[{"type":"text","text":"Flag"}],[{"type":"text","text":"Best for"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"Serial"}],[{"type":"text","text":"-XX:+UseSerialGC","marks":[{"type":"code"}]}],[{"type":"text","text":"Tiny heaps, single-core containers"}],[{"type":"text","text":"One thread, stop-the-world"}]],[[{"type":"text","text":"Parallel"}],[{"type":"text","text":"-XX:+UseParallelGC","marks":[{"type":"code"}]}],[{"type":"text","text":"Batch jobs — maximum throughput"}],[{"type":"text","text":"Many threads, still STW"}]],[[{"type":"text","text":"G1","marks":[{"type":"bold"}]},{"type":"text","text":" (default since 9)"}],[{"type":"text","text":"-XX:+UseG1GC","marks":[{"type":"code"}]}],[{"type":"text","text":"General purpose, heaps of GBs"}],[{"type":"text","text":"Region-based; targets a pause goal ("},{"type":"text","text":"-XX:MaxGCPauseMillis=200","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"ZGC"}],[{"type":"text","text":"-XX:+UseZGC","marks":[{"type":"code"}]},{"type":"text","text":" (generational in 21: "},{"type":"text","text":"-XX:+ZGenerational","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Huge heaps, low latency"}],[{"type":"text","text":"Pauses under a millisecond, mostly concurrent"}]],[[{"type":"text","text":"Shenandoah"}],[{"type":"text","text":"-XX:+UseShenandoahGC","marks":[{"type":"code"}]}],[{"type":"text","text":"Low latency"}],[{"type":"text","text":"Concurrent compaction (OpenJDK builds)"}]],[[{"type":"text","text":"CMS"}],[{"type":"text","text":"—"}],[{"type":"text","text":"—"}],[{"type":"text","text":"Deprecated in 9, "},{"type":"text","text":"removed in 14","marks":[{"type":"bold"}]}]]]},"revision":1},{"id":"91167f3d-e0f9-78e0-ad1b-3a36a13fa36f","type":"code","position":"aB","content":{"language":"","code":"$ java -XX:+UseZGC -Xmx4g -Xlog:gc App.java      # choose a collector, log each GC\n$ java -Xlog:gc*:file=gc.log App.java            # detailed GC log to a file\n$ jcmd <pid> GC.heap_info                        # inspect a running JVM","filename":"Terminal"},"revision":1},{"id":"cc6fd8b3-ed27-7d0e-b8b7-25de2cc2cf5e","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"System.gc(), finalize() and cleanup"}]},"revision":1},{"id":"9275021f-fa1e-7f64-8c67-70cdb9bf2ca2","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System.gc()","marks":[{"type":"code"}]},{"type":"text","text":" is only a "},{"type":"text","text":"hint","marks":[{"type":"bold"}]},{"type":"text","text":" — the JVM may ignore it ("},{"type":"text","text":"-XX:+DisableExplicitGC","marks":[{"type":"code"}]},{"type":"text","text":"), and when honoured it usually triggers an expensive full GC. Never call it to “free memory”."}]}]}},"revision":1},{"id":"9fe42e5f-18ae-72c2-8d59-261ce469963b","type":"callout","position":"aE","content":{"variant":"warning","title":"finalize()","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"finalize()","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"deprecated for removal","marks":[{"type":"bold"}]},{"type":"text","text":" (Java 9/18): it runs at an unpredictable time or never, slows GC, and can resurrect objects. Release resources with "},{"type":"text","text":"try-with-resources","marks":[{"type":"code"}]},{"type":"text","text":"; for a safety net use "},{"type":"text","text":"java.lang.ref.Cleaner","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"882837b0-6e54-72d1-89be-dcfbd495b8dc","type":"code","position":"aF","content":{"language":"java","code":"import java.lang.ref.Cleaner;\n\npublic class Main {\n    static final Cleaner CLEANER = Cleaner.create();\n\n    static class Resource implements AutoCloseable {\n        private final Cleaner.Cleanable cleanable;\n\n        Resource(String name) {\n            // the cleanup action must NOT capture `this`, or the object never becomes unreachable\n            cleanable = CLEANER.register(this, () -> System.out.println(\"released \" + name));\n        }\n\n        @Override\n        public void close() { cleanable.clean(); }   // runs the action at most once\n    }\n\n    public static void main(String[] args) {\n        try (Resource r = new Resource(\"db-connection\")) {\n            System.out.println(\"using the resource\");\n        }\n        System.out.println(\"after try\");\n    }\n}","filename":"Java"},"revision":1},{"id":"c66c5c79-b359-7d2a-a0ff-1f2b7ff3825f","type":"code","position":"aG","content":{"language":"text","code":"using the resource\nreleased db-connection\nafter try","filename":"Output"},"revision":1},{"id":"4250451c-3330-7890-8508-4fdd6825b3d4","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Tuning in practice"}]},"revision":1},{"id":"60cff30b-f008-7b49-8bd9-ca0075278d50","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Measure first: GC logs ("},{"type":"text","text":"-Xlog:gc","marks":[{"type":"code"}]},{"type":"text","text":"), JDK Flight Recorder ("},{"type":"text","text":"-XX:StartFlightRecording","marks":[{"type":"code"}]},{"type":"text","text":"), "},{"type":"text","text":"jstat -gc <pid>","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Size the heap: set "},{"type":"text","text":"-Xms","marks":[{"type":"code"}]},{"type":"text","text":" = "},{"type":"text","text":"-Xmx","marks":[{"type":"code"}]},{"type":"text","text":" for servers to avoid resizing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pick the collector by goal: throughput → Parallel, balanced → G1, latency → ZGC."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reduce garbage: reuse builders, avoid needless boxing, stream large files instead of loading them."}]}]}]}]}},"revision":1},{"id":"7c3cd396-7a6a-77b5-86ea-86c0bc927c25","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can an object be garbage collected while it still references other objects?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes. Reachability is about incoming references "},{"type":"text","text":"from roots","marks":[{"type":"italic"}]},{"type":"text","text":". An object that points to others — even a whole cycle — is garbage as soon as no root can reach it."}]}]}},"revision":1},{"id":"1969b134-f46f-7f17-a676-d74b30ca5f09","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a stop-the-world pause and how do modern collectors reduce it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A pause during which all application threads are stopped so the GC can work on a consistent heap. G1 limits pause length by collecting a subset of regions per cycle; ZGC and Shenandoah do marking "},{"type":"text","text":"and","marks":[{"type":"italic"}]},{"type":"text","text":" compaction concurrently, keeping pauses below ~1 ms regardless of heap size."}]}]}},"revision":1},{"id":"29a592cc-27ba-7788-b21a-6d6722a4ee94","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Minor GC vs major GC?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A minor GC collects only the young generation — frequent and fast because most young objects are dead. A major (old-gen) or full GC collects the old generation or the whole heap — rarer and much more expensive."}]}]}},"revision":1},{"id":"ed78fc4a-4a13-72bf-8cc3-f332f18a3146","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does calling System.gc() guarantee collection?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. It is a request the JVM may ignore. Code that depends on it for correctness is broken."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
