SELECT 'ae5d7fb2-c4e5-75f8-922f-64c47ee3209a', '41064738-53b6-7f00-aac3-544f799675de', 1, 'PUBLISHED', 'Wildcards, PECS & Type Erasure', '[{"id":"fab1ef58-25b2-74c9-88df-13e747c4449a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"List<Integer>","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" a "},{"type":"text","text":"List<Number>","marks":[{"type":"code"}]},{"type":"text","text":". Wildcards ("},{"type":"text","text":"?","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"? extends","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"? super","marks":[{"type":"code"}]},{"type":"text","text":") restore flexibility, PECS tells you which to use, and type erasure explains generics'' odd limitations."}]}]}},"revision":1},{"id":"99d4c1c1-15fe-782a-8b6b-a2b01ee74fae","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Generics are invariant"}]},"revision":1},{"id":"4cd41b3e-673c-79d0-be25-acce0682c655","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Even though "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":" is a "},{"type":"text","text":"Number","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"List<Integer>","marks":[{"type":"code"}]},{"type":"text","text":" is not a subtype of "},{"type":"text","text":"List<Number>","marks":[{"type":"code"}]},{"type":"text","text":". If it were, you could add a "},{"type":"text","text":"Double","marks":[{"type":"code"}]},{"type":"text","text":" to a list of integers through the "},{"type":"text","text":"List<Number>","marks":[{"type":"code"}]},{"type":"text","text":" reference."}]}]}},"revision":1},{"id":"0d0d9499-2c03-7d31-8834-d50d6ae2a0b6","type":"code","position":"a3","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> ints = new ArrayList<>();\n        List<Number> nums = ints;          // not allowed\n        nums.add(3.14);\n    }\n}","filename":"Java"},"revision":1},{"id":"fa9df78d-db88-7096-890d-e4678ed12922","type":"code","position":"a4","content":{"language":"text","code":"Main.java:6: error: incompatible types: List<Integer> cannot be converted to List<Number>\n        List<Number> nums = ints;          // not allowed\n                            ^","filename":"Compiler error"},"revision":1},{"id":"8cd27454-b7d5-7b59-b640-e10e3e9ab4bc","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrays are "},{"type":"text","text":"covariant","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"Integer[]","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"is","marks":[{"type":"italic"}]},{"type":"text","text":" an "},{"type":"text","text":"Object[]","marks":[{"type":"code"}]},{"type":"text","text":"), so the same mistake compiles and only fails at runtime:"}]}]}},"revision":1},{"id":"b65ce69a-13e2-7d71-9371-74721957270c","type":"code","position":"a6","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        Object[] objs = new Integer[2];      // compiles: arrays are covariant\n        objs[0] = 1;\n        try {\n            objs[1] = \"text\";                // runtime type check\n        } catch (ArrayStoreException e) {\n            System.out.println(\"ArrayStoreException: \" + e.getMessage());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"a861cb81-de5a-74fb-8047-a57977fa881a","type":"code","position":"a7","content":{"language":"text","code":"ArrayStoreException: java.lang.String","filename":"Output"},"revision":1},{"id":"8b4a14f8-d909-7dcd-86d3-28f9e8eac0e9","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"The three wildcards"}]},"revision":1},{"id":"b8133d9e-6394-7ac7-ae40-4ce31b1cb769","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Wildcard"}],[{"type":"text","text":"Accepts"}],[{"type":"text","text":"Read as"}],[{"type":"text","text":"Can add?"}]],[[{"type":"text","text":"List<?>","marks":[{"type":"code"}]}],[{"type":"text","text":"A list of "},{"type":"text","text":"any","marks":[{"type":"italic"}]},{"type":"text","text":" type"}],[{"type":"text","text":"Object","marks":[{"type":"code"}]}],[{"type":"text","text":"Only "},{"type":"text","text":"null","marks":[{"type":"code"}]}]],[[{"type":"text","text":"List<? extends Number>","marks":[{"type":"code"}]}],[{"type":"text","text":"List<Number>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"List<Integer>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"List<Double>","marks":[{"type":"code"}]},{"type":"text","text":"…"}],[{"type":"text","text":"Number","marks":[{"type":"code"}]}],[{"type":"text","text":"No (except "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"List<? super Integer>","marks":[{"type":"code"}]}],[{"type":"text","text":"List<Integer>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"List<Number>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"List<Object>","marks":[{"type":"code"}]}],[{"type":"text","text":"Object","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":"s"}]]]},"revision":1},{"id":"8424c7c8-590d-7a75-8b82-beb0c9e98824","type":"code","position":"aA","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static double sum(List<? extends Number> nums) {    // producer: we only read\n        double s = 0;\n        for (Number n : nums) s += n.doubleValue();\n        return s;\n    }\n\n    static void fill(List<? super Integer> sink, int n) { // consumer: we only write\n        for (int i = 1; i <= n; i++) sink.add(i);\n    }\n\n    static int count(Collection<?> anything) { return anything.size(); }\n\n    public static void main(String[] args) {\n        System.out.println(sum(List.of(1, 2, 3)));         // List<Integer>\n        System.out.println(sum(List.of(1.5, 2.5)));        // List<Double>\n\n        List<Number> numbers = new ArrayList<>();\n        List<Object> objects = new ArrayList<>();\n        fill(numbers, 3);\n        fill(objects, 2);\n        System.out.println(numbers + \" \" + objects);\n        System.out.println(count(Set.of(\"a\", \"b\")));\n    }\n}","filename":"Java"},"revision":1},{"id":"1f5870e6-b89a-75bd-ab42-9b5877221a8c","type":"code","position":"aB","content":{"language":"text","code":"6.0\n4.0\n[1, 2, 3] [1, 2]\n2","filename":"Output"},"revision":1},{"id":"eab11685-77be-7e0b-b39a-a0928e0636fa","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"PECS: Producer Extends, Consumer Super"}]},"revision":1},{"id":"3a12dc15-38d5-716f-9953-1071b53ed838","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If a parameter ","marks":[{"type":"code"}]},{"type":"text","text":"produces","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" Ts for you → ? extends T. If it ","marks":[{"type":"code"}]},{"type":"text","text":"consumes","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" Ts → ? super T. Both → plain T.","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"61153105-51e1-7c48-b760-9158db7ed842","type":"code","position":"aE","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    // src produces T (extends), dest consumes T (super) — same shape as Collections.copy\n    static <T> void copy(List<? super T> dest, List<? extends T> src) {\n        for (T item : src) dest.add(item);\n    }\n\n    public static void main(String[] args) {\n        List<Integer> ints = List.of(1, 2);\n        List<Double> doubles = List.of(3.5);\n        List<Number> all = new ArrayList<>();\n        copy(all, ints);                      // T = Integer, Number is a super of it\n        copy(all, doubles);                   // T = Double\n        System.out.println(all);\n\n        List<Object> objs = new ArrayList<>(List.of(\"x\"));\n        Main.<Integer>copy(objs, ints);\n        System.out.println(objs);\n    }\n}","filename":"Java"},"revision":1},{"id":"4be1c678-b926-7655-a272-6ebb02e2ad4e","type":"code","position":"aF","content":{"language":"text","code":"[1, 2, 3.5]\n[x, 1, 2]","filename":"Output"},"revision":1},{"id":"75727b7a-bb8a-78c0-901c-37caf7dc1643","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JDK examples: "},{"type":"text","text":"Collections.copy(List<? super T> dest, List<? extends T> src)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"addAll(Collection<? extends E>)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"sort(Comparator<? super E>)","marks":[{"type":"code"}]},{"type":"text","text":" — a "},{"type":"text","text":"Comparator<Object>","marks":[{"type":"code"}]},{"type":"text","text":" can sort a list of strings."}]}]}},"revision":1},{"id":"fe0f75ff-a43e-75de-8655-5327b170f80b","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Type erasure"}]},"revision":1},{"id":"fc64962b-db3b-7d19-9604-22e996df746e","type":"callout","position":"aI","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Type erasure","marks":[{"type":"bold"}]},{"type":"text","text":" — generics exist only at compile time. The compiler checks types, inserts casts, then replaces each type parameter with its bound ("},{"type":"text","text":"Object","marks":[{"type":"code"}]},{"type":"text","text":" if unbounded). At runtime, "},{"type":"text","text":"List<String>","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"List<Integer>","marks":[{"type":"code"}]},{"type":"text","text":" are the same class, "},{"type":"text","text":"ArrayList","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"60d046d8-eb88-700a-9768-d24060379644","type":"code","position":"aJ","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> a = new ArrayList<>();\n        List<Integer> b = new ArrayList<>();\n        System.out.println(a.getClass() == b.getClass());\n        System.out.println(a.getClass().getName());\n        Object o = a;\n        System.out.println(o instanceof List<?>);      // OK: unbounded wildcard\n        // o instanceof List<String>                   // error: can''t check a type argument at runtime\n    }\n}","filename":"Java"},"revision":1},{"id":"f62a66c6-0b0b-76be-a5ae-5ccc6c272509","type":"code","position":"aK","content":{"language":"text","code":"true\njava.util.ArrayList\ntrue","filename":"Output"},"revision":1},{"id":"b40d9c24-59aa-7c19-a335-0f5ca3548f53","type":"table","position":"aL","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"You can''t…"}],[{"type":"text","text":"Because at runtime "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" is erased"}],[{"type":"text","text":"Workaround"}]],[[{"type":"text","text":"new T()","marks":[{"type":"code"}]}],[{"type":"text","text":"The JVM doesn''t know what "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" is"}],[{"type":"text","text":"Pass a "},{"type":"text","text":"Supplier<T>","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Class<T>","marks":[{"type":"code"}]}]],[[{"type":"text","text":"new T[n]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"new List<String>[n]","marks":[{"type":"code"}]}],[{"type":"text","text":"Arrays need their exact element type at runtime"}],[{"type":"text","text":"Use a "},{"type":"text","text":"List<T>","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":"(T[]) new Object[n]","marks":[{"type":"code"}]},{"type":"text","text":" with care"}]],[[{"type":"text","text":"x instanceof List<String>","marks":[{"type":"code"}]}],[{"type":"text","text":"Type arguments aren''t stored"}],[{"type":"text","text":"instanceof List<?>","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Overload "},{"type":"text","text":"f(List<String>)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"f(List<Integer>)","marks":[{"type":"code"}]}],[{"type":"text","text":"Both erase to "},{"type":"text","text":"f(List)","marks":[{"type":"code"}]},{"type":"text","text":" — same signature"}],[{"type":"text","text":"Use different method names"}]],[[{"type":"text","text":"catch (T e)","marks":[{"type":"code"}]},{"type":"text","text":" / generic exception classes"}],[{"type":"text","text":"Catch needs a runtime type"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"Use primitives as type arguments"}],[{"type":"text","text":"Erasure turns "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" into "},{"type":"text","text":"Object","marks":[{"type":"code"}]}],[{"type":"text","text":"Boxed types, or specialised streams ("},{"type":"text","text":"IntStream","marks":[{"type":"code"}]},{"type":"text","text":")"}]]]},"revision":1},{"id":"11219702-9005-7e4e-a91c-ad53bb32d97d","type":"code","position":"aM","content":{"language":"java","code":"import java.util.*;\nimport java.util.function.Supplier;\n\npublic class Main {\n    static <T> List<T> nCopies(int n, Supplier<T> factory) {    // instead of new T()\n        List<T> out = new ArrayList<>();\n        for (int i = 0; i < n; i++) out.add(factory.get());\n        return out;\n    }\n\n    static <T> T create(Class<T> type) throws ReflectiveOperationException {\n        return type.getDeclaredConstructor().newInstance();\n    }\n\n    public static void main(String[] args) throws Exception {\n        System.out.println(nCopies(3, StringBuilder::new).size());\n        System.out.println(create(ArrayList.class).isEmpty());\n    }\n}","filename":"Java"},"revision":1},{"id":"9053e45d-0fb0-7eff-a755-2afd74356a2e","type":"code","position":"aN","content":{"language":"text","code":"3\ntrue","filename":"Output"},"revision":1},{"id":"dc6428bb-ba71-7076-83cd-14812c7508c7","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Bridge methods and heap pollution"}]},"revision":1},{"id":"648d1f16-ea43-7e9b-9208-ce6273bd2732","type":"text","position":"aP","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When a class implements "},{"type":"text","text":"Comparable<Money>","marks":[{"type":"code"}]},{"type":"text","text":", its "},{"type":"text","text":"compareTo(Money)","marks":[{"type":"code"}]},{"type":"text","text":" erases differently from the interface''s "},{"type":"text","text":"compareTo(Object)","marks":[{"type":"code"}]},{"type":"text","text":". The compiler generates a synthetic "},{"type":"text","text":"bridge method","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"compareTo(Object)","marks":[{"type":"code"}]},{"type":"text","text":" that casts and delegates, so polymorphism still works after erasure."}]}]}},"revision":1},{"id":"083320d1-cfb9-7e7d-989d-f6f987b32331","type":"code","position":"aQ","content":{"language":"java","code":"import java.lang.reflect.Method;\n\npublic class Main {\n    record Money(long cents) implements Comparable<Money> {\n        public int compareTo(Money o) { return Long.compare(cents, o.cents); }\n    }\n\n    public static void main(String[] args) {\n        java.util.List<String> found = new java.util.ArrayList<>();\n        for (Method m : Money.class.getDeclaredMethods())\n            if (m.getName().equals(\"compareTo\"))\n                found.add(\"compareTo(\" + m.getParameterTypes()[0].getSimpleName() + \")\"\n                          + (m.isBridge() ? \" <- bridge\" : \"\"));\n        java.util.Collections.sort(found);\n        found.forEach(System.out::println);\n    }\n}","filename":"Java"},"revision":1},{"id":"57fe7c93-aaaf-721b-a770-2d2a9a89d651","type":"code","position":"aR","content":{"language":"text","code":"compareTo(Money)\ncompareTo(Object) <- bridge","filename":"Output"},"revision":1},{"id":"465e9984-3c76-79fc-800b-3e9dd68a3795","type":"text","position":"aS","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Heap pollution","marks":[{"type":"bold"}]},{"type":"text","text":" happens when a variable of a parameterised type refers to an object that isn''t of that type — typically through raw types, unchecked casts or generic varargs ("},{"type":"text","text":"T...","marks":[{"type":"code"}]},{"type":"text","text":" creates a "},{"type":"text","text":"T[]","marks":[{"type":"code"}]},{"type":"text","text":"). The compiler warns ("},{"type":"text","text":"unchecked","marks":[{"type":"code"}]},{"type":"text","text":"); "},{"type":"text","text":"@SafeVarargs","marks":[{"type":"code"}]},{"type":"text","text":" marks a varargs method that doesn''t misuse its array."}]}]}},"revision":1},{"id":"e9d0d8db-8e84-7200-b0ad-be7406dee942","type":"callout","position":"aT","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"unchecked","marks":[{"type":"code"}]},{"type":"text","text":" warning means the compiler can no longer guarantee type safety: a "},{"type":"text","text":"ClassCastException","marks":[{"type":"code"}]},{"type":"text","text":" may appear later, far from the real bug, at a cast the compiler inserted. Don''t suppress it unless you can prove the cast is safe."}]}]}},"revision":1},{"id":"a3beda17-7b8c-78d9-ab46-7e71ac8a870b","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is PECS?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Producer Extends, Consumer Super","marks":[{"type":"italic"}]},{"type":"text","text":": use "},{"type":"text","text":"? extends T","marks":[{"type":"code"}]},{"type":"text","text":" for a parameter you read "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":"s from, "},{"type":"text","text":"? super T","marks":[{"type":"code"}]},{"type":"text","text":" for one you write "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":"s into. E.g. "},{"type":"text","text":"copy(List<? super T> dest, List<? extends T> src)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"92e97a8d-657e-72fc-8f0e-467547852f00","type":"question","position":"aV","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is List<Integer> not a subtype of List<Number>?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generics are invariant for type safety: if it were, you could write "},{"type":"text","text":"List<Number> n = ints; n.add(2.5);","marks":[{"type":"code"}]},{"type":"text","text":" and corrupt a list of integers. Use "},{"type":"text","text":"List<? extends Number>","marks":[{"type":"code"}]},{"type":"text","text":" when you only need to read."}]}]}},"revision":1},{"id":"0e6a2fb2-8bd9-7c50-b332-7818e1da92a5","type":"question","position":"aW","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is type erasure and what are its consequences?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The compiler removes type arguments after checking them, replacing type variables with their bounds and inserting casts. So generic type info isn''t available at runtime: no "},{"type":"text","text":"new T()","marks":[{"type":"code"}]},{"type":"text","text":", no generic arrays, no "},{"type":"text","text":"instanceof List<String>","marks":[{"type":"code"}]},{"type":"text","text":", and methods differing only by type argument clash."}]}]}},"revision":1},{"id":"431b9025-21bc-789e-9f19-baa832f30a18","type":"question","position":"aX","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"List<?> vs List<Object>?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"List<Object>","marks":[{"type":"code"}]},{"type":"text","text":" is a list you may add "},{"type":"text","text":"any","marks":[{"type":"italic"}]},{"type":"text","text":" object to, and only a "},{"type":"text","text":"List<Object>","marks":[{"type":"code"}]},{"type":"text","text":" can be passed. "},{"type":"text","text":"List<?>","marks":[{"type":"code"}]},{"type":"text","text":" accepts a list of "},{"type":"text","text":"any","marks":[{"type":"italic"}]},{"type":"text","text":" element type, but you can only read "},{"type":"text","text":"Object","marks":[{"type":"code"}]},{"type":"text","text":"s from it and add nothing but "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
