SELECT '65f29043-d9c2-7155-8e89-090864cef30a', '78a01bf2-ba4d-764e-a033-933866ea61e0', 1, 'PUBLISHED', 'Immutable Classes', '[{"id":"87694e09-99b8-7b1f-a15e-54339c74151d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An immutable object''s state can''t change after construction. It is automatically thread-safe, safe to share and cache, and safe as a "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":" key — "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"LocalDate","marks":[{"type":"code"}]},{"type":"text","text":" are all immutable."}]}]}},"revision":1},{"id":"506f4bad-8cb5-737e-9ef9-e42a204ac8c6","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The recipe"}]},"revision":1},{"id":"c5f874c4-9573-73e1-b22f-fc978b9f6c2e","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Make the class ","marks":[{"type":"bold"}]},{"type":"text","text":"final","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"(or make constructors private with static factories) so no subclass can add mutable state."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Make every field ","marks":[{"type":"bold"}]},{"type":"text","text":"private final","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"assigned once, in the constructor."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No setters","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"no method that changes a field. \"Withers\" return a "},{"type":"text","text":"new","marks":[{"type":"italic"}]},{"type":"text","text":" object: "},{"type":"text","text":"withPrice(…)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Defensive copy mutable inputs","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"copy lists/arrays/dates passed to the constructor, so the caller can''t change them later."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Never expose mutable internals","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"return copies or unmodifiable views from getters."}]}]}]}]}},"revision":1},{"id":"32610a47-5a97-789e-b841-35af7f2502db","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"A broken \"immutable\" class"}]},"revision":1},{"id":"c2d6e48f-2b6f-7925-9aa0-706efcc514cb","type":"code","position":"a4","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> tags = new ArrayList<>(List.of(\"java\"));\n        Article a = new Article(\"Intro\", tags);\n        tags.add(\"hacked\");                 // caller still holds the same list\n        a.tags().clear();                   // getter hands out the internal list\n        a.tags().add(\"oops\");\n        System.out.println(a.tags());\n    }\n}\n\nfinal class Article {\n    private final String title;\n    private final List<String> tags;        // final reference, mutable list\n    Article(String title, List<String> tags) { this.title = title; this.tags = tags; }\n    List<String> tags() { return tags; }\n}","filename":"Java"},"revision":1},{"id":"9f97531b-4fa7-747e-a54f-60a314c5f0f6","type":"code","position":"a5","content":{"language":"text","code":"[oops]","filename":"Output"},"revision":1},{"id":"8113ef93-d77b-7457-8eda-f3e09eca890c","type":"callout","position":"a6","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":" makes the "},{"type":"text","text":"reference","marks":[{"type":"italic"}]},{"type":"text","text":" unchangeable, not the object it points to. A "},{"type":"text","text":"final List","marks":[{"type":"code"}]},{"type":"text","text":" can still be cleared."}]}]}},"revision":1},{"id":"15c22e44-cded-7b07-b48d-fad6feac8108","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Fixed with defensive copies"}]},"revision":1},{"id":"f8a1662f-ba04-7605-bdcc-f68b41968027","type":"code","position":"a8","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> tags = new ArrayList<>(List.of(\"java\"));\n        Article a = new Article(\"Intro\", tags);\n        tags.add(\"hacked\");                           // no effect on a\n        try {\n            a.tags().add(\"oops\");\n        } catch (UnsupportedOperationException e) {\n            System.out.println(\"read-only\");\n        }\n        Article b = a.withTitle(\"Basics\");            // \"modify\" = new object\n        System.out.println(a.title() + \" \" + a.tags());\n        System.out.println(b.title() + \" \" + b.tags());\n    }\n}\n\nfinal class Article {\n    private final String title;\n    private final List<String> tags;\n    Article(String title, List<String> tags) {\n        this.title = Objects.requireNonNull(title);\n        this.tags = List.copyOf(tags);                // copy in (and unmodifiable)\n    }\n    String title() { return title; }\n    List<String> tags() { return tags; }              // safe: already unmodifiable\n    Article withTitle(String t) { return new Article(t, tags); }\n}","filename":"Java"},"revision":1},{"id":"5b0651f3-b08b-76ba-9207-c8b158e23a0b","type":"code","position":"a9","content":{"language":"text","code":"read-only\nIntro [java]\nBasics [java]","filename":"Output"},"revision":1},{"id":"f263a873-6aee-7056-be85-fb5d672e6da3","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Unmodifiable view vs immutable copy"}]},"revision":1},{"id":"2889dec7-1635-7e87-887c-46da920d1610","type":"code","position":"aB","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> src = new ArrayList<>(List.of(1, 2));\n        List<Integer> view = Collections.unmodifiableList(src);   // a read-only window\n        List<Integer> copy = List.copyOf(src);                    // an independent snapshot\n        src.add(3);\n        System.out.println(view);    // sees the change!\n        System.out.println(copy);    // doesn''t\n        try {\n            List.of(1, null);\n        } catch (NullPointerException e) {\n            System.out.println(\"List.of rejects nulls\");\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"f55a7969-d1d9-78cf-a3ca-c8e77d748f2e","type":"code","position":"aC","content":{"language":"text","code":"[1, 2, 3]\n[1, 2]\nList.of rejects nulls","filename":"Output"},"revision":1},{"id":"939faa57-89cf-7a7b-8e22-ef36faae6ca7","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"API"}],[{"type":"text","text":"Can you modify it?"}],[{"type":"text","text":"Reflects source changes?"}],[{"type":"text","text":"Nulls"}]],[[{"type":"text","text":"Collections.unmodifiableList(src)","marks":[{"type":"code"}]}],[{"type":"text","text":"No ("},{"type":"text","text":"UnsupportedOperationException","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Yes","marks":[{"type":"bold"}]},{"type":"text","text":" — it''s a view"}],[{"type":"text","text":"Allowed"}]],[[{"type":"text","text":"List.copyOf(src)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Set.copyOf","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Map.copyOf","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"No — snapshot"}],[{"type":"text","text":"Rejected"}]],[[{"type":"text","text":"List.of(…)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Set.of","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Map.of","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"—"}],[{"type":"text","text":"Rejected"}]],[[{"type":"text","text":"stream().toList()","marks":[{"type":"code"}]},{"type":"text","text":" (16+)"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Allowed"}]],[[{"type":"text","text":"Collectors.toList()","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes (currently an "},{"type":"text","text":"ArrayList","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Allowed"}]]]},"revision":1},{"id":"d3da63ec-c51a-7cf6-a1b7-34f21e40c541","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Why bother?"}]},"revision":1},{"id":"e96dc451-b236-71ce-97d8-be58d082860e","type":"callout","position":"aF","content":{"variant":"note","title":"Thread-safe for free","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No state changes → no races, no locks. Can be shared across threads freely."}]}]}},"revision":1},{"id":"27a479ef-da3c-7f79-a1ef-39ee8aee48be","type":"callout","position":"aG","content":{"variant":"note","title":"Safe keys & set members","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash code never changes, so the object never gets lost in a "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"7b86c37f-44da-7d0f-802d-68b44f642221","type":"callout","position":"aH","content":{"variant":"note","title":"Cacheable & shareable","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Integer.valueOf","marks":[{"type":"code"}]},{"type":"text","text":" cache, the string pool and "},{"type":"text","text":"BigInteger.ZERO","marks":[{"type":"code"}]},{"type":"text","text":" all rely on immutability."}]}]}},"revision":1},{"id":"6dddfff9-4288-79e7-87eb-187ff00276cf","type":"callout","position":"aI","content":{"variant":"note","title":"Easier reasoning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Validate once in the constructor; the invariant holds forever. No defensive copies needed by callers."}]}]}},"revision":1},{"id":"14425ac1-8f8e-7473-bacb-669c09f062c9","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The cost is allocating a new object for every change. For heavy step-by-step construction, pair the immutable class with a mutable builder (like "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"StringBuilder","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"9c6c9c14-8742-7e02-a5f5-387a32f54a2b","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you make a class immutable?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":" class, "},{"type":"text","text":"private final","marks":[{"type":"code"}]},{"type":"text","text":" fields, no setters, validate in the constructor, defensively copy mutable arguments in, and never hand out references to mutable internals (return copies or unmodifiable collections). Records do most of this for you, except the deep copying."}]}]}},"revision":1},{"id":"94d6489c-f2a1-76e2-b067-a2fae52e6ea6","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is String immutable?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"So it can be pooled and shared (string literals), cache its hash code (fast "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":" keys), be used safely for security-sensitive values (class names, file paths, URLs) and be shared across threads without synchronization."}]}]}},"revision":1},{"id":"330eb0c6-2cdf-7f56-b8c7-fb92f9cfd3a5","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Collections.unmodifiableList vs List.copyOf?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"unmodifiableList","marks":[{"type":"code"}]},{"type":"text","text":" is a read-only "},{"type":"text","text":"view","marks":[{"type":"italic"}]},{"type":"text","text":": you can''t modify through it, but changes to the underlying list show through. "},{"type":"text","text":"List.copyOf","marks":[{"type":"code"}]},{"type":"text","text":" makes an independent immutable snapshot (and rejects nulls)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
