SELECT 'ab7ac7a1-73b8-726e-93d0-85d125cfb57b', 'dfa86468-c770-7dfc-8808-710da092ea7c', 1, 'PUBLISHED', 'Interfaces', '[{"id":"144bb35f-185b-7327-8af7-ff59eb18c61b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An interface is a contract of methods a class promises to provide. A class can implement many interfaces — Java''s answer to multiple inheritance."}]}]}},"revision":1},{"id":"f1757d9d-cb15-7083-b142-aa502ec573b3","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Interface","marks":[{"type":"bold"}]},{"type":"text","text":" — a reference type declaring abstract methods (plus, since Java 8, "},{"type":"text","text":"default","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" methods, and since Java 9, "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" methods). Fields are implicitly "},{"type":"text","text":"public static final","marks":[{"type":"code"}]},{"type":"text","text":" constants."}]}]}},"revision":1},{"id":"43105f65-060d-714c-bbb1-7e2bc77b5d46","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"What an interface can contain"}]},"revision":1},{"id":"d8cc0db0-84ac-7e83-bd5d-ae2f8a643480","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Member"}],[{"type":"text","text":"Implicit modifiers"}],[{"type":"text","text":"Since"}]],[[{"type":"text","text":"Abstract method"}],[{"type":"text","text":"public abstract","marks":[{"type":"code"}]}],[{"type":"text","text":"1.0"}]],[[{"type":"text","text":"Constant field"}],[{"type":"text","text":"public static final","marks":[{"type":"code"}]}],[{"type":"text","text":"1.0"}]],[[{"type":"text","text":"default","marks":[{"type":"code"}]},{"type":"text","text":" method (has a body, inherited)"}],[{"type":"text","text":"public","marks":[{"type":"code"}]}],[{"type":"text","text":"8"}]],[[{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" method (called on the interface only)"}],[{"type":"text","text":"public","marks":[{"type":"code"}]}],[{"type":"text","text":"8"}]],[[{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"private static","marks":[{"type":"code"}]},{"type":"text","text":" helper method"}],[{"type":"text","text":"—"}],[{"type":"text","text":"9"}]],[[{"type":"text","text":"Nested types"}],[{"type":"text","text":"public static","marks":[{"type":"code"}]}],[{"type":"text","text":"1.0"}]]]},"revision":1},{"id":"04227391-8f78-765a-a340-d6d4e3fd26e2","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Implementing several interfaces"}]},"revision":1},{"id":"864aeb09-f0cb-7330-a460-3a580ed5f0de","type":"code","position":"a5","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    public static void main(String[] args) {\n        Duck duck = new Duck();\n        List<Swimmer> swimmers = new ArrayList<>(List.of(duck, new Fish()));\n        for (Swimmer s : swimmers) s.swim();\n        Flyer f = duck;                     // a Duck is also a Flyer\n        f.fly();\n        System.out.println(Flyer.MAX_ALTITUDE);\n        System.out.println(duck instanceof Swimmer && duck instanceof Flyer);\n    }\n}\n\ninterface Swimmer { void swim(); }\ninterface Flyer {\n    int MAX_ALTITUDE = 10_000;              // public static final\n    void fly();\n}\n\nclass Duck implements Swimmer, Flyer {\n    public void swim() { System.out.println(\"duck paddles\"); }   // must be public\n    public void fly()  { System.out.println(\"duck flies\"); }\n}\n\nclass Fish implements Swimmer {\n    public void swim() { System.out.println(\"fish swims\"); }\n}","filename":"Java"},"revision":1},{"id":"af6be119-8ef8-7c87-b34c-dd41eab4210f","type":"code","position":"a6","content":{"language":"text","code":"duck paddles\nfish swims\nduck flies\n10000\ntrue","filename":"Output"},"revision":1},{"id":"73f0ca6c-cbb1-74c0-9a46-979f0e52e5ab","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Default, static and private methods"}]},"revision":1},{"id":"0863ed51-bebc-703d-9f61-1e5cdd58e2a0","type":"code","position":"a8","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        Greeter en = name -> \"Hello, \" + name;    // one abstract method → lambda works\n        System.out.println(en.greet(\"Asha\"));\n        System.out.println(en.greetLoudly(\"Ravi\"));      // default method\n        System.out.println(Greeter.polite().greet(\"Meera\"));   // static factory\n    }\n}\n\ninterface Greeter {\n    String greet(String name);                  // abstract\n\n    default String greetLoudly(String name) {   // inherited, can be overridden\n        return shout(greet(name));\n    }\n\n    static Greeter polite() {                   // Greeter.polite(), not inherited by implementers\n        return name -> \"Good evening, \" + name;\n    }\n\n    private String shout(String s) {            // helper shared by default methods\n        return s.toUpperCase() + \"!\";\n    }\n}","filename":"Java"},"revision":1},{"id":"b1a09cd1-2029-76f6-a8ae-9926ce2f2507","type":"code","position":"a9","content":{"language":"text","code":"Hello, Asha\nHELLO, RAVI!\nGood evening, Meera","filename":"Output"},"revision":1},{"id":"5c3ad8f7-fa31-717e-a5f7-398a8e5589e6","type":"callout","position":"aA","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Default methods exist so interfaces can "},{"type":"text","text":"evolve","marks":[{"type":"bold"}]},{"type":"text","text":": Java 8 added "},{"type":"text","text":"forEach","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"stream()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"removeIf","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"Collection","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"Iterable","marks":[{"type":"code"}]},{"type":"text","text":" without breaking millions of existing implementations."}]}]}},"revision":1},{"id":"3bca6b76-d484-7b38-8870-765b1131906e","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"The diamond problem with default methods"}]},"revision":1},{"id":"a52d4cd6-2a90-7e7c-ac85-67f218838547","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If a class inherits the same default method from two interfaces, it must override it and may pick one with "},{"type":"text","text":"Interface.super.method()","marks":[{"type":"code"}]},{"type":"text","text":". Rules: (1) a class method always wins over an interface default; (2) a more specific sub-interface wins; (3) otherwise you must resolve it yourself."}]}]}},"revision":1},{"id":"a4f1682e-71f8-751a-9cd6-1fd9bd2dac5a","type":"code","position":"aD","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(new Phone().start());\n    }\n}\n\ninterface Camera { default String start() { return \"camera on\"; } }\ninterface Radio  { default String start() { return \"radio on\"; } }\n\nclass Phone implements Camera, Radio {\n    @Override public String start() {           // required: otherwise compile error\n        return Camera.super.start() + \" + \" + Radio.super.start();\n    }\n}","filename":"Java"},"revision":1},{"id":"a2614b87-49f5-7f89-b6da-5642e10189a2","type":"code","position":"aE","content":{"language":"text","code"