SELECT '0954dfe8-b412-7329-b1a6-a5c048f3ef41', '18c359f2-4028-7d26-8777-00c05cf00b2a', 1, 'PUBLISHED', 'Java Interview Q&A', '[{"id":"42f03abb-276f-7565-ae9d-ab12975d5d5a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The most frequently asked Java interview questions with crisp answers — a final revision sheet."}]}]}},"revision":1},{"id":"10b17c62-e333-7e3f-9131-d6d58a32aae1","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Platform and basics"}]},"revision":1},{"id":"0ef689d7-1972-7097-aae8-6c623f44dda7","type":"question","position":"a2","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the JDK, JRE and JVM?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"JVM","marks":[{"type":"bold"}]},{"type":"text","text":" executes bytecode (interpreter + JIT + GC). The "},{"type":"text","text":"JRE","marks":[{"type":"bold"}]},{"type":"text","text":" is the JVM plus the standard class libraries — enough to "},{"type":"text","text":"run","marks":[{"type":"italic"}]},{"type":"text","text":" programs. The "},{"type":"text","text":"JDK","marks":[{"type":"bold"}]},{"type":"text","text":" is the JRE plus development tools ("},{"type":"text","text":"javac","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"jar","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"jshell","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"jcmd","marks":[{"type":"code"}]},{"type":"text","text":"…) — needed to "},{"type":"text","text":"build","marks":[{"type":"italic"}]},{"type":"text","text":" them. Since Java 11 there''s no separate JRE download; "},{"type":"text","text":"jlink","marks":[{"type":"code"}]},{"type":"text","text":" builds custom runtimes."}]}]}},"revision":1},{"id":"a9ae6b6b-f858-76b9-b2de-8202ac4fcba4","type":"question","position":"a3","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is Java platform independent?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"javac","marks":[{"type":"code"}]},{"type":"text","text":" compiles source to platform-neutral "},{"type":"text","text":"bytecode","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":".class","marks":[{"type":"code"}]},{"type":"text","text":" files). Each OS has its own JVM that runs that same bytecode. “Write once, run anywhere” — the JVM is platform-specific, the bytecode isn''t."}]}]}},"revision":1},{"id":"a398d059-d2b1-7882-8fbf-43a957b7089e","type":"question","position":"a4","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is Java pass-by-value or pass-by-reference?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Always pass-by-value. For objects, the value copied is the "},{"type":"text","text":"reference","marks":[{"type":"italic"}]},{"type":"text","text":": the method can mutate the object it points to, but reassigning the parameter never affects the caller''s variable."}]}]}},"revision":1},{"id":"0cbcf4af-d37b-740a-8d42-ee58fcb0323e","type":"code","position":"a5","content":{"language":"java","code":"public class Main {\n    static void reassign(StringBuilder sb) { sb = new StringBuilder(\"new\"); }\n    static void mutate(StringBuilder sb) { sb.append(\"!\"); }\n\n    public static void main(String[] args) {\n        StringBuilder s = new StringBuilder(\"old\");\n        reassign(s);\n        mutate(s);\n        System.out.println(s);\n    }\n}","filename":"Java"},"revision":1},{"id":"2a84ac58-4da3-75dc-9811-c47f8fbbd0c1","type":"code","position":"a6","content":{"language":"text","code":"old!","filename":"Output"},"revision":1},{"id":"a84f8a75-187c-748c-9d1b-8d2f5be8a2e7","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between == and equals()?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" compares primitive values, or for references whether both point to the "},{"type":"text","text":"same object","marks":[{"type":"italic"}]},{"type":"text","text":". "},{"type":"text","text":"equals()","marks":[{"type":"code"}]},{"type":"text","text":" compares logical equality as defined by the class ("},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":", records…); the default "},{"type":"text","text":"Object.equals","marks":[{"type":"code"}]},{"type":"text","text":" is identity."}]}]}},"revision":1},{"id":"b0593de4-e6c8-7755-afee-e8dfe8799c23","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the contract between equals() and hashCode()?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Equal objects must have equal hash codes. Unequal objects may collide. If you override "},{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":" without "},{"type":"text","text":"hashCode","marks":[{"type":"code"}]},{"type":"text","text":", equal objects land in different buckets and "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"HashSet","marks":[{"type":"code"}]},{"type":"text","text":" lookups fail."}]}]}},"revision":1},{"id":"c28c4dad-86b8-73df-bbcd-5687f1d1ca9b","type":"question","position":"a9","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is String immutable? StringBuilder vs StringBuffer?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Immutability makes the string pool safe, allows caching the hash code, gives thread safety and security (values can''t change after validation). "},{"type":"text","text":"StringBuilder","marks":[{"type":"code"}]},{"type":"text","text":" is a mutable, unsynchronized buffer — use it in single-threaded code; "},{"type":"text","text":"StringBuffer","marks":[{"type":"code"}]},{"type":"text","text":" is the older synchronized version, rarely needed."}]}]}},"revision":1},{"id":"0a562dc1-0d24-7079-83ac-552afc58a3f0","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"final vs finally vs finalize?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":": a variable can''t be reassigned, a method can''t be overridden, a class can''t be extended. "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":": a block that always runs after "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"finalize()","marks":[{"type":"code"}]},{"type":"text","text":": a deprecated "},{"type":"text","text":"Object","marks":[{"type":"code"}]},{"type":"text","text":" method the GC might call before reclaiming an object — don''t use it; use "},{"type":"text","text":"try-with-resources","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Cleaner","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"2c93ceb9-dbc1-7a18-b38d-7cd93b5b3879","type":"code","position":"aB","content":{"language":"java","code":"public class Main {\n    @SuppressWarnings(\"finally\")\n    static int tricky() {\n        try {\n            return 1;\n        } finally {\n            return 2;          // overrides the try''s return (and would swallow exceptions)\n        }\n    }\n\n    static int counter() {\n        int x = 10;\n        try {\n            return x;          // value 10 is saved now\n        } finally {\n            x = 20;            // changing x does not change the saved return value\n        }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(tricky() + \" \" + counter());\n    }\n}","filename":"Java"},"revision":1},{"id":"422dc696-e868-79c0-8be6-8e863b22e332","type":"code","position":"aC","content":{"language":"text","code":"2 10","filename":"Output"},"revision":1},{"id":"a53aeddd-a4f9-7e2b-972b-be58aa565116","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"OOP"}]},"revision":1},{"id":"ab42668f-8495-7160-a7ea-d8d04f87ad00","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Overloading vs overriding?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Overloading","marks":[{"type":"bold"}]},{"type":"text","text":": same name, different parameter lists, in the same class — resolved at "},{"type":"text","text":"compile time","marks":[{"type":"italic"}]},{"type":"text","text":" by the static types of the arguments. "},{"type":"text","text":"Overriding","marks":[{"type":"bold"}]},{"type":"text","text":": a subclass redefines an inherited instance method with the same signature — resolved at "},{"type":"text","text":"run time","marks":[{"type":"italic"}]},{"type":"text","text":" by the object''s actual class (dynamic dispatch). Static methods can''t be overridden, only "},{"type":"text","text":"hidden","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"fe608257-95f9-7507-a1fb-002c8e0917b2","type":"code","position":"aF","content":{"language":"java","code":"public class Main {\n    static class Animal {\n        static String kind() { return \"animal\"; }\n        String sound() { return \"...\"; }\n    }\n    static class Dog extends Animal {\n        static String kind() { return \"dog\"; }          // hides, doesn''t override\n        @Override String sound() { return \"woof\"; }\n    }\n\n    static void print(Object o) { System.out.println(\"object\"); }\n    static void print(String s) { System.out.println(\"string\"); }\n\n    public static void main(String[] args) {\n        Animal a = new Dog();\n        System.out.println(a.sound());     // runtime type decides\n        System.out.println(Animal.kind() + \" \" + Dog.kind());\n        Object o = \"text\";\n        print(o);                          // compile-time type decides\n        print(\"text\");\n    }\n}","filename":"Java"},"revision":1},{"id":"545863ad-c1d6-779f-95b9-94ced12337df","type":"code","position":"aG","content":{"language":"text","code":"woof\nanimal dog\nobject\nstring","filename":"Output"},"revision":1},{"id":"63b1d13b-14bd-7f6b-af81-cb4f36158616","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Abstract class vs interface?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An abstract class can have state (instance fields), constructors and any access level; a class can extend only one. An interface has no instance state, only constants, abstract, "},{"type":"text","text":"default","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" methods; a class can implement many. Use an interface for a capability/contract (“can be compared”), an abstract class for sharing code and state among closely related classes."}]}]}},"revision":1},{"id":"080140e0-45f0-72e5-84b3-aa762647c68a","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the four pillars of OOP in Java?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Encapsulation","marks":[{"type":"bold"}]},{"type":"text","text":" (private state behind methods), "},{"type":"text","text":"Inheritance","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"extends","marks":[{"type":"code"}]},{"type":"text","text":", code reuse and is-a), "},{"type":"text","text":"Polymorphism","marks":[{"type":"bold"}]},{"type":"text","text":" (one interface, many implementations — overriding and dynamic dispatch), "},{"type":"text","text":"Abstraction","marks":[{"type":"bold"}]},{"type":"text","text":" (expose what, hide how — interfaces and abstract classes)."}]}]}},"revision":1},{"id":"b84a8ab4-4336-7709-9474-0d1043d11b38","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Static vs instance members?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Static members belong to the class — one copy, accessed via the class name, loaded when the class initialises. Instance members belong to each object. Static methods have no "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":", so they can''t access instance members directly."}]}]}},"revision":1},{"id":"ca4ce115-0fc6-7744-a168-cadf60c3ece4","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Records vs regular classes?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A record is a transparent, shallowly immutable data carrier: the compiler generates the canonical constructor, accessors, "},{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"hashCode","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"toString","marks":[{"type":"code"}]},{"type":"text","text":". Records are implicitly "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":", can''t extend another class and can''t declare instance fields beyond their components — but can implement interfaces and add methods and validation."}]}]}},"revision":1},{"id":"64b33fb0-04fd-7ac8-84ed-d41b395b432a","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are sealed classes for?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"sealed ... permits A, B","marks":[{"type":"code"}]},{"type":"text","text":" restricts which classes may extend or implement a type. The hierarchy becomes closed and known to the compiler, so a pattern-matching "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" over it can be checked for exhaustiveness without a "},{"type":"text","text":"default","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"7b110e8f-86d7-7497-a6f9-75b81a28237f","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Exceptions"}]},"revision":1},{"id":"5189a472-e6ad-736c-8169-11704878c04a","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Checked vs unchecked exceptions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Checked exceptions (subclasses of "},{"type":"text","text":"Exception","marks":[{"type":"code"}]},{"type":"text","text":" but not "},{"type":"text","text":"RuntimeException","marks":[{"type":"code"}]},{"type":"text","text":", e.g. "},{"type":"text","text":"IOException","marks":[{"type":"code"}]},{"type":"text","text":") must be caught or declared with "},{"type":"text","text":"throws","marks":[{"type":"code"}]},{"type":"text","text":" — for recoverable conditions outside the program''s control. Unchecked exceptions ("},{"type":"text","text":"RuntimeException","marks":[{"type":"code"}]},{"type":"text","text":" and subclasses, e.g. "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IllegalArgumentException","marks":[{"type":"code"}]},{"type":"text","text":") signal programming errors and need not be declared. "},{"type":"text","text":"Error","marks":[{"type":"code"}]},{"type":"text","text":"s ("},{"type":"text","text":"OutOfMemoryError","marks":[{"type":"code"}]},{"type":"text","text":") are serious JVM problems you normally don''t catch."}]}]}},"revision":1},{"id":"0f466441-d6c3-7224-9b2a-e57f9799f440","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does try-with-resources do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It closes every resource declared in the header (anything "},{"type":"text","text":"AutoCloseable","marks":[{"type":"code"}]},{"type":"text","text":") automatically, in reverse order, even when an exception occurs. If both the body and "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" throw, the close exception is attached to the primary one as a "},{"type":"text","text":"suppressed","marks":[{"type":"italic"}]},{"type":"text","text":" exception instead of replacing it."}]}]}},"revision":1},{"id":"22344e43-65a3-77a2-92be-030b1ca4903e","type":"heading","position":"aP","content":{"level":1,"content":[{"type":"text","text":"Collections"}]},"revision":1},{"id":"15c67441-20f1-7c14-b858-80f89b3abc0b","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does HashMap work internally?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An array of buckets. "},{"type":"text","text":"put","marks":[{"type":"code"}]},{"type":"text","text":" computes "},{"type":"text","text":"hashCode()","marks":[{"type":"code"}]},{"type":"text","text":", spreads it ("},{"type":"text","text":"h ^ (h >>> 16)","marks":[{"type":"code"}]},{"type":"text","text":"), and picks bucket "},{"type":"text","text":"hash & (n - 1)","marks":[{"type":"code"}]},{"type":"text","text":". Collisions are chained in a linked list; a bucket with more than 8 entries (when the table has at least 64 buckets) becomes a red-black tree, so worst-case lookup is O(log n). When size exceeds capacity × load factor (0.75), the table doubles and entries are redistributed. "},{"type":"text","text":"get","marks":[{"type":"code"}]},{"type":"text","text":" finds the bucket, then compares with "},{"type":"text","text":"hashCode","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"9c35991d-476c-7ff4-93a0-4ead04753211","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"HashMap vs Hashtable vs ConcurrentHashMap?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":": not thread-safe, allows one "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" key and "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" values. "},{"type":"text","text":"Hashtable","marks":[{"type":"code"}]},{"type":"text","text":": legacy, every method synchronized on one lock, no nulls. "},{"type":"text","text":"ConcurrentHashMap","marks":[{"type":"code"}]},{"type":"text","text":": thread-safe with fine-grained locking (CAS + per-bin locks), lock-free reads, atomic "},{"type":"text","text":"compute","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"merge","marks":[{"type":"code"}]},{"type":"text","text":", no nulls, weakly consistent iterators — the one to use for concurrency."}]}]}},"revision":1},{"id":"a110bf81-0e20-77d9-8162-211e29ab6315","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fail-fast vs fail-safe iterators?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fail-fast iterators ("},{"type":"text","text":"ArrayList","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":") track a "},{"type":"text","text":"modCount","marks":[{"type":"code"}]},{"type":"text","text":" and throw "},{"type":"text","text":"ConcurrentModificationException","marks":[{"type":"code"}]},{"type":"text","text":" if the collection is structurally modified during iteration other than through the iterator. Fail-safe / weakly consistent iterators ("},{"type":"text","text":"CopyOnWriteArrayList","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ConcurrentHashMap","marks":[{"type":"code"}]},{"type":"text","text":") iterate over a snapshot or tolerate concurrent changes and never throw it."}]}]}},"revision":1},{"id":"a9c4fcdc-e13b-74a8-8abc-3472040cae2e","type":"code","position":"aT","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> nums = new ArrayList<>(List.of(1, 2, 3, 4));\n        try {\n            for (Integer n : nums) {\n                if (n % 2 == 0) nums.remove(n);      // structural change during for-each\n            }\n        } catch (ConcurrentModificationException e) {\n            System.out.println(\"ConcurrentModificationException\");\n        }\n        nums = new ArrayList<>(List.of(1, 2, 3, 4));\n        nums.removeIf(n -> n % 2 == 0);              // the safe way\n        System.out.println(nums);\n    }\n}","filename":"Java"},"revision":1},{"id":"3995088c-f64d-7740-90dd-87e5cda8eacc","type":"code","position":"aU","content":{"language":"text","code":"ConcurrentModificationException\n[1, 3]","filename":"Output"},"revision":1},{"id":"947b0c31-64a5-7a4d-9279-3b6e93db4286","type":"question","position":"aV","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Comparable vs Comparator?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Comparable<T>","marks":[{"type":"code"}]},{"type":"text","text":" is implemented by the class itself ("},{"type":"text","text":"compareTo","marks":[{"type":"code"}]},{"type":"text","text":") and defines its single "},{"type":"text","text":"natural ordering","marks":[{"type":"italic"}]},{"type":"text","text":" ("},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":"). "},{"type":"text","text":"Comparator<T>","marks":[{"type":"code"}]},{"type":"text","text":" is a separate object ("},{"type":"text","text":"compare","marks":[{"type":"code"}]},{"type":"text","text":") defining any number of "},{"type":"text","text":"external","marks":[{"type":"italic"}]},{"type":"text","text":" orderings, and composes: "},{"type":"text","text":"Comparator.comparing(Person::age).thenComparing(Person::name).reversed()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"cf197ea0-cdbf-71a4-82e3-3aa4b79cd22e","type":"question","position":"aW","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ArrayList vs LinkedList?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ArrayList","marks":[{"type":"code"}]},{"type":"text","text":" is a resizable array: O(1) random access, amortised O(1) append, O(n) insert/remove in the middle, cache-friendly. "},{"type":"text","text":"LinkedList","marks":[{"type":"code"}]},{"type":"text","text":" is a doubly linked list: O(1) at the ends (or at an iterator position), O(n) access by index, high memory overhead per node. In practice "},{"type":"text","text":"ArrayList","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":" for queues) wins almost always."}]}]}},"revision":1},{"id":"aa30c19b-e4b6-70ea-9385-f35fa6b8b272","type":"heading","position":"aX","content":{"level":1,"content":[{"type":"text","text":"Concurrency"}]},"revision":1},{"id":"debe75a6-04ea-7979-b100-998d636191a2","type":"question","position":"aY","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"volatile vs synchronized vs atomic classes?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" guarantees "},{"type":"text","text":"visibility","marks":[{"type":"italic"}]},{"type":"text","text":" and ordering of a single variable''s reads/writes, but not atomicity of compound actions like "},{"type":"text","text":"count++","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":" gives mutual exclusion "},{"type":"text","text":"and","marks":[{"type":"italic"}]},{"type":"text","text":" visibility for a whole block. "},{"type":"text","text":"AtomicInteger","marks":[{"type":"code"}]},{"type":"text","text":" & co. make single-variable read-modify-write operations atomic with lock-free CAS — ideal for counters."}]}]}},"revision":1},{"id":"16cff7a8-f770-7ce4-bead-a3d7be1bbe7d","type":"question","position":"aZ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"wait() vs sleep()?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"wait()","marks":[{"type":"code"}]},{"type":"text","text":" is an "},{"type":"text","text":"Object","marks":[{"type":"code"}]},{"type":"text","text":" method, must be called while holding that object''s monitor, "},{"type":"text","text":"releases","marks":[{"type":"italic"}]},{"type":"text","text":" the lock and waits for "},{"type":"text","text":"notify","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"notifyAll","marks":[{"type":"code"}]},{"type":"text","text":" (or a timeout). "},{"type":"text","text":"Thread.sleep()","marks":[{"type":"code"}]},{"type":"text","text":" is static, needs no lock and "},{"type":"text","text":"keeps","marks":[{"type":"italic"}]},{"type":"text","text":" any locks it holds while pausing for a fixed time."}]}]}},"revision":1},{"id":"9537d804-bc73-703f-8bf2-42354155d917","type":"question","position":"aa","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runnable vs Callable?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runnable.run()","marks":[{"type":"code"}]},{"type":"text","text":" returns nothing and can''t throw checked exceptions. "},{"type":"text","text":"Callable<V>.call()","marks":[{"type":"code"}]},{"type":"text","text":" returns a value and may throw "},{"type":"text","text":"Exception","marks":[{"type":"code"}]},{"type":"text","text":"; submitting it to an "},{"type":"text","text":"ExecutorService","marks":[{"type":"code"}]},{"type":"text","text":" gives a "},{"type":"text","text":"Future<V>","marks":[{"type":"code"}]},{"type":"text","text":" to fetch the result."}]}]}},"revision":1},{"id":"34c92500-e9bf-7437-a7c2-a956b4bdba5e","type":"question","position":"ab","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are virtual threads?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lightweight threads (Java 21) scheduled by the JVM onto a few platform (OS) threads. When a virtual thread blocks on I/O it unmounts, freeing the carrier thread, so you can run millions of blocking tasks with simple thread-per-request code. Great for I/O-bound work; no gain for CPU-bound work. Don''t pool them."}]}]}},"revision":1},{"id":"b4303bc6-f32e-77ea-8b35-5050014a8a1c","type":"question","position":"ac","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a deadlock and how do you prevent it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two or more threads each hold a lock the other needs, so all wait forever. Prevent it by acquiring locks in a single global order, holding locks briefly, using "},{"type":"text","text":"tryLock","marks":[{"type":"code"}]},{"type":"text","text":" with timeouts, or avoiding shared mutable state (immutable objects, concurrent collections)."}]}]}},"revision":1},{"id":"7cf39308-fbd0-7ea3-ae5c-e52cd77f4d27","type":"heading","position":"ad","content":{"level":1,"content":[{"type":"text","text":"JVM and memory"}]},"revision":1},{"id":"f0f79528-b28c-7112-841e-cd3863fcfa64","type":"question","position":"ae","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the JVM memory areas?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Heap (objects; young + old generations), per-thread stacks (frames with locals), metaspace (class metadata, native memory), PC registers, native method stacks and the code cache (JIT output)."}]}]}},"revision":1},{"id":"7c807a0c-135d-7a70-80a0-ceeaa3a766d8","type":"question","position":"af","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does garbage collection decide what to free?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It traces from GC roots (thread stacks, static fields, JNI refs) and marks every reachable object; everything else is garbage, cycles included. Collection is generational: frequent cheap minor GCs for the young generation, rarer old-generation collections. G1 is the default collector; ZGC offers sub-millisecond pauses."}]}]}},"revision":1},{"id":"bd6f7213-12f3-759f-b901-cd5352b686e7","type":"question","position":"ag","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a ClassNotFoundException and a NoClassDefFoundError?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ClassNotFoundException","marks":[{"type":"code"}]},{"type":"text","text":" is a checked exception when code loads a class "},{"type":"text","text":"by name","marks":[{"type":"italic"}]},{"type":"text","text":" at run time ("},{"type":"text","text":"Class.forName","marks":[{"type":"code"}]},{"type":"text","text":") and it isn''t on the classpath. "},{"type":"text","text":"NoClassDefFoundError","marks":[{"type":"code"}]},{"type":"text","text":" is an "},{"type":"text","text":"Error","marks":[{"type":"code"}]},{"type":"text","text":" when a class that was present at "},{"type":"text","text":"compile time","marks":[{"type":"italic"}]},{"type":"text","text":" can''t be found or failed to initialise when the JVM links it at run time."}]}]}},"revision":1},{"id":"29a0797c-b2a8-7e26-8f94-335c350ccc36","type":"heading","position":"ah","content":{"level":1,"content":[{"type":"text","text":"Functional Java"}]},"revision":1},{"id":"1c4c19f9-0ded-7ce8-97e0-8c59e948339a","type":"question","position":"ai","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a functional interface?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An interface with exactly one abstract method (it may have default/static methods), e.g. "},{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Comparator","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Function<T,R>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Predicate<T>","marks":[{"type":"code"}]},{"type":"text","text":". Lambdas and method references are instances of functional interfaces; "},{"type":"text","text":"@FunctionalInterface","marks":[{"type":"code"}]},{"type":"text","text":" makes the compiler enforce the rule."}]}]}},"revision":1},{"id":"294b95e0-12a8-7477-95cf-b138733106fc","type":"question","position":"aj","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why are streams called lazy?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Intermediate operations ("},{"type":"text","text":"filter","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"sorted","marks":[{"type":"code"}]},{"type":"text","text":") only build a pipeline; nothing runs until a terminal operation ("},{"type":"text","text":"collect","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"forEach","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":"). Elements then flow one at a time through the whole pipeline, and short-circuiting operations ("},{"type":"text","text":"findFirst","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"limit","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"anyMatch","marks":[{"type":"code"}]},{"type":"text","text":") stop early."}]}]}},"revision":1},{"id":"3097056e-040f-78e5-98cf-6e8a5f073f46","type":"code","position":"ak","content":{"language":"java","code":"import java.util.stream.Stream;\n\npublic class Main {\n    public static void main(String[] args) {\n        Stream<Integer> pipeline = Stream.of(1, 2, 3, 4, 5)\n                .filter(n -> { System.out.println(\"filter \" + n); return n % 2 == 0; })\n                .map(n -> { System.out.println(\"map \" + n); return n * 10; });\n        System.out.println(\"nothing has run yet\");\n        System.out.println(\"first = \" + pipeline.findFirst().get());\n    }\n}","filename":"Java"},"revision":1},{"id":"b278a68b-d7ec-77d5-95db-631211bd7ce1","type":"code","position":"al","content":{"language":"text","code":"nothing has run yet\nfilter 1\nfilter 2\nmap 2\nfirst = 20","filename":"Output"},"revision":1},{"id":"c23bbc52-384f-725f-ad1b-a64efe797280","type":"question","position":"am","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How should Optional be used?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"As a "},{"type":"text","text":"return type","marks":[{"type":"italic"}]},{"type":"text","text":" for methods that may have no result, forcing callers to handle absence: "},{"type":"text","text":"findUser(id).map(User::name).orElse(\"guest\")","marks":[{"type":"code"}]},{"type":"text","text":". Don''t use it for fields, parameters or collections, and avoid bare "},{"type":"text","text":"get()","marks":[{"type":"code"}]},{"type":"text","text":" — prefer "},{"type":"text","text":"orElse","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"orElseGet","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"orElseThrow","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ifPresent","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d2e2cd73-75ab-712c-b4a3-0b9e88c885ae","type":"question","position":"an","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"map() vs flatMap() in streams?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":" transforms each element into exactly one element. "},{"type":"text","text":"flatMap","marks":[{"type":"code"}]},{"type":"text","text":" transforms each element into a "},{"type":"text","text":"stream","marks":[{"type":"italic"}]},{"type":"text","text":" and flattens those streams into one — e.g. a list of sentences into a stream of words."}]}]}},"revision":1},{"id":"161a4d46-ba1e-7b58-b4ea-95ed1cf92210","type":"heading","position":"ao","content":{"level":1,"content":[{"type":"text","text":"Rapid-fire tricks"}]},"revision":1},{"id":"de9b2c31-d7c1-7f43-876a-746b4207b29a","type":"code","position":"ap","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(10 / 3 + \" \" + 10 % 3 + \" \" + 10 / 3.0);\n        System.out.println((byte) 200);                 // narrowing wraps\n        char c = ''A'';\n        c += 1;                                         // compound assignment casts implicitly\n        System.out.println(c);\n        int i = 5;\n        i = i++ + ++i;                                  // 5 + 7\n        System.out.println(i);\n        System.out.println(Integer.MAX_VALUE + 1);\n        System.out.println(1.0 / 0 + \" \" + (0.0 / 0 == 0.0 / 0));\n        String s = null;\n        System.out.println(s + \"x\");                    // concatenation turns null into \"null\"\n    }\n}","filename":"Java"},"revision":1},{"id":"ee521204-f6d3-7425-b4c0-ec3a3fe21b78","type":"code","position":"aq","content":{"language":"text","code":"3 1 3.3333333333333335\n-56\nB\n12\n-2147483648\nInfinity false\nnullx","filename":"Output"},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
