WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '18c359f2-4028-7d26-8777-00c05cf00b2a' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
