SELECT '006ac02c-c3f4-7d0e-ac69-ee44e0c79d7e', '6746f79e-e9c0-7afe-8a7f-537db9e5c37f', 1, 'PUBLISHED', 'Iterators & ConcurrentModificationException', '[{"id":"15c8b37c-0345-7ab5-9252-9f7b486e7b99","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Removing from a collection while a for-each loop walks it throws "},{"type":"text","text":"ConcurrentModificationException","marks":[{"type":"code"}]},{"type":"text","text":". Use "},{"type":"text","text":"removeIf","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Iterator.remove","marks":[{"type":"code"}]},{"type":"text","text":", or a concurrent collection."}]}]}},"revision":1},{"id":"e3182b9c-b934-7c98-8a0d-b2131ac72d06","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterator","marks":[{"type":"bold"}]},{"type":"text","text":" — an object with "},{"type":"text","text":"hasNext()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" and optional "},{"type":"text","text":"remove()","marks":[{"type":"code"}]},{"type":"text","text":" that walks a collection. The for-each loop over any "},{"type":"text","text":"Iterable","marks":[{"type":"code"}]},{"type":"text","text":" is compiled into exactly these calls."}]}]}},"revision":1},{"id":"909d9748-a0ca-72be-87d2-1e1f807f3ddd","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Fail-fast iterators"}]},"revision":1},{"id":"efde07d3-91de-7705-998d-988934cf2144","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ArrayList","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":" and friends keep a counter "},{"type":"text","text":"modCount","marks":[{"type":"code"}]},{"type":"text","text":", bumped on every "},{"type":"text","text":"structural","marks":[{"type":"italic"}]},{"type":"text","text":" change (add/remove, not "},{"type":"text","text":"set","marks":[{"type":"code"}]},{"type":"text","text":"). The iterator remembers the value when it was created and checks it on each "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":"; a mismatch throws."}]}]}},"revision":1},{"id":"13cc8b62-faaa-733f-b8a0-197b0ce00684","type":"code","position":"a4","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> nums = new ArrayList<>(List.of(1, 2, 3, 4));\n        try {\n            for (Integer n : nums) {\n                if (n % 2 == 0) nums.remove(n);   // structural change behind the iterator''s back\n            }\n        } catch (ConcurrentModificationException e) {\n            System.out.println(\"ConcurrentModificationException\");\n        }\n        System.out.println(nums);\n    }\n}","filename":"Java"},"revision":1},{"id":"4a3e1782-a7aa-74cc-a3bb-0d651e70ab49","type":"code","position":"a5","content":{"language":"text","code":"ConcurrentModificationException\n[1, 3, 4]","filename":"Output"},"revision":1},{"id":"cd0e1877-7dd3-76c0-8fec-f5d5e7352629","type":"callout","position":"a6","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Despite the name, this has nothing to do with threads — one thread modifying a collection it is iterating is enough. It is also "},{"type":"text","text":"best-effort","marks":[{"type":"italic"}]},{"type":"text","text":": removing the second-to-last element skips the final "},{"type":"text","text":"hasNext()","marks":[{"type":"code"}]},{"type":"text","text":" check and silently exits without an exception, so never rely on it to catch bugs."}]}]}},"revision":1},{"id":"adad40d5-42b4-772b-ae1a-47b10e999a1e","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Three correct ways to remove"}]},"revision":1},{"id":"8b692ff8-caa8-7c1f-b048-1e9d372a1233","type":"code","position":"a8","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> a = new ArrayList<>(List.of(1, 2, 3, 4, 5, 6));\n        a.removeIf(n -> n % 2 == 0);                  // 1. simplest (Java 8+)\n        System.out.println(a);\n\n        List<Integer> b = new ArrayList<>(List.of(1, 2, 3, 4, 5, 6));\n        for (Iterator<Integer> it = b.iterator(); it.hasNext(); ) {\n            if (it.next() % 2 == 0) it.remove();      // 2. the iterator''s own remove\n        }\n        System.out.println(b);\n\n        List<Integer> c = new ArrayList<>(List.of(1, 2, 3, 4, 5, 6));\n        for (int i = c.size() - 1; i >= 0; i--) {     // 3. index loop, backwards\n            if (c.get(i) % 2 == 0) c.remove(i);\n        }\n        System.out.println(c);\n\n        Map<String, Integer> m = new HashMap<>(Map.of(\"a\", 1, \"b\", 2));\n        m.entrySet().removeIf(e -> e.getValue() > 1); // maps: remove through a view\n        System.out.println(m);\n    }\n}","filename":"Java"},"revision":1},{"id":"50287606-449c-7d9b-9bf9-f118cc88d07e","type":"code","position":"a9","content":{"language":"text","code":"[1, 3, 5]\n[1, 3, 5]\n[1, 3, 5]\n{a=1}","filename":"Output"},"revision":1},{"id":"a9fd42c7-446a-7915-a0dc-0b5843e9dcbf","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"ListIterator","marks":[{"type":"code"}]},{"type":"text","text":" — both directions, edit in place"}]},"revision":1},{"id":"36d2aee1-ba94-7f13-950d-0af0ac60dd8d","type":"code","position":"aB","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> words = new ArrayList<>(List.of(\"a\", \"b\", \"c\"));\n        ListIterator<String> it = words.listIterator();\n        while (it.hasNext()) {\n            int i = it.nextIndex();\n            String w = it.next();\n            if (w.equals(\"b\")) {\n                it.set(\"B\");          // replace the element just returned\n                it.add(\"b2\");         // insert after it\n            }\n            System.out.print(i + \":\" + w + \" \");   // \"c\" is now at index 3\n        }\n        System.out.println();\n        while (it.hasPrevious()) System.out.print(it.previous() + \" \");\n        System.out.println();\n    }\n}","filename":"Java"},"revision":1},{"id":"1fd3aab9-4bfc-7103-8f91-fe801a208eba","type":"code","position":"aC","content":{"language":"text","code":"0:a 1:b 3:c\nc b2 B a","filename":"Output"},"revision":1},{"id":"1cf71db6-ae39-76a7-9ee4-b5df2f972a45","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Fail-safe (snapshot / weakly consistent) iterators"}]},"revision":1},{"id":"75e5b9a4-b86d-7805-8b4d-650c75c0c283","type":"code","position":"aE","content":{"language":"java","code":"import java.util.*;\nimport java.util.concurrent.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> cow = new CopyOnWriteArrayList<>(List.of(1, 2, 3));\n        for (Integer n : cow) {\n            if (n == 1) cow.add(99);      // iterator walks a snapshot — no exception\n            System.out.print(n + \" \");\n        }\n        System.out.println(\"-> \" + cow);\n\n        Map<Integer, String> chm = new ConcurrentHashMap<>(Map.of(1, \"a\", 2, \"b\"));\n        for (Integer k : chm.keySet()) chm.remove(k);   // allowed\n        System.out.println(chm);\n    }\n}","filename":"Java"},"revision":1},{"id":"4259d057-2e0a-7dca-a031-8f9d13595acf","type":"code","position":"aF","content":{"language":"text","code":"1 2 3 -> [1, 2, 3, 99]\n{}","filename":"Output"},"revision":1},{"id":"