e":"text","text":" queue"}]],[[{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"HashSet","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(1) avg"}],[{"type":"text","text":"O(1) avg"}],[{"type":"text","text":"O(1) avg"}],[{"type":"text","text":"Worst case O(log n) with treeified bins"}]],[[{"type":"text","text":"TreeMap","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"TreeSet","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"Sorted; floor/ceiling queries"}]],[[{"type":"text","text":"PriorityQueue","marks":[{"type":"code"}]}],[{"type":"text","text":"peek O(1)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"poll O(log n)"}],[{"type":"text","text":"Binary min-heap"}]]]},"revision":1},{"id":"0e01a700-1206-70bc-bdf1-2a3d8fa786d2","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Maps: counting and grouping"}]},"revision":1},{"id":"49e42d0f-67a5-7bc0-ac44-7f96d0a7f410","type":"code","position":"a4","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Map<Character, Integer> freq = new TreeMap<>();          // sorted keys for display\n        for (char c : \"banana\".toCharArray()) {\n            freq.merge(c, 1, Integer::sum);                       // add 1 or start at 1\n        }\n        System.out.println(freq);\n\n        int[] counts = new int[26];                                // faster for lowercase letters\n        for (char c : \"banana\".toCharArray()) counts[c - ''a'']++;\n        System.out.println(counts[''a'' - ''a''] + \" \" + counts[''n'' - ''a'']);\n\n        Map<Integer, List<String>> byLength = new TreeMap<>();\n        for (String w : List.of(\"hi\", \"cat\", \"go\", \"dog\")) {\n            byLength.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);\n        }\n        System.out.println(byLength);\n        System.out.println(freq.getOrDefault(''z'', 0));\n    }\n}","filename":"Java"},"revision":1},{"id":"9e94ae79-e78b-7954-b899-62d1e7c40f15","type":"code","position":"a5","content":{"language":"text","code":"{a=3, b=1, n=2}\n3 2\n{2=[hi, go], 3=[cat, dog]}\n0","filename":"Output"},"revision":1},{"id":"8c864920-974d-713b-a9f9-1dbf7b78cd8e","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Stack, queue and heap"}]},"revision":1},{"id":"61f46d70-b054-7b09-a762-54c0663e62d4","type":"code","position":"a7","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Deque<Integer> stack = new ArrayDeque<>();\n        stack.push(1); stack.push(2); stack.push(3);\n        System.out.println(stack.pop() + \" \" + stack.peek());      // LIFO\n\n        Deque<Integer> queue = new ArrayDeque<>();\n        queue.offer(1); queue.offer(2); queue.offer(3);\n        System.out.println(queue.poll() + \" \" + queue.peek());     // FIFO\n\n        PriorityQueue<Integer> minHeap = new PriorityQueue<>(List.of(5, 1, 4));\n        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Comparator.reverseOrder());\n        maxHeap.addAll(List.of(5, 1, 4));\n        System.out.println(minHeap.poll() + \" \" + maxHeap.poll());\n\n        // heap of int[] pairs ordered by the second value\n        PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> Integer.compare(x[1], y[1]));\n        pq.add(new int[]{7, 30}); pq.add(new int[]{8, 10}); pq.add(new int[]{9, 20});\n        System.out.println(pq.poll()[0]);\n    }\n}","filename":"Java"},"revision":1},{"id":"e252d1a3-62ae-7eb0-a685-5f6614b3607c","type":"code","position":"a8","content":{"language":"text","code":"3 2\n1 2\n1 5\n8","filename":"Output"},"revision":1},{"id":"f5b3e7a7-2c80-7739-a04a-aeb116a65c70","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"TreeMap: ordered queries"}]},"revision":1},{"id":"78c3dc3b-a1a8-7a44-8c3d-a463ee1d2e50","type":"code","position":"aA","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        TreeMap<Integer, String> tm = new TreeMap<>(Map.of(10, \"a\", 20, \"b\", 30, \"c\"));\n        System.out.println(tm.floorKey(25) + \" \" + tm.ceilingKey(25));    // ≤ 25, ≥ 25\n        System.out.println(tm.lowerKey(10) + \" \" + tm.higherKey(30));     // strict: none → null\n        System.out.println(tm.firstKey() + \" \" + tm.lastEntry());\n        System.out.println(tm.headMap(20) + \" \" + tm.tailMap(20, true));\n    }\n}","filename":"Java"},"revision":1},{"id":"52548833-ca96-78e4-b260-ff1a1c9a4d4d","type":"code","position":"aB","content":{"language":"text","code":"20 30\nnull null\n10 30=c\n{10=a} {20=b, 30=c}","filename":"Output"},"revision":1},{"id":"265d6d92-3ca9-7caf-9a72-74ca1bd2db74","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Templates"}]},"revision":1},{"id":"8aa4e56d-a727-7e92-a161-86bc3bc13a94","type":"code","position":"aD","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static int lowerBound(int[] a, int target) {        // first index with a[i] >= target\n        int lo = 0, hi = a.length;\n        while (lo < hi) {\n            int mid = lo + (hi - lo) / 2;                // not (lo + hi) / 2 — may overflow\n            if (a[mid] < target) lo = mid + 1; else hi = mid;\n        }\n        return lo;\n    }\n\n    static int shortestPath(char[][] grid) {            // BFS on a grid, ''#'' = wall\n        int rows = grid.length, cols = grid[0].length;\n        int[][] dist = new int[rows][cols];\n        for (int[] row : dist) Arrays.fill(row, -1);\n        Deque<int[]> q = new ArrayDeque<>();\n        q.offer(new int[]{0, 0});\n        dist[0][0] = 0;\n        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};\n        while (!q.isEmpty()) {\n            int[] cur = q.poll();\n            for (int[] d : dirs) {\n                int r = cur[0] + d[0], c = cur[1] + d[1];\n                if (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != ''#'' && dist[r][c] == -1) {\n                    dist[r][c] = dist[cur[0]][cur[1]] + 1;\n                    q.offer(new int[]{r, c});\n                }\n            }\n        }\n        return dist[rows - 1][cols - 1];\n    }\n\n    public static void main(String[] args) {\n        int[] a = {1, 3, 5, 7};\n        System.out.println(lowerBound(a, 5) + \" \" + lowerBound(a, 9));\n        System.out.println(Arrays.binarySearch(a, 7) + \" \" + Arrays.binarySearch(a, 4));  // -(insertion)-1\n\n        char[][] grid = {\n            \"..#\".toCharArray(),\n            \".##\".toCharArray(),\n            \"...\".toCharArray(),\n        };\n        System.out.println(shortestPath(grid));\n    }\n}","filename":"Java"},"revision":1},{"id":"e044ac3c-5a98-7e94-bd6d-8a6eed322d47","type":"code","position":"aE","content":{"language":"text","code":"2 4\n3 -3\n4","filename":"Output"},"revision":1},{"id":"6101b1ce-936f-7361-ba1a-311650c2a7ec","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Sorting idioms and the subtraction trap"}]},"revision":1},{"id":"59d0c67f-c915-70c5-8935-2fd15a2656f2","type":"code","position":"aG","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[][] intervals = {{5, 6}, {1, 3}, {2, 4}};\n        Arrays.sort(intervals, (x, y) -> Integer.compare(x[0], y[0]));\n        System.out.println(Arrays.deepToString(intervals));\n\n        List<String> words = new ArrayList<>(List.of(\"pear\", \"fig\", \"apple\", \"kiwi\"));\n        words.sort(Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder()));\n        System.out.println(words);\n\n        List<Integer> nums = new ArrayList<>(List.of(1, Integer.MIN_VALUE, 5));\n        nums.sort((x, y) -> x - y);                  // BROKEN: x - y overflows\n        System.out.println(nums);\n        nums.sort(Integer::compare);                 // correct\n        System.out.println(nums);\n    }\n}","filename":"Java"},"revision":1},{"id":"61323c6f-063d-7c55-a304-bba45f763bf9","type":"code","position":"aH","content":{"language":"text","code":"[[1, 3], [2, 4], [5, 6]]\n[fig, kiwi, pear, apple]\n[1, 5, -2147483648]\n[-2147483648, 1, 5]","filename":"Output"},"revision":1},{"id":"b240a327-c9f0-7c18-b657-ea2487dca9a3","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Handy one-liners"}]},"revision":1},{"id":"9e7b4380-c04e-758c-b5de-c21952718126","type":"table","position":"aJ","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Task"}],[{"type":"text","text":"Java"}]],[[{"type":"text","text":"Char ↔ index"}],[{"type":"text","text":"c - ''a''","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"(char) (''a'' + i)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Digit char → int"}],[{"type":"text","text":"c - ''0''","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Character.getNumericValue(c)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Fill / copy arrays"}],[{"type":"text","text":"Arrays.fill(a, -1)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Arrays.copyOfRange(a, l, r)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Sum / max of "},{"type":"text","text":"int[]","marks":[{"type":"code"}]}],[{"type":"text","text":"Arrays.stream(a).sum()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":".max().getAsInt()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"List<Integer>","marks