  ('d9b904c6-01a2-7fb2-a765-9b448f3a5405', 'a2', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Structure"}],[{"type":"text","text":"Access"}],[{"type":"text","text":"Search"}],[{"type":"text","text":"Insert"}],[{"type":"text","text":"Delete"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"int[]","marks":[{"type":"code"}]},{"type":"text","text":" / array"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"—"}],[{"type":"text","text":"—"}],[{"type":"text","text":"Fixed size"}]],[[{"type":"text","text":"ArrayList","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1) amortised at end"}],[{"type":"text","text":"O(n) (shift)"}],[{"type":"text","text":"Default list"}]],[[{"type":"text","text":"LinkedList","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1) at ends"}],[{"type":"text","text":"O(1) at ends"}],[{"type":"text","text":"Rarely the best choice"}]],[[{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1) both ends"}],[{"type":"text","text":"O(1) both ends"}],[{"type":"text","text":"Stack "},{"type":"text","text":"and","marks":[{"type":"bold"}]},{"type":"text","text":" queue"}]],[[{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"HashSet","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(1) avg"}],[{"type":"text","text":"O(1) avg"}],[{"type":"text","text":"O(1) avg"}],[{"type":"text","text":"Worst case O(log n) with treeified bins"}]],[[{"type":"text","text":"TreeMap","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"TreeSet","marks":[{"type":"code"}]}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"Sorted; floor/ceiling queries"}]],[[{"type":"text","text":"PriorityQueue","marks":[{"type":"code"}]}],[{"type":"text","text":"peek O(1)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"poll O(log n)"}],[{"type":"text","text":"Binary min-heap"}]]]}'),
