ard library ("},{"type":"text","text":"rt.jar","marks":[{"type":"code"}]},{"type":"text","text":" before Java 9, modules since). Enough to "},{"type":"text","text":"run","marks":[{"type":"italic"}]},{"type":"text","text":" programs, not compile them."}]}]}},"revision":1},{"id":"2d8316af-c038-78ac-908f-4d5a803d87b2","type":"callout","position":"a4","content":{"variant":"note","title":"JDK — Java Development Kit","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The JRE plus developer tools: "},{"type":"text","text":"javac","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"java","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"jar","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"javadoc","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"jdb","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"jshell","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"jcmd","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"jlink","marks":[{"type":"code"}]},{"type":"text","text":"… What developers install."}]}]}},"revision":1},{"id":"09ba8b19-5f47-76cf-be38-2742dea80caa","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"JDK"}],[{"type":"text","text":"JRE"}],[{"type":"text","text":"JVM"}]],[[{"type":"text","text":"Purpose"}],[{"type":"text","text":"Develop + run"}],[{"type":"text","text":"Run"}],[{"type":"text","text":"Execute bytecode"}]],[[{"type":"text","text":"Contains "},{"type":"text","text":"javac","marks":[{"type":"code"}]},{"type":"text","text":"?"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Contains class library?"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}]],[[{"type":"text","text