SELECT '21c48a87-cd81-7556-af35-780906e010c6', '6dc3ce61-cea0-7024-80e1-96990ca88730', 1, 'PUBLISHED', 'JVM Memory: Heap, Stack & Metaspace', '[{"id":"21340ff0-ef0f-756d-acac-1f2fce9f7778","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The JVM splits memory into areas with different lifetimes: "},{"type":"text","text":"objects on the heap","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"method calls on per-thread stacks","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"class metadata in metaspace","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"facca489-ce84-7530-b76f-93aea2a72ec4","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runtime data areas","marks":[{"type":"bold"}]},{"type":"text","text":" — the regions of memory the JVM specification defines. Some are shared by all threads (heap, metaspace), others are private to each thread (stack, PC register)."}]}]}},"revision":1},{"id":"19b25f2f-daae-7347-b08a-e242f5e5ec5f","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The runtime data areas"}]},"revision":1},{"id":"ac6106c1-e7cd-7467-b640-2e3e8ebebcc1","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Area"}],[{"type":"text","text":"Shared?"}],[{"type":"text","text":"Holds"}],[{"type":"text","text":"Error when full"}]],[[{"type":"text","text":"Heap","marks":[{"type":"bold"}]},{"type":"text","text":" — young gen (Eden + 2 Survivor spaces)"}],[{"type":"text","text":"All threads"}],[{"type":"text","text":"Newly created objects and arrays"}],[{"type":"text","text":"OutOfMemoryError: Java heap space","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Heap","marks":[{"type":"bold"}]},{"type":"text","text":" — old (tenured) gen"}],[{"type":"text","text":"All threads"}],[{"type":"text","text":"Objects that survived several young GCs"}],[{"type":"text","text":"OutOfMemoryError: Java heap space","marks":[{"type":"code"}]}]],[[{"type":"text","text":"JVM stack","marks":[{"type":"bold"}]},{"type":"text","text":" (one per thread)"}],[{"type":"text","text":"Per thread"}],[{"type":"text","text":"One "},{"type":"text","text":"frame","marks":[{"type":"italic"}]},{"type":"text","text":" per method call: local variables, operand stack, return address"}],[{"type":"text","text":"StackOverflowError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Metaspace","marks":[{"type":"bold"}]},{"type":"text","text":" (native memory, Java 8+)"}],[{"type":"text","text":"All threads"}],[{"type":"text","text":"Class metadata: method bytecode, field layout, runtime constant pool"}],[{"type":"text","text":"OutOfMemoryError: Metaspace","marks":[{"type":"code"}]}]],[[{"type":"text","text":"PC register","marks":[{"type":"bold"}]}],[{"type":"text","text":"Per thread"}],[{"type":"text","text":"Address of the bytecode instruction being executed"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"Native method stack","marks":[{"type":"bold"}]}],[{"type":"text","text":"Per thread"}],[{"type":"text","text":"Frames of native (C/C++) methods called through JNI"}],[{"type":"text","text":"StackOverflowError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Code cache","marks":[{"type":"bold"}]}],[{"type":"text","text":"All threads"}],[{"type":"text","text":"Machine code produced by the JIT compiler"}],[{"type":"text","text":"JIT stops compiling (warning)"}]]]},"revision":1},{"id":"bff553e1-9eed-79ed-9ae7-1d398a6522fb","type":"callout","position":"a4","content":{"variant":"note","title":"History","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"string pool","marks":[{"type":"bold"}]},{"type":"text","text":" lives on the heap (moved out of PermGen in Java 7). "},{"type":"text","text":"PermGen","marks":[{"type":"bold"}]},{"type":"text","text":" itself was removed in Java 8 and replaced by "},{"type":"text","text":"metaspace","marks":[{"type":"bold"}]},{"type":"text","text":", which grows in native memory instead of having a fixed size."}]}]}},"revision":1},{"id":"48bd4737-dea0-705b-8749-8b35e260f61a","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"What lives where"}]},"revision":1},{"id":"80c3c94f-fcbd-7577-a517-a7e9f45cc68d","type":"callout","position":"a6","content":{"variant":"note","title":"Primitive locals","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"int x = 5;","marks":[{"type":"code"}]},{"type":"text","text":" inside a method — the value sits directly in the stack frame. Gone when the method returns."}]}]}},"revision":1},{"id":"96673b6a-e1dd-722f-a257-4941d3d8e061","type":"callout","position":"a7","content":{"variant":"note","title":"References","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Box b","marks":[{"type":"code"}]},{"type":"text","text":" is a local of reference type — the "},{"type":"text","text":"reference","marks":[{"type":"italic"}]},{"type":"text","text":" (a pointer-sized value) is on the stack…"}]}]}},"revision":1},{"id":"cc032aa2-fd2d-7c2c-a858-de08e934566d","type":"callout","position":"a8","content":{"variant":"note","title":"Objects","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"…and the "},{"type":"text","text":"new Box()","marks":[{"type":"code"}]},{"type":"text","text":" it points to is on the heap, shared by every reference to it. Instance fields (primitive or not) live inside the object."}]}]}},"revision":1},{"id":"58f9bb52-c80a-7e49-a35c-c3eb5019b49c","type":"callout","position":"a9","content":{"variant":"note","title":"Static fields","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Belong to the class. Since Java 8 they are stored with the "},{"type":"text","text":"Class","marks":[{"type":"code"}]},{"type":"text","text":" object on the heap; the class metadata is in metaspace."}]}]}},"revision":1},{"id":"42b85fbb-0094-7d5e-9ee5-33d36a9e1479","type":"code","position":"aA","content":{"language":"java","code":"public class Main {\n    static class Box { int value; }\n\n    public static void main(String[] args) {\n        int a = 10;           // primitive local → in main''s stack frame\n        int b = a;            // copies the value\n        b++;\n\n        Box x = new Box();    // reference x on the stack, Box object on the heap\n        Box y = x;            // copies the reference, not the object\n        y.value = 42;\n\n        System.out.println(a + \" \" + b);\n        System.out.println(x.value + \" \" + (x == y));\n    }\n}","filename":"Java"},"revision":1},{"id":"faed1352-5916-7a78-a62a-f7415851d91f","type":"code","position":"aB","content":{"language":"text","code":"10 11\n42 true","filename":"Output"},"revision":1},{"id":"dbf93a99-0004-76a8-a444-68db8a40a76a","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Stack frames and StackOverflowError"}]},"revision":1},{"id":"893c3340-e989-7ed7-8cd6-b7fa7327e855","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Call","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Calling a method pushes a new frame onto the current thread''s stack."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Execute","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The frame holds the method''s parameters and locals, plus an operand stack the bytecode works on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The frame is popped — its locals disappear instantly. No GC is needed for stack memory."}]}]}]}]}},"revision":1},{"id":"83e80d36-07f0-7302-afc9-0e66e9ab4d51","type":"code","position":"aE","content":{"language":"java","code":"public class Main {\n    static int depth = 0;\n\n    static void recurse() {\n        depth++;\n        recurse();              // no base case → a new frame on every call\n    }\n\n    public static void main(String[] args) {\n        try {\n            recurse();\n        } catch (StackOverflowError e) {\n            System.out.println(\"StackOverflowError after more than 1000 frames: \" + (depth > 1000));\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"ad0dac9c-00f0-7eed-bb90-56086d0f5c27","type":"code","position":"aF","content":{"language":"text","code":"StackOverflowError after more than 1000 frames: true","filename":"Output"},"revision":1},{"id":"7e50c058-c8ad-7cf3-930d-7b1d609a9724","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"OutOfMemoryError"}]},"revision":1},{"id":"1ab68b93-3593-7fcd-897f-9adbe7c65cdb","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Run with a deliberately tiny heap ("},{"type":"text","text":"-Xmx64m","marks":[{"type":"code"}]},{"type":"text","text":") and ask for a 400 MB array:"}]}]}},"revision":1},{"id":"086f6e70-9c7f-7b3b-beb5-1dd960975041","type":"code","position":"aI","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        try {\n            int[] huge = new int[100_000_000];      // ~400 MB\n            System.out.println(huge.length);\n        } catch (OutOfMemoryError e) {\n            System.out.println(\"OutOfMemoryError: \" + e.getMessage());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"5f6d0b81-97b9-7060-a0a4-911582d9e28e","type":"code","position":"aJ","content":{"language":"text","code":"OutOfMemoryError: Java heap space","filename":"Output"},"revision":1},{"id":"441e8e05-a50d-7a76-b812-94d024bc0f5f","type":"table","position":"aK","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"StackOverflowError","marks":[{"type":"code"}]}],[{"type":"text","text":"OutOfMemoryError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Area"}],[{"type":"text","text":"A thread''s stack"}],[{"type":"text","text":"Heap, metaspace, direct buffers, native threads…"}]],[[{"type":"text","text":"Typical cause"}],[{"type":"text","text":"Unbounded / too deep recursion"}],[{"type":"text","text":"Leak (objects stay reachable), or heap simply too small"}]],[[{"type":"text","text":"Fix"}],[{"type":"text","text":"Base case, iteration, or bigger "},{"type":"text","text":"-Xss","marks":[{"type":"code"}]}],[{"type":"text","text":"Fix the leak (heap dump), then size "},{"type":"text","text":"-Xmx","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Type"}],[{"type":"text","text":"Both extend "},{"type":"text","text":"Error","marks":[{"type":"code"}]},{"type":"text","text":" (via "},{"type":"text","text":"VirtualMachineError","marks":[{"type":"code"}]},{"type":"text","text":") — not meant to be caught in normal code"}],[]]]},"revision":1},{"id":"2b5f68dd-d86c-73f1-9ac6-1ca67e0b620d","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"Sizing flags"}]},"revision":1},{"id":"0e1e97bd-8b21-7726-8eb2-5584b4b6c712","type":"table","position":"aM","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Flag"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"-Xms","marks":[{"type":"code"}]}],[{"type":"text","text":"Initial heap size"}],[{"type":"text","text":"-Xms512m","marks":[{"type":"code"}]}]],[[{"type":"text","text":"-Xmx","marks":[{"type":"code"}]}],[{"type":"text","text":"Maximum heap size (default: 1/4 of physical RAM)"}],[{"type":"text","text":"-Xmx2g","marks":[{"type":"code"}]}]],[[{"type":"text","text":"-Xss","marks":[{"type":"code"}]}],[{"type":"text","text":"Stack size per thread"}],[{"type":"text","text":"-Xss1m","marks":[{"type":"code"}]}]],[[{"type":"text","text":"-XX:MaxMetaspaceSize","marks":[{"type":"code"}]}],[{"type":"text","text":"Cap metaspace (unbounded by default)"}],[{"type":"text","text":"-XX:MaxMetaspaceSize=256m","marks":[{"type":"code"}]}]],[[{"type":"text","text":"-XX:+HeapDumpOnOutOfMemoryError","marks":[{"type":"code"}]}],[{"type":"text","text":"Write a "},{"type":"text","text":".hprof","marks":[{"type":"code"}]},{"type":"text","text":" heap dump when OOM happens"}],[{"type":"text","text":"with "},{"type":"text","text":"-XX:HeapDumpPath=/tmp","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"6e6e1bd3-242b-7e27-9c20-38308e28f1be","type":"code","position":"aN","content":{"language":"","code":"$ java -Xms256m -Xmx1g -Xss512k -XX:+HeapDumpOnOutOfMemoryError App.java\n$ java -XX:+PrintFlagsFinal -version | grep -E \"MaxHeapSize|ThreadStackSize\"","filename":"Terminal"},"revision":1},{"id":"4169f9d0-1e82-7e6e-9228-f81db8b07876","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Escape analysis"}]},"revision":1},{"id":"0c1ecbd5-f2a3-7fd2-a28d-bcbe63314d04","type":"text","position":"aP","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The JIT checks whether an object "},{"type":"text","text":"escapes","marks":[{"type":"italic"}]},{"type":"text","text":" the method that creates it (returned, stored in a field, passed to another thread). If it doesn''t, the JIT may "},{"type":"text","text":"scalar-replace","marks":[{"type":"bold"}]},{"type":"text","text":" it — keep its fields in registers/stack slots and never allocate it on the heap at all."}]}]}},"revision":1},{"id":"13e97a2e-ebfd-7383-abf2-1e96a06b9aa1","type":"code","position":"aQ","content":{"language":"java","code":"public class Main {\n    record Point(int x, int y) {}\n\n    static int distanceSquared(int x, int y) {\n        Point p = new Point(x, y);      // never escapes → candidate for scalar replacement\n        return p.x() * p.x() + p.y() * p.y();\n    }\n\n    public static void main(String[] args) {\n        long sum = 0;\n        for (int i = 0; i < 1_000; i++) sum += distanceSquared(i, i);\n        System.out.println(sum);\n    }\n}","filename":"Java"},"revision":1},{"id":"d87ced21-112c-7f47-ae9c-e80f487f0c70","type":"code","position":"aR","content":{"language":"text","code":"665667000","filename":"Output"},"revision":1},{"id":"a3a67b5e-d521-79c8-9a59-35a9b409fb35","type":"callout","position":"aS","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"All objects live on the heap\" is the "},{"type":"text","text":"language model","marks":[{"type":"italic"}]},{"type":"text","text":". Escape analysis is an invisible optimisation — your program behaves exactly the same either way."}]}]}},"revision":1},{"id":"bc6a3c6b-83b0-7c56-846e-61aa5fee6d16","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Where are local variables, objects and static variables stored?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Local primitives and local references are in the thread''s stack frame. Objects (including their instance fields) are on the heap. Static fields are stored with the class''s "},{"type":"text","text":"Class","marks":[{"type":"code"}]},{"type":"text","text":" object on the heap (Java 8+); the class metadata itself is in metaspace."}]}]}},"revision":1},{"id":"5e7804fc-96b7-724f-a399-1ed221b504aa","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What replaced PermGen and why?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Metaspace (Java 8). PermGen had a fixed maximum size and caused "},{"type":"text","text":"OutOfMemoryError: PermGen space","marks":[{"type":"code"}]},{"type":"text","text":" in apps that load many classes (app servers, dynamic proxies). Metaspace lives in native memory and grows on demand; cap it with "},{"type":"text","text":"-XX:MaxMetaspaceSize","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"e933baa4-f214-7858-b2a4-40c8c9776f50","type":"question","position":"aV","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is the stack or the heap thread-safe?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each thread has its own stack, so locals are never shared — they are inherently thread-confined. The heap is shared by all threads, so objects reachable from more than one thread need synchronization."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
