  ('21340ff0-ef0f-756d-acac-1f2fce9f7778', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The JVM splits memory into areas with different lifetimes: "},{"type":"text","text":"objects on the heap","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"method calls on per-thread stacks","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"class metadata in metaspace","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('facca489-ce84-7530-b76f-93aea2a72ec4', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runtime data areas","marks":[{"type":"bold"}]},{"type":"text","text":" — the regions of memory the JVM specification defines. Some are shared by all threads (heap, metaspace), others are private to each thread (stack, PC register)."}]}]}}'),
  ('19b25f2f-daae-7347-b08a-e242f5e5ec5f', 'a2', 'heading', '{"level":1,"content":[{"type":"text","text":"The runtime data areas"}]}'),
  ('ac6106c1-e7cd-7467-b640-2e3e8ebebcc1', 'a3', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Area"}],[{"type":"text","text":"Shared?"}],[{"type":"text","text":"Holds"}],[{"type":"text","text":"Error when full"}]],[[{"type":"text","text":"Heap","marks":[{"type":"bold"}]},{"type":"text","text":" — young gen (Eden + 2 Survivor spaces)"}],[{"type":"text","text":"All threads"}],[{"type":"text","text":"Newly created objects and arrays"}],[{"type":"text","text":"OutOfMemoryError: Java heap space","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Heap","marks":[{"type":"bold"}]},{"type":"text","text":" — old (tenured) gen"}],[{"type":"text","text":"All threads"}],[{"type":"text","text":"Objects that survived several young GCs"}],[{"type":"text","text":"OutOfMemoryError: Java heap space","marks":[{"type":"code"}]}]],[[{"type":"text","text":"JVM stack","marks":[{"type":"bold"}]},{"type":"text","text":" (one per thread)"}],[{"type":"text","text":"Per thread"}],[{"type":"text","text":"One "},{"type":"text","text":"frame","marks":[{"type":"italic"}]},{"type":"text","text":" per method call: local variables, operand stack, return address"}],[{"type":"text","text":"StackOverflowError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Metaspace","marks":[{"type":"bold"}]},{"type":"text","text":" (native memory, Java 8+)"}],[{"type":"text","text":"All threads"}],[{"type":"text","text":"Class metadata: method bytecode, field layout, runtime constant pool"}],[{"type":"text","text":"OutOfMemoryError: Metaspace","marks":[{"type":"code"}]}]],[[{"type":"text","text":"PC register","marks":[{"type":"bold"}]}],[{"type":"text","text":"Per thread"}],[{"type":"text","text":"Address of the bytecode instruction being executed"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"Native method stack","marks":[{"type":"bold"}]}],[{"type":"text","text":"Per thread"}],[{"type":"text","text":"Frames of native (C/C++) methods called through JNI"}],[{"type":"text","text":"StackOverflowError","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Code cache","marks":[{"type":"bold"}]}],[{"type":"text","text":"All threads"}],[{"type":"text","text":"Machine code produced by the JIT compiler"}],[{"type":"text","text":"JIT stops compiling (warning)"}]]]}'),
  ('bff553e1-9eed-79ed-9ae7-1d398a6522fb', 'a4', 'callout', '{"variant":"note","title":"History","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"string pool","marks":[{"type":"bold"}]},{"type":"text","text":" lives on the heap (moved out of PermGen in Java 7). "},{"type":"text","text":"PermGen","marks":[{"type":"bold"}]},{"type":"text","text":" itself was removed in Java 8 and replaced by "},{"type":"text","text":"metaspace","marks":[{"type":"bold"}]},{"type":"text","text":", which grows in native memory instead of having a fixed size."}]}]}}'),
  ('48bd4737-dea0-705b-8749-8b35e260f61a', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"What lives where"}]}'),
  ('80c3c94f-fcbd-7577-a517-a7e9f45cc68d', 'a6', 'callout', '{"variant":"note","title":"Primitive locals","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"int x = 5;","marks":[{"type":"code"}]},{"type":"text","text":" inside a method — the value sits directly in the stack frame. Gone when the method returns."}]}]}}'),
  ('96673b6a-e1dd-722f-a257-4941d3d8e061', 'a7', 'callout', '{"variant":"note","title":"References","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Box b","marks":[{"type":"code"}]},{"type":"text","text":" is a local of reference type — the "},{"type":"text","text":"reference","marks":[{"type":"italic"}]},{"type":"text","text":" (a pointer-sized value) is on the stack…"}]}]}}'),
  ('cc032aa2-fd2d-7c2c-a858-de08e934566d', 'a8', 'callout', '{"variant":"note","title":"Objects","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"…and the "},{"type":"text","text":"new Box()","marks":[{"type":"code"}]},{"type":"text","text":" it points to is on the heap, shared by every reference to it. Instance fields (primitive or not) live inside the object."}]}]}}'),
  ('58f9bb52-c80a-7e49-a35c-c3eb5019b49c', 'a9', 'callout', '{"variant":"note","title":"Static fields","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Belong to the class. Since Java 8 they are stored with the "},{"type":"text","text":"Class","marks":[{"type":"code"}]},{"type":"text","text":" object on the heap; the class metadata is in metaspace."}]}]}}'),
  ('42b85fbb-0094-7d5e-9ee5-33d36a9e1479', 'aA', 'code', '{"language":"java","code":"public class Main {\n    static class Box { int value; }\n\n    public static void main(String[] args) {\n        int a = 10;           // primitive local → in main''s stack frame\n        int b = a;            // copies the value\n        b++;\n\n        Box x = new Box();    // reference x on the stack, Box object on the heap\n        Box y = x;            // copies the reference, not the object\n        y.value = 42;\n\n        System.out.println(a + \" \" + b);\n        System.out.println(x.value + \" \" + (x == y));\n    }\n}","filename":"Java"}'),
  ('faed1352-5916-7a78-a62a-f7415851d91f', 'aB', 'code', '{"language":"text","code":"10 11\n42 true","filename":"Output"}'),
  ('dbf93a99-0004-76a8-a444-68db8a40a76a', 'aC', 'heading', '{"level":1,"content":[{"type":"text","text":"Stack frames and StackOverflowError"}]}'),
  ('893c3340-e989-7ed7-8cd6-b7fa7327e855', 'aD', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Call","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Calling a method pushes a new frame onto the current thread''s stack."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Execute","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The frame holds the method''s parameters and locals, plus an operand stack the bytecode works on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Return","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The frame is popped — its locals disappear instantly. No GC is needed for stack memory."}]}]}]}]}}'),
