SELECT '61930609-70f0-7e49-8c79-788fc3dd0f9f', 'e99509ed-429e-737c-b88d-c0536bf2334f', 1, 'PUBLISHED', 'Lambdas & Method References', '[{"id":"9460ab25-d639-7c51-9e47-92fa0c4a3bec","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A lambda is an anonymous function you can pass around as a value; a method reference is a lambda that just calls an existing method."}]}]}},"revision":1},{"id":"2524c0f6-e148-7b8c-9e7a-d93ca86787fe","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lambda expression","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"(parameters) -> body","marks":[{"type":"code"}]},{"type":"text","text":" — an instance of a functional interface, written inline. Introduced in Java 8, it replaced most anonymous inner classes."}]}]}},"revision":1},{"id":"c8525329-b37f-75a0-b0b2-788120667d9c","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Syntax forms"}]},"revision":1},{"id":"6704ba83-f66b-7ff2-98a6-adf48959ef6b","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Form"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"No parameters"}],[{"type":"text","text":"() -> 42","marks":[{"type":"code"}]}]],[[{"type":"text","text":"One parameter (parentheses optional)"}],[{"type":"text","text":"s -> s.length()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Several parameters"}],[{"type":"text","text":"(a, b) -> a + b","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Explicit types"}],[{"type":"text","text":"(String a, String b) -> a.compareTo(b)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"var","marks":[{"type":"code"}]},{"type":"text","text":" parameters (11+, allows annotations)"}],[{"type":"text","text":"(var a, var b) -> a + b","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Block body (needs "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"x -> { int y = x * 2; return y + 1; }","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"91907cf7-9b83-7109-8d73-c66aa4057f85","type":"code","position":"a4","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<String> names = new ArrayList<>(List.of(\"Ravi\", \"Asha\", \"Zoe\", \"Mohan\"));\n\n        // Before Java 8: an anonymous class\n        names.sort(new Comparator<String>() {\n            @Override\n            public int compare(String a, String b) {\n                return a.compareTo(b);\n            }\n        });\n        System.out.println(names);\n\n        // Java 8+: a lambda\n        names.sort((a, b) -> b.length() - a.length());\n        System.out.println(names);\n\n        names.removeIf(s -> s.length() < 4);\n        names.forEach(s -> System.out.print(s + \" \"));\n        System.out.println();\n    }\n}","filename":"Java"},"revision":1},{"id":"303cadd7-f1ac-7f66-b75d-11f31e58a76c","type":"code","position":"a5","content":{"language":"text","code":"[Asha, Mohan, Ravi, Zoe]\n[Mohan, Asha, Ravi, Zoe]\nMohan Asha Ravi","filename":"Output"},"revision":1},{"id":"61f99800-8bd4-7edb-8b60-6bcb9c38345c","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Capturing variables: effectively final"}]},"revision":1},{"id":"55d421be-7d3a-7493-b695-e0545584f6c4","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A lambda can read local variables from the enclosing method only if they are "},{"type":"text","text":"effectively final","marks":[{"type":"bold"}]},{"type":"text","text":" — never reassigned after initialisation. The lambda captures the "},{"type":"text","text":"value","marks":[{"type":"italic"}]},{"type":"text","text":", and Java forbids the variable changing underneath it."}]}]}},"revision":1},{"id":"9bd5d803-f61c-7ae7-b163-b7f4f0b3995e","type":"code","position":"a8","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        int count = 0;\n        Runnable r = () -> count++;     // error: must be final or effectively final\n        r.run();\n    }\n}","filename":"Java"},"revision":1},{"id":"230b122e-c1b3-79bb-a233-59d6261d4bef","type":"code","position":"a9","content":{"language":"java","code":"import java.util.*;\nimport java.util.concurrent.atomic.AtomicInteger;\n\npublic class Main {\n    public static void main(String[] args) {\n        String prefix = \"item-\";                  // effectively final: OK to capture\n        AtomicInteger counter = new AtomicInteger();  // the reference is final; its state can change\n        List.of(\"a\", \"b\", \"c\").forEach(s -> {\n            counter.incrementAndGet();\n            System.out.println(prefix + s);\n        });\n        System.out.println(\"count = \" + counter.get());\n    }\n}","filename":"Java"},"revision":1},{"id":"6fa2aafd-6bef-7e1c-bae8-9cd7bf12739a","type":"code","position":"aA","content":{"language":"text","code":"item-a\nitem-b\nitem-c\ncount = 3","filename":"Output"},"revision":1},{"id":"d186dbde-35e4-7bf8-b1b5-104924e0fce7","type":"callout","position":"aB","content":{"variant":"note","title":"Fields are different","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fields (instance or "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":") are "},{"type":"text","text":"not","marks":[{"type":"italic"}]},{"type":"text","text":" restricted — a lambda reads them through "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" or the class. Only captured "},{"type":"text","text":"local","marks":[{"type":"bold"}]},{"type":"text","text":" variables must be effectively final."}]}]}},"revision":1},{"id":"c1c9575c-2ae7-70ba-8f88-2a62346755a2","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" in a lambda vs an anonymous class"}]},"revision":1},{"id":"a9aaf23e-21be-79c8-84f0-7c7f790b0a6c","type":"code","position":"aD","content":{"language":"java","code":"public class Main {\n    String name = \"outer\";\n\n    void demo() {\n        Runnable lambda = () -> System.out.println(\"lambda this: \" + this.name);\n        Runnable anon = new Runnable() {\n            String name = \"anonymous\";\n            @Override\n            public void run() {\n                System.out.println(\"anon this:   \" + this.name);\n            }\n        };\n        lambda.run();\n        anon.run();\n    }\n\n    public static void main(String[] args) {\n        new Main().demo();\n    }\n}","filename":"Java"},"revision":1},{"id":"dcd79c34-d952-7ab7-908d-3940dead505a","type":"code","position":"aE","content":{"language":"text","code":"lambda this: outer\nanon this:   anonymous","filename":"Output"},"revision":1},{"id":"3d847d6e-3ac5-70ee-acf0-a1b476099f58","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Lambda"}],[{"type":"text","text":"Anonymous class"}]],[[{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" refers to"}],[{"type":"text","text":"the "},{"type":"text","text":"enclosing","marks":[{"type":"bold"}]},{"type":"text","text":" instance"}],[{"type":"text","text":"the anonymous object itself"}]],[[{"type":"text","text":"New scope?"}],[{"type":"text","text":"No — can''t redeclare an enclosing local name"}],[{"type":"text","text":"Yes — can shadow names"}]],[[{"type":"text","text":"Implements"}],[{"type":"text","text":"only functional interfaces"}],[{"type":"text","text":"any interface or class, many methods, can hold state"}]],[[{"type":"text","text":"Compiled to"}],[{"type":"text","text":"invokedynamic","marks":[{"type":"code"}]},{"type":"text","text":" + a private method (no extra "},{"type":"text","text":".class","marks":[{"type":"code"}]},{"type":"text","text":" file)"}],[{"type":"text","text":"a separate "},{"type":"text","text":"Outer$1.class","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"4c0cb328-15d7-7b55-a497-3eefd18b2117","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Method references — four kinds"}]},"revision":1},{"id":"6505ed33-823f-7f7e-b613-1ae66455598d","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When a lambda only forwards its arguments to one method, write "},{"type":"text","text":"Class::method","marks":[{"type":"code"}]},{"type":"text","text":" instead."}]}]}},"revision":1},{"id":"bf7c31eb-bae7-7e6e-b16e-daa727784e9c","type":"table","position":"aI","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Kind"}],[{"type":"text","text":"Syntax"}],[{"type":"text","text":"Equivalent lambda"}]],[[{"type":"text","text":"Static method"}],[{"type":"text","text":"Integer::parseInt","marks":[{"type":"code"}]}],[{"type":"text","text":"s -> Integer.parseInt(s)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Instance method of a "},{"type":"text","text":"particular","marks":[{"type":"bold"}]},{"type":"text","text":" object"}],[{"type":"text","text":"System.out::println","marks":[{"type":"code"}]}],[{"type":"text","text":"x -> System.out.println(x)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Instance method of an "},{"type":"text","text":"arbitrary","marks":[{"type":"bold"}]},{"type":"text","text":" object of a type"}],[{"type":"text","text":"String::toUpperCase","marks":[{"type":"code"}]}],[{"type":"text","text":"s -> s.toUpperCase()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Constructor"}],[{"type":"text","text":"ArrayList::new","marks":[{"type":"code"}]}],[{"type":"text","text":"() -> new ArrayList<>()","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"dd923b95-31bc-7fb5-9900-1e5bd345a221","type":"code","position":"aJ","content":{"language":"java","code":"import java.util.*;\nimport java.util.function.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Function<String, Integer> parse = Integer::parseInt;         // static\n        String greeting = \"Hello\";\n        Predicate<String> startsWithIt = greeting::startsWith;       // particular object\n        Function<String, String> upper = String::toUpperCase;        // arbitrary object\n        BiFunction<String, String, Boolean> eq = String::equalsIgnoreCase; // first arg is the receiver\n        Supplier<List<String>> newList = ArrayList::new;             // constructor\n        Function<Integer, int[]> newArray = int[]::new;              // array constructor\n\n        System.out.println(parse.apply(\"41\") + 1);\n        System.out.println(startsWithIt.test(\"Hell\"));\n        System.out.println(upper.apply(\"java\"));\n        System.out.println(eq.apply(\"JAVA\", \"java\"));\n        List<String> list = newList.get();\n        list.add(\"x\");\n        System.out.println(list + \" \" + newArray.apply(3).length);\n    }\n}","filename":"Java"},"revision":1},{"id":"6359c73f-787e-74cc-9105-6a88895eac71","type":"code","position":"aK","content":{"language":"text","code":"42\ntrue\nJAVA\ntrue\n[x] 3","filename":"Output"},"revision":1},{"id":"f5ac5ad8-348b-75a1-a823-f5902bc7ca46","type":"callout","position":"aL","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System.out::println","marks":[{"type":"code"}]},{"type":"text","text":" evaluates "},{"type":"text","text":"System.out","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"once","marks":[{"type":"italic"}]},{"type":"text","text":", when the reference is created — the lambda "},{"type":"text","text":"x -> System.out.println(x)","marks":[{"type":"code"}]},{"type":"text","text":" looks it up on every call. Usually irrelevant, but a "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" receiver in "},{"type":"text","text":"obj::method","marks":[{"type":"code"}]},{"type":"text","text":" throws "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]},{"type":"text","text":" immediately, not when called."}]}]}},"revision":1},{"id":"3e56c130-0cf5-76b8-945e-b607ece88cdb","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Are lambdas just syntactic sugar for anonymous classes?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. They compile to an "},{"type":"text","text":"invokedynamic","marks":[{"type":"code"}]},{"type":"text","text":" call site plus a private synthetic method; the JVM creates the implementation at run time (via "},{"type":"text","text":"LambdaMetafactory","marks":[{"type":"code"}]},{"type":"text","text":"). No "},{"type":"text","text":".class","marks":[{"type":"code"}]},{"type":"text","text":" file per lambda, non-capturing lambdas are cached as singletons, and "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" means the enclosing instance rather than a new object."}]}]}},"revision":1},{"id":"68a2f739-af08-78aa-8e38-d01c5c4abca1","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why must captured local variables be effectively final?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Locals live on the stack frame of the method, which may be gone by the time the lambda runs (e.g. on another thread). Java copies the value into the lambda; allowing later reassignment would make the copy silently stale and invite data races. Use a field, an array element or an "},{"type":"text","text":"AtomicInteger","marks":[{"type":"code"}]},{"type":"text","text":" if you really need mutable state — or better, restructure with a stream reduction."}]}]}},"revision":1},{"id":"7b22c501-82c7-7d0a-a28e-1c83d5ee6a34","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does String::compareTo mean when a Comparator<String> is expected?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It''s an "},{"type":"text","text":"unbound","marks":[{"type":"italic"}]},{"type":"text","text":" instance-method reference: the first parameter becomes the receiver. "},{"type":"text","text":"(a, b) -> a.compareTo(b)","marks":[{"type":"code"}]},{"type":"text","text":". That''s why a two-argument functional interface can be satisfied by a one-argument instance method."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
