SELECT '85c9a750-7ea5-7772-a74a-3bb975dcf3f6', 'dc4376e5-374e-7cfc-ab21-65e9810ca5ad', 1, 'PUBLISHED', 'Methods & Pass-by-Value', '[{"id":"22f17ed6-ff02-7cf0-96a8-fa846a21d198","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Java is "},{"type":"text","text":"always pass-by-value","marks":[{"type":"bold"}]},{"type":"text","text":". For objects, the value passed is a copy of the "},{"type":"text","text":"reference","marks":[{"type":"italic"}]},{"type":"text","text":" — so you can mutate the object, but never reseat the caller''s variable."}]}]}},"revision":1},{"id":"f84bbb46-66f9-7aa8-8023-c10e4b070858","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Anatomy of a method"}]},"revision":1},{"id":"c7d380ef-8f63-734f-b8d5-1d04a875922a","type":"code","position":"a2","content":{"language":"java","code":"public class Main {\n    //  modifiers   return type  name   parameters        throws clause\n    public static   int          add(   int a, int b)    /* throws … */ {\n        return a + b;\n    }\n\n    static void greet(String name) {           // void: returns nothing\n        if (name == null) return;              // early return\n        System.out.println(\"Hi \" + name);\n    }\n\n    public static void main(String[] args) {\n        System.out.println(add(2, 3));\n        greet(\"Asha\");\n        greet(null);\n    }\n}","filename":"Java"},"revision":1},{"id":"737b9c34-6998-7b33-9e2d-5569588e5142","type":"code","position":"a3","content":{"language":"text","code":"5\nHi Asha","filename":"Output"},"revision":1},{"id":"84f7e27c-7709-7444-917a-80efcb99f893","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Part"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"Signature","marks":[{"type":"bold"}]}],[{"type":"text","text":"Name + parameter "},{"type":"text","text":"types","marks":[{"type":"italic"}]},{"type":"text","text":" (e.g. "},{"type":"text","text":"add(int, int)","marks":[{"type":"code"}]},{"type":"text","text":"). Return type and parameter names are "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" part of it."}]],[[{"type":"text","text":"Access modifier"}],[{"type":"text","text":"public","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"protected","marks":[{"type":"code"}]},{"type":"text","text":", package-private (none), "},{"type":"text","text":"private","marks":[{"type":"code"}]}]],[[{"type":"text","text":"static","marks":[{"type":"code"}]}],[{"type":"text","text":"Belongs to the class — call as "},{"type":"text","text":"Main.add(…)","marks":[{"type":"code"}]},{"type":"text","text":" without an object"}]],[[{"type":"text","text":"Return type"}],[{"type":"text","text":"Any type or "},{"type":"text","text":"void","marks":[{"type":"code"}]},{"type":"text","text":"; every path of a non-void method must "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":" or throw"}]],[[{"type":"text","text":"Parameters"}],[{"type":"text","text":"Local variables initialized with copies of the arguments"}]]]},"revision":1},{"id":"480041f6-d7ff-79aa-b1f3-b3f342ddd2d4","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Pass-by-value, demonstrated"}]},"revision":1},{"id":"8621f4b2-989e-7801-aa0c-f50503aae862","type":"code","position":"a6","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static void bump(int x) { x++; }                          // changes the copy only\n\n    static void mutate(List<String> list) { list.add(\"added\"); }   // same object → visible\n\n    static void reassign(List<String> list) {\n        list = new ArrayList<>();                             // local copy now points elsewhere\n        list.add(\"lost\");\n    }\n\n    static void swap(Integer a, Integer b) { Integer t = a; a = b; b = t; }\n\n    public static void main(String[] args) {\n        int n = 5;\n        bump(n);\n        System.out.println(n);\n\n        List<String> items = new ArrayList<>(List.of(\"x\"));\n        mutate(items);\n        reassign(items);\n        System.out.println(items);\n\n        Integer p = 1, q = 2;\n        swap(p, q);\n        System.out.println(p + \" \" + q);                      // swap is impossible this way\n    }\n}","filename":"Java"},"revision":1},{"id":"aaa3f577-1125-7b81-a39c-60ec31c0f1ba","type":"code","position":"a7","content":{"language":"text","code":"5\n[x, added]\n1 2","filename":"Output"},"revision":1},{"id":"9b7a1292-7b0e-77b9-af15-c19c3c3e6c3d","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"caller: "},{"type":"text","text":"items","marks":[{"type":"code"}]},{"type":"text","text":" → [list object] → call copies the reference → param "},{"type":"text","text":"list","marks":[{"type":"code"}]},{"type":"text","text":" → same [list object] → "},{"type":"text","text":"list = new …","marks":[{"type":"code"}]},{"type":"text","text":" rebinds only the param"}]}]}},"revision":1},{"id":"23351126-b822-7236-a61a-79c89fdde493","type":"callout","position":"a9","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"“Objects are passed by reference” is a common but wrong interview answer. The "},{"type":"text","text":"reference","marks":[{"type":"italic"}]},{"type":"text","text":" is passed by value: the method gets its own copy of the pointer."}]}]}},"revision":1},{"id":"e59fa475-6a43-7a2e-9dd3-16af577c19ef","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Return values & multiple results"}]},"revision":1},{"id":"f7a159bf-d53e-7dab-99c0-6f78c701fd47","type":"code","position":"aB","content":{"language":"java","code":"public class Main {\n    record MinMax(int min, int max) {}                 // return several values via a record\n\n    static MinMax range(int... xs) {\n        int lo = Integer.MAX_VALUE, hi = Integer.MIN_VALUE;\n        for (int x : xs) { lo = Math.min(lo, x); hi = Math.max(hi, x); }\n        return new MinMax(lo, hi);\n    }\n\n    public static void main(String[] args) {\n        MinMax r = range(4, -2, 9, 0);\n        System.out.println(r + \" -> \" + r.min() + \"..\" + r.max());\n    }\n}","filename":"Java"},"revision":1},{"id":"c20384a5-053e-78c0-b82a-1c0b64ab12b2","type":"code","position":"aC","content":{"language":"text","code":"MinMax[min=-2, max=9] -> -2..9","filename":"Output"},"revision":1},{"id":"1e7a2d5f-662a-746a-b411-bbe3ac72ec10","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Local variables & scope"}]},"revision":1},{"id":"f5e35042-8e97-77e6-b0c9-cbdb8ce8f557","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Local variables have "},{"type":"text","text":"no default value","marks":[{"type":"bold"}]},{"type":"text","text":" — using one before assignment is a compile error (fields do get defaults)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A variable''s scope is its enclosing block "},{"type":"text","text":"{ … }","marks":[{"type":"code"}]},{"type":"text","text":"; you can''t redeclare a name that is already in scope in the same method."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"var","marks":[{"type":"code"}]},{"type":"text","text":" (Java 10) infers a local''s type: "},{"type":"text","text":"var list = new ArrayList<String>();","marks":[{"type":"code"}]},{"type":"text","text":" — locals only, must be initialized."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parameters can be "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":" to document that they''re not reassigned."}]}]}]}]}},"revision":1},{"id":"e88e50b0-a49c-764c-b0a8-15a7b0565e6e","type":"code","position":"aF","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        int x;\n        System.out.println(x);       // error: variable x might not have been initialized\n    }\n}","filename":"Java"},"revision":1},{"id":"ab19d7fb-9611-7a5c-af29-6ddf715a8a05","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is Java pass-by-value or pass-by-reference?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Strictly pass-by-value. Primitives: the value is copied. Objects: the reference is copied — the method can mutate the shared object but reassigning the parameter never affects the caller''s variable. That''s why a "},{"type":"text","text":"swap(a, b)","marks":[{"type":"code"}]},{"type":"text","text":" method can''t work."}]}]}},"revision":1},{"id":"985499cc-2995-78fb-95e3-0d5231020fde","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can two methods differ only by return type?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. The signature is name + parameter types; "},{"type":"text","text":"int f()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"long f()","marks":[{"type":"code"}]},{"type":"text","text":" in the same class is a compile error because a call "},{"type":"text","text":"f()","marks":[{"type":"code"}]},{"type":"text","text":" would be ambiguous."}]}]}},"revision":1},{"id":"5e7f5dfc-81ac-7653-94d1-61f4c7711f5d","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does static mean for a method?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It belongs to the class, not an instance: no "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":", can''t access instance fields directly, and it is resolved at compile time (not overridden — only hidden)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
