SELECT 'dc4376e5-374e-7cfc-ab21-65e9810ca5ad', '85c9a750-7ea5-7772-a74a-3bb975dcf3f6', 'Methods & Pass-by-Value', 'Methods & Pass-by-Value', 'Java is always pass-by-value. For objects, the value passed is a copy of the reference — so you can mutate the object, but never reseat the caller''s variable.
Anatomy of a method
public class Main {
    //  modifiers   return type  name   parameters        throws clause
    public static   int          add(   int a, int b)    /* throws … */ {
        return a + b;
    }

    static void greet(String name) {           // void: returns nothing
        if (name == null) return;              // early return
        System.out.println("Hi " + name);
    }

    public static void main(String[] args) {
        System.out.println(add(2, 3));
        greet("Asha");
        greet(null);
    }
}
