SELECT 'c83db691-8502-73ca-ba48-23f517584212', '310e1397-5b6d-723f-b046-4c17ab8cba2a', 1, 'PUBLISHED', 'Inner, Nested, Local & Anonymous Classes', '[{"id":"fd92cb8a-ed49-767d-a506-aed2dd73bf84","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class can be declared "},{"type":"text","text":"inside","marks":[{"type":"italic"}]},{"type":"text","text":" another class, method or expression. The four kinds differ in one key way: whether they hold a hidden reference to an enclosing instance."}]}]}},"revision":1},{"id":"99443516-46c6-7e67-8c16-ef96e31d1375","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nested class","marks":[{"type":"bold"}]},{"type":"text","text":" — any class declared inside another class. A "},{"type":"text","text":"static nested","marks":[{"type":"bold"}]},{"type":"text","text":" class is just a namespaced top-level class; a non-static one is an "},{"type":"text","text":"inner","marks":[{"type":"bold"}]},{"type":"text","text":" class and is tied to an instance of the outer class."}]}]}},"revision":1},{"id":"561ac72e-e7f3-70a3-be57-1dd9982d7879","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The four kinds at a glance"}]},"revision":1},{"id":"56a54069-4af6-7617-b53a-b96ff2815aa1","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Kind"}],[{"type":"text","text":"Declared"}],[{"type":"text","text":"Outer instance?"}],[{"type":"text","text":"Typical use"}]],[[{"type":"text","text":"Static nested","marks":[{"type":"bold"}]}],[{"type":"text","text":"static class Node","marks":[{"type":"code"}]},{"type":"text","text":" inside a class"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Helpers that belong with the outer class: "},{"type":"text","text":"Map.Entry","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Builder","marks":[{"type":"code"}]},{"type":"text","text":", linked-list "},{"type":"text","text":"Node","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Inner (member)","marks":[{"type":"bold"}]}],[{"type":"text","text":"class Itr","marks":[{"type":"code"}]},{"type":"text","text":" inside a class"}],[{"type":"text","text":"Yes","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"Outer.this","marks":[{"type":"code"}]}],[{"type":"text","text":"Iterators and views that need the outer object''s fields"}]],[[{"type":"text","text":"Local","marks":[{"type":"bold"}]}],[{"type":"text","text":"class X","marks":[{"type":"code"}]},{"type":"text","text":" inside a method body"}],[{"type":"text","text":"Yes, if in an instance method"}],[{"type":"text","text":"A one-method helper type with a name"}]],[[{"type":"text","text":"Anonymous","marks":[{"type":"bold"}]}],[{"type":"text","text":"new Interface() { … }","marks":[{"type":"code"}]},{"type":"text","text":" expression"}],[{"type":"text","text":"Yes, if in an instance context"}],[{"type":"text","text":"One-off implementation; mostly replaced by lambdas"}]]]},"revision":1},{"id":"5eb4a7e6-6783-7f51-af03-8297174e9123","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Static nested vs inner"}]},"revision":1},{"id":"6be45775-ef8f-775c-bcf5-fdeb60e3a470","type":"code","position":"a5","content":{"language":"java","code":"public class Main {\n    private int size = 3;\n    private static String kind = \"outer\";\n\n    static class StaticNested {            // no outer instance\n        String describe() { return \"nested sees \" + kind; }   // only static members\n    }\n\n    class Inner {                          // bound to a Main instance\n        int size = 10;\n        String describe() {\n            return \"inner \" + size + \", outer \" + Main.this.size;\n        }\n    }\n\n    public static void main(String[] args) {\n        StaticNested n = new StaticNested();          // no Main needed\n        System.out.println(n.describe());\n\n        Main outer = new Main();\n        Main.Inner in = outer.new Inner();            // needs an outer instance\n        System.out.println(in.describe());\n    }\n}","filename":"Java"},"revision":1},{"id":"52265ff9-42c4-7bc4-abec-0f803fca97a1","type":"code","position":"a6","content":{"language":"text","code":"nested sees outer\ninner 10, outer 3","filename":"Output"},"revision":1},{"id":"20f74291-275b-70b6-9aa3-488994378a28","type":"callout","position":"a7","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside an inner class, "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" is the inner object and "},{"type":"text","text":"Main.this","marks":[{"type":"code"}]},{"type":"text","text":" is the enclosing one. Use the qualified form when a field name is shadowed."}]}]}},"revision":1},{"id":"365fa29e-8106-7ede-bf4b-2adf90f77c22","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Local and anonymous classes"}]},"revision":1},{"id":"ce8bcad7-a422-7997-8557-a19d531e1c4f","type":"code","position":"a9","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    interface Greeter { String greet(String name); }\n\n    public static void main(String[] args) {\n        String greeting = \"Hello\";                  // effectively final → can be captured\n\n        class Polite implements Greeter {           // local class: has a name, lives in this method\n            public String greet(String name) { return greeting + \", \" + name + \"!\"; }\n        }\n\n        Greeter shout = new Greeter() {             // anonymous class: no name, one instance\n            @Override\n            public String greet(String name) { return greeting.toUpperCase() + \" \" + name; }\n        };\n\n        Greeter lambda = name -> greeting + \" \" + name;   // same thing, as a lambda\n\n        System.out.println(new Polite().greet(\"Asha\"));\n        System.out.println(shout.greet(\"Ravi\"));\n        System.out.println(lambda.greet(\"Mei\"));\n\n        List<String> names = new ArrayList<>(List.of(\"bob\", \"Al\", \"carol\"));\n        names.sort(new Comparator<String>() {       // classic pre-Java-8 style\n            public int compare(String a, String b) { return a.length() - b.length(); }\n        });\n        System.out.println(names);\n    }\n}","filename":"Java"},"revision":1},{"id":"704ffea9-9fc2-70a0-ad1d-65dbc105170c","type":"code","position":"aA","content":{"language":"text","code":"Hello, Asha!\nHELLO Ravi\nHello Mei\n[Al, bob, carol]","filename":"Output"},"revision":1},{"id":"577324aa-f953-7d70-863e-b0da8eb712ba","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Capturing variables: effectively final"}]},"revision":1},{"id":"11a64d1f-cc64-73bd-82ac-d4eaaafb121c","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Local, anonymous classes and lambdas can read local variables of the enclosing method only if they are "},{"type":"text","text":"final or effectively final","marks":[{"type":"bold"}]},{"type":"text","text":" (never reassigned). The value is "},{"type":"text","text":"copied","marks":[{"type":"italic"}]},{"type":"text","text":" into the object, so allowing later changes would make the copy and the variable disagree."}]}]}},"revision":1},{"id":"3ae45f35-a44d-73ed-8a94-208b583b348c","type":"code","position":"aD","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        int count = 0;\n        Runnable r = () -> System.out.println(count);\n        count++;                 // makes count not effectively final\n        r.run();\n    }\n}","filename":"Java"},"revision":1},{"id":"e06f61a4-ec19-7374-bae6-0093a10afa06","type":"code","position":"aE","content":{"language":"text","code":"Main.java:4: error: local variables referenced from a lambda expression must be final or effectively final\n        Runnable r = () -> System.out.println(count);\n                                              ^","filename":"Compiler error"},"revision":1},{"id":"b1e1d7a5-c1c9-785f-8061-2cbd34519913","type":"callout","position":"aF","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Need a mutable counter inside a lambda? Use an "},{"type":"text","text":"AtomicInteger","marks":[{"type":"code"}]},{"type":"text","text":", a one-element array, or — better — restructure with a stream."}]}]}},"revision":1},{"id":"b99def44-8475-7314-979a-3cb0463b70ac","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Anonymous class vs lambda"}]},"revision":1},{"id":"7d34b144-cf08-7a03-bf71-6c4e8a60decf","type":"table","position":"aH","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Anonymous class"}],[{"type":"text","text":"Lambda"}]],[[{"type":"text","text":"Implements"}],[{"type":"text","text":"Any interface or abstract/concrete class, many methods"}],[{"type":"text","text":"Only a "},{"type":"text","text":"functional interface","marks":[{"type":"bold"}]},{"type":"text","text":" (one abstract method)"}]],[[{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" means"}],[{"type":"text","text":"The anonymous object itself"}],[{"type":"text","text":"The "},{"type":"text","text":"enclosing","marks":[{"type":"bold"}]},{"type":"text","text":" instance"}]],[[{"type":"text","text":"State"}],[{"type":"text","text":"Can have fields"}],[{"type":"text","text":"No fields of its own"}]],[[{"type":"text","text":"Compiled to"}],[{"type":"text","text":"A separate "},{"type":"text","text":"Main$1.class","marks":[{"type":"code"}]},{"type":"text","text":" file"}],[{"type":"text","text":"invokedynamic","marks":[{"type":"code"}]},{"type":"text","text":" — no extra class file"}]]]},"revision":1},{"id":"7a4bcd95-e360-7708-b0c2-fae27b7aa49f","type":"callout","position":"aI","content":{"variant":"warning","title":"Memory leak","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every inner/anonymous class created in an instance method keeps a hidden reference to "},{"type":"text","text":"Outer.this","marks":[{"type":"code"}]},{"type":"text","text":". If it outlives the outer object (a listener, a cached task, a "},{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":" handed to a thread) it keeps the whole outer object alive — a classic "},{"type":"text","text":"memory leak","marks":[{"type":"bold"}]},{"type":"text","text":" (e.g. Android Activities). Prefer "},{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" nested classes unless you really need the outer instance."}]}]}},"revision":1},{"id":"a856c71e-8898-7977-98f1-5e1572d87f18","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Static nested vs inner class — when to use which?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Default to "},{"type":"text","text":"static nested","marks":[{"type":"bold"}]},{"type":"text","text":": it''s cheaper (no hidden outer reference), can be created without an outer instance, and can''t leak the outer object. Use an "},{"type":"text","text":"inner","marks":[{"type":"bold"}]},{"type":"text","text":" class only when it must read or write the outer instance''s state, like an iterator over the outer collection."}]}]}},"revision":1},{"id":"2f313022-9e82-77e4-bd70-507d8d6ae7f2","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why must captured local variables be effectively final?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The lambda/anonymous object gets a "},{"type":"text","text":"copy","marks":[{"type":"italic"}]},{"type":"text","text":" of the value (locals live on the stack and may be gone when the object runs). If the variable could change afterwards, the copy would silently be stale, so Java forbids it at compile time."}]}]}},"revision":1},{"id":"5ea6c6a8-e8e8-70c0-aa80-5a747fa01fef","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does this refer to inside a lambda vs an anonymous class?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In an anonymous class, "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" is the anonymous object. A lambda has no identity of its own, so "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" is the enclosing class instance."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
