SELECT '9a759ed8-f997-7677-b030-7f7300052555', 'a9c828aa-dc2c-775a-b5b5-9ee2d98d8a61', 1, 'PUBLISHED', 'Optional', '[{"id":"bc17c7d4-1e1b-7418-a386-aa3855174dd2","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A container that holds either one value or nothing — a return type that forces callers to think about "},{"type":"text","text":"absence","marks":[{"type":"italic"}]},{"type":"text","text":" instead of forgetting a null check."}]}]}},"revision":1},{"id":"ed8c2ee3-c973-71a2-9449-11eb14dd84b8","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Optional<T>","marks":[{"type":"bold"}]},{"type":"text","text":" — an immutable box that is either "},{"type":"text","text":"present","marks":[{"type":"italic"}]},{"type":"text","text":" (holds a non-null value) or "},{"type":"text","text":"empty","marks":[{"type":"italic"}]},{"type":"text","text":". Introduced in Java 8, designed for "},{"type":"text","text":"method return types","marks":[{"type":"bold"}]},{"type":"text","text":" where \"no result\" is a normal outcome."}]}]}},"revision":1},{"id":"2c4b86cb-62c6-7e38-b9d9-da8ab95c5c03","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Creating"}]},"revision":1},{"id":"2b7a59b9-fd3b-7261-8dd5-dfa0492e959a","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Factory"}],[{"type":"text","text":"When"}]],[[{"type":"text","text":"Optional.of(v)","marks":[{"type":"code"}]}],[{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":" is definitely non-null — throws "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]},{"type":"text","text":" otherwise"}]],[[{"type":"text","text":"Optional.ofNullable(v)","marks":[{"type":"code"}]}],[{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":" may be "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" → empty"}]],[[{"type":"text","text":"Optional.empty()","marks":[{"type":"code"}]}],[{"type":"text","text":"explicitly no value"}]]]},"revision":1},{"id":"cf78f145-3b76-727d-9e81-ca53785dae46","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Using the value — don''t just call "},{"type":"text","text":"get()","marks":[{"type":"code"}]}]},"revision":1},{"id":"9fccb80d-6664-7ff7-b598-e60dc655cad2","type":"code","position":"a5","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static Map<String, String> emails = Map.of(\"asha\", \"asha@mail.com\");\n\n    static Optional<String> findEmail(String user) {\n        return Optional.ofNullable(emails.get(user));\n    }\n\n    public static void main(String[] args) {\n        System.out.println(findEmail(\"asha\"));\n        System.out.println(findEmail(\"ravi\"));\n\n        System.out.println(findEmail(\"ravi\").orElse(\"no-email\"));\n        System.out.println(findEmail(\"asha\").map(String::toUpperCase).orElse(\"?\"));\n        System.out.println(findEmail(\"asha\").filter(e -> e.endsWith(\".org\")).isPresent());\n        findEmail(\"asha\").ifPresent(e -> System.out.println(\"send to \" + e));\n        findEmail(\"ravi\").ifPresentOrElse(\n                e -> System.out.println(\"send to \" + e),\n                () -> System.out.println(\"nobody to email\"));\n        try {\n            findEmail(\"ravi\").orElseThrow();\n        } catch (NoSuchElementException e) {\n            System.out.println(e.getMessage());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"08b5d799-6893-7b06-a232-1c3e7193092b","type":"code","position":"a6","content":{"language":"text","code":"Optional[asha@mail.com]\nOptional.empty\nno-email\nASHA@MAIL.COM\nfalse\nsend to asha@mail.com\nnobody to email\nNo value present","filename":"Output"},"revision":1},{"id