xt","text":")"}]],[[{"type":"text","text":"filter(pred)","marks":[{"type":"code"}]}],[{"type":"text","text":"empty unless the predicate holds"}]],[[{"type":"text","text":"ifPresent(c)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"ifPresentOrElse(c, r)","marks":[{"type":"code"}]},{"type":"text","text":" (9+)"}],[{"type":"text","text":"run code"}]],[[{"type":"text","text":"or(supplier)","marks":[{"type":"code"}]},{"type":"text","text":" (9+)"}],[{"type":"text","text":"fall back to another "},{"type":"text","text":"Optional","marks":[{"type":"code"}]}]],[[{"type":"text","text":"stream()","marks":[{"type":"code"}]},{"type":"text","text":" (9+)"}],[{"type":"text","text":"0- or 1-element stream"}]]]},"revision":1},{"id":"184d7020-72d6-7b87-8b84-3d70d881c0ec","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"The "},{"type":"text","text":"orElse","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"orElseGet","marks":[{"type":"code"}]},{"type":"text","text":" trap"}]},"revision":1},{"id":"de846b4b-0abf-7b4b-81ab-7cf20ebe40e7","type":"code","position":"a9","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static String expensiveDefault() {\n        System.out.println(\"  (computing default...)\");\n        return \"default\";\n    }\n\n    public static void main(String[] args) {\n        Optional<String> name = Optional.of(\"Asha\");\n        System.out.println(\"orElse:\");\n        System.out.println(name.orElse(expensiveDefault()));      // default is computed anyway!\n        System.out.println(\"orElseGet:\");\n        System.out.println(name.orElseGet(Main::expensiveDefault)); // lazy — not called\n    }\n}","filename":"Java"},"revision":1},{"id":"a4f6edd9-f1ba-7f51-88fb-d5b7ad266967","type":"code","position":"aA","content":{"language":"text","code":"orElse:\n  (computing default...)\nAsha\norElseGet:\nAsha","filename":"Output"},"revision":1},{"id":"d505a445-cbdf-70e6-bdab-15bd0c3d3a3d","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"orElse(createUser())","marks":[{"type":"code"}]},{"type":"text","text":" runs "},{"type":"text","text":"createUser()","marks":[{"type":"code"}]},{"type":"text","text":" even when the value is present — wasteful, or a real bug if it has side effects (a DB insert). Use "},{"type":"text","text":"orElseGet","marks":[{"type":"code"}]},{"type":"text","text":" for anything non-trivial."}]}]}},"revision":1},{"id":"ab093b78-9b34-7c1a-b7d5-3b30132ae703","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"flatMap","marks":[{"type":"code"}]},{"type":"text","text":" — chaining without null checks"}]},"revision":1},{"id":"9f6dc763-b036-7f0e-a9b9-4e438698409c","type":"code","position":"aD","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    record Address(String city) {}\n    record User(String name, Optional<Address> address) {}\n\n    public static void main(String[] args) {\n        User withAddr = new User(\"Asha\", Optional.of(new Address(\"Pune\")));\n        User without = new User(\"Ravi\", Optional.empty());\n\n        for (User u : List.of(withAddr, without)) {\n            String city = Optional.of(u)\n                    .flatMap(User::address)          // already Optional → flatMap\n                    .map(Address::city)              // plain value → map\n                    .orElse(\"unknown\");\n            System.out.println(u.name() + \": \" + city);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"8e46d9dd-b76e-780f-b737-30a71d389b10","type":"code","position":"aE","content":{"language":"text","code":"Asha: Pune\nRavi: unknown","filename":"Output"},"revision":1},{"id":"e1b720cd-c520-73a6-b784-92970fa40b39","type":"callout","position":"aF","content":{"variant":"note","title":"Demo only","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The record above stores an "},{"type":"text","text":"Optional","marks":[{"type":"code"}]},{"type":"text","text":" field only to demonstrate "},{"type":"text","text":"flatMap","marks":[{"type":"code"}]},{"type":"text","text":". In real code, keep the field nullable and expose "},{"type":"text","text":"Optional<Address> address()","marks":[{"type":"code"}]},{"type":"text","text":" from a getter."}]}]}},"revision":1},{"id":"3c00267b-0e95-76aa-8ac8-800d76968954","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"How "},{"type":"text","text":"not","marks":[{"type":"italic"}]},{"type":"text","text":" to use Optional"}]},"revision":1},{"id":"7913004b-fb77-7a02-ae9c-558bd5d82742","type":"callout","position":"aH","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"Optional<T>","marks":[{"type":"code"}]},{"type":"text","text":" from methods that may find nothing ("},{"type":"text","text":"findById","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"max","marks":[{"type":"code"}]},{"type":"text","text":"). Chain with "},{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"filter","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"orElse","marks":[{"type":"code"}]},{"type":"text","text":". Return empty collections, not "},{"type":"text","text":"Optional<List<T>>","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"9807fb86-c495-70d4-aa2b-c35b4536831e","type":"callout","position":"aI","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Optional fields, method parameters or collection elements; "},{"type":"text","text":"Optional.get()","marks":[{"type":"code"}]},{"type":"text","text":" without a check; "},{"type":"text","text":"if (opt.isPresent()) opt.get()","marks":[{"type":"code"}]},{"type":"text","text":" (just a verbose null check); returning "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" from a method whose return type is "},{"type":"text","text":"Optional","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"75b65866-a870-72cb-8803-ddbffe0f5c31","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Optional","marks":[{"type":"code"}]},{"type":"text","text":" is not "},{"type":"text","text":"Serializable","marks":[{"type":"code"}]},{"type":"text","text":", adds an allocation, and a parameter of type "},{"type":"text","text":"Optional","marks":[{"type":"code"}]},{"type":"text","text":" can itself be "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" — so it solves nothing there. Primitive versions "},{"type":"text","text":"OptionalInt","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"OptionalLong","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"OptionalDouble","marks":[{"type":"code"}]},{"type":"text","text":" avoid boxing (returned by "},{"type":"text","text":"IntStream.max()","marks":[{"type":"code"}]},{"type":"text","text":" etc.)."}]}]}},"revision":1},{"id":"8ec30011-7167-7a84-94a7-b6d08788c182","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why was Optional added?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To make \"no result\" explicit in an API''s type. A method returning "},{"type":"text","text":"Optional<User>","marks":[{"type":"code"}]},{"type":"text","text":" tells callers at compile time that the user may be missing, pushing them to handle it ("},{"type":"text","text":"orElse","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"orElseThrow","marks":[{"type":"code"}]},{"type":"text","text":") instead of risking a "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]},{"type":"text","text":". It was designed primarily for stream results like "},{"type":"text","text":"findFirst","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"max","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"e73e2cb8-b98f-7933-b631-b54f8dc6e6a1","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difference between orElse and orElseGet?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"orElse(value)","marks":[{"type":"code"}]},{"type":"text","text":" takes an already-computed value, so its argument is evaluated even when the Optional is present. "},{"type":"text","text":"orElseGet(supplier)","marks":[{"type":"code"}]},{"type":"text","text":" takes a function that is called only when empty. Use "},{"type":"text","text":"orElse","marks":[{"type":"code"}]},{"type":"text","text":" for constants, "},{"type":"text","text":"orElseGet","marks":[{"type":"code"}]},{"type":"text","text":" for anything costly or with side effects."}]}]}},"revision":1},{"id":"7e0abe88-86ff-7146-9f57-3afb335532e2","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Should you use Optional as a field or method parameter?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. It''s intended for return types. As a field it isn''t serializable and adds overhead; as a parameter the caller could still pass "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":", and overloading or a nullable parameter is clearer."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
