SELECT '26ccefcb-fb8b-7fe7-abda-67b8a8ca0e81', '7cb42524-911b-7274-beab-6fd0f4b45a58', 1, 'PUBLISHED', 'Method Overriding vs Overloading', '[{"id":"d5e14e5b-c473-7fce-9894-4c557cbfdf1d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Overloading = same name, different parameters, chosen at compile time. Overriding = same signature in a subclass, chosen at runtime."}]}]}},"revision":1},{"id":"ea66dc8f-195d-7dd7-83e5-f611d1b42cb2","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Side by side"}]},"revision":1},{"id":"69c00352-7939-7fcd-aa06-590ac850b31b","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Overloading"}],[{"type":"text","text":"Overriding"}]],[[{"type":"text","text":"Where"}],[{"type":"text","text":"Same class (or inherited)"}],[{"type":"text","text":"Subclass redefines a superclass/interface method"}]],[[{"type":"text","text":"Signature"}],[{"type":"text","text":"Same name, "},{"type":"text","text":"different parameter list","marks":[{"type":"bold"}]}],[{"type":"text","text":"Same name "},{"type":"text","text":"and","marks":[{"type":"bold"}]},{"type":"text","text":" same parameters"}]],[[{"type":"text","text":"Return type"}],[{"type":"text","text":"Anything"}],[{"type":"text","text":"Same or a subtype ("},{"type":"text","text":"covariant","marks":[{"type":"italic"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Access"}],[{"type":"text","text":"Anything"}],[{"type":"text","text":"Same or "},{"type":"text","text":"wider","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"Checked exceptions"}],[{"type":"text","text":"Anything"}],[{"type":"text","text":"Same, narrower or none — never new/broader"}]],[[{"type":"text","text":"Resolved"}],[{"type":"text","text":"Compile time (static binding)"}],[{"type":"text","text":"Runtime (dynamic dispatch)"}]],[[{"type":"text","text":"static","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"final","marks":[{"type":"code"}]}],[{"type":"text","text":"Can be overloaded"}],[{"type":"text","text":"Cannot be overridden"}]],[[{"type":"text","text":"Polymorphism kind"}],[{"type":"text","text":"Compile-time"}],[{"type":"text","text":"Runtime"}]]]},"revision":1},{"id":"f2d57eb3-4690-7a55-b8f6-9c6b451ba51f","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Overloading"}]},"revision":1},{"id":"44d29d75-d7eb-74aa-960d-cfdc6c9864b5","type":"code","position":"a4","content":{"language":"java","code":"public class Main {\n    static String show(int x)          { return \"int \" + x; }\n    static String show(long x)         { return \"long \" + x; }\n    static String show(double x)       { return \"double \" + x; }\n    static String show(Integer x)      { return \"Integer \" + x; }\n    static String show(Object x)       { return \"Object \" + x; }\n    static String show(int... xs)      { return \"varargs \" + xs.length; }\n\n    public static void main(String[] args) {\n        byte b = 5;\n        System.out.println(show(7));        // exact match\n        System.out.println(show(b));        // widening byte → int beats boxing\n        System.out.println(show(7L));\n        System.out.println(show(7.0f));     // float → double\n        System.out.println(show(\"hi\"));     // String → Object\n        System.out.println(show());         // only varargs fits\n    }\n}","filename":"Java"},"revision":1},{"id":"d39e1fd6-a556-7c49-9925-9e2b87b35439","type":"code","position":"a5","content":{"language":"text","code":"int 7\nint 5\nlong 7\ndouble 7.0\nObject hi\nvarargs 0","filename":"Output"},"revision":1},{"id":"de3a9c38-4479-7fa6-b781-12b1becf68da","type":"callout","position":"a6","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Overload resolution picks the most specific method in three phases: (1) exact/widening, (2) boxing/unboxing, (3) varargs. The return type alone never distinguishes overloads."}]}]}},"revision":1},{"id":"1453ce2e-a095-7067-a0b6-ea0d31017437","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Overriding with "},{"type":"text","text":"@Override","marks":[{"type":"code"}]}]},"revision":1},{"id":"d5122271-f390-7748-9cd1-aec7d0109c5d","type":"code","position":"a8","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        Shape s = new Circle(2);           // reference type Shape, object Circle\n        System.out.println(s.name());      // runtime: Circle.name()\n        Circle copy = new Circle(2).copy();   // covariant return: no cast needed\n        System.out.printf(\"%.2f%n\", copy.area());\n    }\n}\n\nclass Shape {\n    protected String name() { return \"shape\"; }\n    Shape copy() { return new Shape(); }\n    double area() { return 0; }\n}\n\nclass Circle extends Shape {\n    private final double r;\n    Circle(double r) { this.r = r; }\n\n    @Override public String name() { return \"circle\"; }        // protected → public: widening OK\n    @Override Circle copy() { return new Circle(r); }          // covariant return type\n    @Override double area() { return Math.PI * r * r; }\n}","filename":"Java"},"revision":1},{"id":"adea5af1-4486-7b31-b1ea-a8fa23f72c28","type":"code","position":"a9","content":{"language":"text","code":"circle\n12.57","filename":"Output"},"revision":1},{"id":"250f72c1-ab76-76ac-a2f2-639ffec5e3d6","type":"callout","position":"aA","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Always write "},{"type":"text","text":"@Override","marks":[{"type":"code"}]},{"type":"text","text":". Without it, a typo or wrong parameter type silently creates an "},{"type":"text","text":"overload","marks":[{"type":"italic"}]},{"type":"text","text":" instead — e.g. "},{"type":"text","text":"public boolean equals(Point p)","marks":[{"type":"code"}]},{"type":"text","text":" does not override "},{"type":"text","text":"equals(Object)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"34cb06bb-f280-7965-ac3a-536303d70dc4","type":"code","position":"aB","content":{"language":"java","code":"class Point {\n    int x;\n    @Override\n    public boolean equals(Point other) { return other.x == x; }   // wrong parameter type\n}","filename":"Java"},"revision":1},{"id":"f6a0e2b6-70d0-7a33-aaf4-05545e669c12","type":"code","position":"aC","content":{"language":"text","code":"Main.java:3: error: method does not override or implement a method from a supertype\n    @Override\n    ^","filename":"javac"},"revision":1},{"id":"0a27f09a-9ae7-7c78-816d-e4bb15da5778","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Rules the compiler enforces"}]},"revision":1},{"id":"1b22fb7c-2a8b-7465-8b89-327a2769cf1a","type":"code","position":"aE","content":{"language":"java","code":"import java.io.IOException;\n\nclass Parent {\n    public void run() { }\n    void load() throws IOException { }\n}\n\nclass Child extends Parent {\n    @Override protected void run() { }   // narrowing public → protected\n}","filename":"Java"},"revision":1},{"id":"82c5a16e-482e-72cc-ab89-90a73b5c8cef","type":"code","position":"aF","content":{"language":"text","code":"Main.java:9: error: run() in Child cannot override run() in Parent\n    @Override protected void run() { }   // narrowing public → protected\n                             ^\n  attempting to assign weaker access privileges; was public","filename":"javac"},"revision":1},{"id":"1d7f54b0-bdf4-7982-b3a5-e3ce96d085d8","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An override "},{"type":"text","text":"may","marks":[{"type":"bold"}]},{"type":"text","text":" throw fewer or narrower checked exceptions ("},{"type":"text","text":"FileNotFoundException","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"IOException","marks":[{"type":"code"}]},{"type":"text","text":"), or none; unchecked exceptions are unrestricted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":" methods can''t be overridden; "},{"type":"text","text":"private","marks":[{"type":"code"}]},{"type":"text","text":" methods aren''t inherited, so a same-named subclass method is just a new method."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Call the parent version with "},{"type":"text","text":"super.method()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"717f9db7-9caf-73b4-b79a-f630b927298d","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Static methods are hidden, not overridden"}]},"revision":1},{"id":"568daa20-2dc9-7308-aa69-02848ab9b345","type":"code","position":"aI","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        Parent p = new Child();\n        System.out.println(p.stat());      // static: chosen by reference type\n        System.out.println(p.inst());      // instance: chosen by object type\n        System.out.println(p.label);       // fields are hidden too\n        System.out.println(((Child) p).label);\n    }\n}\n\nclass Parent {\n    String label = \"parent-field\";\n    static String stat() { return \"Parent.stat\"; }\n    String inst() { return \"Parent.inst\"; }\n}\n\nclass Child extends Parent {\n    String label = \"child-field\";\n    static String stat() { return \"Child.stat\"; }\n    @Override String inst() { return \"Child.inst\"; }\n}","filename":"Java"},"revision":1},{"id":"2cb78f81-e6cc-70b8-8cf7-30da480a199a","type":"code","position":"aJ","content":{"language":"text","code":"Parent.stat\nChild.inst\nparent-field\nchild-field","filename":"Output"},"revision":1},{"id":"62d42758-91fb-7e98-8852-4e79e78f94fb","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can we overload main?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes — any number of "},{"type":"text","text":"main","marks":[{"type":"code"}]},{"type":"text","text":" overloads may exist, but the JVM only launches "},{"type":"text","text":"public static void main(String[] args)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"fdf0815b-eeba-7e5c-9ebf-994fcce6e5ee","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can we override a static or private method?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. A static method with the same signature "},{"type":"text","text":"hides","marks":[{"type":"italic"}]},{"type":"text","text":" the parent''s (resolved by reference type at compile time). A private method isn''t visible to the subclass, so a same-named method is a brand-new method."}]}]}},"revision":1},{"id":"d487a003-eb6e-7ad4-82e0-482c207c2292","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can two overloads differ only by return type?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. The call "},{"type":"text","text":"f(1)","marks":[{"type":"code"}]},{"type":"text","text":" wouldn''t tell the compiler which one you want, so it''s a compile error ("},{"type":"text","text":"method f(int) is already defined","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"b0f969d9-c5a1-77ce-8a4d-64aaa13c0325","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a covariant return type?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An overriding method may return a "},{"type":"text","text":"subtype","marks":[{"type":"italic"}]},{"type":"text","text":" of the parent method''s return type — e.g. "},{"type":"text","text":"Circle copy()","marks":[{"type":"code"}]},{"type":"text","text":" overriding "},{"type":"text","text":"Shape copy()","marks":[{"type":"code"}]},{"type":"text","text":" — so callers need no cast. "},{"type":"text","text":"clone()","marks":[{"type":"code"}]},{"type":"text","text":" overrides commonly use it."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
