SELECT '0f66f52e-c10c-7d71-a852-77b20bfb468e', 'b42d0d52-e1a6-7293-9a41-8151638ac052', 1, 'PUBLISHED', 'Polymorphism & Dynamic Dispatch', '[{"id":"e86b0d4d-066e-7bb3-9a6d-86e19cb3b47c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One reference type, many behaviours: the JVM picks the overriding method of the "},{"type":"text","text":"actual object","marks":[{"type":"italic"}]},{"type":"text","text":" at runtime."}]}]}},"revision":1},{"id":"b11a0973-b3ca-7245-a297-13927866768f","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Polymorphism","marks":[{"type":"bold"}]},{"type":"text","text":" — “many forms” — code written against a supertype works with any subtype. Java has "},{"type":"text","text":"compile-time","marks":[{"type":"bold"}]},{"type":"text","text":" polymorphism (overloading) and "},{"type":"text","text":"runtime","marks":[{"type":"bold"}]},{"type":"text","text":" polymorphism (overriding + dynamic dispatch)."}]}]}},"revision":1},{"id":"f8612ee4-9d4c-71d7-a9d5-758f290a9154","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Runtime polymorphism"}]},"revision":1},{"id":"e8ecb8ba-cebc-75b5-b22f-a196128496b3","type":"code","position":"a3","content":{"language":"java","code":"import java.util.List;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Payment> payments = List.of(new Card(100), new Upi(250), new Cash(40));\n        double total = 0;\n        for (Payment p : payments) {             // one loop, three behaviours\n            System.out.println(p.describe());\n            total += p.fee();\n        }\n        System.out.println(\"total fees = \" + total);\n    }\n}\n\nabstract class Payment {\n    protected final double amount;\n    Payment(double amount) { this.amount = amount; }\n    abstract double fee();\n    String describe() { return getClass().getSimpleName() + \" \" + amount + \" fee \" + fee(); }\n}\n\nclass Card extends Payment { Card(double a) { super(a); } double fee() { return amount * 0.02; } }\nclass Upi  extends Payment { Upi(double a)  { super(a); } double fee() { return 0; } }\nclass Cash extends Payment { Cash(double a) { super(a); } double fee() { return 1; } }","filename":"Java"},"revision":1},{"id":"db0ab7f5-5e55-7025-9dca-cc86b0063ba2","type":"code","position":"a4","content":{"language":"text","code":"Card 100.0 fee 2.0\nUpi 250.0 fee 0.0\nCash 40.0 fee 1.0\ntotal fees = 3.0","filename":"Output"},"revision":1},{"id":"f21f07ae-9106-7894-a26e-025de2c6760c","type":"callout","position":"a5","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Adding a new payment type needs "},{"type":"text","text":"no change","marks":[{"type":"bold"}]},{"type":"text","text":" to the loop — that is the Open/Closed Principle in action, and why polymorphism beats "},{"type":"text","text":"if (type == ...)","marks":[{"type":"code"}]},{"type":"text","text":" chains."}]}]}},"revision":1},{"id":"594a284d-b6fc-76be-a12a-cb58c9060de9","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Static type vs runtime type"}]},"revision":1},{"id":"5e5caf0f-ae55-72f1-b675-7a2f90016362","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Question"}],[{"type":"text","text":"Decided by"}],[{"type":"text","text":"When"}]],[[{"type":"text","text":"Which methods may I "},{"type":"text","text":"call","marks":[{"type":"italic"}]},{"type":"text","text":"?"}],[{"type":"text","text":"Reference (static) type"}],[{"type":"text","text":"Compile time"}]],[[{"type":"text","text":"Which overload is chosen?"}],[{"type":"text","text":"Static types of the arguments"}],[{"type":"text","text":"Compile time"}]],[[{"type":"text","text":"Which override "},{"type":"text","text":"runs","marks":[{"type":"italic"}]},{"type":"text","text":"?"}],[{"type":"text","text":"Runtime class of the object"}],[{"type":"text","text":"Runtime (dynamic dispatch)"}]],[[{"type":"text","text":"Which field is read?"}],[{"type":"text","text":"Reference type — fields are not polymorphic"}],[{"type":"text","text":"Compile time"}]],[[{"type":"text","text":"Which static method runs?"}],[{"type":"text","text":"Reference type"}],[{"type":"text","text":"Compile time"}]]]},"revision":1},{"id":"ba5081d7-f6c0-7b1a-9175-2728f0b454c2","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"How dynamic dispatch works"}]},"revision":1},{"id":"b1d5b597-4d65-7bdf-a897-a464a03eab7a","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compile","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"javac","marks":[{"type":"code"}]},{"type":"text","text":" checks the method exists on the static type and emits "},{"type":"text","text":"invokevirtual Shape.area()","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"invokeinterface","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Look up","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"At runtime the JVM reads the object''s actual class and finds "},{"type":"text","text":"area","marks":[{"type":"code"}]},{"type":"text","text":" in its "},{"type":"text","text":"method table","marks":[{"type":"bold"}]},{"type":"text","text":" (vtable) — the most specific override."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Optimise","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The JIT often "},{"type":"text","text":"inlines","marks":[{"type":"italic"}]},{"type":"text","text":" the call when only one implementation has been seen (monomorphic call site), so polymorphism is usually free."}]}]}]}]}},"revision":1},{"id":"cd2de4ff-500f-7063-8452-a66f528e7533","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Upcasting and downcasting"}]},"revision":1},{"id":"9c286ecf-f6ac-7e93-abea-cd9e82538adc","type":"code","position":"aB","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        Animal a = new Dog();              // upcast: implicit, always safe\n        a.speak();\n        // a.fetch();                      // error: Animal has no fetch()\n\n        if (a instanceof Dog d) {          // pattern matching (Java 16+): test + cast\n            d.fetch();\n        }\n        Dog d2 = (Dog) a;                  // explicit downcast: checked at runtime\n        d2.fetch();\n\n        Animal c = new Cat();\n        try {\n            Dog wrong = (Dog) c;           // compiles, fails at runtime\n            wrong.fetch();\n        } catch (ClassCastException e) {\n            System.out.println(\"ClassCastException\");\n        }\n    }\n}\n\nclass Animal { void speak() { System.out.println(\"...\"); } }\nclass Dog extends Animal {\n    @Override void speak() { System.out.println(\"Woof\"); }\n    void fetch() { System.out.println(\"fetching\"); }\n}\nclass Cat extends Animal { @Override void speak() { System.out.println(\"Meow\"); } }","filename":"Java"},"revision":1},{"id":"b797d499-1d21-701f-b445-b346129fea87","type":"code","position":"aC","content":{"language":"text","code":"Woof\nfetching\nfetching\nClassCastException","filename":"Output"},"revision":1},{"id":"1fbf0025-bcf0-7f7a-ad36-92603e145663","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A downcast