SELECT 'f544294f-cae3-7b3e-b9a6-289c89d2b60d', 'd56022d3-c2ac-7d11-a163-9340cbee2fc7', 1, 'PUBLISHED', 'Queue, Deque & PriorityQueue', '[{"id":"40c4737b-eb45-7448-87a1-9eea1c743c8f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Queue","marks":[{"type":"code"}]},{"type":"text","text":" = FIFO line, "},{"type":"text","text":"Deque","marks":[{"type":"code"}]},{"type":"text","text":" = double-ended (queue "},{"type":"text","text":"and","marks":[{"type":"italic"}]},{"type":"text","text":" stack), "},{"type":"text","text":"PriorityQueue","marks":[{"type":"code"}]},{"type":"text","text":" = always hands you the smallest element next. "},{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"PriorityQueue","marks":[{"type":"code"}]},{"type":"text","text":" cover almost every need."}]}]}},"revision":1},{"id":"03766ccb-3263-71bc-9126-0919ef50c583","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Two method families"}]},"revision":1},{"id":"19d92a66-0d9f-790f-8a44-3f376f0d0e6c","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Action"}],[{"type":"text","text":"Throws on failure"}],[{"type":"text","text":"Returns special value"}]],[[{"type":"text","text":"Insert"}],[{"type":"text","text":"add(e)","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"IllegalStateException","marks":[{"type":"code"}]},{"type":"text","text":" if full"}],[{"type":"text","text":"offer(e)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"false","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Remove head"}],[{"type":"text","text":"remove()","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"NoSuchElementException","marks":[{"type":"code"}]},{"type":"text","text":" if empty"}],[{"type":"text","text":"poll()","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"null","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Look at head"}],[{"type":"text","text":"element()","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"NoSuchElementException","marks":[{"type":"code"}]}],[{"type":"text","text":"peek()","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"null","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"6f74a88d-64cc-7d8f-bcff-45ceb774f070","type":"callout","position":"a3","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer "},{"type":"text","text":"offer","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"poll","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"peek","marks":[{"type":"code"}]},{"type":"text","text":" — empty checks become simple "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" tests. (Which is also why "},{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"PriorityQueue","marks":[{"type":"code"}]},{"type":"text","text":" refuse "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" elements.)"}]}]}},"revision":1},{"id":"3b02d3c0-3a91-76b5-8b56-0ac747de93f5","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":" as a queue and as a stack"}]},"revision":1},{"id":"f280528b-c36d-7886-8637-42299585615b","type":"code","position":"a5","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Deque<Integer> queue = new ArrayDeque<>();   // FIFO: offer at tail, poll at head\n        queue.offer(1);\n        queue.offer(2);\n        queue.offer(3);\n        System.out.println(queue.poll() + \" \" + queue.peek() + \" \" + queue);\n\n        Deque<Integer> stack = new ArrayDeque<>();   // LIFO: push/pop at the head\n        stack.push(1);\n        stack.push(2);\n        stack.push(3);\n        System.out.println(stack.pop() + \" \" + stack.peek() + \" \" + stack);\n\n        Deque<String> dq = new ArrayDeque<>();\n        dq.offerFirst(\"b\");\n        dq.offerFirst(\"a\");\n        dq.offerLast(\"c\");\n        System.out.println(dq.pollLast() + \" \" + dq);\n        System.out.println(new ArrayDeque<Integer>().poll());   // empty -> null\n    }\n}","filename":"Java"},"revision":1},{"id":"7f94c43e-4def-7d9d-a804-ff8db6031500","type":"code","position":"a6","content":{"language":"text","code":"1 2 [2, 3]\n3 2 [2, 1]\nc [a, b]\nnull","filename":"Output"},"revision":1},{"id":"4b05f1bf-63da-7242-b521-27b4d8b102f1","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Deque method"}],[{"type":"text","text":"As a queue"}],[{"type":"text","text":"As a stack"}]],[[{"type":"text","text":"offerLast","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"offer","marks":[{"type":"code"}]}],[{"type":"text","text":"enqueue"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"pollFirst","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"poll","marks":[{"type":"code"}]}],[{"type":"text","text":"dequeue"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"push","marks":[{"type":"code"}]},{"type":"text","text":" (= "},{"type":"text","text":"addFirst","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"—"}],[{"type":"text","text":"push"}]],[[{"type":"text","text":"pop","marks":[{"type":"code"}]},{"type":"text","text":" (= "},{"type":"text","text":"removeFirst","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"—"}],[{"type":"text","text":"pop"}]],[[{"type":"text","text":"peekFirst","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"peek","marks":[{"type":"code"}]}],[{"type":"text","text":"front"}],[{"type":"text","text":"top"}]]]},"revision":1},{"id":"68994498-ee6b-7a03-9098-18ae59ce2cb0","type":"callout","position":"a8","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"Deque<Integer> stack = new ArrayDeque<>()","marks":[{"type":"code"}]},{"type":"text","text":" — the Javadoc of "},{"type":"text","text":"Stack","marks":[{"type":"code"}]},{"type":"text","text":" itself recommends it. "},{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":" is a circular array: O(1) amortised at both ends, no node allocation."}]}]}},"revision":1},{"id":"c994b68c-9f87-712c-90f6-7bb8d07d8b43","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"PriorityQueue","marks":[{"type":"code"}]},{"type":"text","text":" — a binary heap"}]},"revision":1},{"id":"d311dfa3-302b-74c2-95e3-e07c00be392a","type":"code","position":"aA","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        PriorityQueue<Integer> min = new PriorityQueue<>(List.of(5, 1, 8, 3, 2));\n        System.out.println(\"peek=\" + min.peek());\n        StringBuilder sb = new StringBuilder();\n        while (!min.isEmpty()) sb.append(min.poll()).append('' '');\n        System.out.println(\"min-heap order: \" + sb.toString().trim());\n\n        PriorityQueue<Integer> max = new PriorityQueue<>(Comparator.reverseOrder());\n        max.addAll(List.of(5, 1, 8, 3, 2));\n        System.out.println(\"max first: \" + max.poll() + \" \" + max.poll());\n\n        PriorityQueue<String> byLen = new PriorityQueue<>(\n            Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder()));\n        byLen.add