SELECT '8e724562-7058-7fd8-a230-20dec9789a2e', '2676d84e-bf27-7484-91fa-c55bb124ab40', 1, 'PUBLISHED', 'Records', '[{"id":"8a85cf6e-46ff-7e22-80af-6a7d31ccf24c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"record","marks":[{"type":"code"}]},{"type":"text","text":" (Java 16+) is a concise, immutable data carrier: declare the components and the compiler writes the constructor, accessors, "},{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"hashCode","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"toString","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"9595d52a-77d2-709e-bf1a-40b17b34ac8a","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Record","marks":[{"type":"bold"}]},{"type":"text","text":" — a final class whose state is exactly its "},{"type":"text","text":"components","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"record Point(int x, int y) {}","marks":[{"type":"code"}]},{"type":"text","text":" gets "},{"type":"text","text":"private final","marks":[{"type":"code"}]},{"type":"text","text":" fields, a canonical constructor, accessors "},{"type":"text","text":"x()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"y()","marks":[{"type":"code"}]},{"type":"text","text":", and value-based "},{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"hashCode","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"toString","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"c6fbbe19-c3bd-71ed-8bad-879a4d1815c7","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"What you get for free"}]},"revision":1},{"id":"c6010665-45b5-7b97-9e4e-d8055f72a7e4","type":"code","position":"a3","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    record Point(int x, int y) {}\n\n    public static void main(String[] args) {\n        Point p = new Point(3, 4);\n        System.out.println(p);                     // generated toString\n        System.out.println(p.x() + p.y());         // accessors: x(), not getX()\n        System.out.println(p.equals(new Point(3, 4)));\n        System.out.println(new HashSet<>(List.of(p)).contains(new Point(3, 4)));\n    }\n}","filename":"Java"},"revision":1},{"id":"d93195f7-e28d-7905-9b0c-c251fe335e29","type":"code","position":"a4","content":{"language":"text","code":"Point[x=3, y=4]\n7\ntrue\ntrue","filename":"Output"},"revision":1},{"id":"ee56b040-a9a0-7d5d-aa3a-34db9043828e","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Generated member"}],[{"type":"text","text":"For "},{"type":"text","text":"record Point(int x, int y)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Fields"}],[{"type":"text","text":"private final int x; private final int y;","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Canonical constructor"}],[{"type":"text","text":"Point(int x, int y)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Accessors"}],[{"type":"text","text":"int x()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"int y()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"hashCode","marks":[{"type":"code"}]}],[{"type":"text","text":"Compare / hash all components"}]],[[{"type":"text","text":"toString","marks":[{"type":"code"}]}],[{"type":"text","text":"Point[x=3, y=4]","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"48437e3d-5e8e-790b-a912-dae92d82c1f3","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Compact constructor: validate and normalise"}]},"revision":1},{"id":"d0ac3923-8173-7cae-a79b-d66afc78fe93","type":"code","position":"a7","content":{"language":"java","code":"public class Main {\n    record Range(int lo, int hi) {\n        Range {                                    // compact canonical constructor: no parameter list\n            if (lo > hi) throw new IllegalArgumentException(\"lo > hi: \" + lo + \" > \" + hi);\n        }\n        int length() { return hi - lo; }           // extra methods are fine\n        static Range of(int a, int b) {            // static factory\n            return new Range(Math.min(a, b), Math.max(a, b));\n        }\n    }\n\n    record Email(String value) {\n        Email {\n            value = value.trim().toLowerCase();     // reassign the parameter, not this.value\n        }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(new Range(2, 9).length());\n        System.out.println(Range.of(9, 2));\n        System.out.println(new Email(\"  Asha@Mail.COM \"));\n        try {\n            new Range(5, 1);\n        } catch (IllegalArgumentException e) {\n            System.out.println(\"rejected: \" + e.getMessage());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"5b3e8b26-2ec2-7dcf-b3c8-6ff25234a153","type":"code","position":"a8","content":{"language":"text","code":"7\nRange[lo=2, hi=9]\nEmail[value=asha@mail.com]\nrejected: lo > hi: 5 > 1","filename":"Output"},"revision":1},{"id":"aae730a1-9ba5-7db9-a488-8789da1b13ce","type":"callout","position":"a9","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a compact constructor the fields are assigned "},{"type":"text","text":"after","marks":[{"type":"bold"}]},{"type":"text","text":" your code runs, from the (possibly reassigned) parameters. You cannot write "},{"type":"text","text":"this.lo = …","marks":[{"type":"code"}]},{"type":"text","text":" there."}]}]}},"revision":1},{"id":"2bab98de-6ccf-7d78-bf34-d2cffffc6a3e","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Records and shallow immutability"}]},"revision":1},{"id":"997f7eb0-999f-7aeb-837c-1594daaac215","type":"code","position":"aB","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    record Team(String name, List<String> members) {\n        Team {\n            members = List.copyOf(members);        // defensive, unmodifiable copy\n        }\n    }\n\n    public static void main(String[] args) {\n        List<String> list = new ArrayList<>(List.of(\"Asha\"));\n        Team t = new Team(\"core\", list);\n        list.add(\"Ravi\");                          // doesn''t leak into the record\n        System.out.println(t.members());\n        try {\n            t.members().add(\"Mei\");\n        } catch (UnsupportedOperationException e) {\n            System.out.println(\"members are read-only\");\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"093d1ad3-af9c-7d6a-af3a-90adeed7e288","type":"code","position":"aC","content":{"language":"text","code":"[Asha]\nmembers are read-only","filename":"Output"},"revision":1},{"id":"6662170d-4e17-74f7-9052-5943945825b1","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A record''s fields are "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":", but the objects they point to are not magically immutable. A "},{"type":"text","text":"List","marks":[{"type":"code"}]},{"type":"text","text":" component is still mutable unless you copy it with "},{"type":"text","text":"List.copyOf","marks":[{"type":"code"}]},{"type":"text","text":" in the compact constructor."}]}]}},"revision":1},{"id":"a472f6c9-f624-7c72-8fca-a2b7cb9e2c96","type":"heading","position":"aE","