SELECT '3214449a-51b6-7221-b420-4aec1e2f844f', '986ab081-79ca-7aef-9252-dc7291157111', 1, 'PUBLISHED', 'Recursion', '[{"id":"6b6f70c4-a792-7b9f-b4e9-bdd4ae30452b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A method that calls itself on a smaller input. Every recursion needs a "},{"type":"text","text":"base case","marks":[{"type":"bold"}]},{"type":"text","text":"; each call pushes a stack frame, so depth is limited."}]}]}},"revision":1},{"id":"26d088f9-1dca-77e1-8d55-8d2532ebdde8","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursion","marks":[{"type":"bold"}]},{"type":"text","text":" — solving a problem by reducing it to smaller instances of the same problem, until a "},{"type":"text","text":"base case","marks":[{"type":"italic"}]},{"type":"text","text":" can be answered directly."}]}]}},"revision":1},{"id":"1a122251-424f-7993-86d8-df16820a10aa","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The two parts"}]},"revision":1},{"id":"146384b8-32d8-7349-8dcb-a0b2fa3ff3aa","type":"code","position":"a3","content":{"language":"java","code":"public class Main {\n    static long factorial(int n) {\n        if (n <= 1) return 1;                 // base case\n        return n * factorial(n - 1);          // recursive case: smaller input\n    }\n\n    static int sumDigits(int n) {\n        return n < 10 ? n : n % 10 + sumDigits(n / 10);\n    }\n\n    static String reverse(String s) {\n        return s.isEmpty() ? \"\" : reverse(s.substring(1)) + s.charAt(0);\n    }\n\n    public static void main(String[] args) {\n        System.out.println(factorial(5) + \" \" + factorial(20));\n        System.out.println(sumDigits(9875));\n        System.out.println(reverse(\"stack\"));\n    }\n}","filename":"Java"},"revision":1},{"id":"190b2d5f-185c-700a-bb53-f377dcda2579","type":"code","position":"a4","content":{"language":"text","code":"120 2432902008176640000\n29\nkcats","filename":"Output"},"revision":1},{"id":"50250ebe-2906-7309-9d0d-3a0096b7cf98","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"The call stack"}]},"revision":1},{"id":"c3452e55-f680-7ef5-9a9c-2905eceac07e","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"factorial(3)","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" called","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Frame pushed: "},{"type":"text","text":"n=3","marks":[{"type":"code"}]},{"type":"text","text":", waiting on "},{"type":"text","text":"factorial(2)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"factorial(2)","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Frame pushed: "},{"type":"text","text":"n=2","marks":[{"type":"code"}]},{"type":"text","text":", waiting on "},{"type":"text","text":"factorial(1)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"factorial(1)","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" — base case","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Returns "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":"; frame popped."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unwinding","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"2 * 1 = 2","marks":[{"type":"code"}]},{"type":"text","text":" returned, then "},{"type":"text","text":"3 * 2 = 6","marks":[{"type":"code"}]},{"type":"text","text":". Each frame pops as it returns."}]}]}]}]}},"revision":1},{"id":"a9c67e85-ecb9-71bb-8ff3-71ade32edfc5","type":"code","position":"a7","content":{"language":"java","code":"public class Main {\n    static int depth = 0;\n\n    static void dive() {\n        depth++;\n        dive();                               // no base case\n    }\n\n    public static void main(String[] args) {\n        try {\n            dive();\n        } catch (StackOverflowError e) {      // an Error, not an Exception\n            System.out.println(\"StackOverflowError after \" + (depth > 1000 ? \"thousands of\" : \"few\") + \" calls\");\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"b6899777-fa4d-7e82-b14b-5f9d4c48223f","type":"code","position":"a8","content":{"language":"text","code":"StackOverflowError after thousands of calls","filename":"Output"},"revision":1},{"id":"4ab8620f-de1e-7927-a50d-22d574fb58a5","type":"callout","position":"a9","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The JVM does "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" perform tail-call optimization. Even a tail-recursive method uses one frame per call, so deep recursion (e.g. 100 000 levels) overflows the default ~512 KB–1 MB thread stack. Convert to a loop, or run in a thread with a bigger stack."}]}]}},"revision":1},{"id":"d1cbf197-eebc-73b4-8b53-084b93e975ef","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Memoization: from exponential to linear"}]},"revision":1},{"id":"103a812b-a4fb-7ace-ba4b-904d4110e349","type":"code","position":"aB","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static int calls = 0;\n\n    static long fibNaive(int n) {\n        calls++;\n        return n < 2 ? n : fibNaive(n - 1) + fibNaive(n - 2);    // O(2^n)\n    }\n\n    static Map<Integer, Long> memo = new HashMap<>();\n    static long fibMemo(int n) {\n        if (n < 2) return n;\n        Long cached = memo.get(n);\n        if (cached != null) return cached;\n        long v = fibMemo(n - 1) + fibMemo(n - 2);                // O(n)\n        memo.put(n, v);\n        return v;\n    }\n\n    static long fibIter(int n) {                                 // O(n) time, O(1) space\n        long a = 0, b = 1;\n        for (int i = 0; i < n; i++) { long t = a + b; a = b; b = t; }\n        return a;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(fibNaive(25) + \" in \" + calls + \" calls\");\n        System.out.println(fibMemo(90) + \" \" + fibIter(90));\n    }\n}","filename":"Java"},"revision":1},{"id":"722186b6-0634-780a-bc7a-8d2d1eecc3c3","type":"code","position":"aC","content":{"language":"text","code":"75025 in 242785 calls\n2880067194370816120 2880067194370816120","filename":"Output"},"revision":1},{"id":"28b274e0-4165-72d9-9b06-49e755ed9d88","type":"callout","position":"aD","content":{"variant":"note","title":"Gotcha","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Don''t use "},{"type":"text","text":"memo.computeIfAbsent(n, k -> fib(k-1) + fib(k-2))","marks":[{"type":"code"}]},{"type":"text","text":" for recursive memoization on a "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":" — modifying the map inside its own "},{"type":"text","text":"computeIfAbsent","marks":[{"type":"code"}]},{"type":"text","text":" throws "},{"type":"text","text":"ConcurrentModificationException","marks":[{"type":"code"}]},{"type":"text","text":" (Java 9+)."}]}]}},"revision":1},{"id":"5713840d-ba49-7f61-998c-bb1cf1233f71","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Classic recursive patterns"}]},"revision":1},{"id":"0f5b64f3-e4ba-703b-bae1-678c440614cd","type":"code","position":"aF","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static int binarySearch(int[] a, int target, int lo, int hi) {\n        if (lo > hi) return -1;\n        int mid = (lo + hi) >>> 1;\n        if (a[mid] == target) return mid;\n        return a[mid] < target ? binarySearch(a, target, mid + 1, hi)\n                               : binarySearch(a, target, lo, mid - 1);\n    }\n\n    static void subsets(int[] nums, int i, Deque<Integer> cur, List<String> out) {\n        if (i == nums.length) { out.add(cur.toString()); return; }\n        subsets(nums, i + 1, cur, out);            // exclude nums[i]\n        cur.addLast(nums[i]);\n        subsets(nums, i + 1, cur, out);            // include nums[i]\n        cur.removeLast();                          // backtrack\n    }\n\n    static void hanoi(int n, char from, char to, char via, List<String> moves) {\n        if (n == 0) return;\n        hanoi(n - 1, from, via, to, moves);\n        moves.add(from + \">\" + to);\n        hanoi(n - 1, via, to, from, moves);\n    }\n\n    public static void main(String[] args) {\n        System.out.println(binarySearch(new int[]{1, 3, 5, 7, 9}, 7, 0, 4));\n        List<String> out = new ArrayList<>();\n        subsets(new int[]{1, 2, 3}, 0, new ArrayDeque<>(), out);\n        System.out.println(out);\n        List<String> moves = new ArrayList<>();\n        hanoi(3, ''A'', ''C'', ''B'', moves);\n        System.out.println(moves.size() + \" moves: \" + moves);\n    }\n}","filename":"Java"},"revision":1},{"id":"ee6e607c-7dd3-7ca6-b420-6e771855b458","type":"code","position":"aG","content":{"language":"text","code":"3\n[[], [3], [2], [2, 3], [1], [1, 3], [1, 2], [1, 2, 3]]\n7 moves: [A>C, A>B, C>B, A>C, B>A, B>C, A>C]","filename":"Output"},"revision":1},{"id":"f2836b9e-1fdf-736a-aae6-5cfdafa8fdcf","type":"table","position":"aH","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Recursion"}],[{"type":"text","text":"Iteration"}]],[[{"type":"text","text":"Natural for trees, graphs, divide & conquer, backtracking"}],[{"type":"text","text":"Natural for linear scans"}]],[[{"type":"text","text":"O(depth) stack space"}],[{"type":"text","text":"O(1) extra space usually"}]],[[{"type":"text","text":"Risk of "},{"type":"text","text":"StackOverflowError","marks":[{"type":"code"}]}],[{"type":"text","text":"No stack risk"}]],[[{"type":"text","text":"Method-call overhead per step"}],[{"type":"text","text":"Faster in the JVM"}]]]},"revision":1},{"id":"66c50671-76a3-745a-aa0f-d780ebee2e95","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens if a recursive method has no base case?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It recurses until the thread''s stack is exhausted and the JVM throws "},{"type":"text","text":"StackOverflowError","marks":[{"type":"code"}]},{"type":"text","text":" (a subclass of "},{"type":"text","text":"VirtualMachineError","marks":[{"type":"code"}]},{"type":"text","text":", i.e. an "},{"type":"text","text":"Error","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"b1490a66-7bbe-7240-8f6b-6844fa4f4cc8","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does Java optimize tail recursion?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. The JVM spec has no tail-call elimination (partly to keep stack traces and security checks intact), so rewrite deep tail recursion as a loop."}]}]}},"revision":1},{"id":"a6e5076e-9637-7283-b244-b9ac932936bc","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the time complexity of a recursive function?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write the recurrence: e.g. naive Fibonacci "},{"type":"text","text":"T(n) = T(n-1) + T(n-2) + O(1)","marks":[{"type":"code"}]},{"type":"text","text":" → O(2ⁿ) (tighter: φⁿ); binary search "},{"type":"text","text":"T(n) = T(n/2) + O(1)","marks":[{"type":"code"}]},{"type":"text","text":" → O(log n); merge sort "},{"type":"text","text":"T(n) = 2T(n/2) + O(n)","marks":[{"type":"code"}]},{"type":"text","text":" → O(n log n) (Master theorem)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
