SELECT 'ed531634-64ea-7f2f-bc27-064f46cfc55e', 'b00f7840-f7ed-76d0-a939-73b10c324c0f', 1, 'PUBLISHED', 'Sealed Classes & Interfaces', '[{"id":"6cb2699f-4df5-73a4-99a0-99a90e613fce","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"sealed","marks":[{"type":"code"}]},{"type":"text","text":" type (Java 17) lists exactly which classes may extend it. The compiler then knows the full set of subtypes — which makes "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" over them exhaustive."}]}]}},"revision":1},{"id":"ae1b9a7d-74cc-7806-a338-b8c3e0ff2c12","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sealed","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"sealed interface Shape permits Circle, Square","marks":[{"type":"code"}]},{"type":"text","text":" — only the named types may directly implement "},{"type":"text","text":"Shape","marks":[{"type":"code"}]},{"type":"text","text":". Each permitted subtype must itself be "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"sealed","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"non-sealed","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"5c600497-2f6c-7ce7-a624-f7385bfdd6c9","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Why seal a hierarchy?"}]},"revision":1},{"id":"3d46854c-641c-770a-9149-1df37e06f55d","type":"callout","position":"a3","content":{"variant":"note","title":"Closed set of cases","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Model \"one of these and nothing else\": a "},{"type":"text","text":"Result","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"Ok","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Err","marks":[{"type":"code"}]},{"type":"text","text":"; a JSON value is one of six kinds."}]}]}},"revision":1},{"id":"b0ee4c51-e209-7748-a573-a64c6a35108e","type":"callout","position":"a4","content":{"variant":"note","title":"Exhaustive switch","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" over a sealed type needs no "},{"type":"text","text":"default","marks":[{"type":"code"}]},{"type":"text","text":" — and adding a new subtype makes every non-exhaustive switch a "},{"type":"text","text":"compile error","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"593177aa-30f8-7830-ba2c-12eb247d1beb","type":"callout","position":"a5","content":{"variant":"note","title":"Controlled extension","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Public enough to use, not open for arbitrary subclassing — stronger than package-private, weaker than "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"f035eb18-7805-7b44-ba92-ad24a5c2c642","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Subtype modifiers"}]},"revision":1},{"id":"51690f1a-5849-7216-924d-e447f902be47","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Permitted subtype is…"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"final","marks":[{"type":"code"}]}],[{"type":"text","text":"No further subclasses (records and enums are implicitly final)"}]],[[{"type":"text","text":"sealed … permits …","marks":[{"type":"code"}]}],[{"type":"text","text":"Continues the restriction one level down"}]],[[{"type":"text","text":"non-sealed","marks":[{"type":"code"}]}],[{"type":"text","text":"Re-opens that branch — anyone may extend it"}]]]},"revision":1},{"id":"c9053cbb-c1f5-77ea-b5c0-5c2792e7632f","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Sealed interface + records + pattern switch"}]},"revision":1},{"id":"ab313cad-6803-7554-a514-37ef7ad86f80","type":"code","position":"a9","content":{"language":"java","code":"public class Main {\n    sealed interface Shape permits Circle, Square, Rect {}\n    record Circle(double r) implements Shape {}\n    record Square(double side) implements Shape {}\n    record Rect(double w, double h) implements Shape {}\n\n    static double area(Shape s) {\n        return switch (s) {                    // exhaustive: no default\n            case Circle c -> Math.PI * c.r() * c.r();\n            case Square sq -> sq.side() * sq.side();\n            case Rect(double w, double h) -> w * h;     // record pattern (Java 21)\n        };\n    }\n\n    public static void main(String[] args) {\n        Shape[] shapes = { new Circle(1), new Square(2), new Rect(2, 3) };\n        for (Shape s : shapes) System.out.printf(\"%s -> %.2f%n\", s, area(s));\n    }\n}","filename":"Java"},"revision":1},{"id":"bdc3bd3c-c822-7288-89fc-85fd7f183712","type":"code","position":"aA","content":{"language":"text","code":"Circle[r=1.0] -> 3.14\nSquare[side=2.0] -> 4.00\nRect[w=2.0, h=3.0] -> 6.00","filename":"Output"},"revision":1},{"id":"96c59c39-61e0-7c84-9ce1-c69d046a8c99","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is Java''s version of "},{"type":"text","text":"algebraic data types","marks":[{"type":"italic"}]},{"type":"text","text":": the sealed interface is the \"sum\", each record is a \"product\". Together with pattern matching it replaces many uses of the Visitor pattern."}]}]}},"revision":1},{"id":"9c72f716-abe7-7afa-8acb-a5641ce4afe5","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"